fn show_shutdown_feedback(&mut self, tui: &mut tui::Tui) -> Result<()> {
        self.disable_ambient_pet_before_shutdown(tui)?;
        self.chat_widget.show_shutdown_in_progress();
        let screen_size = tui.terminal.last_known_screen_size;
        self.handle_draw_pre_render(tui, screen_size)?;
        self.chat_widget.pre_draw_tick();
        self.render_chat_widget_frame(tui, screen_size)?;
        Ok(())
    }

fn render_chat_widget_frame(&mut self, tui: &mut tui::Tui, screen_size: Size) -> Result<Rect> {
        self.sync_thread_title_progress();
        self.chat_widget
            .set_sparkle_terminal_focus(tui.is_terminal_focused());
        if tui.is_owned_screen() {
            return self.render_owned_transcript(tui, screen_size);
        }
        self.chat_widget
            .empty_state_animation
            .borrow_mut()
            .pause_clock();
        self.chat_widget.sync_warnings(&self.transcript_cells);
        let dashboard_visible = self
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .is_some();
        let dashboard_was_visible = std::mem::replace(
            &mut self.agents_overview.rendered_full_screen,
            dashboard_visible,
        );
        // Full-height inline overlays scroll history off screen without a terminal resize.
        // Rebuild it once when returning to a content-height chat viewport.
        let restoring_inline_viewport = !tui.is_alt_screen_active()
            && tui.terminal.viewport_area.height == screen_size.height
            && self.with_chat_widget_frame(screen_size.width, |height, _| height)
                < screen_size.height;
        if !dashboard_visible && (dashboard_was_visible || restoring_inline_viewport) {
            self.schedule_immediate_resize_reflow(tui);
            self.maybe_run_resize_reflow(tui, screen_size)?;
        }
        self.with_chat_widget_frame(screen_size.width, |desired_height, chat_widget| {
            let desired_height = if dashboard_visible {
                screen_size.height
            } else {
                desired_height
            };
            let mut rendered_area = Rect::default();
            tui.draw_with_resize_reflow(desired_height, screen_size, |frame| {
                let area = frame.area();
                rendered_area = area;
                chat_widget.render(area, frame.buffer);
                self.chat_widget.note_rendered_width(area.width);
                if let Some((x, y)) = chat_widget.cursor_pos(area) {
                    frame.set_cursor_style(chat_widget.cursor_style(area));
                    frame.set_cursor_position((x, y));
                }
            })?;
            Ok(rendered_area)
        })
    }

fn refresh_account_email(&mut self, app_server: &AppServerSession) {
        let request_id = Uuid::new_v4();
        self.account_email_request_id = Some(request_id);
        let request_handle = app_server.request_handle();
        let app_event_tx = self.app_event_tx.clone();
        tokio::spawn(async move {
            let result = tokio::time::timeout(
                Duration::from_secs(/*secs*/ 30),
                request_handle.request_typed::<GetAccountResponse>(ClientRequest::GetAccount {
                    request_id: RequestId::String(format!("account-status-{request_id}")),
                    params: GetAccountParams {
                        refresh_token: false,
                    },
                }),
            )
            .await;
            match result {
                Ok(Ok(response)) => {
                    if let Some(Account::Chatgpt { email, .. }) = response.account {
                        app_event_tx.send(AppEvent::AccountEmailLoaded { request_id, email });
                    }
                }
                Ok(Err(_)) | Err(_) => {
                    tracing::warn!("failed to read account identity after account update");
                }
            }
        });
    }

fn live_center_rename_retains_target_when_status_leaves_filter() -> Result<()> {
    let mut app = make_test_app().await;
    app.chat_widget.toggle_vim_mode_and_notify();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    app.app_event_tx = AppEventSender::new(tx);
    let id = ThreadId::new();
    let other = ThreadId::new();
    let mut threads = vec![
        overview_thread(
            id,
            /*parent_thread_id*/ None,
            "Tar\nget",
            ThreadStatus::Idle,
        ),
        overview_thread(
            other,
            /*parent_thread_id*/ None,
            "Other",
            ThreadStatus::Idle,
        ),
    ];
    for key in [KeyCode::Esc, KeyCode::Enter] {
        threads[0].status = ThreadStatus::Idle;
        let mut view = app.agents_overview_view(threads.clone(), Some(id));
        // Reuse the Ready tab after the first iteration.
        if key == KeyCode::Esc {
            for _ in 0..3 {
                view.handle_key_event(KeyCode::Tab.into());
            }
        }
        view.handle_key_event(KeyCode::Char('r').into());
        assert_eq!(
            view.cursor_style(Rect::default()),
            crossterm::cursor::SetCursorStyle::SteadyBar
        );
        threads[0].status = ThreadStatus::SystemError;
        view = app.agents_overview_view(threads.clone(), Some(id));
        if key == KeyCode::Enter {
            for edit in [
                KeyCode::Esc,
                KeyCode::Char('0'),
                KeyCode::Char('c'),
                KeyCode::Char('w'),
            ] {
                view.handle_key_event(edit.into());
            }
            view.handle_paste("Target".into());
        }
        view.handle_key_event(KeyCode::Char('!').into());
        view.handle_key_event(key.into());
        if key == KeyCode::Esc {
            assert_eq!(
                view.cursor_style(Rect::default()),
                crossterm::cursor::SetCursorStyle::DefaultUserShape
            );
            view.handle_key_event(KeyCode::Esc.into());
        }
        assert_eq!(view.rows[view.selected_index().unwrap()].thread_id, other);
        if key == KeyCode::Enter {
            let rename = rx.try_recv().unwrap();
            assert!(
                matches!(&rename, AppEvent::RenameAgentsOverviewThread { thread_id, name } if *thread_id == id && name == "Target!")
            );
            app.agents_overview.threads = threads
                .iter()
                .map(|thread| {
                    (
                        ThreadId::from_string(&thread.id).unwrap(),
                        Some(thread.clone()),
                    )
                })
                .collect();
            app.agents_overview.visible_thread_ids = view.thread_ids();
            app.chat_widget.show_bottom_pane_view(Box::new(view));
            let mut server = crate::start_embedded_app_server_for_picker(&app.config).await?;
            let mut tui = crate::tui::test_support::make_test_tui()?;
            // Synthetic IDs have no rollout: the server rejects the rename.
            Box::pin(app.handle_event(&mut tui, &mut server, rename)).await?;
            let mut retry = app.agents_overview_view(threads.clone(), Some(other));
            assert_eq!(retry.rows[retry.selected_index().unwrap()].thread_id, id);
            retry.handle_key_event(KeyCode::Enter.into());
            assert!(std::iter::from_fn(|| rx.try_recv().ok()).any(|event| matches!(event, AppEvent::RenameAgentsOverviewThread { thread_id, name } if thread_id == id && name == "Target!")));
            server.shutdown().await?;
        } else {
            assert!(rx.try_recv().is_err());
        }
    }
    Ok(())
}

fn live_center_fixed_shortcuts_yield_to_configured_actions() {
    let mut app = make_test_app().await;
    let config: TuiKeymap = toml::from_str("[list]\ncancel = 'q'").unwrap();
    app.keymap = RuntimeKeymap::from_config(&config).unwrap();
    for editor_key in ['/', 'r'] {
        let mut view = app.agents_overview_view(
            vec![overview_thread(
                ThreadId::from_u128(/*value*/ 42),
                /*parent_thread_id*/ None,
                "Task",
                ThreadStatus::Idle,
            )],
            /*selected_thread_id*/ None,
        );
        view.handle_key_event(KeyCode::Char(editor_key).into());
        assert!(
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .editing_metadata()
        );
        view.handle_key_event(KeyCode::Char('q').into());
        assert!(
            !app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .editing_metadata()
        );
        assert!(!view.is_complete());
    }
    for (binding, key) in [
        ("tab", KeyEvent::from(KeyCode::Tab)),
        ("?", KeyEvent::from(KeyCode::Char('?'))),
        (
            "shift-?",
            KeyEvent::new(KeyCode::Char('?'), KeyModifiers::SHIFT),
        ),
        ("f9", KeyEvent::from(KeyCode::F(9))),
        ("enter", KeyEvent::from(KeyCode::Enter)),
    ] {
        let mut app = make_test_app().await;
        let config: TuiKeymap = toml::from_str(&format!(
            "[list]\ncancel = 'f9'\n[agents]\nresume = '{binding}'"
        ))
        .unwrap();
        app.keymap = RuntimeKeymap::from_config(&config).unwrap();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        app.app_event_tx = AppEventSender::new(tx);
        let mut view = app.agents_overview_view(Vec::new(), /*selected_thread_id*/ None);
        view.handle_key_event(KeyCode::Esc.into());
        assert!(!view.is_complete());
        if key.code == KeyCode::Char('?') {
            assert!(!screen(&view, /*width*/ 100, /*height*/ 24).contains("? help"));
        }
        if key.code == KeyCode::Enter {
            assert!(!screen(&view, /*width*/ 100, /*height*/ 24).contains("enter open"));
            view.handle_key_event(KeyCode::Char('?').into());
            assert!(!screen(&view, /*width*/ 100, /*height*/ 24).contains("enter open"));
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .server_version_notice = Some("Version notice".into());
            assert!(screen(&view, /*width*/ 100, /*height*/ 24).contains("f9 back"));
            view.handle_key_event(KeyCode::Esc.into());
            assert!(screen(&view, /*width*/ 100, /*height*/ 24).contains("Task shortcuts"));
            view.handle_key_event(KeyCode::F(9).into());
            assert!(!screen(&view, /*width*/ 100, /*height*/ 24).contains("Task shortcuts"));
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .server_version_notice = None;
            view.handle_key_event(KeyCode::Char('/').into());
            assert!(!screen(&view, /*width*/ 100, /*height*/ 24).contains("enter open"));
        }
        view.handle_key_event(key);
        assert!(!view.is_complete());
        assert!(
            matches!(rx.try_recv(), Ok(AppEvent::OpenResumePicker)),
            "{binding}"
        );
        assert!(rx.try_recv().is_err());
    }
}

