fn prepare_agents_overview_removal(&mut self, removed: &HashSet<ThreadId>) {
        let selected = self.agents_overview.selection_after_removal.or_else(|| {
            let index = self
                .chat_widget
                .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)?;
            self.agents_overview.visible_thread_ids.get(index).copied()
        });
        let Some(selected) = selected.filter(|id| removed.contains(id)) else {
            return;
        };
        let threads = self
            .agents_overview
            .threads
            .values()
            .flatten()
            .cloned()
            .collect();
        self.agents_overview.selection_after_removal = self
            .agents_overview_view(threads, Some(selected))
            .selection_after_removal(removed);
    }

fn command_center_action_failures_remain_visible() -> Result<()> {
    let mut app = Box::pin(make_test_app()).await;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let thread_id = ThreadId::new();
    let view = app.agents_overview_view(Vec::new(), /*selected_thread_id*/ None);
    app.chat_widget.show_bottom_pane_view(Box::new(view));
    for (event, expected) in [
        (
            AppEvent::SelectAgentsOverviewThread { thread_id },
            "is unavailable",
        ),
        (
            AppEvent::RenameAgentsOverviewThread {
                thread_id,
                name: "New name".into(),
            },
            "Failed to rename task",
        ),
        (
            AppEvent::StopAgentsOverviewThread { thread_id },
            "Failed to stop background task",
        ),
    ] {
        Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
        let rendered = render_bottom_popup(&app.chat_widget, /*width*/ 96);
        assert!(rendered.contains("Unable to complete action"), "{rendered}");
        assert!(rendered.contains(expected), "{rendered}");
        app.chat_widget.handle_key_event(KeyCode::Esc.into());
        assert!(
            render_bottom_popup(&app.chat_widget, /*width*/ 96).contains("Agent command center")
        );
    }
    // The retained primary task can also fail in the nested agent-attachment path.
    app.primary_thread_id = Some(thread_id);
    Box::pin(app.handle_event(
        &mut tui,
        &mut server,
        AppEvent::SelectAgentsOverviewThread { thread_id },
    ))
    .await?;
    let rendered = render_bottom_popup(&app.chat_widget, /*width*/ 96);
    assert!(rendered.contains("Unable to complete action"), "{rendered}");
    assert!(rendered.contains("is no longer available"), "{rendered}");
    server.shutdown().await?;
    Ok(())
}

fn overview_fork_preserves_an_open_side_conversation() -> Result<()> {
