fn command_center_attach_conflict_opens_read_only_and_retries() -> Result<()> {
    let mut app = Box::pin(make_test_app()).await;
    trust_fixture_folders(&mut app);
    std::fs::write(
        app.config.codex_home.join("config.toml"),
        "[tui]\nresume_cwd = \"current\"\n",
    )?;
    for cwd in [test_path_buf("/"), app.config.cwd.to_path_buf()] {
        crate::legacy_core::config::set_project_trust_level(
            app.config.codex_home.as_path(),
            &cwd,
            codex_protocol::config_types::TrustLevel::Trusted,
        )
        .map_err(std::io::Error::other)?;
    }
    let thread_id = ThreadId::from_string(
        &app_test_support::create_fake_rollout(
            app.config.codex_home.as_path(),
            "2025-01-05T12-00-00",
            "2025-01-05T12:00:00Z",
            "Saved task",
            Some(&app.config.model_provider_id),
            /*git_info*/ None,
        )
        .expect("saved task"),
    )?;
    let mut owner = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    Box::pin(owner.resume_thread(
        &app.local_settings,
        app.config.clone(),
        thread_id,
        crate::app_server_session::ResumeModelSettings::PreserveExistingThread,
    ))
    .await?;
    let thread = owner
        .thread_read(thread_id, /*include_turns*/ false)
        .await?;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    app.app_server_target = AppServerTarget::LocalDaemon {
        allow_embedded_fallback: true,
        endpoint: crate::resolve_remote_addr("ws://127.0.0.1:4500")?,
    };
    app.chat_widget.remote_connection =
        crate::status::remote_connection::remote_connection_status_value(
            &app.app_server_target,
            /*server_version*/ None,
        );
    app.agents_overview
        .threads
        .insert(thread_id, Some(thread.clone()));
    app.chat_widget.insert_str("Retained task draft");
    app.agents_overview.input_states.insert(
        thread_id,
        app.chat_widget
            .capture_thread_input_state()
            .expect("task draft"),
    );
    app.agents_overview.dispatched_requests.insert(
        thread_id,
        vec![ServerRequest::ToolRequestUserInput {
            request_id: RequestId::Integer(42),
            params: ToolRequestUserInputParams {
                thread_id: thread_id.to_string(),
                turn_id: "turn".into(),
                item_id: "question".into(),
                questions: Vec::new(),
                is_blocking: true,
                auto_resolution_ms: None,
            },
        }]
        .into_iter()
        .map(|request| BufferedServerRequest::new(request, &server.request_handle()))
        .collect(),
    );
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    app.app_event_tx = AppEventSender::new(tx);
    let mut view = app.agents_overview_view(vec![thread], Some(thread_id));
    view.handle_key_event(KeyCode::Esc.into());
    app.chat_widget.show_bottom_pane_view(Box::new(view));
    let selection = app
        .chat_widget
        .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID);
    let mut tui = crate::tui::test_support::make_test_tui()?;

    app.config.approvals_reviewer = ApprovalsReviewer::AutoReview;
    app.runtime_approvals_reviewer_override = Some(ApprovalsReviewer::AutoReview);
    app.runtime_approval_policy_override = Some(RuntimeApprovalPolicyOverride::Explicit(
        AskForApproval::Never,
    ));
    app.runtime_permission_profile_override =
        Some(RuntimePermissionProfileOverride::from_config(&app.config));
    let expected_overrides = (
        app.runtime_approvals_reviewer_override,
        app.runtime_approval_policy_override,
        app.runtime_permission_profile_override.clone(),
    );
    app.chat_widget.handle_key_event(KeyCode::Right.into());
    let event = rx.try_recv()?;
    assert!(
        matches!(event, AppEvent::SelectAgentsOverviewThread { thread_id: id } if id == thread_id)
    );
    Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
    assert_eq!(app.chat_widget.thread_id(), Some(thread_id));
    assert!(app.chat_widget.is_external_writer_view());
    assert_eq!(
        app.thread_event_channels[&thread_id].attachment(),
        ThreadEventAttachment::ExternalWriter
    );
    assert_eq!(app.agents_overview.dispatched_requests[&thread_id].len(), 1);
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Retained task draft"
    );
    let turns = app.thread_event_channels[&thread_id]
        .store
        .lock()
        .await
        .snapshot()
        .turns;
    assert!(serde_json::to_string(&turns)?.contains("Saved task"));
    insta::with_settings!({snapshot_path => "../snapshots"}, {
        insta::assert_snapshot!("agents_overview_attach_conflict", render_bottom_popup(&app.chat_widget, /*width*/ 96));
    });

    for key in [KeyCode::Left, KeyCode::Esc] {
        Box::pin(app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(key.into()))).await?;
        assert_eq!(
            app.chat_widget
                .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID),
            selection
        );

        // Opening the displayed task returns to the same frozen snapshot without retrying.
        Box::pin(app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::SelectAgentsOverviewThread { thread_id },
        ))
        .await?;
    }
    assert!(app.chat_widget.no_modal_or_popup_active());
    assert!(app.chat_widget.is_external_writer_view());
    app.chat_widget.handle_paste(" should be ignored".into());
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Retained task draft"
    );
    assert_eq!(
        app.thread_event_channels[&thread_id]
            .store
            .lock()
            .await
            .snapshot()
            .turns,
        turns
    );

    // An explicit retry remains read-only while the other server owns the task.
    Box::pin(app.handle_key_event(&mut tui, &mut server, KeyCode::Char('r').into())).await;
    assert!(app.chat_widget.is_external_writer_view());
    assert_eq!(
        (
            app.runtime_approvals_reviewer_override,
            app.runtime_approval_policy_override,
            app.runtime_permission_profile_override.clone()
        ),
        expected_overrides,
    );
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Retained task draft"
    );
    assert!(
        server
            .thread_loaded_list(codex_app_server_protocol::ThreadLoadedListParams {
                cursor: None,
                limit: None,
            })
            .await?
            .data
            .is_empty()
    );

    // Buffered requests stay untouched while viewing; remove the synthetic request before retry.
    assert_eq!(
        app.agents_overview
            .dispatched_requests
            .remove(&thread_id)
            .unwrap()
            .len(),
        1
    );
    owner.shutdown().await?;
    Box::pin(app.handle_key_event(&mut tui, &mut server, KeyCode::Char('r').into())).await;
    assert_eq!(app.chat_widget.thread_id(), Some(thread_id));
    assert!(!app.chat_widget.is_external_writer_view());
    assert_eq!(
        app.thread_event_channels[&thread_id].attachment(),
        ThreadEventAttachment::Live
    );
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Retained task draft"
    );
    assert!(app.chat_widget.no_modal_or_popup_active());
    server.shutdown().await?;
    Ok(())
}

fn refresh_changed_agents_overview_threads(
        &mut self,
        app_server: &AppServerSession,
    ) {
        if self
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .is_none()
            || (!self.agents_overview.initialized && self.agents_overview.request_id.is_none())
        {
            return;
        }
        self.start_agents_overview_refresh(app_server);
    }

fn start_agents_overview_refresh(&mut self, app_server: &AppServerSession) {
        let visible = self
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .is_some();
        if !visible
            && (self.agents_overview.initialized
                || matches!(self.app_server_target, AppServerTarget::Embedded))
        {
            return;
        }
        if self.agents_overview.request_id.is_some() {
            self.agents_overview.refresh_pending = true;
            return;
        }
        if self.agents_overview.initialized
            && self.agents_overview.refresh_thread_ids.is_empty()
            && !self.agents_overview.show_more_requested
            && !(self.agents_overview.refill_count > 0 && self.agents_overview.discovery.has_more())
            && !self.agents_overview.pin_refresh_requested
        {
            return;
        }

        self.agents_overview.pin_refresh_requested = false;
        let request_id = Uuid::new_v4();
        self.agents_overview.request_id = Some(request_id);
        let initialized = self.agents_overview.initialized;
        let refill = self.agents_overview.refill_count;
        let show_more =
            refill == 0 && std::mem::take(&mut self.agents_overview.show_more_requested);
        self.agents_overview.refresh_show_more = show_more;
        let discover =
            !initialized || show_more || (refill > 0 && self.agents_overview.discovery.has_more());
        let limit = if initialized && refill > 0 {
            refill.min(10)
        } else {
            10
        };
        let mut discovery = discover.then(|| {
            if initialized {
                self.agents_overview.discovery.clone()
            } else {
                self.agents_overview.removed_threads.clear();
                Default::default()
            }
        });
        let mut thread_ids = std::mem::take(&mut self.agents_overview.refresh_thread_ids);
        self.agents_overview.active_refresh_thread_ids = thread_ids.clone();
        let request_handle = app_server.request_handle();
        let app_event_tx = self.app_event_tx.clone();
        self.agents_overview
            .view_state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .loading = discover;
        let refresh_task = tokio::spawn(async move {
            let result = async {
                let mut threads = HashMap::new();
                let mut last_messages = HashMap::new();
                let mut recent_seed_complete = true;
                let pinned_thread_ids = match list_pinned_threads(&request_handle).await {
                    Ok(Some(pinned_threads)) => {
                        let mut ids = Vec::with_capacity(pinned_threads.len());
                        for thread in pinned_threads {
                            if let Ok(thread_id) = ThreadId::from_string(&thread.id) {
                                ids.push(thread_id);
                                threads.insert(thread_id, Some(thread));
                            }
                        }
                        Some(Some(ids))
                    }
                    Ok(None) => Some(None),
                    Err(error) => {
                        tracing::warn!(%error, "failed to list pinned agent threads");
                        None
                    }
                };
                if let Some(discovery) = &mut discovery {
                    let loaded = async {
                        if initialized {
                            return Ok(ThreadLoadedListResponse {
                                data: Vec::new(),
                                next_cursor: None,
                            });
                        }
                        request_handle
                            .request_typed::<ThreadLoadedListResponse>(
                                ClientRequest::ThreadLoadedList {
                                    request_id: RequestId::String(Uuid::new_v4().to_string()),
                                    params: ThreadLoadedListParams {
                                        cursor: None,
                                        limit: None,
                                    },
                                },
                            )
                            .await
                    };
                    let (loaded, (recent, complete)) =
                        tokio::join!(loaded, discovery.next_batch(&request_handle, limit));
                    let loaded = loaded.map_err(|error| error.to_string())?;
                    recent_seed_complete = complete;
                    thread_ids.extend(
                        loaded
                            .data
                            .into_iter()
                            .filter_map(|id| ThreadId::from_string(&id).ok()),
                    );
                    thread_ids.extend(detail_thread_ids(recent.iter()));
                    for thread in recent {
                        if let Ok(thread_id) = ThreadId::from_string(&thread.id) {
                            threads.insert(thread_id, Some(thread));
                        }
                    }
                }

                let mut reads = tokio::task::JoinSet::new();
                for thread_id in thread_ids {
                    threads.entry(thread_id).or_default();
                    let request_handle = request_handle.clone();
                    reads.spawn(async move {
                        match request_handle
                            .request_typed::<ThreadReadResponse>(ClientRequest::ThreadRead {
                                request_id: RequestId::String(Uuid::new_v4().to_string()),
                                params: ThreadReadParams {
                                    thread_id: thread_id.to_string(),
                                    include_turns: false,
                                },
                            })
                            .await
                        {
                            Ok(mut response) => {
                                let mut last_message = None;
                                if let Ok(turns) = request_handle
                                    .request_typed::<ThreadTurnsListResponse>(
                                        ClientRequest::ThreadTurnsList {
                                            request_id: RequestId::String(
                                                Uuid::new_v4().to_string(),
                                            ),
                                            params: ThreadTurnsListParams {
                                                thread_id: thread_id.to_string(),
                                                cursor: None,
                                                limit: Some(1),
                                                sort_direction: None,
                                                items_view: None,
                                            },
                                        },
                                    )
                                    .await
                                    && let Some(turn) = turns.data.first()
                                {
                                    if let Some(ThreadItem::UserMessage { content, .. }) =
                                        turn.items.first()
                                    {
                                        response.thread.preview =
                                            ChatWidget::user_message_display_from_inputs(content)
                                                .message;
                                    }
                                    last_message =
                                        turn.items.iter().rev().find_map(|item| match item {
                                            ThreadItem::AgentMessage { text, .. } => {
                                                Some(preview_agent_message(text))
                                            }
                                            _ => None,
                                        });
                                }
                                Some((thread_id, response.thread, last_message))
                            }
                            Err(error) => {
                                tracing::warn!(%thread_id, %error, "failed to read agent thread");
                                None
                            }
                        }
                    });
                    if reads.len() >= 16
                        && let Some(Ok(Some((thread_id, thread, last_message)))) =
                            reads.join_next().await
                    {
                        threads.insert(thread_id, Some(thread));
                        if let Some(message) = last_message {
                            last_messages.insert(thread_id, message);
                        }
                    }
                }
                while let Some(result) = reads.join_next().await {
                    if let Ok(Some((thread_id, thread, last_message))) = result {
                        threads.insert(thread_id, Some(thread));
                        if let Some(message) = last_message {
                            last_messages.insert(thread_id, message);
                        }
                    }
                }
                Ok(AgentsOverviewThreadRefresh {
                    threads,
                    last_messages,
                    recent_seed_complete,
                    discovery,
                    pinned_thread_ids,
                })
            }
            .await;
            app_event_tx.send(AppEvent::AgentsOverviewThreadsLoaded { request_id, result });
        });
        self.agents_overview.refresh_task = Some(refresh_task.abort_handle());
    }

fn show_more_agents_overview(&mut self, app_server: &AppServerSession) {
        if !self.agents_overview.discovery.has_more() {
            return;
        }
        self.agents_overview.show_more_requested |= self.agents_overview.refill_count == 0;
        self.start_agents_overview_refresh(app_server);
    }

fn refresh_agents_overview_usage(
        &mut self,
        app_server: &AppServerSession,
        frame_requester: FrameRequester,
    ) {
        if self.reconnect.offline
            || self.agents_overview.usage_disabled
            || self.agents_overview.pending_usage.is_some()
            || !self.chat_widget.has_codex_backend_auth()
            || !matches!(
                self.chat_widget.current_plan_type(),
                Some(
                    PlanType::Business
                        | PlanType::EnterpriseCbpUsageBased
                        | PlanType::EnterpriseCbpAutomation
                )
            )
        {
            return;
        }
        let Some(thread_id) = self
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .and_then(|index| self.agents_overview.visible_thread_ids.get(index))
            .copied()
        else {
            return;
        };
        if let Some(age) = self
            .agents_overview
            .usage
            .get(&thread_id)
            .and_then(|usage| usage.fetched_at)
            .map(|fetched| fetched.elapsed())
            && age < REFRESH_INTERVAL
        {
            frame_requester.schedule_frame_in(REFRESH_INTERVAL - age);
            return;
        }
        let request_id = Uuid::new_v4();
        self.agents_overview.pending_usage = Some((thread_id, request_id));
        let request_handle = app_server.request_handle();
        let app_event_tx = self.app_event_tx.clone();
        tokio::spawn(async move {
            let result = tokio::time::timeout(
                THREAD_USAGE_FETCH_TIMEOUT,
                fetch_thread_usage(request_handle, thread_id),
            )
            .await
            .map_err(|_| "dashboard usage request timed out".to_string())
            .and_then(|result| result.map_err(|error| error.to_string()));
            app_event_tx.send(AppEvent::AgentsOverviewUsageLoaded {
                thread_id,
                request_id,
                result,
            });
        });
    }

