fn activate(&mut self) {
        if self.selected == usize::MAX && self.state().has_more {
            if !self.state().loading {
                self.state().loading = true;
                self.app_event_tx.send(AppEvent::ShowMoreAgentsOverview);
            }
            return;
        }
        let input = self.state().input.text().to_owned();
        if self.state().rename_target.is_some() && !input.trim().is_empty() {
            if let Some(row) = self.selected_row() {
                self.app_event_tx
                    .send(AppEvent::RenameAgentsOverviewThread {
                        thread_id: row.thread_id,
                        name: input.trim().to_string(),
                    });
            }
            self.state().rename_target = None;
            self.state().input.set_text_clearing_elements("");
            self.reconcile_command_center_selection();
        } else if let Some(row) = self
            .selected_row()
            .filter(|_| self.state().rename_target.is_none())
        {
            self.app_event_tx
                .send(AppEvent::SelectAgentsOverviewThread {
                    thread_id: row.thread_id,
                });
            if self.state().searching {
                let mut state = self.state();
                state.search.clear();
                state.searching = false;
            }
        }
    }

fn handle_key_event(&mut self, mut key: KeyEvent) {
        // Terminals encode Shift-Tab as either BackTab or Tab with the shift modifier.
        if key.code == KeyCode::BackTab {
            key.code = KeyCode::Tab;
            key.modifiers.insert(KeyModifiers::SHIFT);
        }
        if key.kind == crossterm::event::KeyEventKind::Release {
            return;
        }
        if self.rename_key(key) || self.command_center_key(key) {
            return;
        }
        if key.code == KeyCode::Backspace
            && self.state().editing_metadata()
            && key.modifiers.is_empty()
            && self.keymap.action_for(key).is_none()
        {
            self.edit_input(|input| {
                input.pop();
            });
            return;
        }
        if is_plain_text_key_event(key)
            && let KeyCode::Char(character) = key.code
            && self.state().editing_metadata()
        {
            self.edit_input(|input| input.push(character));
            return;
        }

        if self.agents_keymap.search.is_pressed(key) {
            let mut state = self.state();
            if state.rename_target.is_none() {
                state.searching = !state.searching;
                if !state.searching {
                    state.search.clear();
                }
            }
            return;
        }

        if (self.state().connection_notice.is_some()
            || self.state().creating_worktree
            || self.state().removal.is_some())
            && self.keymap.action_for(key) != Some(ListAction::Cancel)
        {
            match self.keymap.action_for(key) {
                Some(ListAction::MoveUp) => self.move_selection(/*forward*/ false),
                Some(ListAction::MoveDown) => self.move_selection(/*forward*/ true),
                Some(action @ (ListAction::PageUp | ListAction::PageDown)) => {
                    self.page_selection(action)
                }
                Some(ListAction::JumpTop) => {
                    self.selected = self.visible_indices().first().copied().unwrap_or(0);
                }
                Some(ListAction::JumpBottom) => {
                    self.selected = self.visible_indices().last().copied().unwrap_or(0);
                }
                _ => {}
            }
            return;
        }

        if self.agents_keymap.resume.is_pressed(key) {
            self.app_event_tx.send(AppEvent::OpenResumePicker);
            return;
        }
        if self.agents_keymap.toggle_grouping.is_pressed(key) {
            let mut state = self.state();
            state.grouping = match state.grouping {
                AgentsOverviewGrouping::Project => AgentsOverviewGrouping::Status,
                AgentsOverviewGrouping::Status => AgentsOverviewGrouping::Model,
                AgentsOverviewGrouping::Model => AgentsOverviewGrouping::Project,
            };
            self.app_event_tx
                .send(AppEvent::PersistAgentsOverviewGrouping(state.grouping));
            return;
        }
        if self.agents_keymap.toggle_pin.is_pressed(key) {
            if self.can_toggle_selected_pin()
                && let (Some(ranks), Some(row)) = (&self.pinned_thread_ranks, self.selected_row())
            {
                let thread_id = row.thread_id;
                let pinned = !ranks.contains_key(&thread_id);
                self.pin_action_pending = true;
                self.app_event_tx
                    .send(AppEvent::ToggleAgentsOverviewPin { thread_id, pinned });
            }
            return;
        }
        if self.agents_keymap.new_task.is_pressed(key) {
            self.app_event_tx.send(AppEvent::NewAgentsOverviewSession {
                cwd: self.selected_row().map(|row| row.thread.cwd.clone()),
            });
            return;
        }
        if self.agents_keymap.new_worktree.is_pressed(key) {
            if self.worktrees_enabled {
                self.app_event_tx.send(AppEvent::NewAgentsOverviewWorktree {
                    cwd: self.selected_row().map(|row| row.thread.cwd.clone()),
                });
            }
            return;
        }
        if self.agents_keymap.fork.is_pressed(key) {
            if let Some(row) = self.selected_row() {
                self.app_event_tx.send(AppEvent::ForkAgentsOverviewThread {
                    thread_id: row.thread_id,
                });
            }
            return;
        }
        if self.agents_keymap.rename.is_pressed(key) {
            if let Some(row) = self.selected_row() {
                let mut state = self.state();
                if state.rename_target.is_none() {
                    state.set_rename_input(
                        row.thread.name.as_deref().unwrap_or_default(),
                        &self.editor_keymap,
                    );
                    state.search.clear();
                    state.searching = false;
                    state.rename_target = Some(row.thread_id);
                }
            }
            return;
        }
        for (bindings, action) in [
            (&self.agents_keymap.archive, AgentsOverviewAction::Archive),
            (&self.agents_keymap.delete, AgentsOverviewAction::Delete),
        ] {
            if bindings.is_pressed(key) {
                if let Some(row) = self.selected_row() {
                    self.app_event_tx
                        .send(AppEvent::ConfirmAgentsOverviewAction {
                            thread_id: row.thread_id,
                            action,
                        });
                }
                return;
            }
        }
        if self.agents_keymap.hide.is_pressed(key) {
            if let Some(row) = self.selected_row() {
                let thread_id = row.thread_id;
                self.app_event_tx
                    .send(AppEvent::HideAgentsOverviewThread { thread_id });
            }
            return;
        }
        if self.agents_keymap.stop.is_pressed(key) {
            if let Some(row) = self.selected_row()
                && matches!(row.thread.status, ThreadStatus::Active { .. })
            {
                self.app_event_tx.send(AppEvent::StopAgentsOverviewThread {
                    thread_id: row.thread_id,
                });
            }
            return;
        }

        if let Some(action) = self.keymap.action_for(key) {
            if self.state().rename_target.is_some()
                && matches!(action, ListAction::JumpTop | ListAction::JumpBottom)
            {
                return;
            }
            match action {
                ListAction::MoveUp => self.move_selection(/*forward*/ false),
                ListAction::MoveDown => self.move_selection(/*forward*/ true),
                ListAction::JumpTop => {
                    self.selected = self.visible_indices().first().copied().unwrap_or(0);
                }
                ListAction::JumpBottom => {
                    self.selected = self.visible_indices().last().copied().unwrap_or(0);
                }
                ListAction::Accept => self.activate(),
                ListAction::Cancel => {
                    if matches!(self.on_ctrl_c(), CancellationEvent::NotHandled) {
                        self.state().completion = Some(ViewCompletion::Cancelled);
                    }
                }
                ListAction::PageUp | ListAction::PageDown => {
                    self.page_selection(action);
                }
                ListAction::MoveRight if !self.state().editing_metadata() => self.activate(),
                ListAction::MoveLeft | ListAction::MoveRight => {}
            }
        } else if key.code == KeyCode::Backspace {
            self.edit_input(|input| {
                input.pop();
            });
        }
    }

fn handle_server_request_event(
        &mut self,
        app_server_client: &AppServerSession,
        buffered_request: BufferedServerRequest,
    ) {
        let request = &buffered_request.request;
        let thread_id = server_request_thread_id(request);
        if thread_id
            .is_some_and(|thread_id| self.temporary_structured_requests.contains_key(&thread_id))
        {
            self.reject_unsupported_app_server_request(
                super::app_server_requests::UnsupportedAppServerRequest {
                    request_id: request.id().clone(),
                    message:
                        "temporary structured threads cannot request tools or user interaction"
                            .to_string(),
                },
                &buffered_request,
            )
            .await;
            return;
        }
        if let ServerRequest::DynamicToolCall { request_id, params } = &request {
            if self.dynamic_tool_tasks.contains_key(request_id)
                || (params.namespace.as_deref() != Some(crate::dynamic_tools::NAMESPACE)
                    && !app_server_client.uses_embedded_app_server())
            {
                return;
            }

            let requires_mcp = crate::dynamic_tools::DELEGATION_TOOLS
                .contains(&params.tool.as_str())
                || matches!(
                    app_server_client.thread_tool_transport(),
                    crate::dynamic_tools_mcp::ThreadToolTransport::Mcp(_)
                );
            if app_server_client.uses_embedded_app_server()
                || requires_mcp
                || codex_protocol::ThreadId::from_string(&params.thread_id)
                    .is_ok_and(|thread_id| self.abandoned_side_threads.contains(&thread_id))
            {
                let response = crate::dynamic_tools::failure_response(if requires_mcp {
                    "TUI task tools require the approval-gated MCP server"
                } else {
                    "TUI dynamic tools require an active external task"
                });
                self.app_event_tx.send(AppEvent::DynamicToolCallCompleted {
                    request_id: request_id.clone(),
                    response,
                });
                return;
            }

            let request_handle = app_server_client.request_handle();
            let app_event_tx = self.app_event_tx.clone();
            let status_updates = self.dynamic_tool_status_updates.subscribe();
            let request_id = request_id.clone();
            let task_request_id = request_id.clone();
            let source_thread_id = params.thread_id.clone();
            let inherits_task_tools = params.tool == "fork_thread"
                && params
                    .arguments
                    .get("threadId")
                    .and_then(serde_json::Value::as_str)
                    .and_then(|thread_id| ThreadId::from_string(thread_id).ok())
                    .is_none_or(|thread_id| app_server_client.task_tools_available(thread_id));
            let params = params.clone();
            let mut thread_start_params =
                crate::app_server_session::thread_start_params_from_config(
                    &self.config,
                    app_server_client.thread_params_mode(),
                    app_server_client.remote_cwd_override(),
                    /*session_start_source*/ None,
                );
            app_server_client
                .thread_tool_transport()
                .configure(&mut thread_start_params);
            let features = self.config.features.get().clone();
            let task = tokio::spawn(async move {
                let response = crate::dynamic_tools::execute(
                    request_handle,
                    params,
                    thread_start_params,
                    features,
                    status_updates,
                    Some(&app_event_tx),
                )
                .await;
                if inherits_task_tools
                    && response.success
                    && let [
                        codex_app_server_protocol::DynamicToolCallOutputContentItem::InputText {
                            text,
                        },
                    ] = response.content_items.as_slice()
                    && let Ok(result) = serde_json::from_str::<serde_json::Value>(text)
                    && let Some(thread_id) =
                        result.get("threadId").and_then(serde_json::Value::as_str)
                    && let Ok(thread_id) = ThreadId::from_string(thread_id)
                {
                    app_event_tx.send(AppEvent::TaskToolsAvailable { thread_id });
                }
                app_event_tx.send(AppEvent::DynamicToolCallCompleted {
                    request_id,
                    response,
                });
            });
            self.dynamic_tool_tasks
                .insert(task_request_id, (source_thread_id, task));
            return;
        }

        let background_voice = self.background_voice.as_ref().is_some_and(|owner| {
            owner.realtime_conversation_is_running()
                && owner.thread_id().is_some()
                && owner.thread_id() == thread_id
        });
        if thread_id.is_some_and(|thread_id| self.abandoned_side_threads.contains(&thread_id)) {
            self.reject_unsupported_app_server_request(
                super::app_server_requests::UnsupportedAppServerRequest {
                    request_id: request.id().clone(),
                    message: "side conversation was closed".to_string(),
                },
                &buffered_request,
            )
            .await;
            return;
        }
        if thread_id.is_some()
            && self.primary_thread_id.is_none()
            && !background_voice
            && self.pending_startup_thread_start
        {
            if let Some(unsupported) = self
                .pending_app_server_requests
                .note_buffered_request(&buffered_request)
            {
                self.reject_unsupported_app_server_request(unsupported, &buffered_request)
                    .await;
                return;
            }
            self.pending_primary_events
                .push_back(ThreadBufferedEvent::Request(Box::new(
                    buffered_request.request,
                )));
            return;
        }
        let unsupported_request = matches!(
            &request,
            ServerRequest::DynamicToolCall { .. }
                | ServerRequest::AttestationGenerate { .. }
                | ServerRequest::CurrentTimeRead { .. }
                | ServerRequest::ApplyPatchApproval { .. }
                | ServerRequest::ExecCommandApproval { .. }
        );
        if let ServerRequest::PermissionsRequestApproval { request_id, params } = &request
            && let Err(err) = CoreRequestPermissionProfile::try_from(params.permissions.clone())
        {
            self.reject_unsupported_app_server_request(
                super::app_server_requests::UnsupportedAppServerRequest {
                    request_id: request_id.clone(),
                    message: format!("failed to localize requested filesystem paths: {err}"),
                },
                &buffered_request,
            )
            .await;
            return;
        }
        if self
            .pending_app_server_requests
            .contains_server_request(request)
        {
            return;
        }
        if let Some(thread_id) = thread_id
            && self.primary_thread_id != Some(thread_id)
            && self.active_thread_id != Some(thread_id)
            && !unsupported_request
            && !background_voice
            && let Some(requests) = self.agents_overview.dispatched_requests.get_mut(&thread_id)
        {
            requests.push(buffered_request);
            return;
        }
        if thread_id.is_some()
            && self.primary_thread_id.is_none()
            && !background_voice
            && !self.pending_startup_thread_start
            && !unsupported_request
        {
            return;
        }
        if let Some(thread_id) = thread_id
            && self.primary_thread_id.is_some()
            && self.primary_thread_id != Some(thread_id)
            && !self.thread_event_channels.contains_key(&thread_id)
            && self.agent_navigation.get(&thread_id).is_none()
            && !self.side_threads.contains_key(&thread_id)
            && !unsupported_request
        {
            let thread = app_server_client
                .request_handle()
                .request_typed::<ThreadReadResponse>(ClientRequest::ThreadRead {
                    request_id: RequestId::String(format!("subagent-approval-{thread_id}")),
                    params: ThreadReadParams {
                        thread_id: thread_id.to_string(),
                        include_turns: false,
                    },
                })
                .await;
            let Ok(ThreadReadResponse { thread, .. }) = thread else {
                return;
            };
            let SessionSource::SubAgent(SubAgentSource::ThreadSpawn {
                parent_thread_id, ..
            }) = thread.source
            else {
                return;
            };
            if !self.owns_thread_for_routing(parent_thread_id) {
                if self
                    .agents_overview
                    .dispatched_requests
                    .contains_key(&parent_thread_id)
                {
                    self.agents_overview
                        .dispatched_requests
                        .entry(thread_id)
                        .or_default()
                        .push(buffered_request);
                }
                return;
            }
        }

        let unsupported = self
            .pending_app_server_requests
            .note_buffered_request(&buffered_request);
        if let Some(unsupported) = unsupported {
            self.reject_unsupported_app_server_request(unsupported, &buffered_request)
                .await;
            return;
        }

        let Some(thread_id) = thread_id else {
            tracing::warn!("ignoring threadless app-server request");
            return;
        };

        let result = if self.primary_thread_id.is_none() && !background_voice {
            self.enqueue_primary_thread_request(buffered_request.request)
                .await
        } else {
            self.enqueue_thread_request(thread_id, buffered_request.request)
                .await
        };
        if let Err(err) = result {
            tracing::warn!("failed to enqueue app-server request: {err}");
        }
    }

