fn schedule_config_notification_test(&mut self) {
        if self.config_notification_test_pending.is_some() {
            self.chat_widget.refresh_config_panel(/*notice*/ Some(
                "Test already scheduled · switch apps".into(),
            ));
            return;
        }
        self.config_notification_test_generation = self
            .config_notification_test_generation
            .wrapping_add(/*rhs*/ 1);
        let generation = self.config_notification_test_generation;
        self.config_notification_test_pending = Some(generation);
        self.chat_widget.refresh_config_panel(
            /*notice*/ Some("Test scheduled in 5s · switch apps".into()),
        );
        let tx = self.app_event_tx.clone();
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_secs(/*secs*/ 5)).await;
            tx.send(AppEvent::SendConfigTestNotification { generation });
        });
    }

fn send_config_notification_test(&mut self, tui: &mut tui::Tui, generation: u64) {
        if self.config_notification_test_pending != Some(generation) {
            return;
        }
        self.config_notification_test_pending = None;
        let notice = if !tui.notify_test("Codex notification test") {
            "Could not send test · check terminal connection"
        } else if codex_terminal_detection::terminal_info().name
            == codex_terminal_detection::TerminalName::Ghostty
            && tui.is_terminal_focused()
        {
            "Test sent · Ghostty hides banners while focused"
        } else {
            "Test sent · check terminal/system settings"
        };
        if !self
            .chat_widget
            .refresh_config_panel(/*notice*/ Some(notice.into()))
        {
            self.chat_widget
                .add_info_message(notice.into(), /*hint*/ None);
        }
        tui.frame_requester().schedule_frame();
    }

fn config_toggle_save_uses_host_config_and_applies_live_while_offline() -> Result<()> {
    let root = tempfile::tempdir()?;
    let home = root.path().join("home");
    let local_cwd = root.path().join("local");
    let session_cwd = root.path().join("session");
    std::fs::create_dir_all(&home)?;
    for (cwd, auto_recap) in [(&local_cwd, false), (&session_cwd, true)] {
        std::fs::create_dir_all(cwd.join(".codex"))?;
        std::fs::write(
            cwd.join(".codex/config.toml"),
            format!("[tui]\nauto_recap = {auto_recap}\n"),
        )?;
    }
    let local_cwd = AbsolutePathBuf::from_absolute_path(std::fs::canonicalize(local_cwd)?)?;
    let session_cwd = AbsolutePathBuf::from_absolute_path(std::fs::canonicalize(session_cwd)?)?;
    ConfigEditsBuilder::new(&home)
        .set_project_trust_level(local_cwd.to_path_buf(), TrustLevel::Trusted)
        .set_project_trust_level(session_cwd.to_path_buf(), TrustLevel::Trusted)
        .apply()
        .await
        .map_err(|error| color_eyre::eyre::eyre!(error.to_string()))?;
    let loader_overrides = LoaderOverrides::without_managed_config_for_tests();
    let config = ConfigBuilder::default()
        .codex_home(home)
        .harness_overrides(ConfigOverrides {
            cwd: Some(local_cwd.to_path_buf()),
            ..Default::default()
        })
        .loader_overrides(loader_overrides.clone())
        .build()
        .await?;
    assert!(!config.tui_auto_recap);

    let mut app = Box::pin(make_test_app()).await;
    app.config = config.clone();
    app.local_settings = LocalSettings::from(&config);
    app.launch_cwd = local_cwd.to_path_buf();
    app.config.cwd = session_cwd.clone();
    app.loader_overrides = loader_overrides;
    app.app_server_target = AppServerTarget::Remote {
        endpoint: crate::RemoteAppServerEndpoint::WebSocket {
            websocket_url: "ws://127.0.0.1:8765".to_string(),
            auth_token: None,
        },
    };
    app.reconnect.offline = true;

    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut session_config = config;
    session_config.cwd = session_cwd.clone();
    let init = app.chatwidget_init_for_forked_or_resumed_thread(
        &mut tui,
        session_config,
        /*initial_user_message*/ None,
    );
    app.chat_widget = ChatWidget::new_with_app_event(init);
    app.local_settings.tui.auto_recap = true;
    app.chat_widget.local_settings.tui.auto_recap = true;

    Box::pin(app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::SaveConfigPreference(ConfigPreference::Toggle {
            setting: ConfigToggle::AutomaticRecaps,
            enabled: false,
        }),
    ))
    .await?;

    app.chat_widget.handle_key_event(KeyCode::Char('a').into());
    assert!(app.chat_widget.is_in_paste_burst());
    Box::pin(app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::SaveConfigPreference(ConfigPreference::Toggle {
            setting: ConfigToggle::PasteDetection,
            enabled: false,
        }),
    ))
    .await?;

    assert_eq!(
        (
            app.local_settings.tui.auto_recap,
            app.chat_widget.local_settings.tui.auto_recap,
            app.chat_widget.config_panel_tui.auto_recap,
            app.local_settings.tui.disable_paste_burst,
            app.chat_widget.local_settings.tui.disable_paste_burst,
        ),
        (false, false, false, Some(true), Some(true)),
    );
    assert!(!app.chat_widget.is_in_paste_burst());
    app.chat_widget.handle_key_event(KeyCode::Char('b').into());
    assert!(!app.chat_widget.is_in_paste_burst());
    let saved: toml::Value = toml::from_str(&std::fs::read_to_string(
        &app.local_settings.user_config_path,
    )?)?;
    assert_eq!(saved["tui"]["auto_recap"].as_bool(), Some(false));
    assert_eq!(saved["tui"]["disable_paste_burst"].as_bool(), Some(true));
    assert_eq!(app.launch_cwd, local_cwd.to_path_buf());
    assert_eq!(
        (&app.config.cwd, &app.chat_widget.config_ref().cwd),
        (&session_cwd, &session_cwd),
    );

    app_server.shutdown().await?;
    Ok(())
}

