fn open_daemon_menu(&mut self) {
        let status = self
            .chat_widget
            .remote_connection
            .as_ref()
            .filter(|_| matches!(self.app_server_target, AppServerTarget::LocalDaemon { .. }))
            .map(|connection| format!("Running daemon: {}", connection.version))
            .unwrap_or_else(|| "Not connected to the local background server.".to_string());
        let mut header = vec![Line::from("Daemon".bold()), Line::from(status.dim())];
        let unavailable = if matches!(self.app_server_target, AppServerTarget::Remote { .. }) {
            Some(
                "Manage this server on its host. Local daemon updates are unavailable for remote connections.",
            )
        } else if self.daemon_cli_executable.is_none() {
            Some("Run the Codex CLI to manage the daemon from this menu.")
        } else {
            None
        };
        if let Some(guidance) = unavailable {
            header.push(Line::from(guidance.dim()));
        }
        let has_package = self.daemon_cli_executable.as_ref().is_some_and(|path| {
            codex_install_context::InstallContext::from_exe(
                cfg!(target_os = "macos"),
                Some(path.as_path()),
                /*method_override*/ None,
            )
            .package_layout
            .is_some()
        });
        let mut items: Vec<SelectionItem> = [
            (
                DaemonUpdateSource::PublicStable,
                "Install latest public stable",
            ),
            (DaemonUpdateSource::ThisCli, "Use this CLI build"),
        ]
        .into_iter()
        .map(|(source, name)| SelectionItem {
            name: name.to_string(),
            is_disabled: unavailable.is_some(),
            disabled_reason: (unavailable.is_none()
                && source == DaemonUpdateSource::ThisCli
                && !has_package)
                .then(|| "This CLI has no local package to copy".to_string()),
            actions: vec![Box::new(move |tx| {
                tx.send(AppEvent::ConfirmDaemonUpdate(source));
            })],
            dismiss_on_select: true,
            ..Default::default()
        })
        .collect();
        items.push(SelectionItem {
            name: "Restart background server".to_string(),
            is_disabled: !self
                .chat_widget
                .remote_connection
                .as_ref()
                .is_some_and(|connection| connection.is_managed_daemon)
                || self.reconnect.offline
                || self.daemon_restart.is_some(),
            disabled_reason: self
                .chat_widget
                .remote_connection
                .as_ref()
                .filter(|connection| connection.is_local_daemon && !connection.is_managed_daemon)
                .map(|_| {
                    "Codex hasn't verified it manages this server. Restart it where it was started."
                        .to_string()
                }),
            actions: vec![Box::new(|tx| tx.send(AppEvent::ConfirmDaemonRestart))],
            dismiss_on_select: true,
            ..Default::default()
        });
        self.chat_widget.show_selection_view(SelectionViewParams {
            header: Box::new(DaemonMenuHeader(header)),
            items,
            ..SelectionViewParams::picker()
        });
    }

fn confirm_daemon_restart(&mut self) {
        if !self
            .chat_widget
            .remote_connection
            .as_ref()
            .is_some_and(|connection| connection.is_managed_daemon)
            || self.daemon_restart.is_some()
        {
            return;
        }
        self.chat_widget.show_selection_view(SelectionViewParams {
            header: Box::new(DaemonMenuHeader(vec![
                Line::from("Restart background server?".bold()),
                Line::from("Active or queued work in other chats may be interrupted."),
                Line::from("Codex will reconnect automatically."),
            ])),
            items: vec![
                SelectionItem {
                    name: "Cancel".to_string(),
                    dismiss_on_select: true,
                    ..Default::default()
                },
                SelectionItem {
                    name: "Restart".to_string(),
                    actions: vec![Box::new(|tx| tx.send(AppEvent::RunDaemonRestart))],
                    require_explicit_confirmation: true,
                    dismiss_on_select: true,
                    ..Default::default()
                },
            ],
            ..SelectionViewParams::confirmation()
        });
    }

fn confirm_daemon_update(&mut self, source: DaemonUpdateSource) {
        let Some(executable) = &self.daemon_cli_executable else {
            return;
        };
        if matches!(self.app_server_target, AppServerTarget::Remote { .. }) {
            return;
        }
        let mut explanation = match source {
            DaemonUpdateSource::PublicStable => "Install the latest public stable release. Restore production updates; keep your automatic-update setting.".to_string(),
            DaemonUpdateSource::ThisCli => {
                let version = codex_install_context::InstallContext::current()
                    .package_manifest()
                    .map_or_else(|| CODEX_CLI_VERSION.to_string(), |manifest| manifest.version.to_string());
                format!("Use this CLI package v{version} from {}. Copy the complete package and pin it against automatic updates.", executable.display())
            }
        };
        explanation.push_str("\nThis may restart the daemon and interrupt active or queued work.\nCodex exits to update in this terminal. Relaunch it afterward.");
        let mut header = vec![Line::from("Update daemon and exit Codex?".bold())];
        header.extend(explanation.lines().map(|line| Line::from(line.to_owned())));
        self.chat_widget.show_selection_view(SelectionViewParams {
            header: Box::new(DaemonMenuHeader(header)),
            items: vec![
                SelectionItem {
                    name: "Cancel".to_string(),
                    dismiss_on_select: true,
                    ..Default::default()
                },
                SelectionItem {
                    name: "Update and exit".to_string(),
                    actions: vec![Box::new(move |tx| {
                        tx.send(AppEvent::RunDaemonUpdate(source))
                    })],
                    require_explicit_confirmation: true,
                    dismiss_on_select: true,
                    ..Default::default()
                },
            ],
            ..SelectionViewParams::confirmation()
        });
    }

fn daemon_menu_is_read_only_and_confirmation_can_cancel_or_handoff() {
    let mut app = make_test_app().await;
    let (chat, _, mut rx, _) = make_chatwidget_manual_with_sender().await;
    app.chat_widget = chat;
    let package = tempfile::tempdir().unwrap();
    std::fs::create_dir(package.path().join("bin")).unwrap();
    std::fs::write(package.path().join("bin/codex"), "CLI").unwrap();
    std::fs::write(package.path().join("codex-package.json"), "{}").unwrap();
    app.daemon_cli_executable =
        Some(AbsolutePathBuf::from_absolute_path(package.path().join("bin/codex")).unwrap());
    app.app_server_target = AppServerTarget::LocalDaemon {
        allow_embedded_fallback: true,
        endpoint: crate::RemoteAppServerEndpoint::UnixSocket {
            socket_path: AbsolutePathBuf::relative_to_current_dir("codex.sock").unwrap(),
        },
    };
    app.chat_widget.remote_connection = Some(RemoteConnectionStatus {
        address: "local".into(),
        version: "v0.153.0".into(),
        is_local_daemon: true,
        is_managed_daemon: true,
    });
    app.initialize_server_version_notice("0.154.0", Some("0.153.0"));
    let view = app.agents_overview_view(Vec::new(), /*selected_thread_id*/ None);
    app.chat_widget.show_bottom_pane_view(Box::new(view));
    let overview = render_bottom_popup(&app.chat_widget, /*width*/ 80);
    insta::assert_snapshot!(overview.lines().find(|line| line.contains("Service v")).unwrap().trim(), @"Service v0.153.0 < Codex CLI v0.154.0 · /daemon");
    let executable = app.daemon_cli_executable.clone();
    for (width, source, snapshot) in [
        (
            80,
            DaemonUpdateSource::PublicStable,
            "daemon_stable_confirmation",
        ),
        (100, DaemonUpdateSource::ThisCli, "daemon_cli_confirmation"),
    ] {
        app.daemon_cli_executable = executable.clone();
        app.open_daemon_menu();
        if source == DaemonUpdateSource::PublicStable {
            insta::assert_snapshot!(
                "daemon_menu",
                render_bottom_popup(&app.chat_widget, /*width*/ 80)
            );
        } else {
            app.chat_widget.handle_key_event(KeyCode::Down.into());
        }
        assert!(rx.try_recv().is_err());
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(
            matches!(rx.try_recv().unwrap(), AppEvent::ConfirmDaemonUpdate(selected) if selected == source)
        );
        app.daemon_cli_executable = Some(
            AbsolutePathBuf::from_absolute_path(if cfg!(windows) {
                r"C:\cli-build\bin\codex"
            } else {
                "/x/cli-build/bin/codex"
            })
            .unwrap(),
        );
        app.confirm_daemon_update(source);
        insta::assert_snapshot!(
            snapshot,
            render_bottom_popup(&app.chat_widget, width)
                .replace(r"C:\cli-build\bin\codex", "/x/cli-build/bin/codex")
        );
        // The default choice cancels without emitting an update or exiting.
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(rx.try_recv().is_err());
        assert_eq!(app.pending_update_action, None);
        app.confirm_daemon_update(source);
        app.chat_widget.handle_key_event(KeyCode::Down.into());
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(
            matches!(rx.try_recv().unwrap(), AppEvent::RunDaemonUpdate(selected) if selected == source)
        );
    }

    app.daemon_cli_executable = executable.clone();
    app.open_daemon_menu();
    let mut terminal = crate::custom_terminal::Terminal::with_options(
        crate::test_backend::VT100Backend::new(/*width*/ 120, /*height*/ 30),
    )
    .unwrap();
    let area = Rect::new(0, 0, 120, 30);
    terminal.set_viewport_area(area);
    crate::terminal_palette::with_test_default_colors(
        crate::terminal_probe::DefaultColors {
            fg: (229, 229, 229),
            bg: (30, 40, 56),
        },
        || {
            terminal
                .draw(|frame| app.chat_widget.render(area, frame.buffer_mut()))
                .unwrap()
        },
    );
    app.chat_widget.handle_key_event(KeyCode::Down.into());
    app.chat_widget.handle_key_event(KeyCode::Down.into());
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(
        rx.try_recv().unwrap(),
        AppEvent::ConfirmDaemonRestart
    ));
    app.confirm_daemon_restart();
    insta::assert_snapshot!(
        "daemon_restart_confirmation",
        render_bottom_popup(&app.chat_widget, /*width*/ 80)
    );
    crate::terminal_palette::with_test_default_colors(
        crate::terminal_probe::DefaultColors {
            fg: (229, 229, 229),
            bg: (30, 40, 56),
        },
        || {
            // Simulate a terminal that erased the menu's blank tails with its default
            // background rather than the cached panel color.
            use std::io::Write;
            for y in 0..area.height {
                write!(terminal.backend_mut(), "\x1b[{};25H\x1b[0m\x1b[K", y + 1).unwrap();
            }
            terminal
                .draw(|frame| app.chat_widget.render(area, frame.buffer_mut()))
                .unwrap();
            let expected = crate::custom_terminal::test_support::last_rendered_buffer(&terminal);
            let screen = terminal.backend().vt100().screen();
            for y in 0..area.height {
                for x in 24..96 {
                    let expected_bg = match expected[(x, y)].bg {
                        ratatui::style::Color::Rgb(r, g, b) => vt100::Color::Rgb(r, g, b),
                        ratatui::style::Color::Reset => vt100::Color::Default,
                        _ => continue,
                    };
                    assert_eq!(
                        screen.cell(y, x).unwrap().bgcolor(),
                        expected_bg,
                        "at {x}, {y}: {:?}",
                        expected[(x, y)]
                    );
                }
            }
        },
    );
    // Cancel is the default; a confirmed restart stays in the TUI.
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(rx.try_recv().is_err());
    app.confirm_daemon_restart();
    app.chat_widget.handle_key_event(KeyCode::Down.into());
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(rx.try_recv().unwrap(), AppEvent::RunDaemonRestart));

    // A local socket alone does not mean Codex can restart its owner.
    app.chat_widget
        .remote_connection
        .as_mut()
        .unwrap()
        .is_managed_daemon = false;
    app.open_daemon_menu();
    insta::assert_snapshot!(
        "daemon_unmanaged",
        render_bottom_popup(&app.chat_widget, /*width*/ 80)
    );
    app.chat_widget.handle_key_event(KeyCode::Down.into());
    app.chat_widget.handle_key_event(KeyCode::Down.into());
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(
        rx.try_recv().unwrap(),
        AppEvent::ConfirmDaemonUpdate(_)
    ));
    app.confirm_daemon_restart();
    assert!(rx.try_recv().is_err());

    // Maintenance remains available when startup selects the embedded server.
    app.app_server_target = AppServerTarget::Embedded;
    app.chat_widget.remote_connection = None;
    app.daemon_cli_executable = executable;
    for source in [
        DaemonUpdateSource::PublicStable,
        DaemonUpdateSource::ThisCli,
    ] {
        app.open_daemon_menu();
        if source == DaemonUpdateSource::PublicStable {
            insta::assert_snapshot!(
                "daemon_disconnected",
                render_bottom_popup(&app.chat_widget, /*width*/ 80)
            );
        } else {
            app.chat_widget.handle_key_event(KeyCode::Down.into());
        }
        assert!(rx.try_recv().is_err());
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(
            matches!(rx.try_recv().unwrap(), AppEvent::ConfirmDaemonUpdate(selected) if selected == source)
        );
        app.confirm_daemon_update(source);
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(rx.try_recv().is_err());
        assert_eq!(app.pending_update_action, None);
        app.confirm_daemon_update(source);
        app.chat_widget.handle_key_event(KeyCode::Down.into());
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(
            matches!(rx.try_recv().unwrap(), AppEvent::RunDaemonUpdate(selected) if selected == source)
        );
    }

    std::fs::remove_file(package.path().join("codex-package.json")).unwrap();
    // The full CLI can have any filename; capability comes from its entry point.
    app.daemon_cli_executable =
        Some(AbsolutePathBuf::from_absolute_path(package.path().join("bin/codex-tui")).unwrap());
    app.open_daemon_menu();
    insta::assert_snapshot!(
        "daemon_unpackaged_cli",
        render_bottom_popup(&app.chat_widget, /*width*/ 80)
    );
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(
        rx.try_recv().unwrap(),
        AppEvent::ConfirmDaemonUpdate(DaemonUpdateSource::PublicStable)
    ));

    app.daemon_cli_executable = None;
    app.open_daemon_menu();
    insta::assert_snapshot!(
        "daemon_no_cli_handoff",
        render_bottom_popup(&app.chat_widget, /*width*/ 80)
    );
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    assert!(rx.try_recv().is_err());
}

fn persist_daybreak_selection(
        &mut self,
        app_server: &mut AppServerSession,
        thread_id: ThreadId,
        enabled: bool,
    ) {
        if !self
            .chat_widget
            .config_ref()
            .features
            .enabled(Feature::CliDaybreak)
            || self.active_thread_id != Some(thread_id)
        {
            return;
        }
        if enabled
            && (!self.chat_widget.daybreak_account_eligible()
                || !crate::daybreak::available(&self.chat_widget.model_catalog().models))
        {
            self.chat_widget.add_error_message(
                "Daybreak availability could not be confirmed for this account.".into(),
            );
            return;
        }
        match app_server
            .thread_read(thread_id, /*include_turns*/ false)
            .await
        {
            Ok(thread) if !thread.ephemeral => {
                let request_id = app_server.next_request_id();
                let response: Result<codex_app_server_protocol::ThreadMetadataUpdateResponse, _> =
                    app_server
                        .request_handle()
                        .request_typed(ClientRequest::ThreadMetadataUpdate {
                            request_id,
                            params: codex_app_server_protocol::ThreadMetadataUpdateParams {
                                thread_id: thread_id.to_string(),
                                daybreak_enabled: Some(enabled),
                                project_id: None,
                                git_info: None,
                            },
                        })
                        .await;
                if let Err(error) = response {
                    self.chat_widget.add_error_message(format!(
                        "Failed to save Daybreak for this thread: {error}"
                    ));
                    return;
                }
            }
            Ok(_) => {}
            Err(error) => {
                self.chat_widget.add_error_message(format!(
                    "Failed to read the thread to save Daybreak: {error}"
                ));
                return;
            }
        }
        self.chat_widget.set_daybreak_enabled(enabled);
        if self.primary_thread_id == Some(thread_id)
            && let Some(session) = self.primary_session_configured.as_mut()
        {
            session.daybreak_enabled = enabled;
        }
        if let Some(channel) = self.thread_event_channels.get(&thread_id) {
            let mut store = channel.store.lock().await;
            if let Some(session) = store.session.as_mut() {
                session.daybreak_enabled = enabled;
            }
        }
        self.refresh_status_line();
        let edits = vec![crate::config_update::replace_config_value(
            "daybreak",
            serde_json::json!(enabled),
        )];
        match self
            .persist_model_defaults(
                app_server.request_handle(),
                edits,
                "default Daybreak preference",
            )
            .await
        {
            Ok(()) => match crate::config_update::read_effective_config(
                app_server.request_handle(),
                self.chat_widget
                    .config_ref()
                    .cwd
                    .to_string_lossy()
                    .into_owned(),
            )
            .await
            {
                Ok(response) => {
                    self.config.daybreak_enabled = response
                        .config
                        .additional
                        .get("daybreak")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false)
                }
                Err(error) => self.chat_widget.add_error_message(format!(
                    "Failed to read the default Daybreak preference: {error}"
                )),
            },
            Err(error) => self.chat_widget.add_error_message(format!(
                "Failed to save the default Daybreak preference: {error}"
            )),
        }
        self.chat_widget.add_info_message(
            format!(
                "Daybreak {}. Applies to new turns.",
                if enabled { "on" } else { "off" }
            ),
            /*hint*/ None,
        );
    }

