fn browsing_requires_fresh_escape_presses_and_ignores_confirmation_repeats() -> Result<()> {
    let (mut app, mut events, _operations) = make_test_app_with_channels().await;
    attach_thread(&mut app, ThreadId::new());
    app.transcript_cells = vec![user_cell("first prompt"), user_cell("second prompt")];
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    app.transcript_view
        .set_presentation(/*detailed*/ true, HistoryRenderMode::Rich);
    app.chat_widget.apply_external_edit("draft".to_string());
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
        .await?;
    assert!(!app.backtrack.overlay_preview_active);
    assert_eq!(app.chat_widget.composer_text_with_pending(), "draft");
    app.chat_widget.apply_external_edit(String::new());
    app.transcript_view
        .set_presentation(/*detailed*/ false, HistoryRenderMode::Rich);
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
        .await?;
    app.handle_tui_event(
        &mut tui,
        &mut server,
        TuiEvent::Key(KeyEvent::new_with_kind(
            KeyCode::Esc,
            KeyModifiers::NONE,
            KeyEventKind::Repeat,
        )),
    )
    .await?;
    assert!(!app.backtrack.overlay_preview_active);
    for key in [KeyCode::PageUp, KeyCode::F(8)] {
        app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(key.into()))
            .await?;
        assert!(!app.backtrack.primed);
        app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
            .await?;
        assert!(!app.backtrack.overlay_preview_active);
    }
    app.handle_tui_event(
        &mut tui,
        &mut server,
        TuiEvent::Mouse(crossterm::event::MouseEvent {
            kind: crossterm::event::MouseEventKind::Moved,
            column: 1,
            row: 1,
            modifiers: KeyModifiers::NONE,
        }),
    )
    .await?;
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
        .await?;
    for (code, kind) in [
        (KeyCode::Esc, KeyEventKind::Repeat),
        (KeyCode::Enter, KeyEventKind::Repeat),
        (KeyCode::Enter, KeyEventKind::Release),
    ] {
        app.handle_tui_event(
            &mut tui,
            &mut server,
            TuiEvent::Key(KeyEvent::new_with_kind(code, KeyModifiers::NONE, kind)),
        )
        .await?;
        assert!(app.backtrack.overlay_preview_active);
    }
    // Enter during history loading has no selected prompt to confirm.
    app.backtrack.nth_user_message = usize::MAX;
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Enter.into()))
        .await?;
    assert!(app.backtrack.overlay_preview_active);
    assert!(
        !std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event, AppEvent::RevertSessionForPromptEdit { .. }))
    );
    for (binding, keys) in [
        ("f8", vec![KeyCode::F(8)]),
        ("f8 v", vec![KeyCode::F(8), KeyCode::Char('v')]),
    ] {
        app.keymap = RuntimeKeymap::from_config(&toml::from_str(&format!(
            "[chat]\ntoggle_voice = '{binding}'"
        ))?)
        .expect("valid voice binding");
        let thread_id = app.chat_widget.thread_id().unwrap();
        crate::chatwidget::activate_voice_for_thread(&mut app.chat_widget, thread_id);
        for key in keys {
            app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(key.into()))
                .await?;
        }
        assert_eq!(
            (
                app.backtrack.overlay_preview_active,
                app.chat_widget.realtime_conversation_is_running()
            ),
            (false, false)
        );
        for _ in 0..2 {
            app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
                .await?;
        }
        assert!(app.backtrack.overlay_preview_active);
    }
    app.keymap = RuntimeKeymap::from_config(&toml::from_str(
        "[global]\nopen_external_editor = [\"f6 f7\"]",
    )?)
    .expect("valid editor chord");
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::F(6).into()))
        .await?;
    assert!(!app.backtrack.overlay_preview_active);
    assert!(app.key_chord_matcher.is_pending());
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::F(7).into()))
        .await?;
    assert_eq!(
        (
            app.backtrack.overlay_preview_active,
            app.chat_widget.external_editor_state()
        ),
        (false, ExternalEditorState::Requested)
    );
    server.shutdown().await?;
    tui.set_owned_screen(/*owned*/ false)?;
    Ok(())
}

fn plan_menu_allows_transcript_selection_and_copy_but_respects_popup_bounds() -> Result<()> {
    let (mut app, mut events, _operations) = make_test_app_with_channels().await;
    app.local_settings.tui.copy_on_select = codex_config::types::CopyOnSelect::Never;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    let size = tui.terminal.size()?;
    complete_plan_turn(&mut app);
    while let Ok(event) = events.try_recv() {
        if matches!(event, AppEvent::InsertHistoryCell(_)) {
            app.handle_event(&mut tui, &mut server, event).await?;
        }
    }
    let bottom = app.render_owned_transcript(&mut tui, size)?;
    let before = screen(&tui);
    for (kind, column, row) in [
        (MouseEventKind::ScrollUp, 1, bottom.y),
        (MouseEventKind::ScrollDown, 1, bottom.y),
        (MouseEventKind::ScrollUp, size.width, 1),
    ] {
        app.handle_tui_event(&mut tui, &mut server, pointer_event(kind, column, row))
            .await?;
        app.render_owned_transcript(&mut tui, size)?;
        assert_eq!(screen(&tui), before);
        assert!(!app.transcript_view.has_active_interaction());
    }
    let (plan_row, plan_column) = before
        .lines()
        .enumerate()
        .find_map(|(row, line)| {
            line.find("Plan step")
                .map(|column| (row as u16, column as u16))
        })
        .expect("visible plan step");
    for event in [
        pointer_event(
            MouseEventKind::Down(MouseButton::Left),
            plan_column,
            plan_row,
        ),
        TuiEvent::Draw,
        pointer_event(
            MouseEventKind::Drag(MouseButton::Left),
            plan_column + 4,
            plan_row,
        ),
        TuiEvent::Draw,
        pointer_event(
            MouseEventKind::Up(MouseButton::Left),
            plan_column + 4,
            plan_row,
        ),
    ] {
        app.handle_tui_event(&mut tui, &mut server, event).await?;
    }
    let selected = app
        .transcript_view
        .selected_text(&app.transcript_cells)
        .expect("selected plan text");
    assert!("Plan step".contains(&selected), "selected {selected:?}");
    app.handle_tui_event(
        &mut tui,
        &mut server,
        TuiEvent::Key(KeyEvent::new(KeyCode::Insert, KeyModifiers::CONTROL)),
    )
    .await?;
    assert!(tui.clipboard.is_busy());
    assert!(app.chat_widget.has_active_modal());
    app.render_owned_transcript(&mut tui, size)?;
    let buffer = crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal);
    let selection = (0..size.width)
        .map(|column| {
            if buffer[(column, plan_row)]
                .modifier
                .contains(ratatui::style::Modifier::REVERSED)
            {
                '^'
            } else {
                '·'
            }
        })
        .collect::<String>();
    insta::assert_snapshot!(
        "plan_prompt_selection",
        format!(
            "{selection}\n\n{}",
            render_bottom_popup(&app.chat_widget, /*width*/ 80),
        )
    );
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Esc.into()))
        .await?;
    app.transcript_view.end_selection(&app.transcript_cells);
    app.transcript_view.jump_to_latest();
    app.chat_widget.apply_external_edit("/m".to_string());
    app.render_owned_transcript(&mut tui, size)?;
    let popup = screen(&tui);
    let popup_row = popup
        .lines()
        .position(|line| line.contains("› /model"))
        .unwrap() as u16;
    assert!(!app.chat_widget.has_active_modal());
    assert!(!app.chat_widget.no_modal_or_popup_active());
    for kind in [MouseEventKind::ScrollUp, MouseEventKind::ScrollDown] {
        app.handle_tui_event(
            &mut tui,
            &mut server,
            pointer_event(kind, /*column*/ 1, popup_row),
        )
        .await?;
        app.render_owned_transcript(&mut tui, size)?;
        assert_eq!(screen(&tui), popup);
        assert!(app.transcript_view.is_following());
    }
    tui.set_owned_screen(/*owned*/ false)?;
    server.shutdown().await?;
    Ok(())
}

fn submitting_a_draft_from_history_queues_once_and_follows_immediately() -> Result<()> {
    let (mut app, mut events, _operations) = make_test_app_with_channels().await;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    let size = Size::new(/*width*/ 80, /*height*/ 12);
    app.transcript_cells = vec![Arc::new(PlainHistoryCell::new(
        (0..30).map(|row| format!("row {row}").into()).collect(),
    ))];
    app.render_owned_transcript(&mut tui, size)?;
    app.transcript_view
        .scroll(&app.transcript_cells, /*rows*/ -10);
    app.chat_widget
        .apply_external_edit("send this once".to_string());
    while events.try_recv().is_ok() {}

    app.handle_tui_event(
        &mut tui,
        &mut server,
        TuiEvent::Key(KeyEvent::from(KeyCode::Enter)),
    )
    .await?;
    let mut follows = 0;
    while let Ok(event) = events.try_recv() {
        if matches!(event, AppEvent::FollowTranscript) {
            follows += 1;
            app.handle_event(&mut tui, &mut server, event).await?;
        }
    }
    assert_eq!(follows, 1);
    assert!(app.transcript_view.is_following());
    assert_eq!(
        app.chat_widget.queued_user_message_texts(),
        vec!["send this once"]
    );
    assert_eq!(app.chat_widget.composer_text_with_pending(), "");
    server.shutdown().await?;
    tui.set_owned_screen(/*owned*/ false)?;
    Ok(())
}

fn plan_menu_allows_transcript_wheel_scrolling_and_keeps_keyboard_ownership() -> Result<()> {
    for close in [KeyCode::Esc, KeyCode::Enter] {
        let (mut app, mut events, _operations) = make_test_app_with_channels().await;
        let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        tui.set_owned_screen(/*owned*/ true)?;
        let size = tui.terminal.size()?;
        complete_plan_turn(&mut app);
        while let Ok(event) = events.try_recv() {
            if matches!(event, AppEvent::InsertHistoryCell(_)) {
                app.handle_event(&mut tui, &mut server, event).await?;
            }
        }
        let bottom = app.render_owned_transcript(&mut tui, size)?;
        let latest = screen(&tui);
        let menu = render_bottom_popup(&app.chat_widget, /*width*/ 80);
        for kind in [
            MouseEventKind::ScrollUp,
            MouseEventKind::ScrollDown,
            MouseEventKind::ScrollUp,
        ] {
            app.handle_tui_event(
                &mut tui,
                &mut server,
                pointer_event(kind, /*column*/ 1, /*row*/ 1),
            )
            .await?;
            app.render_owned_transcript(&mut tui, size)?;
            assert_eq!(render_bottom_popup(&app.chat_widget, /*width*/ 80), menu);
            if kind == MouseEventKind::ScrollDown {
                assert_eq!(screen(&tui), latest);
                assert!(app.transcript_view.is_following());
            } else {
                assert_ne!(screen(&tui), latest);
                assert!(!app.transcript_view.is_following());
            }
        }
        let scrolled = screen(&tui);
        if close == KeyCode::Esc {
            insta::assert_snapshot!("plan_prompt_scrolled", scrolled);
        }
        for (key, selected) in [(KeyCode::PageDown, "› 3."), (KeyCode::PageUp, "› 1.")] {
            app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(key.into()))
                .await?;
            app.render_owned_transcript(&mut tui, size)?;
            assert!(render_bottom_popup(&app.chat_widget, /*width*/ 80).contains(selected));
            assert_eq!(
                screen(&tui)
                    .lines()
                    .take(usize::from(bottom.y))
                    .collect::<Vec<_>>(),
                scrolled
                    .lines()
                    .take(usize::from(bottom.y))
                    .collect::<Vec<_>>(),
            );
        }
        while events.try_recv().is_ok() {}
        app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(close.into()))
            .await?;
        assert!(!app.chat_widget.has_active_modal());
        assert!(!app.transcript_view.is_following());
        let mut follows = 0;
        let mut submissions = Vec::new();
        while let Ok(event) = events.try_recv() {
            match event {
                AppEvent::FollowTranscript => follows += 1,
                AppEvent::SubmitUserMessageWithMode {
                    text,
                    collaboration_mode,
                } => {
                    submissions.push((text, collaboration_mode.mode));
                }
                _ => {}
            }
        }
        let expected = if close == KeyCode::Enter {
            (
                1,
                vec![("Implement the plan.".to_string(), Some(ModeKind::Default))],
            )
        } else {
            (0, Vec::new())
        };
        assert_eq!((follows, submissions), expected);
        tui.set_owned_screen(/*owned*/ false)?;
        server.shutdown().await?;
    }
    Ok(())
}

