fn save_quick_dial(&mut self, slot: u8, dial: Option<QuickDial>) {
        let key = slot.to_string();
        let read_only = {
            let mut slot_sources = self
                .config
                .config_layer_stack
                .layers_high_to_low()
                .filter(|layer| {
                    layer
                        .config
                        .get("tui")
                        .and_then(|tui| tui.get("presets"))
                        .and_then(|dials| dials.get(&key))
                        .is_some()
                })
                .map(|layer| &layer.name);
            let outside_user_config = |source: &ConfigLayerSource| {
                !matches!(source, ConfigLayerSource::User { file, .. }
                    if file == &self.local_settings.user_config_path)
            };
            if dial.is_some() {
                slot_sources.next().is_some_and(outside_user_config)
            } else {
                slot_sources.any(outside_user_config)
            }
        };
        if read_only {
            self.chat_widget.add_error_message(format!(
                "Preset {slot} is defined outside your user config. Edit its source configuration instead."
            ));
            self.restore_quick_dial_editor(slot, &dial);
            return;
        }
        let segments = vec!["tui".into(), "presets".into(), key.clone()];
        let edit = match &dial {
            Some(candidate) => {
                if let Err(reason) = candidate.validate() {
                    self.chat_widget.add_error_message(reason.into());
                    self.restore_quick_dial_editor(slot, &dial);
                    return;
                }
                let mut table = toml_edit::Table::new();
                table["input"] = toml_edit::value(&candidate.input);
                // An explicit empty label masks labels inherited from lower layers.
                table["label"] = toml_edit::value(candidate.label.as_deref().unwrap_or_default());
                ConfigEdit::SetPath {
                    segments,
                    value: toml_edit::Item::Table(table),
                }
            }
            None => ConfigEdit::ClearPath { segments },
        };
        if let Err(error) =
            ConfigEditsBuilder::for_config_path(self.local_settings.user_config_path.as_path())
                .with_edits([edit])
                .apply()
                .await
        {
            self.chat_widget.add_error_message(format!(
                "Failed to update preset {slot}: {}",
                format_config_error(&error)
            ));
            self.restore_quick_dial_editor(slot, &dial);
            return;
        }
        let message = match dial {
            Some(mut dial) => {
                dial.label.get_or_insert_default();
                self.local_settings.tui.quick_dials.insert(key, dial);
                format!("Saved preset {slot}.")
            }
            None => {
                self.local_settings.tui.quick_dials.remove(&key);
                format!("Deleted preset {slot}.")
            }
        };
        self.chat_widget.local_settings.tui.quick_dials =
            self.local_settings.tui.quick_dials.clone();
        self.chat_widget.add_info_message(message, /*hint*/ None);
    }

fn forget_realtime_replay_thread(&mut self, thread_id: ThreadId) {
        self.realtime_replay_order
            .retain(|saved| *saved != thread_id);
        self.pending_realtime_transcript_replay.remove(&thread_id);
        self.pending_realtime_speech_replay.remove(&thread_id);
    }

fn retain_realtime_replay_state_before_replace(&mut self) {
        if let Some(thread_id) = self.chat_widget.thread_id() {
            if self.chat_widget.may_receive_realtime_transcripts() {
                self.note_realtime_replay_thread(thread_id);
                // Even a session without captions can receive a final queued caption
                // after this widget has been replaced.
                self.pending_realtime_transcript_replay
                    .entry(thread_id)
                    .or_default();
            }
            let cells = self.chat_widget.take_realtime_transcript_cells_for_replay();
            if !cells.is_empty() {
                self.note_realtime_replay_thread(thread_id);
                let pending = self
                    .pending_realtime_transcript_replay
                    .entry(thread_id)
                    .or_default();
                // Only the active widget produces these cells; reattachment consumes them
                // before another widget for this thread can become active.
                // Up to 32 accepted cells plus one partial for each speaker.
                debug_assert!(pending.len() + cells.len() <= 34);
                pending.extend(cells);
            }
        }
        for (thread_id, turn_id, item) in self
            .chat_widget
            .take_undelivered_realtime_speech_for_replay()
        {
            self.note_realtime_replay_thread(thread_id);
            let pending = self
                .pending_realtime_speech_replay
                .entry(thread_id)
                .or_default();
            // The active widget is the only producer for a thread; selecting
            // that thread reconciles these records before it can produce more.
            debug_assert!(pending.len() < 16);
            pending.push((turn_id, item));
        }
    }

fn persist_realtime_input_channel(
        &mut self,
        channel: Option<MicrophoneChannels>,
    ) {
        self.persist_realtime_audio(
            "microphone_channel",
            channel.map(|channel| match channel {
                MicrophoneChannels::Single(channel) => i64::from(channel.get()).into(),
                MicrophoneChannels::Multiple(channels) => toml::Value::Array(
                    channels
                        .into_iter()
                        .map(|channel| i64::from(channel.get()).into())
                        .collect(),
                ),
            }),
        )
        .await;
    }

fn persist_realtime_device(
        &mut self,
        kind: AudioDeviceKind,
        name: Option<String>,
    ) {
        let key = match kind {
            AudioDeviceKind::Input => "microphone",
            AudioDeviceKind::Output => "speaker",
        };
        self.persist_realtime_audio(key, name.map(Into::into)).await;
        self.list_realtime_devices(kind);
    }

