fn request_scrollback_history_top_up(&self, rendered_rows: usize) {
        if self.scrollback_history_needs_top_up(rendered_rows)
            && let Some(thread_id) = self.chat_widget.thread_id()
        {
            tracing::debug!(
                %thread_id,
                rendered_rows,
                max_rows = self.resize_reflow_max_rows(),
                "refilling underfilled terminal scrollback from paginated history"
            );
            self.app_event_tx
                .send(crate::app_event::AppEvent::RequestOlderScrollbackHistory { thread_id });
        }
    }

fn begin_initial_history_replay_buffer(&mut self) {
        if self.overlay.is_none() {
            self.initial_history_replay_buffer = Some(Default::default());
        }
    }

fn begin_thread_switch_history_replay_buffer(&mut self) {
        if self.resize_reflow_max_rows().is_some() && self.overlay.is_none() {
            self.initial_history_replay_buffer = Some(InitialHistoryReplayBuffer {
                retained_lines: VecDeque::new(),
                render_from_transcript_tail: true,
                was_truncated: false,
            });
        }
    }

fn finish_initial_history_replay_buffer(&mut self, tui: &mut tui::Tui) {
        let Some(buffer) = self.initial_history_replay_buffer.take() else {
            return;
        };
        if tui.is_owned_screen() {
            self.discard_scrollback_render_work(tui);
            tui.frame_requester().schedule_frame();
            return;
        }

        if buffer.render_from_transcript_tail || self.overlay.is_some() {
            // Reflow clears any pre-replay or partially emitted history and applies the reserved
            // history width. It also waits for an active overlay to close before rebuilding.
            self.schedule_immediate_resize_reflow(tui);
            return;
        }

        if buffer.retained_lines.is_empty() {
            self.request_scrollback_history_top_up(/*rendered_rows*/ 0);
            return;
        }

        let mut retained_lines = buffer.retained_lines.into_iter().collect::<Vec<_>>();
        let width = self
            .chat_widget
            .history_wrap_width(tui.terminal.last_known_screen_size.width);
        self.prepend_scrollback_history_notice(&mut retained_lines, buffer.was_truncated, width);
        let retained_rows = retained_lines.len();
        tui.insert_history_hyperlink_lines_with_wrap_policy(
            retained_lines,
            self.history_line_wrap_policy(),
        );
        if self.pending_thread_usage_history_refresh
            && let Err(err) = self.refresh_thread_usage_history_tail(tui)
        {
            tracing::warn!(error = %err, "failed to refresh thread usage after initial replay");
        }
        self.request_scrollback_history_top_up(retained_rows);
    }

fn retry_safety_buffered_turn(
        &mut self,
        tui: &mut tui::Tui,
        app_server: &mut AppServerSession,
        retry: SafetyBufferedRetry,
    ) {
        let SafetyBufferedRetry {
            thread_id,
            turn_id,
            model,
            mut turn,
            prompt,
        } = retry;
        if self.active_thread_id != Some(thread_id)
            || self.chat_widget.thread_id() != Some(thread_id)
            || self.primary_thread_id != Some(thread_id)
        {
            return;
        }
        if !self.chat_widget.can_retry_safety_buffered_turn(&turn_id) {
            return;
        }

        let retry_config = self.chat_widget.config_ref().clone();
        let input_state = self.chat_widget.capture_thread_input_state();
        if self.pending_server_profiles.contains_key(&thread_id) {
            self.fail_safety_buffered_branch(
                input_state,
                prompt,
                color_eyre::eyre::eyre!("Wait for permissions to update before forking."),
            );
            return;
        }

        let AppCommand::UserTurn {
            items,
            cwd,
            active_permission_profile,
            approval_policy,
            approvals_reviewer,
            model: turn_model,
            effort,
            collaboration_mode,
            ..
        } = &mut turn
        else {
            self.chat_widget.add_error_message(
                "Failed to retry with a faster model: original turn is unavailable.".to_string(),
            );
            return;
        };
        let permissions_override = Self::turn_permissions_override_from_config(
            &retry_config,
            active_permission_profile.as_ref(),
            self.runtime_permission_profile_override
                .as_ref()
                .and_then(RuntimePermissionProfileOverride::turn_permission_profile),
        );
        if let Err(err) = turn_permissions_overrides(permissions_override, cwd.as_path()) {
            self.chat_widget
                .add_error_message(format!("Failed to retry with a faster model: {err}"));
            return;
        }
        let daybreak_enabled = self.chat_widget.daybreak_enabled
            && !self.chat_widget.side_conversation_active()
            && !self.side_threads.contains_key(&thread_id);
        let eligible_account = self.chat_widget.daybreak_account_eligible();
        if let Err(message) = crate::daybreak::program_for_turn(
            &self.chat_widget.model_catalog().models,
            &model,
            eligible_account,
            daybreak_enabled,
        ) {
            self.chat_widget.add_error_message(message);
            return;
        }
        *turn_model = model.clone();
        *effort = Some(ReasoningEffortConfig::Low);
        *collaboration_mode = collaboration_mode.as_ref().map(|mode| {
            mode.with_updates(
                Some(model),
                Some(Some(ReasoningEffortConfig::Low)),
                /*developer_instructions*/ None,
            )
        });

        if let Err(err) = app_server.turn_interrupt(thread_id, turn_id.clone()).await {
            self.chat_widget
                .add_error_message(format!("Failed to retry with a faster model: {err}"));
            return;
        }

        let thread = match async {
            let mut thread = app_server
                .thread_read(thread_id, /*include_turns*/ false)
                .await?;
            if thread.history_mode == ThreadHistoryMode::Legacy {
                app_server
                    .hydrate_initial_thread_history(
                        &mut thread,
                        /*turn_cursor*/ None,
                        /*item_cursor*/ None,
                        /*config*/ None,
                        /*local_settings*/ None,
                        crate::app_server_session::HistoryHydrationScope::Initial,
                    )
                    .await?;
            } else {
                let page = app_server
                    .thread_turns_page(thread_id, /*cursor*/ None, INITIAL_HISTORY_TURN_LIMIT)
                    .await?;
                thread.turns = page.data.into_iter().rev().collect();
                if let Some(turn_index) = thread.turns.iter().position(|turn| turn.id == turn_id) {
                    let page = app_server
                        .thread_items_page(
                            thread_id,
                            Some(&turn_id),
                            /*cursor*/ None,
                            HISTORY_ITEM_PAGE_LIMIT,
                        )
                        .await?;
                    if page.next_cursor.is_some() {
                        color_eyre::eyre::bail!(
                            "Cannot safely retry a turn whose input exceeds the bounded history page."
                        );
                    }
                    let turn = &mut thread.turns[turn_index];
                    turn.items = page
                        .data
                        .into_iter()
                        .rev()
                        .map(|entry| entry.item)
                        .collect();
                    turn.items_view = TurnItemsView::Full;
                }
            }
            Ok::<_, color_eyre::Report>(thread)
        }
        .await
        {
            Ok(thread) => thread,
            Err(err) => {
                self.fail_safety_buffered_branch(input_state, prompt, err);
                return;
            }
        };
        if let Err(err) = safety_retry_fork_point(&thread.turns, &turn_id) {
            self.fail_safety_buffered_branch(input_state, prompt, err);
            return;
        }
        items.extend(
            thread
                .turns
                .iter()
                .find(|turn| turn.id == turn_id)
                .into_iter()
                .flat_map(|turn| &turn.items)
                .filter_map(|item| match item {
                    ThreadItem::UserMessage { content, .. } => Some(content),
                    _ => None,
                })
                .skip(/*n*/ 1)
                .flat_map(|content| {
                    std::iter::once(UserInput::Text {
                        text: "\n".to_string(),
                        text_elements: Vec::new(),
                    })
                    .chain(content.iter().cloned())
                }),
        );
        let retry_display = ChatWidget::user_message_display_from_inputs(items);

        self.config = retry_config.clone();
        let selected_profile = self.selected_server_profile(thread_id);
        let started = app_server
            .fork_thread_at(
                &self.local_settings,
                retry_config,
                thread_id,
                /*last_turn_id*/ None,
                /*before_turn_id*/ Some(turn_id),
                ForkGoalContinuation::DeferUntilNextTurn,
                selected_profile.as_ref(),
            )
            .await;
        let started = match started {
            Ok(started) => started,
            Err(err) => {
                self.fail_safety_buffered_branch(input_state, prompt, err);
                return;
            }
        };
        let retry_thread_id = started.session.thread_id;
        *approval_policy = started.session.approval_policy;
        *approvals_reviewer = Some(started.session.approvals_reviewer);
        *active_permission_profile = started.session.active_permission_profile.clone();

        self.detach_current_thread_for_navigation(app_server, Some(retry_thread_id))
            .await;
        if let Err(err) = self
            .replace_chat_widget_with_app_server_thread(
                tui,
                started,
                ThreadAttachPresentation::SessionLineage,
                /*initial_user_message*/ None,
            )
            .await
        {
            self.fail_safety_buffered_branch(input_state, prompt, err);
            return;
        }

        if selected_profile.is_some() {
            self.adopt_inherited_server_selection();
        }
        let failure_input_state = input_state.clone();
        self.chat_widget.restore_thread_input_state(
            input_state,
            ThreadInputStateRestoreMode {
                preserve_in_flight_turn: false,
            },
        );
        self.chat_widget
            .prepare_safety_buffered_retry_submission(prompt.clone());
        if let Err(err) = self
            .submit_thread_op(app_server, retry_thread_id, turn)
            .await
        {
            self.fail_safety_buffered_branch(failure_input_state, prompt, err);
            return;
        }
        self.chat_widget
            .commit_safety_buffered_retry_submission(retry_display);
    }

