fn handle_model_migration_prompt_if_needed(
    tui: &mut tui::Tui,
    config: &mut Config,
    local_settings: &crate::local_settings::LocalSettings,
    launch_choices: &mut crate::app_server_session::StartupLaunchChoices,
    model: &str,
    app_event_tx: &AppEventSender,
    available_models: &[ModelPreset],
) -> std::io::Result<Option<AppExitInfo>> {
    let upgrade = model_upgrade_for_migration(&config.model_provider_id, model, available_models);

    if let Some(ModelUpgrade {
        id: target_model,
        migration_config_key,
        model_link,
        upgrade_copy,
        migration_markdown,
        ..
    }) = upgrade.as_ref()
    {
        if migration_prompt_hidden(local_settings, migration_config_key.as_str()) {
            return Ok(None);
        }

        let target_model = target_model.to_string();
        if !should_show_model_migration_prompt(
            &config.model_provider_id,
            model,
            &target_model,
            &local_settings.notices.model_migrations,
            available_models,
        ) {
            return Ok(None);
        }

        let current_preset = available_models.iter().find(|preset| preset.model == model);
        let Some(target_preset) = target_preset_for_upgrade(available_models, &target_model) else {
            return Ok(None);
        };
        let target_display_name = target_preset.display_name.clone();
        let heading_label = if target_display_name == model {
            target_model.clone()
        } else {
            target_display_name.clone()
        };
        let target_description =
            (!target_preset.description.is_empty()).then(|| target_preset.description.clone());
        let can_opt_out = current_preset.is_some();
        let prompt_copy = migration_copy_for_models(
            model,
            &target_model,
            model_link.clone(),
            upgrade_copy.clone(),
            migration_markdown.clone(),
            heading_label,
            target_description,
            can_opt_out,
        );
        match run_model_migration_prompt(tui, prompt_copy).await? {
            ModelMigrationOutcome::Accepted => {
                apply_accepted_model_migration(
                    config,
                    launch_choices,
                    app_event_tx,
                    model.to_string(),
                    target_model.clone(),
                    target_preset.default_reasoning_effort.clone(),
                );
            }
            ModelMigrationOutcome::Rejected => {
                app_event_tx.send(AppEvent::PersistModelMigrationPromptAcknowledged {
                    from_model: model.to_string(),
                    to_model: target_model.clone(),
                });
            }
            ModelMigrationOutcome::Exit => {
                return Ok(Some(AppExitInfo {
                    token_usage: TokenUsage::default(),
                    thread_id: None,
                    resume_hint: None,
                    disconnect_info: None,
                    update_action: None,
                    exit_reason: ExitReason::UserRequested,
                }));
            }
        }
    }

    Ok(None)
}

