fn render_skill_load_warning_cells(errors: &[SkillErrorInfo]) -> String {
        let (tx, mut rx) = unbounded_channel();
        let app_event_tx = AppEventSender::new(tx);

        for message in skill_load_warning_messages(errors) {
            app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
                history_cell::new_warning_event(message),
            )));
        }

        let mut rendered = Vec::new();
        while let Ok(AppEvent::InsertHistoryCell(cell)) = rx.try_recv() {
            rendered.extend(
                cell.transcript_lines(/*width*/ 120)
                    .iter()
                    .map(render_line_text),
            );
        }
        rendered.join("\n")
    }

fn emit_system_bwrap_warning(app_event_tx: &AppEventSender, config: &Config) {
    let Some(message) = codex_sandboxing::system_bwrap_warning(
        &config.permissions.effective_permission_profile(),
        &config.cwd,
    ) else {
        return;
    };

    app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
        history_cell::StartupWarningsCell::new(vec![message]),
    )));
}

fn apply_accepted_model_migration(
    config: &mut Config,
    launch_choices: &mut crate::app_server_session::StartupLaunchChoices,
    app_event_tx: &AppEventSender,
    from_model: String,
    target_model: String,
    target_default_effort: ReasoningEffortConfig,
) {
    app_event_tx.send(AppEvent::PersistModelMigrationPromptAcknowledged {
        from_model,
        to_model: target_model.clone(),
    });

    launch_choices.model = Some(target_model.clone());
    launch_choices.effort = Some(serde_json::json!(target_default_effort));
    config.model = Some(target_model.clone());
    config.model_reasoning_effort = Some(target_default_effort.clone());
    app_event_tx.send(AppEvent::UpdateModel(target_model.clone()));
    app_event_tx.send(AppEvent::UpdateReasoningEffort(Some(
        target_default_effort.clone(),
    )));
    app_event_tx.send(AppEvent::PersistModelSelection {
        model: target_model,
        effort: Some(target_default_effort),
    });
}

