        ThreadEventSnapshot {
            delegated_turns: Vec::new(),
            session: Some(test_thread_session(thread_id, test_path_buf("/tmp/main"))),
            turns: Vec::new(),
            events: vec![
                ThreadBufferedEvent::Notification(Box::new(ServerNotification::Warning(
                    WarningNotification {
