fn selecting_cyber_model_defaults_active_thread_to_auto_review() {
    Box::pin(async {
        let mut app = make_test_app().await;
        app.config
            .permissions
            .approval_policy
            .set(AskForApproval::UnlessTrusted.to_core())
            .expect("set approval policy");
