    );
    insta::assert_snapshot!(
        crate::chatwidget::tests::helpers::render_bottom_popup(&app.chat_widget, /*width*/ 80)
            .lines().next().unwrap(), @"› Keep this unsent draft");
    // Seed persisted history without sending the user's draft. Subsequent navigation
    // must exercise thread/resume, including its restoration of permission settings.
    for id in [first, other] {
        server.thread_inject_items(id, vec![serde_json::from_value(serde_json::json!({
            "type": "message", "role": "assistant", "content": [{"type": "output_text", "text": "saved history"}]
        }))?]).await?;
        app.agents_overview.blank_sessions.remove(&id);
    }
    for profile_id in [":read-only", ":workspace"] {
        app.select_agents_overview_thread(&mut tui, &mut server, first)
            .await?;
        assert_eq!(app.chat_widget.thread_id(), Some(first));
        assert_eq!(
            app.chat_widget.composer_text_with_pending(),
            "Keep this unsent draft"
        );
        app.select_permission_profile(
            &mut server,
            PermissionProfileSelection {
                profile_id: profile_id.into(),
                approval_policy: Some(AskForApproval::OnRequest),
                approvals_reviewer: Some(ApprovalsReviewer::User),
                display_label: profile_id.into(),
            },
        )
        .await;
        while let Ok(event) = events.try_recv() {
            if matches!(event, AppEvent::CodexOp(_)) {
                Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
            }
        }
        confirm_permission_selection(&mut app, &mut server, first).await?;
        // Test both immediate creation and creation after A -> B -> A.
        for switch in [false, true] {
            if switch {
                for target in [other, first] {
                    app.select_agents_overview_thread(&mut tui, &mut server, target)
                        .await?;
                    assert_eq!(app.chat_widget.thread_id(), Some(target));
                }
            }
            app.new_agents_overview_session(&mut tui, &mut server, /*cwd*/ None)
                .await?;
            let starts = recorded_params(&requests, "thread/start");
            let params = starts.last().unwrap();
            assert_eq!(
                (&params["permissions"], &params["approvalsReviewer"]),
                (&serde_json::json!(profile_id), &serde_json::json!("user"))
            );
            assert_eq!(
                (
                    app.chat_widget
                        .config_ref()
                        .permissions
                        .active_permission_profile(),
                    app.chat_widget.config_ref().approvals_reviewer
                ),
                (
                    Some(ActivePermissionProfile::new(profile_id)),
                    ApprovalsReviewer::User
                ),
            );
        }
    }
    app.select_agents_overview_thread(&mut tui, &mut server, first)
        .await?;
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Keep this unsent draft"
    );
    assert!(recorded_params(&requests, "turn/start").is_empty());
    app.select_agents_overview_thread(&mut tui, &mut server, startup)
        .await?;
    app.chat_widget.insert_str("Background draft");
    app.select_agents_overview_thread(&mut tui, &mut server, first)
        .await?;
    assert!(
        server
            .thread_settings_update(codex_app_server_protocol::ThreadSettingsUpdateParams {
                thread_id: startup.to_string(),
                approval_policy: Some(AskForApproval::OnRequest),
                approvals_reviewer: Some(codex_app_server_protocol::ApprovalsReviewer::User),
                permissions: Some(":read-only".into()),
                model: Some("gpt-5.5".into()),
                ..Default::default()
            })
            .await?
    );
    let settings = next_thread_settings_updated(&mut server, startup).await;
    app.handle_app_server_event(
        &server,
        codex_app_server_client::AppServerEvent::ServerNotification(Box::new(
            ServerNotification::ThreadSettingsUpdated(settings),
        )),
    )
    .await;
    app.select_agents_overview_thread(&mut tui, &mut server, startup)
        .await?;
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        "Background draft"
    );
    assert_eq!(app.chat_widget.current_model(), "gpt-5.5");
    let op = app
        .chat_widget
        .submit_user_message_as_plain_user_turn(crate::chatwidget::UserMessage::from("Hello"))
        .expect("submit the first turn");
    app.submit_thread_op(&mut server, startup, op).await?;
    let turns = recorded_params(&requests, "turn/start");
    let params = turns.last().expect("turn/start was sent");
    assert_eq!(
        (
            &params["permissions"],
            &params["approvalPolicy"],
            &params["model"]
        ),
        (
            &serde_json::Value::Null,
            &serde_json::json!("on-request"),
            &serde_json::json!("gpt-5.5")
        )
    );
    server.shutdown().await?;
    proxy.await??;
    Ok(())
}

fn command_center_new_checkout_and_worktree_preserve_source_and_default_branch() -> Result<()>
{
    use codex_worktree::CreateWorktree;
    use codex_worktree::WorktreeManager;
    use codex_worktree::WorktreeSettings;
    for (remote_only, stale_local) in [(false, false), (true, false), (false, true)] {
        let directory = tempdir()?;
        let source = directory.path().join("project");
        std::fs::create_dir_all(source.join("subdir"))?;
        let git = |args: &[&str]| {
            let output = std::process::Command::new("git")
                .args(["-c", "commit.gpgSign=false"])
                .args(args)
                .current_dir(&source)
                .env("GIT_AUTHOR_NAME", "Test")
                .env("GIT_AUTHOR_EMAIL", "test@example.com")
                .env("GIT_COMMITTER_NAME", "Test")
                .env("GIT_COMMITTER_EMAIL", "test@example.com")
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-b", "main"]);
        std::fs::write(source.join("subdir/file"), "default branch")?;
        git(&["add", "."]);
        git(&["commit", "-m", "default"]);
        if remote_only {
            git(&["update-ref", "refs/remotes/origin/release/default", "HEAD"]);
            git(&[
                "symbolic-ref",
                "refs/remotes/origin/HEAD",
                "refs/remotes/origin/release/default",
            ]);
        }
        git(&["checkout", "-b", "feature"]);
        std::fs::write(source.join("subdir/file"), "feature commit")?;
        git(&["commit", "-am", "feature"]);
        if remote_only {
            git(&["branch", "-D", "main"]);
        }
        if stale_local {
            git(&["update-ref", "refs/remotes/origin/main", "main"]);
            git(&[
                "symbolic-ref",
                "refs/remotes/origin/HEAD",
                "refs/remotes/origin/main",
            ]);
            git(&["branch", "-f", "main", "feature"]);
        }
        let home = directory.path().join("home");
        std::fs::create_dir(&home)?;
        std::fs::write(
            home.join("config.toml"),
            format!(
                "approvals_reviewer = \"auto_review\"\nsandbox_mode = \"workspace-write\"\napproval_policy = \"on-request\"\nwindows.sandbox = \"unelevated\"\n[projects.{:?}]\ntrust_level = \"trusted\"\n",
                codex_config::loader::project_trust_key(&source),
            ),
        )?;
        let manager =
            WorktreeManager::new(WorktreeSettings::for_cli(&home, /*desktop*/ None).unwrap());
        let selected = manager
            .create(&CreateWorktree {
                source_cwd: source.join("subdir"),
                base: Some("feature".into()),
            })
            .unwrap();
        manager
            .bind_thread(&selected.root, "existing-owner")
            .unwrap();
        std::fs::write(selected.cwd.join("file"), "dirty edit")?;
        std::fs::write(selected.cwd.join("untracked"), "untracked")?;
        for receiver_closed in [true, false] {
            let unclaimed = manager
                .create(&CreateWorktree {
                    source_cwd: source.join("subdir"),
                    base: Some("feature".into()),
                })
                .unwrap();
            let root = unclaimed.root.clone();
            let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
            let receiver = (!receiver_closed).then_some(rx);
            AppEventSender::new(tx).send(AppEvent::AgentsOverviewWorktreeCreated(Ok(
                PendingWorktree {
                    manager: manager.clone(),
                    checkout: Some(unclaimed),
                },
            )));
            drop(receiver);
            assert!(!root.exists());
            assert_eq!(manager.list(&source).unwrap().len(), 1);
        }
        let (mut app, mut events, _) = make_test_app_with_channels().await;
        app.config.codex_home = home.clone().abs();
        app.config.cwd = selected.cwd.clone().abs();
        app.chat_widget.windows_sandbox_local_server = cfg!(target_os = "windows");
        app.harness_overrides.cwd = Some(selected.cwd.clone());
        trust_launch_folder(&mut app);
        let (mut server, requests, proxy) = start_recording_app_server_with_history(
            &app.config,
            HistoryCapabilities::Current,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
            crate::app_server_session::ThreadParamsMode::Embedded,
            LoaderOverrides::default(),
        )
        .await?;
        let mut tui = make_test_tui()?;
        tui.pause_events();
        let new_session = app.new_agents_overview_session(
            &mut tui,
            &mut server,
            Some(selected.cwd.clone().abs()),
        );
        let size = std::mem::size_of_val(&new_session);
        assert!(
            size < 64 * 1024,
            "new-session wrapper future is {size} bytes"
        );
        new_session.await?;
        let first = app.chat_widget.thread_id().expect("new checkout session");
        assert!(!crate::session_resume::cwds_differ(
            app.chat_widget.config_ref().cwd.as_path(),
            &selected.cwd
        ));
        assert_eq!(
            manager.owner(&selected.root).unwrap(),
            Some("existing-owner".into())
        );
        // Exercise the menu's ordered events, not the separate profile-selection API.
        app.chat_widget
            .set_feature_enabled(Feature::GuardianApproval, /*enabled*/ true);
        Box::pin(app.handle_event(&mut tui, &mut server, AppEvent::OpenPermissionsPopup)).await?;
        tokio::time::timeout(Duration::from_secs(3), async {
            while let Some(event) = events.recv().await {
                let loaded = matches!(&event, AppEvent::PermissionProfilesLoaded { .. });
                Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
                if loaded {
                    return Ok::<_, color_eyre::Report>(());
                }
            }
            color_eyre::eyre::bail!("permissions menu event stream closed")
        })
        .await??;
        app.chat_widget.handle_key_event(KeyCode::Up.into());
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        while let Ok(event) = events.try_recv() {
            Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
        }
        confirm_permission_selection(&mut app, &mut server, first).await?;
        assert_eq!(
            app.chat_widget.config_ref().approvals_reviewer,
            ApprovalsReviewer::User
        );
        app.new_agents_overview_worktree(&mut tui, &mut server, Some(selected.cwd.clone().abs()))
            .await;
        assert!(app.pending_managed_worktree_creation);
        let result = tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                if let Some(AppEvent::AgentsOverviewWorktreeCreated(result)) = events.recv().await {
                    break result;
                }
            }
        })
        .await?
        .map_err(|message| color_eyre::eyre::eyre!(message))?;
        let checkout = result.checkout.as_ref().unwrap().clone();
        assert_eq!(
            std::fs::read_to_string(checkout.cwd.join("file"))?,
            "default branch"
        );
        assert!(!checkout.cwd.join("untracked").exists());
        assert_eq!(checkout.cwd, checkout.root.join("subdir"));
        Box::pin(app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::AgentsOverviewWorktreeCreated(Ok(result)),
        ))
        .await?;
        let second = app.chat_widget.thread_id().expect("new worktree session");
        assert_ne!(first, second);
        assert_eq!(
            recorded_params(&requests, "thread/start").last().unwrap()["approvalsReviewer"],
            serde_json::json!("user")
        );
        assert_eq!(
            app.chat_widget.config_ref().approvals_reviewer,
            ApprovalsReviewer::User
        );
        assert_eq!(
            manager.owner(&checkout.root).unwrap(),
            Some(second.to_string())
        );
        assert_eq!(recorded_params(&requests, "turn/start").len(), 0);
        assert_eq!(
            std::fs::read_to_string(selected.cwd.join("file"))?,
            "dirty edit"
        );
        server.shutdown().await?;
        proxy.await??;
        if !remote_only && !stale_local {
            let unused = manager
                .create(&CreateWorktree {
                    source_cwd: source.join("subdir"),
                    base: Some("main".into()),
                })
                .unwrap();
            let (mut failed_server, _, failed_proxy) = start_recording_app_server_with_history(
                &app.config,
                HistoryCapabilities::ThreadStartFails,
                /*blocked_thread_list*/ None,
                /*failed_thread_name*/ None,
                crate::app_server_session::ThreadParamsMode::Embedded,
                LoaderOverrides::default(),
            )
            .await?;
            let view = app.agents_overview_view(Vec::new(), /*selected_thread_id*/ None);
            app.chat_widget.show_bottom_pane_view(Box::new(view));
            app.start_agents_overview_session(
                &mut tui,
                &mut failed_server,
                Some(unused.cwd.clone().abs()),
                Some((manager.clone(), unused.clone())),
                /*startup_draft*/ None,
            )
            .await?;
            assert_eq!(app.chat_widget.thread_id(), Some(second));
            assert_eq!(manager.owner(&unused.root).unwrap(), None);
            assert!(unused.root.exists());
            let rendered = crate::chatwidget::tests::helpers::render_bottom_popup(
                &app.chat_widget,
                /*width*/ 500,
            );
            insta::assert_snapshot!(
                "command_center_retained_worktree_error",
                rendered.replace(&unused.root.display().to_string(), "<worktree>")
            );
            failed_server.shutdown().await?;
            failed_proxy.await??;
        }
    }
    Ok(())
}

fn browsing_loads_before_the_oldest_prompt_after_a_partial_answer() -> Result<()> {
    for cancel_before_completion in [false, true] {
        let (mut app, _codex_home, thread_id) =
            completed_history_app(&["Oldest", "Middle", "Newest"]).await?;
        let (mut app_server, _requests, proxy) = start_recording_app_server(
            &app.config,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
        )
        .await?;
        let started = app_server
            .resume_thread(
                &app.local_settings,
                app.config.clone(),
                thread_id,
                crate::app_server_session::ResumeModelSettings::RestoreFromThread,
            )
            .await?;
        // A transport page may begin inside the preceding answer, well before its first prompt.
        app.transcript_cells = (0..30)
            .map(|index| {
                Arc::new(PlainHistoryCell::new(vec![
                    format!("Earlier answer fragment {index}").into(),
                ])) as Arc<dyn HistoryCell>
            })
            .collect();
        app.transcript_cells
            .extend(crate::thread_transcript::thread_items_to_transcript_cells(
                Some(thread_id),
                &app.config.cwd,
                started.turns.iter().flat_map(|turn| turn.items.clone()),
                crate::thread_transcript::RawReasoningVisibility::Hidden,
                Some(&app.config),
            ));
        app.enqueue_primary_thread_session(started.session, started.turns)
            .await?;
        app.scrollback_has_older_history = app_server.has_older_history(thread_id);
        let (event_tx, mut event_rx) = tokio::sync::mpsc::unbounded_channel();
        app.app_event_tx = crate::app_event_sender::AppEventSender::new(event_tx);
        app.transcript_view.history = TranscriptHistoryState::Partial;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        tui.set_owned_screen(/*owned*/ true)?;
        let size = tui.terminal.size()?;
        app.render_owned_transcript(&mut tui, size)?;
        for _ in 0..2 {
            app.handle_tui_event(
                &mut tui,
                &mut app_server,
                TuiEvent::Key(KeyCode::Esc.into()),
            )
            .await?;
        }
        assert_eq!(
            (
                app.backtrack.overlay_preview_active,
                app.backtrack.nth_user_message
            ),
            (true, 0)
        );
        assert!(!app.transcript_view.needs_history(&app.transcript_cells));
        app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Draw)
            .await?;
        assert_eq!(
            app.transcript_view.history,
            TranscriptHistoryState::LoadingOlder
        );
        let first_event = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), event_rx.recv())
            .await?
            .expect("older history completion");
        let AppEvent::OlderThreadHistoryLoaded { cursor, .. } = first_event else {
            panic!("expected an older history completion")
        };
        // Repeated navigation while loading must keep a single request in flight.
        for code in [KeyCode::Left, KeyCode::Char('h')] {
            app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Key(code.into()))
                .await?;
        }
        assert!(app_server.is_older_history_page_pending(thread_id, &cursor));
        assert!(event_rx.try_recv().is_err());
        // Complete only an answer item first: browsing must continue to a page with a prompt.
        let first_page = app_server
            .thread_items_page(
                thread_id,
                /*turn_id*/ None,
                Some(cursor.clone()),
                /*limit*/ 1,
            )
            .await?;
        let next_cursor = first_page.next_cursor.clone().expect("older prompt page");
        if cancel_before_completion {
            app.handle_tui_event(
                &mut tui,
                &mut app_server,
                TuiEvent::Key(KeyCode::Esc.into()),
            )
            .await?;
        }
        app.handle_older_history_page(
            &mut tui,
            &mut app_server,
            thread_id,
            &cursor,
            Ok(first_page),
        )
        .await?;
        assert_eq!(
            app_server.is_older_history_page_pending(thread_id, &next_cursor),
            !cancel_before_completion
        );
        if cancel_before_completion {
            assert_eq!(
                (
                    app.backtrack.overlay_preview_active,
                    app.transcript_view.is_following()
                ),
                (false, true)
            );
        } else {
            let final_event =
                tokio::time::timeout(Duration::from_secs(/*secs*/ 5), event_rx.recv())
                    .await?
                    .expect("older prompt completion");
            Box::pin(app.handle_event(&mut tui, &mut app_server, final_event)).await?;
            assert_eq!(
                (app.backtrack.nth_user_message, app.transcript_view.history),
                (2, TranscriptHistoryState::Complete)
            );
            for (code, selected) in [(KeyCode::Left, 1), (KeyCode::Char('h'), 0)] {
                app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Key(code.into()))
                    .await?;
                assert_eq!(app.backtrack.nth_user_message, selected);
            }
            app.render_owned_transcript(&mut tui, size)?;
            let buffer = crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal);
            let text = buffer
                .content()
                .iter()
                .map(ratatui::buffer::Cell::symbol)
                .collect::<String>();
            assert!(text.contains("Oldest prompt"), "{text}");
        }
        tui.set_owned_screen(/*owned*/ false)?;
        app_server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn refreshed_active_reasoning_accepts_later_deltas_and_complete_summary() {
    for (refresh, refreshed_item_is_partial, capacity, voice_handoff) in [
        (true, false, 1, false),
        (true, true, 1, false),
        (false, false, 8, false),
        (false, false, 1, false),
        (true, false, 1, true),
    ] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        let thread_id = ThreadId::new();
        let session = test_thread_session(thread_id, app.config.cwd.to_path_buf());
        let mut turn = test_turn("reasoning-turn", TurnStatus::InProgress, Vec::new());
        let channel =
            ThreadEventChannel::new_with_session(capacity, session.clone(), vec![turn.clone()]);
        {
            let mut store = channel.store.lock().await;
            store.push_notification(ServerNotification::ItemStarted(ItemStartedNotification {
                thread_id: thread_id.to_string(),
                turn_id: turn.id.clone(),
                item: ThreadItem::Reasoning {
                    id: "reasoning".into(),
                    summary: Vec::new(),
                    content: Vec::new(),
                },
                started_at_ms: 0,
            }));
            store.push_notification(ServerNotification::ReasoningSummaryTextDelta(
                ReasoningSummaryTextDeltaNotification {
                    thread_id: thread_id.to_string(),
                    turn_id: turn.id.clone(),
                    item_id: "reasoning".into(),
                    delta: "**First heading**\nOriginal analysis paragraph".into(),
                    summary_index: 0,
                },
            ));
            assert_eq!(store.buffer.len(), capacity.min(/*other*/ 2));
            if voice_handoff {
                store.push_notification(ServerNotification::ItemStarted(ItemStartedNotification {
                    thread_id: thread_id.to_string(),
                    turn_id: turn.id.clone(),
                    item: ThreadItem::UserMessage {
                        id: "voice-handoff".into(),
                        client_id: None,
                        content: vec![AppServerUserInput::Text {
                            text: "<realtime_delegation><input>spoken follow-up</input></realtime_delegation>".into(),
                            text_elements: Vec::new(),
                        }],
                    },
                    started_at_ms: 0,
                }));
            }
        }
        let mut snapshot = channel.store.lock().await.snapshot();
        app.thread_event_channels.insert(thread_id, channel);
        if refreshed_item_is_partial {
            turn.items.push(ThreadItem::Reasoning {
                id: "reasoning".into(),
                summary: vec!["**First heading**\nOriginal analysis paragraph".into()],
                content: Vec::new(),
            });
        }
        if refresh {
            app.apply_refreshed_snapshot_thread(
                thread_id,
                AppServerStartedThread {
                    session,
                    turns: vec![turn],
                    blocks_direct_input: false,
                    task_tools_available: false,
                },
                &mut snapshot,
            )
            .await;
            assert!(snapshot.events.is_empty());
        }
        assert!(snapshot.active_reasoning_item.is_some());
        app.replay_thread_snapshot(snapshot, /*resume_restored_queue*/ false);
        app.chat_widget.handle_server_notification(
            ServerNotification::ReasoningSummaryTextDelta(ReasoningSummaryTextDeltaNotification {
                thread_id: thread_id.to_string(),
                turn_id: "reasoning-turn".into(),
                item_id: "reasoning".into(),
                delta: "\n**Running checks**\nFinal paragraph".into(),
                summary_index: 0,
            }),
            /*replay_kind*/ None,
        );
        assert!(render_bottom_popup(&app.chat_widget, /*width*/ 80).contains("Final paragraph"));
        let completed = ServerNotification::ItemCompleted(ItemCompletedNotification {
                thread_id: thread_id.to_string(),
                turn_id: "reasoning-turn".into(),
                item: ThreadItem::Reasoning {
                    id: "reasoning".into(),
                    summary: vec![
                        "**First heading**\nOriginal analysis paragraph\n**Running checks**\nFinal paragraph"
                            .into(),
                    ],
                    content: Vec::new(),
                },
                completed_at_ms: 0,
            });
        let store = &app.thread_event_channels[&thread_id].store;
        store.lock().await.push_notification_ref(&completed);
        assert!(
            store
                .lock()
                .await
                .snapshot()
                .active_reasoning_item
                .is_none()
        );
        app.chat_widget
            .handle_server_notification(completed, /*replay_kind*/ None);
        app.chat_widget.handle_server_notification(
            ServerNotification::ReasoningSummaryTextDelta(ReasoningSummaryTextDeltaNotification {
                thread_id: thread_id.to_string(),
                turn_id: "reasoning-turn".into(),
                item_id: "reasoning".into(),
                delta: "\n**Stale heading**".into(),
                summary_index: 0,
            }),
            /*replay_kind*/ None,
        );
        assert!(!render_bottom_popup(&app.chat_widget, /*width*/ 80).contains("Stale heading"));
        let transcript = std::iter::from_fn(|| events.try_recv().ok())
            .filter_map(|event| match event {
                AppEvent::InsertHistoryCell(cell)
                    if cell
                        .as_any()
                        .is::<crate::history_cell::ReasoningSummaryCell>() =>
                {
                    Some(lines_to_single_string(&cell.transcript_lines(/*width*/ 80)))
                }
                _ => None,
            })
            .collect::<String>();
        insta::allow_duplicates! {
            insta::assert_snapshot!(transcript, @"
            • Original analysis paragraph
              Running checks
              Final paragraph
            ");
        }
    }
}

fn evicted_voice_marker_survives_widget_snapshot_for_late_reasoning() {
    let thread_id = ThreadId::new();
    let mut store = ThreadEventStore::new(/*capacity*/ 1);
    store.push_notification(ServerNotification::ItemStarted(
        codex_app_server_protocol::ItemStartedNotification {
            thread_id: thread_id.to_string(),
            turn_id: "voice-turn".into(),
            started_at_ms: 0,
            item: ThreadItem::UserMessage {
                id: "user".into(),
                client_id: None,
                content: vec![codex_app_server_protocol::UserInput::Text {
                    text: "<realtime_delegation><input>question</input></realtime_delegation>"
                        .into(),
                    text_elements: Vec::new(),
                }],
            },
        },
    ));
    store.push_notification(delta(&thread_id.to_string(), "voice-turn", "private"));
    let snapshot = store.snapshot();
    assert!(snapshot.events.is_empty());
    assert!(snapshot.turns.is_empty());
    assert_eq!(snapshot.delegated_turns, vec!["voice-turn"]);

    let mut app = make_test_app().await;
    let (widget, _sender, mut events, _ops) =
        crate::chatwidget::tests::make_chatwidget_manual_with_sender().await;
