fn only_confirmed_picker_model_changes_can_arm_the_sparkle() -> Result<()> {
    for completion in [
        "esc",
        "ctrl_c",
        "same_model",
        "automatic_while_open",
        "pick_astra",
        "old_task",
    ] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        app.local_settings.tui.animations = true;
        app.local_settings.tui.effects.starfield = true;
        app.local_settings.tui.disable_paste_burst = Some(true);
        let mut server = start_config_write_test_app_server(&app).await?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        let thread = started("gpt-5.5");
        let original_id = thread.session.thread_id;
        app.replace_chat_widget_with_app_server_thread(
            &mut tui,
            thread,
            ThreadAttachPresentation::Fresh,
            /*initial_user_message*/ None,
        )
        .await?;
        assert!(!visible(&app.chat_widget));
        type_into(&mut app.chat_widget, "/model");
        app.chat_widget.handle_key_event(KeyCode::Enter.into());
        assert!(app.chat_widget.has_active_view());

        match completion {
            "esc" | "ctrl_c" => {
                let key = if completion == "esc" {
                    KeyCode::Esc.into()
                } else {
                    KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL)
                };
                app.chat_widget.handle_key_event(key);
                assert!(!app.chat_widget.has_active_view());
                app.chat_widget.set_model("gpt-6-astra");
            }
            "same_model" => {
                assert_eq!(
                    choose_model(
                        &mut app,
                        &mut tui,
                        &mut server,
                        &mut events,
                        "gpt-5.5",
                        KeyCode::Enter,
                    )
                    .await?,
                    0
                );
                app.chat_widget.set_model("gpt-6-astra");
            }
            "automatic_while_open" => {
                app.chat_widget.set_model("gpt-6-astra");
                app.chat_widget
                    .handle_key_event(KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL));
                assert!(!app.chat_widget.has_active_view());
            }
            "pick_astra" => {
                assert_eq!(
                    choose_model(
                        &mut app,
                        &mut tui,
                        &mut server,
                        &mut events,
                        "gpt-6-astra",
                        KeyCode::Enter,
                    )
                    .await?,
                    1
                );
            }
            "old_task" => {
                app.replace_chat_widget_with_app_server_thread(
                    &mut tui,
                    started("gpt-5.5"),
                    ThreadAttachPresentation::Fresh,
                    /*initial_user_message*/ None,
                )
                .await?;
                app.chat_widget.set_model("gpt-6-astra");
                app.handle_event(
                    &mut tui,
                    &mut server,
                    AppEvent::AstraSelectedFromModelPicker {
                        thread_id: original_id,
                        model: "gpt-6-astra".into(),
                        action: AstraModelPickerAction::UpdateModel,
                    },
                )
                .await?;
            }
            _ => unreachable!(),
        }
        assert_eq!(
            visible(&app.chat_widget),
            completion == "pick_astra",
            "{completion}"
        );
    }
    Ok(())
}

fn astra_picker_confirms_the_model_at_application_after_an_automatic_update() -> Result<()> {
    let mut snapshots = Vec::new();
    for (picker, key, switches_away) in [
        ("default no-op", KeyCode::Enter, false),
        ("session no-op", KeyCode::Char('s'), false),
        ("advanced no-op", KeyCode::Enter, false),
        ("default queued no-op", KeyCode::Enter, false),
        ("session queued no-op", KeyCode::Char('s'), false),
        ("default changes model", KeyCode::Enter, true),
        ("session changes model", KeyCode::Char('s'), true),
        ("advanced changes model", KeyCode::Enter, true),
    ] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        app.config.model = Some("gpt-5.5".into());
        app.local_settings.tui.animations = true;
        app.local_settings.tui.effects.starfield = true;
        let mut server = start_config_write_test_app_server(&app).await?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        let thread = server.start_thread(&app.config).await?;
        app.replace_chat_widget_with_app_server_thread(
            &mut tui,
            thread,
            ThreadAttachPresentation::Fresh,
            /*initial_user_message*/ None,
        )
        .await?;
        if switches_away {
            app.chat_widget.set_model("gpt-6-astra");
        }
        assert!(!visible(&app.chat_widget));

        let mut preset = crate::test_support::TEST_MODEL_PRESETS[0].clone();
        preset.model = "gpt-6-astra".into();
        preset.default_reasoning_effort = if picker.starts_with("advanced") {
            ReasoningEffortConfig::Ultra
        } else {
            ReasoningEffortConfig::Medium
        };
        preset.supported_reasoning_efforts = vec![
            ReasoningEffortPreset {
                effort: preset.default_reasoning_effort.clone(),
                description: "Selected effort".into(),
            },
            ReasoningEffortPreset {
                effort: ReasoningEffortConfig::Low,
                description: "Low effort".into(),
            },
        ];
        if picker.starts_with("advanced") {
            app.chat_widget.open_advanced_reasoning_popup(preset);
        } else {
            app.chat_widget.open_reasoning_popup(preset);
        }
        assert!(app.chat_widget.has_active_view());
        if !picker.contains("queued") {
            app.chat_widget.set_model(if switches_away {
                "gpt-5.5"
            } else {
                "gpt-6-astra"
            });
            assert!(app.chat_widget.has_active_view());
        }
        app.chat_widget.handle_key_event(key.into());
        if picker.contains("queued") {
            app.chat_widget.set_model("gpt-6-astra");
        }
        while let Ok(event) = events.try_recv() {
            if matches!(
                &event,
                AppEvent::UpdateModel(_)
                    | AppEvent::UpdateReasoningEffort(_)
                    | AppEvent::SelectSessionModel { .. }
                    | AppEvent::ApplyAdvancedReasoning { .. }
                    | AppEvent::AstraSelectedFromModelPicker { .. }
            ) {
                app.handle_event(&mut tui, &mut server, event).await?;
            }
        }
        assert!(!app.chat_widget.has_active_view(), "{picker}");
        assert_eq!(app.chat_widget.current_model(), "gpt-6-astra", "{picker}");
        assert_eq!(visible(&app.chat_widget), switches_away, "{picker}");
        if picker.starts_with("default") && !picker.contains("queued") {
            let rendered = render_with_sparkle_palette(&app.chat_widget);
            let lines = rendered.lines().collect::<Vec<_>>();
            let prompt = lines
                .iter()
                .position(|line| line.contains("Ask Codex to do anything"))
                .expect("empty composer shows its placeholder");
            let composer = lines[prompt.saturating_sub(1)..=prompt + 1].join("\n");
            snapshots.push(format!("{picker}:\n{composer}"));
        }
        server.shutdown().await?;
    }
    insta::assert_snapshot!(snapshots.join("\n\n"));
    Ok(())
}

fn astra_picker_xhigh_applies_on_a_bounded_stack() -> Result<()> {
    const STACK_SIZE: usize = 4 * 1024 * 1024;
    const SERVER_STACK_SIZE: usize = 8 * 1024 * 1024;
    const WORKER_THREADS: usize = 1;

    std::thread::Builder::new()
        .name("astra-picker".into())
        .stack_size(STACK_SIZE)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(WORKER_THREADS)
                .thread_stack_size(SERVER_STACK_SIZE)
                .enable_all()
                .build()?;
            runtime.block_on(Box::pin(async {
                let (mut app, mut events, _ops) = Box::pin(make_test_app_with_channels()).await;
                app.config.model = Some("gpt-5.5".into());
                let mut server = Box::pin(start_config_write_test_app_server(&app)).await?;
                let mut tui = crate::tui::test_support::make_test_tui()?;
                let thread = server.start_thread(&app.config).await?;
                Box::pin(app.replace_chat_widget_with_app_server_thread(
                    &mut tui,
                    thread,
                    ThreadAttachPresentation::Fresh,
                    /*initial_user_message*/ None,
                ))
                .await?;

                let mut preset = crate::test_support::TEST_MODEL_PRESETS[0].clone();
                preset.model = "gpt-6-astra".into();
                preset.default_reasoning_effort = ReasoningEffortConfig::XHigh;
                preset.supported_reasoning_efforts = vec![
                    ReasoningEffortPreset {
                        effort: ReasoningEffortConfig::XHigh,
                        description: "Extra High".into(),
                    },
                    ReasoningEffortPreset {
                        effort: ReasoningEffortConfig::Low,
                        description: "Low".into(),
                    },
                ];
                app.chat_widget.open_reasoning_popup(preset);
                app.chat_widget.handle_key_event(KeyCode::Enter.into());
                let mut confirmed = false;
                while let Ok(event) = events.try_recv() {
                    confirmed |= matches!(event, AppEvent::AstraSelectedFromModelPicker { .. });
                    if matches!(
                        &event,
                        AppEvent::AstraSelectedFromModelPicker { .. }
                            | AppEvent::UpdateReasoningEffort(_)
                            | AppEvent::PersistModelSelection { .. }
                    ) {
                        Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
                    }
                }
                assert!(confirmed);
                assert_eq!(
                    (
                        app.chat_widget.current_model(),
                        app.chat_widget.current_reasoning_effort(),
                    ),
                    ("gpt-6-astra", Some(ReasoningEffortConfig::XHigh)),
                );
                server.shutdown().await?;
                Ok(())
            }))
        })?
        .join()
        .expect("Astra picker thread panicked")
}

fn history_hydration_metadata_tracks_missing_turns_and_stale_completions_keep_new_request()
-> Result<()> {
    let (mut app, _codex_home, target) =
        history_fixture(&[1, 1, 1, 1, 0, 1, 0, 0, 0, 0, 0, 0, 1]).await?;
    app.local_settings.transcript_mode = TranscriptMode::Terminal;
    app.local_settings.tui.terminal_resize_reflow_max_rows = Some(1);
    let (mut server, requests, proxy) = start_recording_app_server(
        &app.config,
        /*blocked_thread_list*/ None,
        /*failed_thread_name*/ None,
    )
    .await?;
    // Resume materializes the hand-written rollout into the server's item projection.
    // Exclude turns so the explicit hydration below remains the only history load.
    let _: ThreadResumeResponse = server
        .request_handle()
        .request_typed(ClientRequest::ThreadResume {
            request_id: server.next_request_id(),
            params: ThreadResumeParams {
                thread_id: target.thread_id.to_string(),
                exclude_turns: true,
                ..ThreadResumeParams::default()
            },
        })
        .await?;
    let mut thread = server
        .thread_read(target.thread_id, /*include_turns*/ false)
        .await?;
    server
        .hydrate_initial_thread_history(
            &mut thread,
            /*turn_cursor*/ None,
            /*item_cursor*/ None,
            Some(&app.config),
            Some(&app.local_settings),
            HistoryHydrationScope::Initial,
        )
        .await?;
    assert_eq!(
        thread
            .turns
            .iter()
            .flat_map(|turn| &turn.items)
            .map(ThreadItem::id)
            .collect::<Vec<_>>(),
        vec!["item-12-0"]
    );
    let old_cursor = server
        .begin_older_history_page(target.thread_id)
        .expect("older page");
    let page = server
        .thread_items_page(
            target.thread_id,
            /*turn_id*/ None,
            Some(old_cursor.clone()),
            /*limit*/ 2,
        )
        .await?;
    let items = server
        .apply_older_history_page(target.thread_id, &old_cursor, page, &mut thread.turns)
        .await?;
    assert_eq!(
        items.iter().map(ThreadItem::id).collect::<Vec<_>>(),
        vec!["item-3-0", "item-5-0"]
    );
    assert_eq!(
        thread
            .turns
            .iter()
            .flat_map(|turn| &turn.items)
            .map(ThreadItem::id)
            .collect::<Vec<_>>(),
        vec!["item-3-0", "item-5-0", "item-12-0"]
    );
    let metadata = recorded_params(&requests, "thread/turns/list");
    assert_eq!(
        metadata
            .iter()
            .map(|params| params["limit"].as_u64().unwrap())
            .collect::<Vec<_>>(),
        vec![5, 2, 2, 1]
    );
    assert_eq!(
        recorded_params(&requests, "thread/read")
            .into_iter()
            .map(serde_json::from_value::<ThreadReadParams>)
            .collect::<Result<Vec<_>, _>>()?,
        vec![ThreadReadParams {
            thread_id: target.thread_id.to_string(),
            include_turns: false,
        }]
    );

    let cursor = server
        .begin_older_history_page(target.thread_id)
        .expect("next page");
    assert_ne!(old_cursor, cursor);
    let mut tui = crate::tui::test_support::make_test_tui()?;
    // The response is stale even when its thread is no longer displayed. Ignore its error first.
    app.transcript_view.history = TranscriptHistoryState::LoadingOlder;
    for result in [
        Err("obsolete transport failure".to_string()),
        Ok(ThreadItemsListResponse {
            data: Vec::new(),
            next_cursor: None,
            backwards_cursor: None,
        }),
    ] {
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::OlderThreadHistoryLoaded {
                thread_id: target.thread_id,
                cursor: old_cursor.clone(),
                result,
            },
        )
        .await?;
        assert!(server.is_older_history_page_pending(target.thread_id, &cursor));
        assert_eq!(
            app.transcript_view.history,
            TranscriptHistoryState::LoadingOlder
        );
    }
    server.shutdown().await?;
    proxy.await??;
    Ok(())
}

