fn luna_reserve_entry_dispatches_an_already_queued_turn_with_accepted_settings() -> Result<()>
{
    for mode in [ModeKind::Default, ModeKind::Plan] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        let (mut server, requests, proxy) =
            backend_banner_fallback_tests::start_fallback_thread(&mut app).await?;
        configure_reserve_catalog(&mut app);
        app.chat_widget
            .set_feature_enabled(Feature::FastMode, /*enabled*/ true);
        app.chat_widget.set_service_tier(Some("fast".into()));
        if mode == ModeKind::Plan {
            app.chat_widget
                .handle_key_event(KeyEvent::from(KeyCode::BackTab));
        }
        app.chat_widget
            .restore_user_message_to_composer(UserMessage::from("continue"));
        app.chat_widget
            .handle_key_event(KeyEvent::from(KeyCode::Enter));
        let pending = std::iter::from_fn(|| events.try_recv().ok())
            .find(|event| matches!(event, AppEvent::CodexOp(AppCommand::UserTurn { .. })))
            .expect("queued turn before the usage response");
        requests.lock().unwrap().clear();
        let mut tui = crate::tui::test_support::make_test_tui()?;
        let generation = app.rate_limit_hard_stop_generation;
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::RateLimitsLoaded {
                request_id: 1,
                origin: RateLimitRefreshOrigin::Periodic,
                hard_stop_generation: generation,
                result: Ok(reserve_response()),
            },
        )
        .await?;
        app.handle_event(&mut tui, &mut server, pending).await?;
        let sent = requests.lock().unwrap().clone();
        let methods: Vec<_> = sent.iter().map(|request| request.method.as_str()).collect();
        assert_eq!(methods, ["thread/settings/update", "turn/start"]);
        let settings: ThreadSettingsUpdateParams =
            serde_json::from_value(sent[0].params.clone().unwrap())?;
        let turn: codex_app_server_protocol::TurnStartParams =
            serde_json::from_value(sent[1].params.clone().unwrap())?;
        assert_eq!(
            (
                turn.model,
                turn.effort,
                turn.service_tier,
                turn.collaboration_mode
            ),
            (
                settings.model,
                settings.effort,
                settings.service_tier,
                settings.collaboration_mode
            )
        );
        assert_eq!(app.chat_widget.effective_collaboration_mode().mode, mode);
        server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn luna_reserve_recovery_restores_task_and_pending_turn_after_fresh_backend_read()
-> Result<()> {
    for has_credits in [false, true] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        let (mut server, requests, proxy) =
            backend_banner_fallback_tests::start_fallback_thread(&mut app).await?;
        configure_reserve_catalog(&mut app);
        app.chat_widget
            .set_feature_enabled(Feature::FastMode, /*enabled*/ false);
        app.chat_widget
            .set_feature_enabled(Feature::UltrafastMode, /*enabled*/ false);
        app.chat_widget
            .set_reasoning_effort(Some(ReasoningEffortConfig::High));
        let original_mode = app.chat_widget.effective_collaboration_mode();
        let config_path = app.config.codex_home.join("config.toml");
        let saved_config = std::fs::read(&config_path).ok();
        let mut tui = crate::tui::test_support::make_test_tui()?;
        requests.lock().unwrap().clear();
        let generation = app.rate_limit_hard_stop_generation;
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::RateLimitsLoaded {
                request_id: 1,
                origin: RateLimitRefreshOrigin::Periodic,
                hard_stop_generation: generation,
                result: Ok(reserve_response()),
            },
        )
        .await?;
        assert_eq!(app.chat_widget.current_model(), "gpt-reserve");

        // A prompt composed before the next accepted read must use the recovered model, once.
        app.chat_widget
            .handle_key_event(KeyEvent::from(KeyCode::Esc));
        app.chat_widget
            .restore_user_message_to_composer(UserMessage::from("continue"));
        app.chat_widget
            .handle_key_event(KeyEvent::from(KeyCode::Enter));
        let mut pending = std::iter::from_fn(|| events.try_recv().ok())
            .find_map(|event| match event {
                AppEvent::CodexOp(op @ AppCommand::UserTurn { .. }) => Some(op),
                _ => None,
            })
            .expect("queued user turn");
        assert_matches!(&pending, AppCommand::UserTurn {model, ..} if model == "gpt-reserve");
        while events.try_recv().is_ok() {}

        let mut recovered = reserve_response();
        recovered.ordinary_usage_allowed = Some(!has_credits);
        recovered.rate_limits.credits = Some(codex_app_server_protocol::CreditsSnapshot {
            has_credits,
            unlimited: false,
            balance: None,
        });
        recovered.rate_limit_upsell = None;
        // A rounded percentage is not an authorization decision; backend allowed=true wins.
        for (request_id, hard_stop_generation, expected) in [
            (2, generation.wrapping_sub(1), "gpt-reserve"),
            (3, generation, "gpt-5.5"),
            (4, generation, "gpt-5.5"),
        ] {
            app.handle_event(
                &mut tui,
                &mut server,
                AppEvent::RateLimitsLoaded {
                    request_id,
                    origin: RateLimitRefreshOrigin::Periodic,
                    hard_stop_generation,
                    result: Ok(recovered.clone()),
                },
            )
            .await?;
            assert_eq!(app.chat_widget.current_model(), expected);
        }
        assert_eq!(
            app.chat_widget.effective_collaboration_mode(),
            original_mode
        );
        assert!(!render_bottom_popup(&app.chat_widget, /*width*/ 100).contains("Luna Reserve"));
        app.chat_widget
            .apply_reserve_fallback_to_pending_turn(&mut pending);
        assert_matches!(pending, AppCommand::UserTurn { model, effort, collaboration_mode, .. }
        if model == "gpt-5.5" && effort == original_mode.reasoning_effort()
            && collaboration_mode == Some(original_mode.clone()));
        let sent = requests.lock().unwrap().clone();
        assert_eq!(sent.len(), 2);
        let restored: ThreadSettingsUpdateParams =
            serde_json::from_value(sent[1].params.clone().unwrap())?;
        assert_eq!(
            restored,
            ThreadSettingsUpdateParams {
                thread_id: app.active_thread_id.unwrap().to_string(),
                model: Some("gpt-5.5".into()),
                effort: Some(ReasoningEffortConfig::High),
                collaboration_mode: Some(original_mode),
                service_tier: None,
                ..Default::default()
            }
        );
        assert_eq!(std::fs::read(&config_path).ok(), saved_config);
        let queued = std::iter::from_fn(|| events.try_recv().ok()).collect::<Vec<_>>();
        assert!(
            !queued.iter().any(|event| matches!(
                event,
                AppEvent::CodexOp(_) | AppEvent::PersistModelSelection { .. }
            )),
            "recovery must not replay a turn or change global defaults"
        );
        let notice = queued
            .iter()
            .find_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => {
                    Some(lines_to_single_string(&cell.display_lines(/*width*/ 100)))
                }
                _ => None,
            })
            .expect("recovery notice");
        insta::assert_snapshot!("luna_reserve_recovery_notice", notice);
        server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn unicode_math_termination_preserves_source_through_mode_and_resize() -> Result<()> {
    for (kind, status) in [
        ("answer", TurnStatus::Interrupted),
        ("plan", TurnStatus::Interrupted),
        ("plan_error", TurnStatus::Failed),
        ("plan_policy", TurnStatus::Failed),
    ] {
        for ending in ["\n", ""] {
            let (mut app, mut events, _op_rx) = make_test_app_with_channels().await;
            let mut app_server = start_config_write_test_app_server(&app).await?;
            let mut tui = crate::tui::test_support::make_test_tui()?;
            let thread_id = ThreadId::new();
            let plan = kind != "answer";
            if plan {
                app.chat_widget
                    .set_feature_enabled(Feature::CollaborationModes, /*enabled*/ true);
                app.chat_widget
                    .set_collaboration_mask(CollaborationModeMask {
                        name: "Plan".into(),
                        mode: Some(ModeKind::Plan),
                        model: None,
                        reasoning_effort: None,
                        developer_instructions: None,
                    });
            }
            app.chat_widget.handle_server_notification(
                turn_started_notification(thread_id, "math-turn"),
                /*replay_kind*/ None,
            );
            let source = format!("Intro.\n\n$$\n\\frac{{a+b+c+d+e+f}}{{g+h}}{ending}");
            for delta in ["Intro.\n\n", &source[8..]] {
                let notification = if plan {
                    ServerNotification::PlanDelta(
                        codex_app_server_protocol::PlanDeltaNotification {
                            thread_id: thread_id.to_string(),
                            turn_id: "math-turn".into(),
                            item_id: "math-message".into(),
                            delta: delta.into(),
                        },
                    )
                } else {
                    agent_message_delta_notification(thread_id, "math-turn", "math-message", delta)
                };
                app.chat_widget
                    .handle_server_notification(notification, /*replay_kind*/ None);
                for _ in 0..10 {
                    app.chat_widget.on_commit_tick();
                }
            }
            let mut completed = turn_completed_notification(thread_id, "math-turn", status.clone());
            if matches!(kind, "plan_error" | "plan_policy")
                && let ServerNotification::TurnCompleted(notification) = &mut completed
            {
                notification.turn.error = Some(AppServerTurnError {
                    message: if kind == "plan_policy" {
                        r#"{"error":{"code":"bio_policy"}}"#.into()
                    } else {
                        "Server error".into()
                    },
                    codex_error_info: None,
                    additional_details: None,
                    misalignment: None,
                });
            }
            app.chat_widget
                .handle_server_notification(completed, /*replay_kind*/ None);
            let mut saved = Vec::new();
            while let Ok(event) = events.try_recv() {
                if let AppEvent::ConsolidateAgentMessage { source, .. }
                | AppEvent::ConsolidateProposedPlan(source) = &event
                {
                    saved.push(source.trim_end_matches('\n').to_owned());
                }
                if matches!(
                    event,
                    AppEvent::InsertHistoryCell(_)
                        | AppEvent::ConsolidateAgentMessage { .. }
                        | AppEvent::ConsolidateProposedPlan(_)
                ) {
                    app.handle_event(&mut tui, &mut app_server, event).await?;
                }
            }
            assert_eq!(saved, vec![source.trim_end_matches('\n').to_owned()]);
            let mut expected = [None, None];
            for raw in [false, true, false] {
                app.chat_widget.set_raw_output_mode(raw);
                for width in [80, 20, 80] {
                    let rendered = app
                        .render_transcript_lines_for_reflow(width)
                        .lines
                        .iter()
                        .map(rendered_line_text)
                        .collect::<Vec<_>>()
                        .join("\n");
                    let content = rendered.split_whitespace().collect::<String>();
                    assert_eq!(
                        expected[usize::from(raw)].get_or_insert_with(|| content.clone()),
                        &content
                    );
                    if !raw && width == 20 && !ending.is_empty() && kind != "plan_policy" {
                        insta::assert_snapshot!(format!("{kind}_math_narrow"), rendered);
                    }
                }
            }
        }
    }
    Ok(())
}

fn mcp_login_retry_suppresses_old_completion_and_late_browser_open() {
    let (mut app, mut events, _op_rx) = make_test_app_with_channels().await;
    while events.try_recv().is_ok() {}
    let mut server = crate::start_embedded_app_server_for_picker(app.chat_widget.config_ref())
        .await
        .unwrap();
    let mut tui = crate::tui::test_support::make_test_tui().unwrap();
    let thread_id = ThreadId::new();
    app.primary_thread_id = Some(thread_id);
    app.active_thread_id = Some(thread_id);
    app.active_mcp_login_ids
        .insert("enterprise".into(), "old".into());
    app.active_mcp_login_ids
        .insert("other".into(), "other-login".into());
    app.pending_mcp_login_start = Some(PendingMcpLoginStart {
        request_id: "retry".into(),
        name: "enterprise".into(),
        thread_id,
        completions: Vec::new(),
    });
    for (login_id, success) in [("old", false), ("new", true)] {
        app.handle_app_server_event(
            &server,
            codex_app_server_client::AppServerEvent::ServerNotification(Box::new(
                ServerNotification::McpServerOauthLoginCompleted(
                    McpServerOauthLoginCompletedNotification {
                        name: "enterprise".into(),
                        thread_id: Some(thread_id.to_string()),
                        login_id: Some(login_id.into()),
                        success,
                        error: (!success).then(|| "Enterprise sign-in failed.".into()),
                    },
                ),
            )),
        )
        .await;
    }
    assert!(events.try_recv().is_err());
    app.handle_event(
        &mut tui,
        &mut server,
        AppEvent::McpLoginStarted {
            request_id: "retry".into(),
            result: Ok(McpServerOauthLoginResponse {
                authorization_url: String::new(),
                login_id: Some("new".into()),
            }),
        },
    )
    .await
    .unwrap();
    let snapshot = app.thread_event_channels[&thread_id]
        .store
        .lock()
        .await
        .snapshot();
    assert_eq!(snapshot.events.len(), 1);
    for event in snapshot.events {
        app.handle_thread_event_replay(event);
    }
    assert_eq!(
        next_history_message(&mut events),
        "• Signed in to enterprise."
    );
    assert!(events.try_recv().is_err());
    // A cancellation delivered after the replacement response is stale as well.
    app.handle_app_server_event(
        &server,
        codex_app_server_client::AppServerEvent::ServerNotification(Box::new(
            ServerNotification::McpServerOauthLoginCompleted(
                McpServerOauthLoginCompletedNotification {
                    name: "enterprise".into(),
                    thread_id: Some(thread_id.to_string()),
                    login_id: Some("old".into()),
                    success: false,
                    error: Some("Enterprise sign-in failed.".into()),
                },
            ),
        )),
    )
    .await;
    assert_eq!(
        app.thread_event_channels[&thread_id]
            .store
            .lock()
            .await
            .snapshot()
            .events
            .len(),
        1
    );
    // Retrying one server must not discard a different server's outstanding OAuth result.
    app.handle_app_server_event(
        &server,
        codex_app_server_client::AppServerEvent::ServerNotification(Box::new(
            ServerNotification::McpServerOauthLoginCompleted(
                McpServerOauthLoginCompletedNotification {
                    name: "other".into(),
                    thread_id: Some(thread_id.to_string()),
                    login_id: Some("other-login".into()),
                    success: true,
                    error: None,
                },
            ),
        )),
    )
    .await;
    let snapshot = app.thread_event_channels[&thread_id]
        .store
        .lock()
        .await
        .snapshot();
    assert_eq!(snapshot.events.len(), 2);
    app.handle_thread_event_replay(snapshot.events.last().unwrap().clone());
    assert!(next_history_message(&mut events).contains("Signed in to other."));
    server.shutdown().await.unwrap();
}

fn overlapping_mcp_login_preserves_first_start() {
    let (mut app, mut events, _op_rx) = make_test_app_with_channels().await;
    while events.try_recv().is_ok() {}
    let mut server = crate::start_embedded_app_server_for_picker(app.chat_widget.config_ref())
        .await
        .unwrap();
