fn misalignment_continuation_requires_current_review_and_submits_once() -> Result<()> {
    for (reject, preserve, daybreak, rollout_enabled, has_chatgpt_account) in [
        (false, false, false, true, true),
        (false, true, true, true, true),
        (true, false, false, true, true),
        (false, false, false, false, true),
        (false, true, true, false, true),
        // Continuations submit directly rather than via the normal turn-start path.
        (false, false, false, true, false),
        (false, true, true, true, false),
    ] {
        let (mut app, mut rx, _) = make_test_app_with_channels().await;
        app.chat_widget
            .set_feature_enabled(Feature::CliDaybreak, rollout_enabled);
        app.chat_widget
            .set_feature_enabled(Feature::ApiKeyCyberAccessPrograms, !has_chatgpt_account);
        let (mut server, requests, proxy) = start_recording_app_server(
            &app.config,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
        )
        .await?;
        let mut session = if reject {
            test_thread_session(ThreadId::new(), app.config.cwd.to_path_buf())
        } else {
            server.start_thread(&app.config).await?.session
        };
        let thread_id = session.thread_id;
        // Resend local restrictions restored after reconnect, rather than inheriting server settings.
        session.approval_policy = AskForApproval::OnRequest;
        session.permission_profile = PermissionProfile::read_only();
        session.active_permission_profile = None;
        app.active_thread_id = Some(thread_id);
        app.chat_widget.handle_thread_session(session);
        if !reject {
            app.chat_widget.update_account_state(
                (!has_chatgpt_account).then_some(crate::status::StatusAccountDisplay::ApiKey),
                /*plan_type*/ None,
                has_chatgpt_account,
                /*has_codex_backend_auth*/ has_chatgpt_account,
            );
            app.chat_widget.open_model_popup();
            let request_id = std::iter::from_fn(|| rx.try_recv().ok())
                .filter_map(|event| match event {
                    AppEvent::FetchModels { request_id } => Some(request_id),
                    _ => None,
                })
                .last()
                .expect("model catalog request");
            let mut model = crate::test_support::TEST_MODEL_PRESETS[0].clone();
            model.model = app.chat_widget.current_model().to_string();
            model.available_access_programs = Some(ModelAccessPrograms {
                cyber: vec![
                    CyberAccessProgram::Standard,
                    CyberAccessProgram::DaybreakBlue,
                ],
            });
            app.chat_widget
                .on_models_loaded(request_id, Ok(vec![model]));
            app.chat_widget
                .handle_key_event(KeyEvent::from(KeyCode::Esc));
            app.chat_widget.set_daybreak_enabled(daybreak);
        }
        app.runtime_permission_profile_override = Some(if preserve {
            RuntimePermissionProfileOverride::from_restored_config(app.chat_widget.config_ref())
        } else {
            RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref())
        });
        app.chat_widget.handle_server_notification(
            error_notification(thread_id, "failed-turn", policy_error()),
            /*replay_kind*/ None,
        );
        app.chat_widget
            .handle_key_event(KeyEvent::from(KeyCode::Enter));
        let review = std::iter::from_fn(|| rx.try_recv().ok())
            .find_map(|event| match event {
                AppEvent::ReviewMisalignment(review) => Some(review),
                _ => None,
            })
            .expect("review action");
        let mut tui = crate::tui::test_support::make_test_tui()?;
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::ReviewMisalignment(Arc::clone(&review)),
        )
        .await?;
        let Some(Overlay::Static(overlay)) = app.overlay.as_mut() else {
            panic!("findings overlay")
        };
        let mut terminal = ratatui::Terminal::new(ratatui::backend::TestBackend::new(
            /*width*/ 38, /*height*/ 16,
        ))?;
        terminal.draw(|frame| overlay.render(frame.area(), frame.buffer_mut()))?;
        insta::assert_snapshot!("misalignment_findings_38", terminal.backend());
        app.overlay = None;
        assert!(recorded_params(&requests, "turn/start").is_empty());
        let mut withdrawn = policy_error();
        withdrawn
            .misalignment
            .as_mut()
            .unwrap()
            .detailed_explanation = None;
        // Reject both a newer turn and withdrawn findings followed by an empty duplicate.
        for notifications in [
            vec![turn_completed_notification(
                thread_id,
                "newer-turn",
                TurnStatus::Completed,
            )],
            vec![
                error_notification(thread_id, &review.turn_id, withdrawn.clone()),
                ServerNotification::TurnCompleted(TurnCompletedNotification {
                    thread_id: thread_id.to_string(),
                    turn: Turn {
                        error: Some(AppServerTurnError {
                            misalignment: None,
                            ..withdrawn
                        }),
                        ..test_turn(&review.turn_id, TurnStatus::Failed, Vec::new())
                    },
                }),
            ],
        ] {
            for notification in notifications {
                app.enqueue_thread_notification(thread_id, notification)
                    .await?;
            }
            app.continue_misalignment(&mut server, Arc::clone(&review))
                .await;
            assert!(recorded_params(&requests, "turn/start").is_empty());
            app.thread_event_channels.remove(&thread_id);
        }

        if reject {
            app.continue_misalignment(&mut server, Arc::clone(&review))
                .await;
            assert!(app.chat_widget.has_misalignment_policy_violation());
            let errors = std::iter::from_fn(|| rx.try_recv().ok())
                .filter_map(|event| match event {
                    AppEvent::InsertHistoryCell(cell) => {
                        Some(lines_to_single_string(&cell.display_lines(/*width*/ 80)))
                    }
                    _ => None,
                })
                .collect::<Vec<_>>()
                .join("\n");
            insta::assert_snapshot!(
                "misalignment_continue_failed",
                format!(
                    "{errors}\n{}",
                    render_bottom_popup(&app.chat_widget, /*width*/ 80)
                )
            );
            server.shutdown().await?;
            proxy.await??;
            continue;
        }
        // A settings error is not a new turn and must not silently disable Continue.
        app.enqueue_thread_notification(
            thread_id,
            error_notification(
                thread_id,
                "settings-update",
                AppServerTurnError {
                    codex_error_info: Some(AppServerCodexErrorInfo::BadRequest),
                    ..policy_error()
                },
            ),
        )
        .await?;
        app.continue_misalignment(&mut server, Arc::clone(&review))
            .await;
        app.continue_misalignment(&mut server, Arc::clone(&review))
            .await;
        assert!(!app.chat_widget.has_misalignment_policy_violation());
        let params = recorded_params(&requests, "turn/start");
        let [params] = params.as_slice() else {
            panic!("expected one turn/start: {params:?}")
        };
        let mut params: codex_app_server_protocol::TurnStartParams =
            serde_json::from_value(params.clone())?;
        let metadata = params.responsesapi_client_metadata.take().unwrap();
        let override_value: serde_json::Value =
            serde_json::from_str(&metadata["misalignment_override"])?;
        let timestamp = override_value["timestamp"].as_u64().unwrap();
        assert_eq!(metadata.len(), 1);
        assert_eq!(override_value, serde_json::json!({"timestamp": timestamp}));
        let config = app.chat_widget.config_ref();
        assert_eq!(
            params,
            codex_app_server_protocol::TurnStartParams {
                thread_id: thread_id.to_string(),
                cwd: Some(config.cwd.to_path_buf()),
                runtime_workspace_roots: Some(
                    config.permissions.user_visible_workspace_roots().to_vec()
                ),
                approval_policy: Some(AskForApproval::OnRequest),
                approvals_reviewer: Some(config.approvals_reviewer.into()),
                sandbox_policy: (!preserve).then(|| config.legacy_sandbox_policy().into()),
                cyber_access_program: rollout_enabled.then_some(if daybreak {
                    CyberAccessProgram::DaybreakBlue.into()
                } else {
                    CyberAccessProgram::Standard.into()
                }),
                input: vec![codex_app_server_protocol::UserInput::Text {
                    text: "Continue **only** within the requested scope.\nDo not edit files."
                        .to_string(),
                    text_elements: Vec::new(),
                }],
                ..Default::default()
            }
        );
        server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn accepted_model_migration_persists_target_default_reasoning_effort() -> Result<()> {
    let mut migration_copies = Vec::new();
    for (model, replacement, provider_id, presets) in [
        ("gpt-5.4", "gpt-6-sol", "openai", all_model_presets()),
        ("gpt-5.4-mini", "gpt-6-luna", "openai", all_model_presets()),
        ("gpt-5.5", "gpt-6-sol", "openai", all_model_presets()),
        ("gpt-5.6-luna", "gpt-6-luna", "openai", all_model_presets()),
        ("gpt-5.6-terra", "gpt-6-sol", "openai", all_model_presets()),
        ("gpt-5.6-sol", "gpt-6-sol", "openai", all_model_presets()),
        (
            "openai.gpt-5.4",
            "openai.gpt-6-sol",
            "amazon-bedrock",
            bedrock_model_presets(),
        ),
    ] {
        let codex_home = tempdir()?;
        std::fs::write(
            codex_home.path().join("config.toml"),
            format!(
                "model = \"{model}\"\nmodel_reasoning_effort = \"xhigh\"\nmodel_provider = \"{provider_id}\"\n"
            ),
        )?;
        let mut config = ConfigBuilder::default()
            .codex_home(codex_home.path().to_path_buf())
            .build()
            .await?;
        let current_model = config.model.clone().expect("saved model");
        let provider = config.model_provider.clone();
        let upgrade = model_upgrade_for_migration(provider_id, &current_model, &presets)
            .expect("catalog selection should have an upgrade");
        assert_eq!(upgrade.id, replacement);
        assert!(should_show_model_migration_prompt(
            provider_id,
            &current_model,
            &upgrade.id,
            &BTreeMap::new(),
            &presets,
        ));
        let target =
            target_preset_for_upgrade(&presets, &upgrade.id).expect("available replacement");
        let target_effort = target.default_reasoning_effort.clone();
        let can_opt_out = presets.iter().any(|preset| preset.model == current_model);
        let copy = migration_copy_for_models(
            &current_model,
            &upgrade.id,
            upgrade.model_link,
            upgrade.upgrade_copy,
            upgrade.migration_markdown,
            target.display_name.clone(),
            Some(target.description.clone()),
            can_opt_out,
        );
        migration_copies.push(model_migration_copy_to_plain_text(&copy));

        let (tx_raw, mut rx) = unbounded_channel();
        let app_event_tx = AppEventSender::new(tx_raw);
        apply_accepted_model_migration(
            &mut config,
            &mut crate::app_server_session::StartupLaunchChoices::default(),
            &app_event_tx,
            current_model,
            upgrade.id,
            target_effort.clone(),
        );

        assert_eq!(
            (
                config.model.as_deref(),
                config.model_reasoning_effort.as_ref(),
                config.model_provider_id.as_str(),
                &config.model_provider,
            ),
            (
                Some(replacement),
                Some(&target_effort),
                provider_id,
                &provider
            )
        );

        let acknowledged = rx.try_recv().expect("acknowledged event");
        assert_matches!(
            acknowledged,
            AppEvent::PersistModelMigrationPromptAcknowledged { from_model, to_model }
                if from_model == model && to_model == replacement
        );

        let update_model = rx.try_recv().expect("update model event");
        assert_matches!(
            update_model,
            AppEvent::UpdateModel(updated_model) if updated_model == replacement
        );

        let update_effort = rx.try_recv().expect("update effort event");
        assert_matches!(
            update_effort,
            AppEvent::UpdateReasoningEffort(Some(effort)) if effort == target_effort
        );

        let persist_selection = rx.try_recv().expect("persist model selection event");
        assert_matches!(
            persist_selection,
            AppEvent::PersistModelSelection { model: selected_model, effort }
                if selected_model == replacement && effort == Some(target_effort)
        );
    }
    assert_snapshot!(migration_copies.join("\n"), @r"
    GPT-5.4 is no longer available

    Codex now uses GPT-6 Sol in place of GPT-5.4. Switch to GPT-6 Sol to continue.

    GPT-5.4 Mini is no longer available

    Codex now uses GPT-6 Luna in place of GPT-5.4 Mini. Switch to GPT-6 Luna to continue.

    Meet GPT-6 Sol

    Our latest Sol is more intelligent and more efficient so your usage limits go further. This model is a great daily driver for complex tasks, especially coding.

    Meet GPT-6 Luna

    Our latest Luna is significantly more efficient, so your usage limits go even further. Reach for it for any job that doesn't require frontier intelligence.

    Meet GPT-6 Sol

    Our latest Sol is more intelligent and more efficient so your usage limits go further. This model is a great daily driver for complex tasks, especially coding.

    Meet GPT-6 Sol

    Our latest Sol is more intelligent and more efficient so your usage limits go further. This model is a great daily driver for complex tasks, especially coding.

    GPT-5.4 on Amazon Bedrock is no longer offered in Codex

    Codex now uses GPT-6 Sol on Amazon Bedrock in place of GPT-5.4 on Amazon Bedrock. Switch to GPT-6 Sol on Amazon Bedrock to continue.
    ");
    Ok(())
}

