    let fast = Some(ServiceTier::Fast.request_value());
    let thread_id = ThreadId::new();
    let mut session = test_thread_session(thread_id, test_path_buf("/tmp/project"));
    session.model = "gpt-5.5".to_string();
    app.primary_thread_id = Some(thread_id);
    app.active_thread_id = Some(thread_id);
    app.primary_session_configured = Some(session.clone());
    app.thread_event_channels.insert(
        thread_id,
        ThreadEventChannel::new_with_session(/*capacity*/ 4, session.clone(), Vec::new()),
    );
    app.chat_widget.handle_thread_session(session.clone());
    app.chat_widget
        .set_feature_enabled(Feature::FastMode, /*enabled*/ true);
    app.chat_widget.open_model_popup();
    let request_id = std::iter::from_fn(|| rx.try_recv().ok())
        .find_map(|event| match event {
            AppEvent::FetchModels { request_id } => Some(request_id),
            _ => None,
        })
        .expect("initial model request");
    let mut hidden = all_model_presets();
    for preset in &mut hidden {
        preset.show_in_picker = false;
    }
    Box::pin(app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::ModelsLoaded {
            request_id,
            result: Ok(hidden),
        },
    ))
    .await?;
    app.chat_widget.open_model_popup();
    assert!(app.chat_widget.no_modal_or_popup_active());
    let request = std::iter::from_fn(|| rx.try_recv().ok())
        .find(|event| matches!(event, AppEvent::FetchModels { .. }))
        .expect("catalog request");

    Box::pin(app.handle_event(&mut tui, &mut app_server, request)).await?;
    let mut loaded = tokio::time::timeout(Duration::from_secs(/*secs*/ 10), async {
        loop {
            if let Some(event @ AppEvent::ModelsLoaded { .. }) = rx.recv().await {
                break event;
            }
        }
    })
    .await?;
    let AppEvent::ModelsLoaded {
        result: Ok(models), ..
    } = &mut loaded
    else {
        panic!("model/list should return models");
    };
    assert!(!models.is_empty());
    for model in models.iter_mut() {
        model.is_default = model.model == "gpt-5.5";
        model.default_service_tier = model
            .is_default
            .then(|| ServiceTier::Fast.request_value().to_string());
    }
    let expected = models.clone();
    Box::pin(app.handle_event(&mut tui, &mut app_server, loaded)).await?;
    assert!(app.chat_widget.no_modal_or_popup_active());
    app.chat_widget.open_model_popup();
    assert!(!app.chat_widget.no_modal_or_popup_active());

    session.service_tier = fast.map(str::to_string);
    let channel = &app.thread_event_channels[&thread_id];
    let cached = channel.store.lock().await.session.clone();
    assert_eq!(
        (&app.primary_session_configured, &cached),
        (&Some(session.clone()), &Some(session.clone()))
    );
    app.chat_widget.handle_thread_session(test_thread_session(
        ThreadId::new(),
        test_path_buf("/tmp/other"),
    ));
    app.chat_widget.handle_thread_session(cached.unwrap());
    assert_eq!(app.chat_widget.current_service_tier(), fast);
    let stale = AppEvent::ModelsLoaded {
        request_id: uuid::Uuid::new_v4(),
        result: Ok(all_model_presets()),
    };
    Box::pin(app.handle_event(&mut tui, &mut app_server, stale)).await?;
    assert_eq!(
        (
            app.model_catalog.try_list_models().unwrap(),
            app.chat_widget.model_catalog().try_list_models().unwrap(),
        ),
        (expected.clone(), expected)
    );
    let mut config = app.config.clone();
    config.service_tier = None;
    config.features.enable(Feature::FastMode)?;
    for (model, expected_tier) in [(None, fast), (Some("gpt-5.6-terra"), Some("default"))] {
        config.model = model.map(str::to_string);
        let started = app_server.start_thread(&config).await?;
        assert_eq!(started.session.service_tier.as_deref(), expected_tier);
    }
    app_server.shutdown().await?;
    Ok(())
}

fn session_model_selection_preserves_defaults_and_updates_active_thread() -> Result<()> {
    for mode in [ModeKind::Default, ModeKind::Plan] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        app.config.model = Some("gpt-5.5".into());
        app.config.model_reasoning_effort = Some(ReasoningEffortConfig::Medium);
        app.config.plan_mode_reasoning_effort = Some(ReasoningEffortConfig::Low);
        let config_path = app.config.codex_home.join("config.toml");
        let original = "# My defaults\nmodel = 'gpt-5.5'\nmodel_reasoning_effort = 'medium'\nplan_mode_reasoning_effort = 'low'\n";
        std::fs::write(&config_path, original)?;
        let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
        let started = server.start_thread(&app.config).await?;
        let thread_id = started.session.thread_id;
        app.enqueue_primary_thread_session(started.session, started.turns)
            .await?;
        app.chat_widget
            .set_feature_enabled(Feature::CollaborationModes, /*enabled*/ true);
        if mode == ModeKind::Plan {
            let mask = collaboration_modes::plan_mask(app.model_catalog.as_ref()).unwrap();
            app.chat_widget.set_collaboration_mask(mask);
        }
        let mut tui = crate::tui::test_support::make_test_tui()?;
        for effort in [
            ReasoningEffortConfig::High,
            ReasoningEffortConfig::Ultra,
            ReasoningEffortConfig::Max,
        ] {
            while events.try_recv().is_ok() {}
            let command = match effort {
                ReasoningEffortConfig::High => {
                    "/model gpt-5.6-terra --reasoning high --speed=standard".into()
                }
                ReasoningEffortConfig::Ultra => "/model --reasoning=ultra".into(),
                ReasoningEffortConfig::Max => "/model --reasoning max".into(),
                _ => unreachable!(),
            };
            app.chat_widget.apply_external_edit(command);
            app.chat_widget.handle_key_event(KeyCode::Esc.into());
            app.chat_widget.handle_key_event(KeyCode::Enter.into());
            let mut messages = Vec::new();
            while let Ok(event) = events.try_recv() {
                if let AppEvent::InsertHistoryCell(cell) = &event {
                    messages.push(lines_to_single_string(&cell.transcript_lines(/*width*/ 80)));
                }
                Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
            }
            let settings = next_thread_settings_updated(&mut server, thread_id).await;
            assert_eq!(
                (
                    settings.thread_settings.model.as_str(),
                    settings.thread_settings.effort.clone(),
                    settings.thread_settings.service_tier.as_deref(),
                ),
                ("gpt-5.6-terra", Some(effort.clone()), Some("default"))
            );
            if mode == ModeKind::Default && effort == ReasoningEffortConfig::High {
                for command in [
                    "/model gpt-5.6-terra fast",
                    "/model gpt-5.6-terra --speeed=fast",
                    "/model gpt-5.6-terra --reasoning=invalid",
                    "/model --speed",
                    "/model --reasoning=",
                    "/model --reasoning --speed=standard",
                    "/model --speed=fast --speed standard",
                ] {
                    app.chat_widget.apply_external_edit(command.into());
                    app.chat_widget.handle_key_event(KeyCode::Esc.into());
                    app.chat_widget.handle_key_event(KeyCode::Enter.into());
                }
                while let Ok(event) = events.try_recv() {
                    assert!(!matches!(
                        event,
                        AppEvent::SelectSessionModel { .. }
                            | AppEvent::AstraSelectedFromModelPicker { .. }
                    ));
                    if let AppEvent::InsertHistoryCell(cell) = &event {
                        messages.push(lines_to_single_string(&cell.transcript_lines(/*width*/ 80)));
                    }
                    Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
                }
                insta::assert_snapshot!("session_only_model_confirmation", messages.join("\n"));
            }
            app.enqueue_thread_notification(
                thread_id,
                ServerNotification::ThreadSettingsUpdated(settings),
            )
            .await?;
            assert_eq!(
                (
                    app.chat_widget.current_model(),
                    app.chat_widget.current_reasoning_effort()
                ),
                ("gpt-5.6-terra", Some(effort))
            );
            assert_eq!(std::fs::read(&config_path)?, original.as_bytes());
        }
        let fresh = server.start_thread(&app.config).await?;
        assert_eq!(
            (fresh.session.model.as_str(), fresh.session.reasoning_effort),
            ("gpt-5.5", Some(ReasoningEffortConfig::Medium))
        );
        assert_eq!(
            app.config.plan_mode_reasoning_effort,
            Some(ReasoningEffortConfig::Low)
        );
        server.shutdown().await?;
    }
    Ok(())
}

fn model_default_saves_report_server_outcomes_and_target_server_profile() -> Result<()> {
    for outcome in ["saved", "overridden", "rejected"] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        app.config.model_reasoning_effort = Some(ReasoningEffortConfig::Medium);
        let local_config_path = app.config.codex_home.join("config.toml");
        let local_config_before = std::fs::read(&local_config_path).ok();
        let server_home = tempfile::tempdir()?;
        let base_path = server_home.path().join("config.toml");
        let profile_path = server_home.path().join("work.config.toml");
        std::fs::write(&base_path, "# Base configuration stays unchanged.\n")?;
        std::fs::write(&profile_path, "")?;
        let mut loader_overrides = LoaderOverrides::without_managed_config_for_tests();
        loader_overrides.user_config_path =
            Some(AbsolutePathBuf::from_absolute_path(&profile_path)?);
        loader_overrides.user_config_profile = Some("work".parse()?);
        let overrides = if outcome == "overridden" {
            vec![
                ("model".into(), toml::Value::String("gpt-5.6-terra".into())),
                (
                    "model_reasoning_effort".into(),
                    toml::Value::String("low".into()),
                ),
                (
                    "plan_mode_reasoning_effort".into(),
                    toml::Value::String("low".into()),
                ),
                ("service_tier".into(), toml::Value::String("flex".into())),
            ]
        } else {
            Vec::new()
        };
        let config = ConfigBuilder::default()
            .codex_home(server_home.path().to_path_buf())
            .cli_overrides(overrides.clone())
            .loader_overrides(loader_overrides.clone())
            .harness_overrides(ConfigOverrides {
                cwd: Some(server_home.path().to_path_buf()),
                ..Default::default()
            })
            .build()
            .await?;
        let client = crate::start_embedded_app_server(
            codex_arg0::Arg0DispatchPaths::default(),
            config,
            overrides,
            loader_overrides,
            /*strict_config*/ false,
            codex_config::CloudConfigBundleLoader::default(),
            codex_feedback::CodexFeedback::new(),
            /*log_db*/ None,
            /*state_db*/ None,
            Arc::new(codex_exec_server::EnvironmentManager::default_for_tests()),
            Default::default(),
        )
        .await?;
        let mut server = AppServerSession::new(
            crate::backend_id::BackendId::new(),
            AppServerClient::InProcess(client),
            crate::app_server_session::ThreadParamsMode::Remote,
        );
        if outcome == "rejected" {
            std::fs::write(&profile_path, "[broken")?;
        }
        while events.try_recv().is_ok() {}
        let mut tui = crate::tui::test_support::make_test_tui()?;
        for event in [
            AppEvent::PersistModelSelection {
                model: "gpt-5.5".into(),
                effort: Some(ReasoningEffortConfig::High),
            },
            AppEvent::PersistPlanModeReasoningEffort(Some(ReasoningEffortConfig::High)),
            AppEvent::PersistServiceTierSelection {
                service_tier: Some(ServiceTier::Fast.request_value().into()),
            },
            AppEvent::ApplyAdvancedReasoning {
                model: "gpt-5.5".into(),
                effort: ReasoningEffortConfig::Ultra,
            },
        ] {
            Box::pin(app.handle_event(&mut tui, &mut server, event)).await?;
        }
        let mut service_tier_error = None;
        let messages = std::iter::from_fn(|| events.try_recv().ok())
            .filter_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => {
                    if outcome == "rejected" {
                        let text = lines_to_single_string(&cell.transcript_lines(/*width*/ 200));
                        if text.contains("Failed to save default service tier") {
                            service_tier_error = Some(
                                text.replace(&profile_path.display().to_string(), "<config-path>"),
                            );
                        }
                    }
                    Some(lines_to_single_string(&cell.transcript_lines(/*width*/ 80)))
                }
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert_eq!(
            messages.matches("higher-priority").count(),
            if outcome == "overridden" { 4 } else { 0 }
        );
        assert_eq!(
            messages.matches("Failed to save").count(),
            if outcome == "rejected" { 4 } else { 0 }
        );
        if outcome == "overridden" {
            insta::assert_snapshot!("overridden_model_defaults", messages);
        }
        let persisted = std::fs::read_to_string(&profile_path)?;
        if outcome == "rejected" {
            insta::assert_snapshot!(
                "service_tier_default_save_error",
                service_tier_error.expect("expected a service-tier save error")
            );
            assert_eq!(persisted, "[broken");
            assert!(!messages.contains("Model changed"));
            assert!(!messages.contains("Service tier set"));
        } else {
            assert_eq!(
                toml::from_str::<toml::Value>(&persisted)?,
                toml::Value::Table(toml::toml! {
                    model = "gpt-5.5"
                    model_reasoning_effort = "medium"
                    plan_mode_reasoning_effort = "high"
                    service_tier = "fast"
                })
            );
        }
        assert_eq!(std::fs::read(&local_config_path).ok(), local_config_before);
        assert_eq!(
            std::fs::read_to_string(&base_path)?,
            "# Base configuration stays unchanged.\n"
        );
        server.shutdown().await?;
    }
    Ok(())
}

fn reconnect_daemon_command_center_after_socket_replacement_without_a_conversation()
-> Result<()> {
    use super::super::agents_overview::AGENTS_OVERVIEW_VIEW_ID;
    use codex_app_server_protocol::Thread;
    use codex_app_server_protocol::ThreadStatus;
    use tokio::net::UnixListener;

    // Losing an optional, previously opened thread must not strand the command center either.
    for (previous_thread, changed_child_permissions, overview_initialized) in [
        (None, false, false),
        (None, false, true),
        (Some(ThreadId::new()), false, true),
        (Some(ThreadId::new()), true, true),
    ] {
        let (mut app, mut events, _) = make_test_app_with_channels().await;
        app.keymap.app.open_agents = vec![crate::key_hint::alt(KeyCode::Char('a'))];
        let child = ThreadId::new();
        let child_recap = recap::RecapProgress {
            completed_turns: 3,
            last_recapped_turn_count: Some(3),
        };
        app.config.model = Some("gpt-test".into());
        app.active_thread_id = previous_thread;
        app.primary_thread_id = previous_thread;
        if let Some(id) = previous_thread {
            app.config
                .permissions
                .set_permission_profile(PermissionProfile::read_only())?;
            app.runtime_approval_policy_override = Some(RuntimeApprovalPolicyOverride::Explicit(
                AskForApproval::OnRequest,
            ));
            app.runtime_permission_profile_override =
                Some(RuntimePermissionProfileOverride::from_config(&app.config));
            let mut session = test_thread_session(id, app.config.cwd.to_path_buf());
            session.approval_policy = AskForApproval::OnRequest;
            session.permission_profile = PermissionProfile::read_only();
            app.primary_session_configured = Some(session.clone());
            app.chat_widget.handle_thread_session(session.clone());
            app.ensure_thread_channel(id)
                .store
                .lock()
                .await
                .set_session(
                    session,
                    vec![test_turn(
                        "cached",
                        TurnStatus::Completed,
                        vec![ThreadItem::Plan {
                            id: "cached-plan".into(),
                            text: "Cached previous conversation".into(),
                        }],
                    )],
                );
            app.chat_widget
                .restore_user_message_to_composer("old draft".into());
            app.store_active_thread_receiver().await;
            app.chat_widget
                .handle_key_event(KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL));
            assert!(app.chat_widget.composer_is_empty());
            app.chat_widget
                .restore_user_message_to_composer("latest draft".into());
        }
        if previous_thread.is_some() {
            let child_session = test_thread_session(child, app.config.cwd.to_path_buf());
            app.ensure_thread_channel(child)
                .store
                .lock()
                .await
                .set_session(child_session, Vec::new());
            app.thread_event_channels[&child]
                .store
                .lock()
                .await
                .merge_recap_progress(child_recap);
            app.upsert_agent_picker_thread(
                child, /*agent_nickname*/ None, /*agent_role*/ None,
                /*is_closed*/ false,
            );
        }
        let selected = ThreadId::from_string("00000000-0000-0000-0000-000000000001")?;
        let vanished = ThreadId::new();
        let added = ThreadId::new();
        let make_thread = |id: ThreadId, name: &str, status: ThreadStatus| -> Result<Thread> {
            Ok(serde_json::from_value(json!({
                "id": id.to_string(), "sessionId": id.to_string(), "preview": name, "name": name,
                "ephemeral": false, "modelProvider": "test-provider", "createdAt": 1,
                "updatedAt": chrono::Utc::now().timestamp() - 120, "status": status,
                "cwd": app.config.cwd, "cliVersion": "0.0.0", "source": "cli", "turns": []
            }))?)
        };
        let child_thread = make_thread(child, "Cached child", ThreadStatus::NotLoaded)?;
        let stale = vec![
            make_thread(
                selected,
                "Selected task",
                ThreadStatus::Active {
                    active_flags: Vec::new(),
                },
            )?,
            make_thread(vanished, "Vanished task", ThreadStatus::Idle)?,
        ];
        let fresh = [
            make_thread(selected, "Selected task", ThreadStatus::Idle)?,
            make_thread(
                added,
                "New task",
                ThreadStatus::Active {
                    active_flags: Vec::new(),
                },
            )?,
        ];
        let stale_threads = stale
            .iter()
            .map(|thread| Ok((ThreadId::from_string(&thread.id)?, Some(thread.clone()))))
            .collect::<Result<HashMap<_, _>>>()?;
        app.agents_overview.threads = stale_threads.clone();
        app.agents_overview
            .last_messages
            .insert(selected, "Pre-disconnect answer".into());
        app.agents_overview.initialized = overview_initialized;
        // This task was unarchived elsewhere while disconnected.
        app.agents_overview.removed_threads.insert(added);
        let mut view = app.agents_overview_view(
            stale.clone(),
            Some(if previous_thread.is_some() {
                vanished
            } else {
                selected
            }),
        );
        view.handle_key_event(KeyCode::Char('r').into());
        view.handle_key_event(KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL));
        view.handle_paste("Keep this task draft!".into());
        app.agents_overview.visible_thread_ids = view.thread_ids();
        app.chat_widget.show_bottom_pane_view(Box::new(view));
        let draft = |app: &App| {
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .input
                .text()
                .to_string()
        };
        let stale_request = Uuid::new_v4();
        app.agents_overview.request_id = Some(stale_request);
        app.agents_overview.refresh_pending = true;
        let refresh = tokio::spawn(std::future::pending::<()>());
        app.agents_overview.refresh_task = Some(refresh.abort_handle());
        let directory = tempfile::tempdir()?;
        let socket_path = directory.path().join("daemon.sock");
        let listener = UnixListener::bind(&socket_path)?;
        let endpoint = crate::RemoteAppServerEndpoint::UnixSocket {
            socket_path: codex_utils_absolute_path::AbsolutePathBuf::try_from(socket_path.clone())?,
        };
        app.app_server_target = AppServerTarget::LocalDaemon {
            allow_embedded_fallback: true,
            endpoint: endpoint.clone(),
        };
        let interrupted_setup = previous_thread.is_none() && !overview_initialized;
        if interrupted_setup {
            let preset = codex_utils_approval_presets::builtin_approval_presets()
                .into_iter()
                .find(|preset| preset.id == "auto")
                .expect("auto preset");
            app.windows_sandbox.pending_setup =
                Some((WindowsSandboxEnableMode::Elevated, preset, None));
            app.windows_sandbox.setup_started_at = Some(Instant::now());
        } else if previous_thread.is_none() {
            app.chat_widget.windows_sandbox_elevated_setup_complete = true;
        }
        let available = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let server_available = Arc::clone(&available);
        let restored_previous = previous_thread
            .map(|id| make_thread(id, "Recovered task", ThreadStatus::NotLoaded))
            .transpose()?;
        let server = tokio::spawn(async move {
            let mut listener = listener;
            let mut methods = Vec::new();
            let mut child_opened = false;
            for connection in 0..(2 + usize::from(previous_thread.is_some())) {
                let (stream, _) = listener.accept().await?;
                let socket = tokio_tungstenite::accept_async(stream).await?;
                methods.extend(serve_reconnect_requests(socket, |request| std::future::ready({
                    match request.method.as_str() {
                        "config/read" => Some(json!({"error": {"code": -32601, "message": "unsupported"}})),
                        "thread/loaded/list" if connection == 0 => None,
                        "thread/resume" if connection == 1 && previous_thread.is_some() => None,
                        "thread/resume" if request.params.as_ref().unwrap()["threadId"] != child.to_string() && !server_available.load(std::sync::atomic::Ordering::SeqCst) => Some(json!({"error": {"code": -32600, "message": "thread no longer exists"}})),
                        "thread/resume" => {
                            let mut thread = if request.params.as_ref().unwrap()["threadId"] == child.to_string() {
                                child_opened = true;
                                child_thread.clone()
                            } else {
                                restored_previous.clone().unwrap()
                            };
                            if changed_child_permissions && thread.id != child.to_string() {
                                thread.turns = vec![test_turn("saved", TurnStatus::InProgress, Vec::new())];
                            }
                            let (approval, sandbox) = if changed_child_permissions && thread.id != child.to_string() {
                                ("on-request", "readOnly")
                            } else {
                                ("never", "dangerFullAccess")
                            };
                            Some(json!({"result": {"thread": thread, "model": "gpt-test", "modelProvider": "test-provider", "cwd": thread.cwd, "approvalPolicy": approval, "approvalsReviewer": "user", "sandbox": {"type": sandbox}, "reasoningEffort": null}}))
                        }
                        "turn/start" => {
                            let params = request.params.as_ref().unwrap();
                            assert_eq!(params["approvalPolicy"], "on-request");
                            assert_eq!(params["sandboxPolicy"]["type"], if changed_child_permissions { json!(null) } else { json!("readOnly") });
                            assert_eq!(params["input"][0]["text"], "latest draft!");
                            Some(json!({"result": {"turn": {"id": "fresh", "items": [], "status": "inProgress"}}}))
                        }
                        "thread/loaded/list" => Some(json!({"result": {"data": [selected, added], "nextCursor": null}})),
                        "thread/list" => Some(json!({"result": {"data": [], "nextCursor": null}})),
                        "thread/turns/list" => Some(json!({"result": {"data": [], "nextCursor": null}})),
                        "thread/goal/get" => Some(json!({"result": {"goal": null}})),
                        "thread/read" if request.params.as_ref().unwrap()["threadId"] == child.to_string() => Some(json!({"result": {"thread": child_thread}})),
                        "thread/read" if previous_thread.is_some_and(|id| request.params.as_ref().unwrap()["threadId"] == id.to_string()) => Some(if changed_child_permissions && child_opened {
                            let mut thread = restored_previous.clone().unwrap();
                            let status = if server_available.load(std::sync::atomic::Ordering::SeqCst) { TurnStatus::InProgress } else { TurnStatus::Completed };
                            thread.turns = vec![test_turn("saved", status, Vec::new())];
                            json!({"result": {"thread": thread}})
                        } else if server_available.load(std::sync::atomic::Ordering::SeqCst) { json!({"result": {"thread": restored_previous}}) } else { json!({"error": {"code": -32600, "message": "thread no longer exists"}}) }),
                        "thread/read" if request.params.as_ref().unwrap()["threadId"] == vanished.to_string() => Some(json!({"error": {"code": -32600, "message": "thread no longer exists"}})),
                        "thread/read" => Some(json!({"result": {"thread": fresh.iter().find(|thread| request.params.as_ref().unwrap()["threadId"] == thread.id).unwrap()}})),
                        method => panic!("unexpected daemon reconnect request: {method}"),
                    }
                })).await?);
                if connection == 0 {
                    drop(listener);
                    std::fs::remove_file(&socket_path)?;
                    listener = UnixListener::bind(&socket_path)?;
                }
            }
            Ok::<_, color_eyre::Report>(methods)
        });
        let mut session = AppServerSession::new(
            crate::backend_id::BackendId::new(),
            crate::connect_remote_app_server(endpoint).await?,
            ThreadParamsMode::Embedded,
        );
        assert!(
            session
                .thread_loaded_list(ThreadLoadedListParams {
                    cursor: None,
                    limit: Some(100)
                })
                .await
                .is_err()
        );
        let disconnected = session.next_event().await.unwrap();
        // A shutdown error can cover the initial command center when its first New fails.
        if previous_thread.is_none() && overview_initialized {
            app.show_agents_overview_error(
                Some("Codex's background server is shutting down"),
                "Waiting for active turns.".into(),
            );
        }
        app.handle_app_server_event(&session, disconnected).await;
        assert!(app.reconnect.offline);
        assert!(app.agents_overview.last_messages.is_empty());
        assert!(refresh.await.unwrap_err().is_cancelled());
        assert_eq!(
            (
                app.agents_overview.request_id,
                app.agents_overview.refresh_pending
            ),
            (None, false)
        );
        app.apply_agents_overview_thread_refresh(
            &session,
            stale_request,
            Ok(AgentsOverviewThreadRefresh {
                last_messages: HashMap::new(),
                threads: HashMap::new(),
                recent_seed_complete: false,
                discovery: None,
                pinned_thread_ids: None,
            }),
        );
        assert_eq!(app.agents_overview.visible_thread_ids.len(), 2);
        let mut tui = crate::tui::test_support::make_test_tui()?;
        assert_eq!(draft(&app), "Keep this task draft!");
        if previous_thread.is_none() && !overview_initialized {
            assert_snapshot!(
                "daemon_command_center_reconnecting",
                render_bottom_popup(&app.chat_widget, /*width*/ 100)
            );
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .connection_notice =
                Some("Reconnect failed — agent list is stale; relaunch to retry");
            assert_snapshot!(
                "daemon_command_center_failed",
                render_bottom_popup(&app.chat_widget, /*width*/ 100)
            );
        }
        let connected = reconnect(
            session.backend_id(),
            app.app_server_target.clone(),
            app.config.clone(),
            app.local_settings.clone(),
            previous_thread,
            /*remote_cwd*/ None,
            session.thread_tool_transport(),
            app.reconnect.presentation,
        )
        .await?;
        app.finish_reconnect(
            &mut tui,
            &mut session,
            &mut events,
            connected,
            CODEX_CLI_VERSION,
        )
        .await?;
        if interrupted_setup {
            assert!(app.windows_sandbox.pending_setup.is_none());
            assert!(app.windows_sandbox.setup_started_at.is_none());
            let mut retained = Vec::new();
            let mut saw_warning = false;
            while let Ok(event) = events.try_recv() {
                if let AppEvent::InsertHistoryCell(cell) = &event {
                    let rendered = lines_to_single_string(&cell.display_lines(/*width*/ 100));
                    if rendered.contains("Windows sandbox setup was interrupted") {
                        insta::assert_snapshot!(rendered, @"■ Windows sandbox setup was interrupted. Restart Codex before using Agent mode.");
                        saw_warning = true;
                        continue;
                    }
                }
                retained.push(event);
            }
            assert!(saw_warning);
            for event in retained {
                app.app_event_tx.send(event);
            }
        } else if previous_thread.is_none() {
            assert!(app.chat_widget.windows_sandbox_elevated_setup_complete);
        }
        assert!(!app.reconnect.offline);
        assert_eq!(app.current_displayed_thread_id(), previous_thread);

        tokio::time::timeout(Duration::from_secs(/*secs*/ 5), async {
            let mut deferred = Vec::new();
            while app.agents_overview.request_id.is_some() {
                let event = events.recv().await.expect("inventory refresh event");
                if matches!(event, AppEvent::AgentsOverviewThreadsLoaded { .. }) {
                    app.handle_event(&mut tui, &mut session, event).await?;
                } else {
                    deferred.push(event);
                }
            }
            for event in deferred {
                app.app_event_tx.send(event);
            }
            Ok::<_, color_eyre::Report>(())
        })
        .await??;
        assert!(app.agents_overview.visible_thread_ids.contains(&vanished));

        // Missing metadata alone does not evict a retained row; an archive notification does.
        app.handle_app_server_event(
            &session,
            AppServerEvent::ServerNotification(Box::new(ServerNotification::ThreadArchived(
                ThreadArchivedNotification {
                    thread_id: vanished.to_string(),
                },
            ))),
        )
        .await;
        let index = app
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .unwrap();
        if previous_thread.is_none() {
            assert_eq!(app.agents_overview.visible_thread_ids[index], selected);
        }
        assert!(!app.agents_overview.visible_thread_ids.contains(&vanished));
        assert!(app.agents_overview.visible_thread_ids.contains(&added));
        assert_eq!(
            draft(&app),
            if previous_thread.is_some() {
                ""
            } else {
                "Keep this task draft!"
            }
        );
        if previous_thread.is_some() {
            let history = drain_history(&mut app, &mut tui, &mut session, &mut events).await?;
            assert!(history.contains("Unsubmitted title: Keep this task draft!"));
            assert_snapshot!(
                "daemon_command_center_vanished_rename",
                render_bottom_popup(&app.chat_widget, /*width*/ 100)
            );
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            )
            .await?;
            assert!(
                !std::iter::from_fn(|| events.try_recv().ok())
                    .any(|event| matches!(event, AppEvent::NewAgentsOverviewSession { .. }))
            );
        }
        assert!(
            app.agents_overview
                .view_state
                .lock()
                .unwrap()
                .connection_notice
                .is_none()
        );
        app.apply_agents_overview_thread_refresh(
            &session,
            stale_request,
            Ok(AgentsOverviewThreadRefresh {
                last_messages: HashMap::new(),
                threads: stale_threads,
                recent_seed_complete: true,
                discovery: None,
                pinned_thread_ids: None,
            }),
        );
        assert!(!app.agents_overview.visible_thread_ids.contains(&vanished));

        if let Some(id) = previous_thread {
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)),
            )
            .await?;

            assert!(!app.chat_widget.has_active_view());
            assert_eq!(app.current_displayed_thread_id(), Some(id));
            let history = drain_history(&mut app, &mut tui, &mut session, &mut events).await?;
            assert!(history.contains("Cached previous conversation"));

            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Char('l'), KeyModifiers::CONTROL)),
            )
            .await?;
            let preserved_history =
                drain_history(&mut app, &mut tui, &mut session, &mut events).await?;
            assert_eq!(preserved_history, history);

            let content = &preserved_history[preserved_history
                .find("Cached previous conversation")
                .unwrap()..];
            assert_snapshot!(
                "reconnected_unavailable_conversation",
                format!(
                    "{content}\n{}",
                    render_bottom_popup(&app.chat_widget, /*width*/ 80)
                )
            );

            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            )
            .await?;
            assert_eq!(app.chat_widget.composer_text_with_pending(), "latest draft");
            assert!(
                !std::iter::from_fn(|| events.try_recv().ok())
                    .any(|event| matches!(event, AppEvent::CodexOp(AppCommand::UserTurn { .. })))
            );
            app.handle_tui_event(&mut tui, &mut session, TuiEvent::Paste("!".into()))
                .await?;
            assert_eq!(
                app.chat_widget.composer_text_with_pending(),
                "latest draft!"
            );
            app.handle_event(&mut tui, &mut session, AppEvent::OpenAgentsOverview)
                .await?;
            assert!(app.chat_widget.has_active_view());
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)),
            )
            .await?;
            assert_eq!(
                app.chat_widget.composer_text_with_pending(),
                "latest draft!"
            );
            available.store(
                !changed_child_permissions,
                std::sync::atomic::Ordering::SeqCst,
            );
            app.select_agent_thread(&mut tui, &mut session, child)
                .await?;
            assert_eq!(app.recap.progress(), child_recap);
            assert_eq!(app.primary_thread_id, Some(id));
            assert_eq!(
                app.chat_widget
                    .config_ref()
                    .permissions
                    .permission_profile(),
                &PermissionProfile::Disabled
            );
            if changed_child_permissions {
                app.runtime_approval_policy_override = Some(
                    RuntimeApprovalPolicyOverride::Explicit(AskForApproval::Never),
                );
                app.runtime_permission_profile_override = Some(
                    RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref()),
                );
                app.select_agent_thread(&mut tui, &mut session, id).await?;
                assert!(app.thread_unavailable(id));
                assert_eq!(app.current_displayed_thread_id(), Some(id));
                assert_eq!(
                    app.chat_widget
                        .config_ref()
                        .permissions
                        .permission_profile(),
                    &PermissionProfile::read_only()
                );
            }
            available.store(true, std::sync::atomic::Ordering::SeqCst);
            app.handle_event(
                &mut tui,
                &mut session,
                AppEvent::SelectAgentsOverviewThread { thread_id: id },
            )
            .await?;
            assert!(!app.thread_unavailable(id));
            assert_eq!(
                app.primary_session_configured,
                app.thread_event_channels[&id].store.lock().await.session
            );
            assert!(!app.agent_navigation.get(&id).unwrap().is_closed);
            app.agent_navigation.mark_running(id);
            assert!(app.agent_navigation.get(&id).unwrap().is_running);
            assert_eq!(
                app.chat_widget.composer_text_with_pending(),
                "latest draft!"
            );
            if changed_child_permissions {
                assert!(app.chat_widget.is_task_running_for_test());
                // From an empty draft, daemon Ctrl+C offers the existing Cancel task action.
                for key in [
                    KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL),
                    KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
                    KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
                ] {
                    app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(key))
                        .await?;
                }
                assert!(std::iter::from_fn(|| events.try_recv().ok())
                    .any(|event| matches!(event, AppEvent::RunningTaskExit { action: RunningTaskExitAction::CancelTask, thread_id } if thread_id == id)));
                app.handle_app_server_event(
                    &session,
                    codex_app_server_client::AppServerEvent::ServerNotification(Box::new(
                        turn_completed_notification(id, "saved", TurnStatus::Completed),
                    )),
                )
                .await;
                app.drain_active_thread_events(&mut tui).await?;
                app.chat_widget
                    .restore_user_message_to_composer("latest draft!".into());
            }
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            )
            .await?;
            while let Ok(event) = events.try_recv() {
                if matches!(event, AppEvent::CodexOp(AppCommand::UserTurn { .. })) {
                    app.handle_event(&mut tui, &mut session, event).await?;
                }
            }
            let channel = app.thread_event_channels.get(&id).unwrap();
            let event = ThreadBufferedEvent::Notification(Box::new(
                agent_message_delta_notification(id, "new-turn", "new-item", "fresh delivery"),
            ));
            channel.sender.send(event).await?;
            assert!(app.active_thread_rx.as_mut().unwrap().try_recv().is_ok());
        }
        session.shutdown().await?;
        let methods = server.await??;
        assert_eq!(
            methods
                .iter()
                .filter(|method| *method == "turn/start")
                .count(),
            usize::from(previous_thread.is_some())
        );
        assert_eq!(
            methods.iter().any(|method| method == "thread/resume"),
            previous_thread.is_some()
        );
        assert_eq!(
            methods
                .iter()
                .filter(|method| *method == "initialize")
                .count(),
            2 + usize::from(previous_thread.is_some())
        );
    }
    Ok(())
}

fn replacement_failure_keeps_current_task_and_restores_input() -> Result<()> {
    for fail_read in [false, true] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        let home = tempdir()?;
        app.config.codex_home = home.path().to_path_buf().abs();
        app.config.sqlite = SqliteConfig::new_for_testing(home.path().abs());
        let current = ThreadId::new();
        app.enqueue_primary_thread_session(
            test_thread_session(current, app.config.cwd.to_path_buf()),
            Vec::new(),
        )
        .await?;
        while events.try_recv().is_ok() {}
        let original_config = app.config.clone();
        let (mut server, requests, proxy) = start_recording_app_server_with_history(
            &app.config,
            HistoryCapabilities::ThreadStartFails,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
            crate::app_server_session::ThreadParamsMode::Embedded,
            LoaderOverrides::default(),
        )
        .await?;
        if fail_read {
            std::fs::write(home.path().join("config.toml"), "invalid = [")?;
        }
        let mut tui = crate::tui::test_support::make_test_tui()?;
        app.start_fresh_session(
            &mut tui,
            &mut server,
            /*session_start_source*/ None,
            Some("keep this request".into()),
            /*new_thread_name*/ None,
        )
        .await;
        assert_eq!(app.chat_widget.thread_id(), Some(current));
        assert_eq!(app.active_thread_id, Some(current));
        assert!(app.active_thread_rx.is_some());
        assert_eq!(app.config, original_config);
        assert_eq!(
            app.chat_widget.composer_text_with_pending(),
            "keep this request"
        );
        assert!(recorded_params(&requests, "thread/unsubscribe").is_empty());
        assert_eq!(
            recorded_params(&requests, "thread/start").len(),
            usize::from(!fail_read)
        );
        let errors = std::iter::from_fn(|| events.try_recv().ok())
            .filter_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => {
                    Some(lines_to_single_string(&cell.display_lines(/*width*/ 1000)))
                }
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");
        if fail_read {
            insta::assert_snapshot!(errors, @"■ Failed to read new session defaults: config/read failed in TUI");
        } else {
            insta::assert_snapshot!(errors, @"■ Failed to start a fresh session through the app server: thread/start failed during TUI bootstrap: thread/start failed: replacement unavailable (code -32603)");
        }
        server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn replacement_uses_server_defaults_and_preserves_explicit_launch_settings() -> Result<()> {
    for (managed_effort, explicit, expected_model, expected_effort) in [
        (None, "saved", "server-model", "high"),
        (Some("medium"), "model", "cli-model", "high"),
        (Some("medium"), "effort", "server-model", "low"),
        (None, "profile_model", "profile-model", "high"),
        (None, "profile_effort", "server-model", "low"),
        (None, "profile_summary", "server-model", "high"),
        (None, "profile_summary_off", "server-model", "high"),
        (None, "profile_summary_cli", "server-model", "high"),
        (Some("medium"), "profile_model", "profile-model", "high"),
        (Some("medium"), "profile_effort", "server-model", "low"),
        (Some(""), "profile", "profile-model", "low"),
        (Some("medium"), "profile", "profile-model", "low"),
        (
            Some("medium"),
            "profile_unrelated",
            "managed-model",
            "medium",
        ),
    ] {
        let (mut app, mut events, _ops) = make_test_app_with_channels().await;
        let server_home = tempdir()?;
        let client_home = tempdir()?;
        std::fs::write(
            server_home.path().join("work.config.toml"),
            "model = \"server-model\"\nmodel_reasoning_effort = \"high\"\n",
        )?;
        std::fs::write(
            client_home.path().join("config.toml"),
            "model = \"stale-client-model\"\nmodel_reasoning_effort = \"low\"\nmodel_reasoning_summary = \"detailed\"\nfeatures.concurrent_reasoning_summaries = true\n",
        )?;
        if let Some(effort) = managed_effort {
            let effort = if effort.is_empty() {
                String::new()
            } else {
                format!("model_reasoning_effort = {effort:?}\n")
            };
            std::fs::write(
                server_home.path().join("requirements.toml"),
                format!("[models.new_thread]\nmodel = \"managed-model\"\n{effort}"),
            )?;
        }
        let mut server_config = app.config.clone();
        server_config.codex_home = server_home.path().to_path_buf().abs();
        server_config.sqlite = SqliteConfig::new_for_testing(server_home.path().abs());
        let (mut server, requests, proxy) = start_recording_app_server_with_history(
            &server_config,
            HistoryCapabilities::Current,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
            if explicit.starts_with("profile_summary") {
                crate::app_server_session::ThreadParamsMode::Embedded
            } else {
                crate::app_server_session::ThreadParamsMode::Remote
            },
            LoaderOverrides {
                user_config_path: Some(server_home.path().join("work.config.toml").abs()),
                user_config_profile: Some("work".parse()?),
                system_requirements_path: Some(server_home.path().join("requirements.toml")),
                ..LoaderOverrides::default()
            },
        )
        .await?;
        server = server.with_remote_cwd_override(Some(server_config.cwd.to_path_buf()));
        server.bootstrap(&server_config).await?;
        app.config.codex_home = client_home.path().to_path_buf().abs();
        app.config.sqlite = SqliteConfig::new_for_testing(client_home.path().abs());
        app.chat_widget
            .handle_thread_session_quiet(test_thread_session(
                ThreadId::new(),
                client_home.path().to_path_buf(),
            ));
        match explicit {
            "model" => app.harness_overrides.model = Some("cli-model".to_string()),
            "effort" => app.cli_kv_overrides.push((
                "model_reasoning_effort".to_string(),
                TomlValue::String("low".to_string()),
            )),
            profile @ ("profile"
            | "profile_model"
            | "profile_effort"
            | "profile_unrelated"
            | "profile_summary"
            | "profile_summary_off"
            | "profile_summary_cli") => {
                let path = client_home.path().join("work.config.toml");
                std::fs::write(
                    &path,
                    match profile {
                        "profile_model" => "model = \"profile-model\"\n",
                        "profile_effort" => "model_reasoning_effort = \"low\"\n",
                        "profile_unrelated" => "model_verbosity = \"low\"\n",
                        "profile_summary" => {
                            "model_reasoning_summary = \"detailed\"\nfeatures.concurrent_reasoning_summaries = true\n"
                        }
                        "profile_summary_off" | "profile_summary_cli" => {
                            "model_reasoning_summary = \"detailed\"\nfeatures.concurrent_reasoning_summaries = false\n"
                        }
                        _ => "model = \"profile-model\"\nmodel_reasoning_effort = \"low\"\n",
                    },
                )?;
                app.loader_overrides.user_config_path = Some(path.abs());
                app.loader_overrides.user_config_profile = Some("work".parse()?);
            }
            _ => {}
        }
        if explicit == "profile_summary_cli" {
            app.cli_kv_overrides.push((
                "features.concurrent_reasoning_summaries".into(),
                true.into(),
            ));
        }
        if explicit.starts_with("profile_summary") {
            app.app_server_target = AppServerTarget::LocalDaemon {
                allow_embedded_fallback: true,
                endpoint: crate::RemoteAppServerEndpoint::UnixSocket {
                    socket_path: client_home.path().join("daemon.sock").abs(),
                },
            };
            app.open_agents_overview(&server);
        }
        let mut tui = crate::tui::test_support::make_test_tui()?;
        app.start_fresh_session(
            &mut tui,
            &mut server,
            /*session_start_source*/ None,
            /*initial_user_message*/ None,
            /*new_thread_name*/ None,
        )
        .await;
        let starts = recorded_params(&requests, "thread/start");
        assert_eq!(starts.len(), 1);
        assert_eq!(
            (
                starts[0]["config"].get("model_reasoning_summary"),
                starts[0]["config"]["features"].get("concurrent_reasoning_summaries"),
            ),
            (
                explicit
                    .starts_with("profile_summary")
                    .then_some(&serde_json::json!("detailed")),
                explicit
                    .starts_with("profile_summary")
                    .then_some(&serde_json::json!(explicit != "profile_summary_off")),
            ),
            "{explicit}",
        );
        assert_eq!(
            (
                &starts[0]["model"],
                &starts[0]["config"]["model_reasoning_effort"]
            ),
            (
                &serde_json::json!(expected_model),
                &serde_json::json!(expected_effort)
            ),
        );
        assert_eq!(
            recorded_params(&requests, "config/read"),
            vec![
                serde_json::json!({"cwd": if explicit.starts_with("profile_summary") {
                    client_home.path().display().to_string()
                } else {
                    server_config.cwd.display().to_string()
                }, "includeLayers": true})
            ],
        );
        if explicit == "saved" {
            let rendered = render_bottom_popup(&app.chat_widget, /*width*/ 80)
                .replace(&server_config.cwd.display().to_string(), "<PROJECT>");
            insta::assert_snapshot!(rendered, @r"
            › Ask Codex to do anything

              server-model high · <PROJECT>
            ");
        }
        if explicit.starts_with("profile_summary") {
            // Opening the overview starts background RPCs. Let them finish before
            // closing the client so the proxy is not writing to a closed socket.
            loop {
                let event = events.recv().await.expect("agents overview refresh");
                if matches!(event, AppEvent::AgentsOverviewThreadsLoaded { .. }) {
                    break;
                }
            }
        }
        server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn stale_history_completions_preserve_the_current_request_and_failure_can_retry() -> Result<()>
{
    let (mut app, _codex_home, thread_id) =
        completed_history_app(&["Oldest", "Middle", "Newest"]).await?;
    let (mut app_server, _requests, proxy) = start_recording_app_server(
        &app.config,
        /*blocked_thread_list*/ None,
        /*failed_thread_name*/ None,
    )
    .await?;
    let started = app_server
        .resume_thread(
            &app.local_settings,
            app.config.clone(),
            thread_id,
            crate::app_server_session::ResumeModelSettings::RestoreFromThread,
        )
        .await?;
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    app.scrollback_has_older_history = app_server.has_older_history(thread_id);
    app.transcript_view.history = TranscriptHistoryState::LoadingBeginning;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    let cursor = app_server
        .begin_older_history_page(thread_id)
        .expect("older page");
    let page = app_server
        .thread_items_page(
            thread_id,
            /*turn_id*/ None,
            Some(cursor.clone()),
            /*limit*/ 1,
        )
        .await?;
    for result in [Ok(page.clone()), Err("obsolete request failed".to_string())] {
        app.handle_older_history_page(
            &mut tui,
            &mut app_server,
            thread_id,
            "obsolete-cursor",
            result,
        )
        .await?;
        assert_eq!(
            (
                app.transcript_cells.len(),
                app.transcript_view.history,
                app_server.is_older_history_page_pending(thread_id, &cursor),
            ),
            (0, TranscriptHistoryState::LoadingBeginning, true),
        );
    }
    let failure = AppEvent::OlderThreadHistoryLoaded {
        thread_id,
        cursor: cursor.clone(),
        result: Err("current request failed".to_string()),
    };
    Box::pin(app.handle_event(&mut tui, &mut app_server, failure)).await?;
    app.handle_owned_transcript_event(&mut tui, &mut app_server, &TuiEvent::Draw)?;
    assert_eq!(
        (
            app.transcript_view.history,
            app_server.is_older_history_page_pending(thread_id, &cursor),
        ),
        (TranscriptHistoryState::Failed, false),
    );
    assert_eq!(
        app_server.begin_older_history_page(thread_id),
        Some(cursor.clone())
    );
    app_server.cancel_older_history_page(thread_id, "obsolete-cursor");
    assert!(app_server.is_older_history_page_pending(thread_id, &cursor));
    app.transcript_view.history = TranscriptHistoryState::LoadingOlder;
    // Initialize the viewport as the app's first draw does before accepting Find input.
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 80, /*height*/ 1,
    );
    let mut buffer = Buffer::empty(area);
    app.transcript_view
        .render(area, &mut buffer, &app.transcript_cells);
    app.transcript_view
        .jump_to_entry(&app.transcript_cells, /*index*/ 0);
    app.transcript_view.begin_search();
    app.transcript_view.paste_search("Middle answer");
    app.transcript_view.advance_search(&app.transcript_cells);
    let next_cursor = page.next_cursor.clone().expect("another older page");
    app.handle_older_history_page(&mut tui, &mut app_server, thread_id, &cursor, Ok(page))
        .await?;
    assert_eq!(app.transcript_view.history, TranscriptHistoryState::Partial);
    assert!(!app.transcript_cells.is_empty());
    // The received page must be searched before another page can start, even near the top.
    assert!(!app_server.is_older_history_page_pending(thread_id, &next_cursor));
    // Scanning yields after the completion footer before reaching the answer in the same page.
    for _ in 0..8 {
        if !app.transcript_view.advance_search(&app.transcript_cells) {
            break;
        }
    }
    app.transcript_view
        .render(area, &mut buffer, &app.transcript_cells);
    let rendered = buffer
        .content()
        .iter()
        .map(ratatui::buffer::Cell::symbol)
        .collect::<String>();
    assert!(rendered.contains("Middle answer"), "rendered: {rendered:?}",);

    assert_eq!(
        app_server.begin_older_history_page(thread_id),
        Some(next_cursor.clone())
    );
    app.handle_older_history_page(
        &mut tui,
        &mut app_server,
        thread_id,
        &cursor,
        Err("previous page failed late".to_string()),
    )
    .await?;
    assert!(app_server.is_older_history_page_pending(thread_id, &next_cursor));
    let history = app.transcript_view.history;
    let cell_count = app.transcript_cells.len();
    app.chat_widget.handle_thread_session(test_thread_session(
        ThreadId::new(),
        app.config.cwd.to_path_buf(),
    ));
    app.handle_older_history_page(
        &mut tui,
        &mut app_server,
        thread_id,
        &next_cursor,
        Err("previous thread failed late".to_string()),
    )
    .await?;
    assert_eq!(
        (
            app.transcript_view.history,
            app.transcript_cells.len(),
            app_server.is_older_history_page_pending(thread_id, &next_cursor),
        ),
        (history, cell_count, false),
    );
    tui.set_owned_screen(/*owned*/ false)?;
    app_server.shutdown().await?;
    proxy.await??;
    Ok(())
}

fn beginning_navigation_holds_the_view_until_the_last_page_arrives() -> Result<()> {
    for initial_scroll in [0, -1] {
        let (mut app, _codex_home, thread_id) =
            completed_history_app(&["Oldest", "Middle", "Newest"]).await?;
        let (mut app_server, _requests, proxy) = start_recording_app_server(
            &app.config,
            /*blocked_thread_list*/ None,
            /*failed_thread_name*/ None,
        )
        .await?;
        let started = app_server
            .resume_thread(
                &app.local_settings,
                app.config.clone(),
                thread_id,
                crate::app_server_session::ResumeModelSettings::RestoreFromThread,
            )
            .await?;
        app.transcript_cells = crate::thread_transcript::thread_items_to_transcript_cells(
            Some(thread_id),
            &app.config.cwd,
            started.turns.iter().flat_map(|turn| turn.items.clone()),
            crate::thread_transcript::RawReasoningVisibility::Hidden,
            Some(&app.config),
        );
        app.enqueue_primary_thread_session(started.session, started.turns)
            .await?;
        let (event_tx, mut event_rx) = tokio::sync::mpsc::unbounded_channel();
        app.app_event_tx = crate::app_event_sender::AppEventSender::new(event_tx);
        app.scrollback_has_older_history = app_server.has_older_history(thread_id);
        app.transcript_view.history = TranscriptHistoryState::Partial;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        tui.set_owned_screen(/*owned*/ true)?;
        let size = ratatui::layout::Size::new(/*width*/ 80, /*height*/ 12);
        let render = |app: &mut App, tui: &mut tui::Tui| -> Result<Buffer> {
            tui.screen_size_for_event(&TuiEvent::Resize(size))?;
            let bottom = app.render_owned_transcript(tui, size)?;
            let area = Rect::new(/*x*/ 0, /*y*/ 0, size.width, bottom.y);
            let mut buffer = Buffer::empty(area);
            app.transcript_view
                .render(area, &mut buffer, &app.transcript_cells);
            Ok(buffer)
        };
        render(&mut app, &mut tui)?;
        if initial_scroll != 0 {
            app.transcript_view
                .scroll(&app.transcript_cells, initial_scroll);
        }
        let before = render(&mut app, &mut tui)?;

        // Hold a small first page so the test can inspect each request/completion boundary.
        let cursor = app_server
            .begin_older_history_page(thread_id)
            .expect("older page");
        let first_page = app_server
            .thread_items_page(
                thread_id,
                /*turn_id*/ None,
                Some(cursor.clone()),
                /*limit*/ 1,
            )
            .await?;
        let final_cursor = first_page.next_cursor.clone().expect("another older page");
        tui.screen_size_for_event(&TuiEvent::Resize(size))?;
        assert!(app.handle_owned_transcript_event(
            &mut tui,
            &mut app_server,
            &TuiEvent::Key(KeyEvent::new(KeyCode::Char('<'), KeyModifiers::ALT)),
        )?);
        assert_eq!(
            (render(&mut app, &mut tui)?, app.transcript_view.history),
            (before.clone(), TranscriptHistoryState::LoadingBeginning),
        );
        app.handle_older_history_page(
            &mut tui,
            &mut app_server,
            thread_id,
            &cursor,
            Ok(first_page),
        )
        .await?;
        assert!(app_server.is_older_history_page_pending(thread_id, &final_cursor));
        let final_event = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), event_rx.recv())
            .await?
            .expect("final page completion");
        assert!(matches!(
            &final_event,
            AppEvent::OlderThreadHistoryLoaded { result: Ok(page), .. }
                if page.next_cursor.is_none()
        ));
        // A draw while the completion is waiting must leave the viewport and loading intent intact.
        app.handle_owned_transcript_event(&mut tui, &mut app_server, &TuiEvent::Draw)?;
        assert_eq!(
            (render(&mut app, &mut tui)?, app.transcript_view.history),
            (before, TranscriptHistoryState::LoadingBeginning),
        );
        Box::pin(app.handle_event(&mut tui, &mut app_server, final_event)).await?;
        let final_buffer = render(&mut app, &mut tui)?;
        let visible = final_buffer
            .content()
            .iter()
            .map(ratatui::buffer::Cell::symbol)
            .collect::<String>();
        assert!(visible.contains("Oldest prompt"), "visible: {visible}");
        assert_eq!(
            (
                app.transcript_view.history,
                app.transcript_view.is_following(),
                app_server.has_older_history(thread_id),
            ),
            (TranscriptHistoryState::Complete, false, false),
        );
        tui.set_owned_screen(/*owned*/ false)?;
        app_server.shutdown().await?;
        proxy.await??;
    }
    Ok(())
}

fn open_patch(app: &mut App, rx: &mut UnboundedReceiver<AppEvent>) -> ApplyPatchApprovalRequest {
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Char('a'), KeyModifiers::CONTROL));
    let mut fullscreen = None;
    while let Ok(event) = rx.try_recv() {
        match event {
            AppEvent::FullScreenApprovalRequest(ApprovalRequest::ApplyPatch(request)) => {
                assert!(fullscreen.replace(request).is_none());
            }
            AppEvent::SubmitThreadOp { .. } => panic!("opening the pager must not decide approval"),
            _ => {}
        }
    }
    fullscreen.expect("Ctrl+A should open the pending patch")
}

fn assert_decision(
    app: &mut App,
    rx: &mut UnboundedReceiver<AppEvent>,
    thread_id: ThreadId,
    decision: FileChangeApprovalDecision,
) {
    let mut submitted = Vec::new();
    while let Ok(event) = rx.try_recv() {
        if let AppEvent::SubmitThreadOp { thread_id, op } = event {
            submitted.push((thread_id, op));
        }
    }
    let expected_op = AppCommand::patch_approval(ITEM_ID.to_string(), decision.clone());
    assert_eq!(submitted, vec![(thread_id, expected_op.clone())]);
    let thread_id = thread_id.to_string();
    assert_eq!(
        app.pending_app_server_requests
            .take_resolution(&thread_id, expected_op.clone()),
        Ok(Some(AppServerRequestResolution {
            request_id: AppServerRequestId::Integer(17),
            result: serde_json::json!({ "decision": decision }),
        }))
    );
    assert_eq!(
        app.pending_app_server_requests
            .take_resolution(&thread_id, expected_op),
        Ok(None)
    );
}

