fn active_patch_approval_pager_preserves_changes_and_accepts_once() -> Result<()> {
    let (mut app, mut rx, _op_rx) = make_test_app_with_channels().await;
    let thread_id = ThreadId::new();
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut app_server = start_config_write_test_app_server(&app).await?;
    enqueue_pending_patch(&mut app, thread_id).await?;
    drain_pending_patch(&mut app, &mut tui).await?;

    let request = open_patch(&mut app, &mut rx);
    assert_eq!(request.changes, expected_changes());
    assert_eq!(request.id, ITEM_ID);
    app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::FullScreenApprovalRequest(ApprovalRequest::ApplyPatch(request)),
    )
    .await?;
    let first = render_pager(&mut app, /*width*/ 48, /*height*/ 11);
    insta::with_settings!({snapshot_path => "../../snapshots"}, {
        insta::assert_snapshot!("patch_approval_pager_top", format!("{first:?}"));
    });

    app.handle_tui_event(
        &mut tui,
        &mut app_server,
        TuiEvent::Key(KeyEvent::new(KeyCode::End, KeyModifiers::NONE)),
    )
    .await?;
    let last = render_pager(&mut app, /*width*/ 48, /*height*/ 11);
    insta::with_settings!({snapshot_path => "../../snapshots"}, {
        insta::assert_snapshot!("patch_approval_pager_bottom", format!("{last:?}"));
    });
    let _ = render_pager(&mut app, /*width*/ 36, /*height*/ 7);
    assert_eq!(render_pager(&mut app, /*width*/ 48, /*height*/ 11), last);

    app.handle_tui_event(
        &mut tui,
        &mut app_server,
        TuiEvent::Key(KeyEvent::new(KeyCode::Char('q'), KeyModifiers::NONE)),
    )
    .await?;
    assert!(app.overlay.is_none());
    assert!(
        app.pending_app_server_requests
            .contains_server_request(&self::request(thread_id))
    );
    assert_eq!(open_patch(&mut app, &mut rx).changes, expected_changes());
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE));
    assert_decision(
        &mut app,
        &mut rx,
        thread_id,
        FileChangeApprovalDecision::Accept,
    );
    Ok(())
}

fn inline_server_permission_selection_holds_queued_prompt_until_confirmation() -> Result<()> {
    let (mut app, mut events, mut ops) = make_test_app_with_channels().await;
    let home = tempdir()?;
    std::fs::write(
        home.path().join("config.toml"),
        "default_permissions = \":workspace\"\n[permissions.server-only]\nextends = \":read-only\"\n",
    )?;
    let server_config = ConfigBuilder::default()
        .codex_home(home.path().into())
        .build()
        .await?;
    let mut server = crate::start_embedded_app_server_for_picker(&server_config).await?;
    let started = server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    while events.try_recv().is_ok() {}
    while ops.try_recv().is_ok() {}

    app.chat_widget.select_permission_profile("server-only");
    assert!(app.chat_widget.queue_user_message_with_options(
        crate::chatwidget::UserMessage::from("use the selected profile"),
        crate::bottom_pane::QueuedInputAction::Plain,
        Vec::new(),
    ));
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut settings_settled = false;
    for _ in 0..20 {
        if app
            .agents_overview
            .requested_permission_profiles
            .contains_key(&thread_id)
        {
            break;
        }
        let event = tokio::time::timeout(std::time::Duration::from_secs(/*secs*/ 2), events.recv())
            .await?
            .expect("app event channel should remain open");
        app.handle_event(&mut tui, &mut server, event).await?;
    }
    assert!(
        app.agents_overview
            .requested_permission_profiles
            .contains_key(&thread_id)
    );
    while let Ok(event) = events.try_recv() {
        app.handle_event(&mut tui, &mut server, event).await?;
    }
    assert!(ops.try_recv().is_err());

    let settings = next_thread_settings_updated(&mut server, thread_id).await;
    app.enqueue_thread_notification(
        thread_id,
        ServerNotification::ThreadSettingsUpdated(settings),
    )
    .await?;
    for _ in 0..20 {
        let event = tokio::time::timeout(std::time::Duration::from_secs(/*secs*/ 2), events.recv())
            .await?
            .expect("app event channel should remain open");
        let settled = matches!(event, AppEvent::SettingsSelectionSettled);
        app.handle_event(&mut tui, &mut server, event).await?;
        if settled {
            settings_settled = true;
            break;
        }
    }
    assert!(settings_settled);

    let Op::UserTurn { items, .. } = next_user_turn_op(&mut ops) else {
        panic!("expected queued user turn");
    };
    assert_eq!(
        items,
        vec![AppServerUserInput::Text {
            text: "use the selected profile".to_string(),
            text_elements: Vec::new(),
        }]
    );
    server.shutdown().await?;
    Ok(())
}

fn custom_permission_selection_uses_server_definition_and_preserves_state_on_rejection()
-> Result<()> {
    let (mut app, mut events, _ops) = make_test_app_with_channels().await;
    app.config.ephemeral = false;
    let home = tempdir()?;
    std::fs::write(
        home.path().join("config.toml"),
        "default_permissions = \":workspace\"\n[permissions.shared]\nextends = \":workspace\"\n",
    )?;
    let server_config = ConfigBuilder::default()
        .codex_home(home.path().into())
        .build()
        .await?;
    let mut server = crate::start_embedded_app_server_for_picker(&server_config).await?;
    let started = server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    let client_home = tempdir()?;
    std::fs::write(
        client_home.path().join("config.toml"),
        "default_permissions = \":workspace\"\n[permissions.shared]\nextends = \":danger-full-access\"\n",
    )?;
    let client_config = ConfigBuilder::default()
        .codex_home(client_home.path().into())
        .build()
        .await?;
    app.config.codex_home = client_config.codex_home;
    app.config.custom_permission_profiles = client_config.custom_permission_profiles;
    let selection = PermissionProfileSelection {
        profile_id: "shared".into(),
        approval_policy: Some(AskForApproval::Never),
        approvals_reviewer: None,
        display_label: "shared".into(),
    };
    app.chat_widget.handle_server_notification(
        turn_started_notification(thread_id, "turn-1"),
        /*replay_kind*/ None,
    );
    assert!(app.chat_widget.is_user_turn_pending_or_running());
    let before = RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref());
    app.select_permission_profile(&mut server, selection.clone())
        .await;
    assert_eq!(
        RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref()),
        before
    );
    let settings = next_thread_settings_updated(&mut server, thread_id).await;
    let expected = PermissionProfile::from_legacy_sandbox_policy_for_cwd(
        &settings.thread_settings.sandbox_policy.to_core(),
        settings.thread_settings.cwd.as_path(),
    );
    assert!(matches!(
        settings.thread_settings.sandbox_policy,
        codex_app_server_protocol::SandboxPolicy::WorkspaceWrite { .. }
    ));
    app.enqueue_thread_notification(
        thread_id,
        ServerNotification::ThreadSettingsUpdated(settings),
    )
    .await?;
    assert_eq!(
        (
            app.chat_widget
                .config_ref()
                .permissions
                .permission_profile(),
            app.chat_widget
                .config_ref()
                .permissions
                .approval_policy
                .value()
        ),
        (&expected, AskForApproval::Never.to_core())
    );
    std::fs::write(
        home.path().join("config.toml"),
        "default_permissions = \":workspace\"\n[permissions.shared]\nextends = \":read-only\"\n[permissions.other]\nextends = \":read-only\"\n",
    )?;
    app.select_permission_profile(
        &mut server,
        PermissionProfileSelection {
            approval_policy: None,
            ..selection.clone()
        },
    )
    .await;
    let settings = next_thread_settings_updated(&mut server, thread_id).await;
    assert!(matches!(
        settings.thread_settings.sandbox_policy,
        codex_app_server_protocol::SandboxPolicy::ReadOnly { .. }
    ));
    app.enqueue_thread_notification(
        thread_id,
        ServerNotification::ThreadSettingsUpdated(settings),
    )
    .await?;
    app.chat_widget.handle_server_notification(
        turn_completed_notification(thread_id, "turn-1", TurnStatus::Completed),
        /*replay_kind*/ None,
    );
    // Unchanged re-selection is accepted without requiring a notification.
    app.select_permission_profile(&mut server, selection.clone())
        .await;
    assert!(!app.reject_pending_permission_change());
    assert!(app.agents_overview.requested_permission_profiles.is_empty());
    // Another client's policy change must not leave a no-op request's old policy behind.
    server
        .thread_settings_update(ThreadSettingsUpdateParams {
            thread_id: thread_id.to_string(),
            approval_policy: Some(AskForApproval::OnRequest),
            ..Default::default()
        })
        .await?;
    let settings = next_thread_settings_updated(&mut server, thread_id).await;
    app.enqueue_thread_notification(
        thread_id,
        ServerNotification::ThreadSettingsUpdated(settings),
    )
    .await?;
    app.select_permission_profile(
        &mut server,
        PermissionProfileSelection {
            profile_id: "other".into(),
            approval_policy: None,
            approvals_reviewer: None,
            display_label: "other".into(),
        },
    )
    .await;
    assert_eq!(
        app.agents_overview.requested_permission_profiles[&thread_id].approval_policy,
        Some(AskForApproval::OnRequest)
    );
    let settings = next_thread_settings_updated(&mut server, thread_id).await;
    app.enqueue_thread_notification(
        thread_id,
        ServerNotification::ThreadSettingsUpdated(settings),
    )
    .await?;
    assert!(app.agents_overview.requested_permission_profiles.is_empty());
    let confirmed = RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref());
    let confirmed_config = app.config.clone();
    app.select_permission_profile(
        &mut server,
        PermissionProfileSelection {
            profile_id: "missing-on-server".into(),
            ..selection
        },
    )
    .await;
    assert_eq!(
        RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref()),
        confirmed
    );
    assert!(!app.pending_server_profiles.contains_key(&thread_id));
    assert_eq!(app.config, confirmed_config);
    assert_eq!(
        app.agents_overview
            .selected_permission_profiles
            .get(&thread_id)
            .map(String::as_str),
        Some("other")
    );
    // Materialize the task so /fork exercises persisted history with the confirmed profile.
    server.thread_inject_items(thread_id, vec![serde_json::from_value(serde_json::json!({
        "type": "message", "role": "assistant", "content": [{"type": "output_text", "text": "saved history"}]
    }))?]).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    while events.try_recv().is_ok() {}
    let side = server
        .fork_side_thread(
            &app.local_settings,
            app.config.clone(),
            thread_id,
            app.agents_overview
                .requested_permission_profiles
                .get(&thread_id),
        )
        .await?;
    assert_eq!(
        (
            side.session.permission_profile,
            side.session.approval_policy
        ),
        (PermissionProfile::read_only(), AskForApproval::OnRequest)
    );
    app.cli_kv_overrides.push((
        "permissions.other.extends".into(),
        TomlValue::String(":danger-full-access".into()),
    ));
    // Both the accepted request and its confirmed descendant remain server-owned.
    for _ in 0..2 {
        let previous_thread_id = app.chat_widget.thread_id();
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::ForkCurrentSession { name: None },
        )
        .await?;
        assert_ne!(app.chat_widget.thread_id(), previous_thread_id);
        assert_eq!(
            RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref()),
            confirmed
        );
    }
    server.shutdown().await?;
    Ok(())
}

fn successful_plugin_uninstall_dispatches_plugin_list_refresh() -> Result<()> {
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let cwd = app.chat_widget.config_ref().cwd.to_path_buf();
    while app_event_rx.try_recv().is_ok() {}

    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(
        app.chat_widget.config_ref(),
    ))
    .await?;
    let control = Box::pin(app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::PluginUninstallLoaded {
            cwd: cwd.clone(),
            plugin_id: "plugin-docs".to_string(),
            plugin_display_name: "Docs".to_string(),
            result: Ok(PluginUninstallResponse {}),
        },
    ))
    .await?;
    assert!(matches!(control, AppRunControl::Continue));

    let refresh_result = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            match app_event_rx.recv().await {
                Some(AppEvent::PluginsLoaded {
                    cwd: event_cwd,
                    result,
                }) if event_cwd == cwd => break result,
                Some(_) => {}
                None => panic!("app event channel closed before plugin refresh completed"),
            }
        }
    })
    .await
    .expect("dispatcher should initiate a plugin list refresh");
    refresh_result.expect("plugin list refresh should succeed");

    app_server.shutdown().await?;
    Ok(())
}

fn projectless_permissions_survive_session_transitions_without_trust() -> Result<()> {
    let (mut app, mut events, _) = make_test_app_with_channels().await;
    let home = tempfile::tempdir()?;
    app.config.codex_home = home.path().to_path_buf().abs();
    app.config.sqlite = codex_state::SqliteConfig::new_for_testing(home.path().abs());
    let source = tempfile::tempdir()?;
    let destination = tempfile::tempdir()?;
    let model = core_test_support::responses::start_mock_server().await;
    let response = core_test_support::responses::mount_sse_once(
        &model,
        core_test_support::responses::sse(vec![
            core_test_support::responses::ev_response_created("saved-permissions"),
            core_test_support::responses::ev_completed("saved-permissions"),
        ]),
    )
    .await;
    std::fs::write(
        home.path().join("config.toml"),
        format!(
            r#"model = "gpt-5.2"
model_provider = "test"
[model_providers.test]
name = "test"
base_url = "{}/v1"
wire_api = "responses"
[windows]
sandbox = "unelevated"
"#,
            model.uri()
        ),
    )?;
    app.config = app
        .rebuild_config_for_cwd(source.path().to_path_buf())
        .await?;
    app.chat_widget
        .handle_thread_session_quiet(test_thread_session(
            ThreadId::new(),
            source.path().to_path_buf(),
        ));
    let mut server = crate::start_embedded_app_server_for_picker(&app.config).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.pause_events();
    app.start_fresh_session(
        &mut tui,
        &mut server,
        /*session_start_source*/ None,
        /*initial_user_message*/ None,
        /*new_thread_name*/ None,
    )
    .await;
    assert!(
        app.config
            .permissions
            .permission_profile()
            .file_system_sandbox_policy()
            .can_write_local_path_with_cwd(source.path(), source.path())
    );
    assert!(matches!(
        app.config.permissions.approval_policy.value(),
        codex_protocol::protocol::AskForApproval::Granular(_)
    ));
    // Saving history must not turn implicit writable defaults into read-only on /cd.
    server
        .thread_inject_items(
            app.chat_widget.thread_id().expect("fresh task"),
            vec![App::side_boundary_prompt_item()],
        )
        .await?;
    let fresh_destination = tempfile::tempdir()?;
    for cwd in [fresh_destination.path(), source.path()] {
        assert!(
            app.chat_widget
                .rollout_path()
                .as_deref()
                .is_some_and(rollout_path_is_resumable)
        );
        app.change_working_directory(&mut tui, &mut server, cwd.abs())
            .await;
        assert_eq!(app.config.cwd.as_path(), cwd);
        assert_eq!(
            app.config.permissions.active_permission_profile(),
            Some(ActivePermissionProfile::new(":workspace"))
        );
        assert!(matches!(
            app.config.permissions.approval_policy.value(),
            codex_protocol::protocol::AskForApproval::Granular(_)
        ));
    }
    let mut readonly = app.config.clone();
    readonly
        .permissions
        .set_permission_profile_from_session_snapshot(PermissionProfileSnapshot::active(
            PermissionProfile::read_only(),
            ActivePermissionProfile::new(":read-only"),
        ))?;
    let saved = server.start_thread(&readonly).await?;
    server
        .thread_inject_items(
            saved.session.thread_id,
            vec![App::side_boundary_prompt_item()],
        )
        .await?;
    tui.pause_events();
    app.launch_cwd = source.path().to_path_buf();
    let backend_id = server.backend_id();
    app.resume_target_session(
        &mut tui,
        &mut server,
        SessionTarget {
            backend_id,
            path: None,
            thread_id: saved.session.thread_id,
            cwd: Some(source.path().to_path_buf()),
            history_mode: None,
        },
    )
    .await?;
    assert_eq!(app.chat_widget.thread_id(), Some(saved.session.thread_id));
    assert_eq!(
        app.config.permissions.active_permission_profile(),
        Some(ActivePermissionProfile::new(":read-only"))
    );
    // A normal turn must leave the saved profile on the server, even though the
    // widget knows its ID. Complete the turn so /cd exercises saved history.
    while events.try_recv().is_ok() {}
    app.chat_widget.apply_external_edit("hello".into());
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
    let op = std::iter::from_fn(|| events.try_recv().ok())
        .find_map(|event| match event {
            AppEvent::CodexOp(op @ AppCommand::UserTurn { .. }) => Some(op),
            _ => None,
        })
        .expect("user turn");
    assert!(
        app.try_submit_active_thread_op_via_app_server(&mut server, saved.session.thread_id, &op)
            .await?
    );
    tokio::time::timeout(Duration::from_secs(/*secs*/ 30), async {
        loop {
            let page = server
                .thread_turns_page(
                    saved.session.thread_id,
                    /*cursor*/ None,
                    /*limit*/ 1,
                )
                .await?;
            if page
                .data
                .first()
                .is_some_and(|turn| turn.status == codex_app_server_protocol::TurnStatus::Completed)
            {
                return Ok::<_, color_eyre::Report>(());
            }
            tokio::time::sleep(Duration::from_millis(/*millis*/ 10)).await;
        }
    })
    .await??;
    response.single_request();
    let (next, _) = app.load_new_session_config(&server).await?;
    assert_eq!(
        next.permissions.permission_profile(),
        &PermissionProfile::workspace_write()
    );
    let before = app.chat_widget.thread_id();
    app.change_working_directory(
        &mut tui,
        &mut server,
        destination.path().to_path_buf().abs(),
    )
    .await;
    assert_eq!(app.config.cwd.as_path(), destination.path());
    assert_ne!(app.chat_widget.thread_id(), before);
    assert!(
        !app.config
            .permissions
            .effective_permission_profile()
            .file_system_sandbox_policy()
            .can_write_local_path_with_cwd(destination.path(), destination.path())
    );
    assert!(!std::fs::read_to_string(home.path().join("config.toml"))?.contains("trust_level"));
    let untrusted = tempfile::tempdir()?;
    let config_path = home.path().join("config.toml");
    std::fs::write(
        &config_path,
        format!(
            "{}\n[projects.{}]\ntrust_level = \"untrusted\"\n",
            std::fs::read_to_string(&config_path)?,
            serde_json::to_string(untrusted.path())?
        ),
    )?;
    app.change_working_directory(&mut tui, &mut server, untrusted.path().abs())
        .await;
    assert_eq!(
        (
            app.config.cwd.as_path(),
            app.config.permissions.approval_policy.value()
        ),
        (
            untrusted.path(),
            codex_protocol::protocol::AskForApproval::UnlessTrusted
        )
    );
    // A new task in a marked project still gets implicit defaults when leaving it.
    std::fs::create_dir(untrusted.path().join(".codex"))?;
    std::fs::write(untrusted.path().join(".codex/config.toml"), "")?;
    crate::config_update::write_trusted_project(server.request_handle(), untrusted.path()).await?;
    app.new_agents_overview_session(&mut tui, &mut server, Some(untrusted.path().abs()))
        .await?;
    server
        .thread_inject_items(
            app.chat_widget.thread_id().expect("new project task"),
            vec![App::side_boundary_prompt_item()],
        )
        .await?;
    app.change_working_directory(&mut tui, &mut server, source.path().abs())
        .await;
    assert_eq!(
        (
            app.config.cwd.as_path(),
            app.config.permissions.active_permission_profile()
        ),
        (
            source.path(),
            Some(ActivePermissionProfile::new(":workspace"))
        )
    );
    server.shutdown().await?;
    Ok(())
}

fn quick_dials_respect_profile_and_external_ownership() -> Result<()> {
    let (mut app, mut events, _ops) = make_test_app_with_channels().await;
    let codex_home = app.config.codex_home.to_path_buf();
    let base_path = app.local_settings.user_config_path.clone();
    let profile_path = AbsolutePathBuf::from_absolute_path(codex_home.join("work.config.toml"))?;
    std::fs::write(
        base_path.as_path(),
        "[tui.presets.1]\ninput = 'base prompt'\nlabel = 'base label'\n",
    )?;
    std::fs::write(
        profile_path.as_path(),
        "[tui.presets.1]\ninput = 'profile prompt'\n",
    )?;
    let mut loader_overrides = LoaderOverrides::without_managed_config_for_tests();
    loader_overrides.user_config_path = Some(profile_path.clone());
    loader_overrides.user_config_profile = Some("work".parse()?);
    let external =
        toml::from_str::<toml::Value>("input = 'externally managed prompt'\nlabel = 'external'\n")?;
    let config = ConfigBuilder::default()
        .codex_home(codex_home)
        .loader_overrides(loader_overrides)
        .cli_overrides(vec![("tui.presets.2".into(), external)])
        .build()
        .await?;
    app.config.config_layer_stack = config.config_layer_stack.clone();
    app.local_settings = crate::local_settings::LocalSettings::from(&config);
    app.chat_widget.local_settings = app.local_settings.clone();

    let replacement = QuickDial {
        input: "replacement prompt".into(),
        label: None,
    };
    app.save_quick_dial(/*slot*/ 1, Some(replacement.clone()))
        .await;
    assert_eq!(
        toml::from_str::<toml::Value>(&std::fs::read_to_string(profile_path.as_path())?)?,
        toml::from_str::<toml::Value>(
            "[tui.presets.1]\ninput = 'replacement prompt'\nlabel = ''\n"
        )?
    );
    assert_eq!(
        std::fs::read_to_string(base_path.as_path())?,
        "[tui.presets.1]\ninput = 'base prompt'\nlabel = 'base label'\n"
    );

    while events.try_recv().is_ok() {}
    let profile_before_rejections = std::fs::read(profile_path.as_path())?;
    let dials_before_rejections = app.local_settings.tui.quick_dials.clone();
    app.save_quick_dial(/*slot*/ 1, /*dial*/ None).await;
    app.save_quick_dial(
        /*slot*/ 2,
        Some(QuickDial {
            input: "local replacement".into(),
            label: None,
        }),
    )
    .await;
    assert_eq!(
        (
            std::fs::read(profile_path.as_path())?,
            &app.local_settings.tui.quick_dials,
            &app.chat_widget.local_settings.tui.quick_dials,
        ),
        (
            profile_before_rejections,
            &dials_before_rejections,
            &dials_before_rejections,
        )
    );
    let errors = std::iter::from_fn(|| events.try_recv().ok())
        .filter_map(|event| match event {
            AppEvent::InsertHistoryCell(cell) => {
                Some(lines_to_single_string(
                    &cell.transcript_lines(/*width*/ 200),
                ))
            }
            _ => None,
        })
        .filter(|message| message.contains("defined outside your user config"))
        .count();
    assert_eq!(errors, 2);
    Ok(())
}

fn quick_dial_write_failure_leaves_file_and_memory_unchanged() -> Result<()> {
    let (mut app, mut events, _ops) = make_test_app_with_channels().await;
    let config_path = app.local_settings.user_config_path.clone();
    let existing = QuickDial {
        input: "existing prompt".into(),
        label: Some("existing".into()),
    };
    app.local_settings
        .tui
        .quick_dials
        .insert("4".into(), existing);
    app.chat_widget.local_settings = app.local_settings.clone();
    std::fs::write(config_path.as_path(), "[broken")?;
    let file_before = std::fs::read(config_path.as_path())?;
    let dials_before = app.local_settings.tui.quick_dials.clone();
    while events.try_recv().is_ok() {}

    app.save_quick_dial(
        /*slot*/ 4,
        Some(QuickDial {
            input: "replacement prompt".into(),
            label: None,
        }),
    )
    .await;

    assert_eq!(
        (
            std::fs::read(config_path.as_path())?,
            &app.local_settings.tui.quick_dials,
            &app.chat_widget.local_settings.tui.quick_dials,
        ),
        (file_before, &dials_before, &dials_before)
    );
    let messages = std::iter::from_fn(|| events.try_recv().ok())
        .filter_map(|event| match event {
            AppEvent::InsertHistoryCell(cell) => {
                Some(lines_to_single_string(
                    &cell.transcript_lines(/*width*/ 200),
                ))
            }
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n");
    assert!(messages.contains("Failed to update preset 4"));
    assert!(!messages.contains("Saved preset 4"));
    Ok(())
}

