            .on_rate_limit_snapshot(Some(rate_limit_snapshot(
                /*used_percent*/ 20,
                /*rate_limit_reached_type*/ None,
                Some(false),
            )));
        let origin = match origin_name {
            "startup" => RateLimitRefreshOrigin::StartupPrefetch {
                reset_hint_request_id: app.chat_widget.start_rate_limit_reset_startup_check(),
            },
            "status" => {
                let request_id = 7;
                app.chat_widget
                    .add_status_output(/*refreshing_rate_limits*/ true, Some(request_id));
                RateLimitRefreshOrigin::StatusCommand { request_id }
            }
            "usage" => {
                let startup_request_id = app.chat_widget.start_rate_limit_reset_startup_check();
                app.chat_widget.finish_rate_limit_reset_hint_refresh(
                    startup_request_id,
                    Vec::new(),
                    Ok(RateLimitResetCreditsSummary {
                        available_count: 0,
                        credits: None,
                    }),
                );
                app.chat_widget.insert_str("/usage");
                app.chat_widget
                    .handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
                app.chat_widget
                    .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
                loop {
                    match app_event_rx.try_recv() {
                        Ok(AppEvent::RefreshRateLimits { origin }) => break origin,
                        Ok(_) => {}
                        other => panic!("expected usage refresh request, got {other:?}"),
                    }
                }
            }
            "reset-picker" => RateLimitRefreshOrigin::ResetPicker {
                request_id: app.chat_widget.show_rate_limit_reset_loading_popup(),
            },
            "reset-consume" => RateLimitRefreshOrigin::ResetConsume {
                request_id: app.chat_widget.show_rate_limit_reset_consuming_popup(),
            },
            _ => unreachable!("unknown refresh origin"),
        };
        let read_generation = app.rate_limit_hard_stop_generation;
        let mut rolling_snapshot = rate_limit_snapshot(
            /*used_percent*/ 95,
            Some(RateLimitReachedType::WorkspaceMemberUsageLimitReached),
            Some(true),
        );
        if origin_name == "reset-picker" {
            rolling_snapshot.limit_id = Some("codex_other".to_string());
        }
        deliver_rolling_rate_limit_snapshot(&mut app, &app_server, rolling_snapshot).await;
        assert_ne!(read_generation, app.rate_limit_hard_stop_generation);

        let control = Box::pin(app.handle_event(
            &mut tui,
            &mut app_server,
            AppEvent::RateLimitsLoaded {
                request_id: 0,
                origin,
                hard_stop_generation: read_generation,
                result: Ok(account_rate_limits_response(rate_limit_snapshot(
                    /*used_percent*/ 0,
                    /*rate_limit_reached_type*/ None,
                    Some(false),
                ))),
            },
        ))
        .await?;
        assert!(matches!(control, AppRunControl::Continue));

        let popup = render_bottom_popup(&app.chat_widget, /*width*/ 100);
        match origin_name {
            "usage" => assert!(
                popup.contains("Redeem reset    None available"),
                "expected usage reset availability, got: {popup}"
            ),
            "reset-picker" => {
                assert!(popup.contains("You don't have any usage limit resets available."));
            }
            "reset-consume" => {
                assert!(popup.contains("Usage reset. You have 0 usage limit resets left."));
            }
            "startup" | "status" => {}
            _ => unreachable!("unknown refresh origin"),
        }

        let status = render_status_output(&mut app, &mut app_event_rx);
        assert!(
            status.contains("80% left"),
            "expected {origin_name} to preserve the last account usage snapshot, got: {status}"
        );
        deliver_usage_limit_error(&mut app);
        let popup = render_bottom_popup(&app.chat_widget, /*width*/ 100);
        assert!(
            popup.contains("Request a limit increase from your owner"),
            "expected {origin_name} to preserve workspace error routing, got: {popup}"
        );

        app_server.shutdown().await?;
    }

    Ok(())
}

fn delegated_core_events_keep_private_output_hidden_and_deliver_final_speech() -> Result<()> {
    core_test_support::skip_if_no_network!(Ok(()));

    let mut commentary =
        responses::ev_assistant_message("private-commentary", "PRIVATE COMMENTARY");
    commentary["item"]["phase"] = json!("commentary");
    let mut final_answer = responses::ev_assistant_message(
        "public-final",
        "[ANALYSIS] is the marker you asked about.",
    );
    final_answer["item"]["phase"] = json!("final_answer");
    let model_server = create_mock_responses_server_sequence_unchecked(vec![
        responses::sse(vec![
            responses::ev_response_created("delegated-response"),
            responses::ev_reasoning_item("private-reasoning", &["PRIVATE REASONING"], &[]),
            commentary,
            final_answer,
            responses::ev_completed("delegated-response"),
        ]),
        responses::sse(vec![
            responses::ev_response_created("typed-response"),
            responses::ev_assistant_message("typed-final", "Typed answer stays visible."),
            responses::ev_completed("typed-response"),
        ]),
    ])
    .await;
    Mock::given(method("POST"))
        .and(path("/v1/live"))
        .respond_with(
            ResponseTemplate::new(200)
                .insert_header("Location", "/v1/live/rtc_tui_handoff")
                .set_body_string("v=answer\r\n"),
        )
        .mount(&model_server)
        .await;
    let realtime_server =
        responses::start_websocket_server_with_headers(vec![WebSocketConnectionConfig {
            requests: vec![
                vec![
                    json!({
                        "type": "session.started",
                        "session": { "id": "sess_tui_handoff", "instructions": "backend prompt" }
                    }),
                    json!({
                        "type": "delegation.created",
                        "offset_ms": 100,
                        "item": {
                            "id": "delegation_tui",
                            "type": "delegation",
                            "target": "client",
                            "content": [{"type": "input_text", "text": "explain the marker"}]
                        }
                    }),
                ],
                vec![],
                vec![],
                vec![],
            ],
            response_headers: Vec::new(),
            accept_delay: None,
            close_after_requests: false,
        }])
        .await;

    let (mut app, mut app_events, mut ops) = make_test_app_with_channels().await;
    let codex_home = tempfile::tempdir()?;
    MockResponsesConfig::new(&model_server.uri())
        .with_root_config(&format!(
            "experimental_realtime_ws_base_url = {:?}\nexperimental_realtime_webrtc_call_base_url = {:?}",
            realtime_server.uri(),
            format!("{}/v1", model_server.uri()),
        ))
        .with_extra_config("[realtime]\nversion = \"v3\"\ntype = \"conversational\"")
        .write(codex_home.path())?;
    codex_login::login_with_api_key(
        codex_home.path(),
        "sk-test-key",
        AuthCredentialsStoreMode::File,
        AuthKeyringBackendKind::default(),
    )?;
    app.config.codex_home = codex_home.path().to_path_buf().abs();
    app.config.sqlite = codex_state::SqliteConfig::new_for_testing(codex_home.path().abs());
    app.config.cli_auth_credentials_store_mode = AuthCredentialsStoreMode::File;
    app.config.model = Some("mock-model".to_string());
    app.config.model_provider_id = "mock_provider".to_string();
    app.config.model_provider = ModelProviderInfo {
        name: "Mock provider for test".to_string(),
        base_url: Some(format!("{}/v1", model_server.uri())),
        request_max_retries: Some(0),
        stream_max_retries: Some(0),
        ..ModelProviderInfo::default()
    };
    app.config.experimental_realtime_ws_base_url = Some(realtime_server.uri().to_string());
    app.config.experimental_realtime_webrtc_call_base_url =
        Some(format!("{}/v1", model_server.uri()));

    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let started = app_server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    crate::chatwidget::activate_voice_for_thread(&mut app.chat_widget, thread_id);
    while ops.try_recv().is_ok() {}
    let mut tui = crate::tui::test_support::make_test_tui()?;
    app_server
        .thread_realtime_start(
            thread_id,
            "v=offer\r\n".to_string(),
            /*model*/ None,
            /*voice*/ None,
        )
        .await?;
    // The sideband fixture sends its delegation after the first outbound request.
    app_server
        .thread_realtime_append_speech(thread_id, "fixture prompt".to_string())
        .await?;

    // Keep the real Core delegation running while another session is visible.
    let other = app_server.start_thread(&app.config).await?;
    let other_id = other.session.thread_id;
    app.replace_chat_widget_with_app_server_thread(
        &mut tui,
        other,
        super::super::session_lifecycle::ThreadAttachPresentation::Fresh,
        /*initial_user_message*/ None,
    )
    .await?;
    assert_eq!(app.voice_owner_thread_id(), Some(thread_id));
    assert_eq!(app.chat_widget.thread_id(), Some(other_id));

    let mut rendered = Vec::new();
    let speech = timeout(Duration::from_secs(15), async {
        loop {
            tokio::select! {
                event = app_server.next_event() => {
                    app.handle_app_server_event(
                        &app_server,
                        event.expect("embedded app-server should stay connected"),
                    ).await;
                    app.drain_active_thread_events(&mut tui).await?;
                }
                event = app_events.recv() => {
                    let event = event.expect("TUI event stream should stay open");
                    if let AppEvent::InsertHistoryCell(cell) = &event {
                        rendered.extend(cell.display_lines(/*width*/ 80).into_iter().map(|line| line.to_string()));
                    }
                    app.handle_event(&mut tui, &mut app_server, event).await?;
                }
                op = ops.recv(), if !ops.is_closed() => {
                    let op = op.expect("TUI command stream should stay open");
                    if matches!(op, Op::RealtimeConversationSpeech { .. }) {
                        break Ok::<_, color_eyre::Report>(op);
                    }
                    app.handle_event(&mut tui, &mut app_server, AppEvent::CodexOp(op)).await?;
                }
            }
        }
    })
    .await??;
    assert!(
        matches!(&speech, Op::RealtimeConversationSpeech { text, .. } if text.as_str() == "[ANALYSIS] is the marker you asked about."),
        "unexpected speech: {speech:?}"
    );
    app.handle_event(&mut tui, &mut app_server, AppEvent::CodexOp(speech))
        .await?;
    assert_eq!(
        timeout(
            Duration::from_secs(5),
            realtime_server.wait_for_request(/*connection_index*/ 0, /*request_index*/ 1),
        )
        .await?
        .body_json(),
        json!({
            "type": "session.context.append",
            "content": [{
                "type": "input_text",
                "text": "[ANALYSIS] is the marker you asked about."
            }],
            "channel": "speakable"
        })
    );
    assert_eq!(app.chat_widget.thread_id(), Some(other_id));
    assert_eq!(app.voice_owner_thread_id(), Some(thread_id));
    app.select_agent_thread(&mut tui, &mut app_server, thread_id)
        .await?;
    assert!(app.chat_widget.realtime_conversation_is_running());
    let rendered = rendered.join("\n");
    assert!(!rendered.contains("PRIVATE REASONING"), "{rendered}");
    assert!(!rendered.contains("PRIVATE COMMENTARY"), "{rendered}");
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 80, /*height*/ 24,
    );
    let mut buffer = Buffer::empty(area);
    app.chat_widget.render(area, &mut buffer);
    let visible = buffer
        .content()
        .iter()
        .map(ratatui::buffer::Cell::symbol)
        .collect::<String>();
    assert!(!visible.contains("PRIVATE REASONING"), "{visible}");
    assert!(!visible.contains("PRIVATE COMMENTARY"), "{visible}");
    assert!(
        ops.try_recv().is_err(),
        "a final answer must be sent only once"
    );

    // Replaying a still-live answer must not duplicate the caption that arrives later.
    app.chat_widget.handle_server_notification(
        ServerNotification::ThreadRealtimeTranscriptDone(
            codex_app_server_protocol::ThreadRealtimeTranscriptDoneNotification {
                thread_id: thread_id.to_string(),
                role: "assistant".into(),
                text: "[ANALYSIS] is the marker you asked about.".into(),
            },
        ),
        /*replay_kind*/ None,
    );
    while let Ok(event) = app_events.try_recv() {
        app.handle_event(&mut tui, &mut app_server, event).await?;
    }
    assert_eq!(
        app.transcript_cells
            .iter()
            .flat_map(|cell| cell.display_lines(/*width*/ 100))
            .filter(|line| line
                .to_string()
                .contains("[ANALYSIS] is the marker you asked about."))
            .count(),
        1,
    );

    // A typed request on the same live thread must follow the normal visible path.
    app.chat_widget
        .restore_user_message_to_composer(UserMessage::from("typed follow-up"));
    app.chat_widget
        .handle_key_event(crossterm::event::KeyEvent::new(
            crossterm::event::KeyCode::Enter,
            crossterm::event::KeyModifiers::NONE,
        ));
    let mut typed_rendered = Vec::new();
    timeout(Duration::from_secs(10), async {
        loop {
            tokio::select! {
                event = app_server.next_event() => {
                    let event = event.expect("embedded app-server should stay connected");
                    let completed = matches!(&event, AppServerEvent::ServerNotification(notification)
                        if matches!(notification.as_ref(), ServerNotification::TurnCompleted(_)));
                    app.handle_app_server_event(&app_server, event).await;
                    app.drain_active_thread_events(&mut tui).await?;
                    if completed {
                        break Ok::<_, color_eyre::Report>(());
                    }
                }
                event = app_events.recv() => {
                    let event = event.expect("TUI event stream should stay open");
                    if let AppEvent::InsertHistoryCell(cell) = &event {
                        typed_rendered.extend(cell.display_lines(/*width*/ 80).into_iter().map(|line| line.to_string()));
                    }
                    app.handle_event(&mut tui, &mut app_server, event).await?;
                }
                op = ops.recv(), if !ops.is_closed() => {
                    let op = op.expect("TUI command stream should stay open");
                    assert!(!matches!(op, Op::RealtimeConversationSpeech { .. }), "typed answer must not be spoken");
                    app.handle_event(&mut tui, &mut app_server, AppEvent::CodexOp(op)).await?;
                }
            }
        }
    })
    .await??;
    while let Ok(event) = app_events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = &event {
            typed_rendered.extend(
                cell.display_lines(/*width*/ 80)
                    .into_iter()
                    .map(|line| line.to_string()),
            );
        }
        app.handle_event(&mut tui, &mut app_server, event).await?;
    }
    assert!(
        typed_rendered
            .join("\n")
            .contains("Typed answer stays visible."),
        "typed final must appear in history: {typed_rendered:?}"
    );
    assert!(ops.try_recv().is_err(), "typed answer must not be spoken");
    realtime_server.shutdown().await;
    app_server.shutdown().await?;
    Ok(())
}

fn switching_threads_keeps_the_source_voice_partial_only_on_reattach() {
    let (mut app, _events, _ops) = make_test_app_with_channels().await;
    let source = ThreadId::new();
    app.active_thread_id = Some(source);
    app.chat_widget
        .handle_thread_session_quiet(test_thread_session(source, app.config.cwd.to_path_buf()));
    crate::chatwidget::activate_voice_for_thread(&mut app.chat_widget, source);
    app.chat_widget.handle_server_notification(
        ServerNotification::ThreadRealtimeTranscriptDelta(
            codex_app_server_protocol::ThreadRealtimeTranscriptDeltaNotification {
                thread_id: source.to_string(),
                role: "user".into(),
                delta: "spoken partial".into(),
            },
        ),
        /*replay_kind*/ None,
    );

    let side = ThreadId::new();
    let (side_widget, _, mut side_events, _) = make_chatwidget_manual_with_sender().await;
    app.active_thread_id = Some(side);
    app.replace_chat_widget(side_widget);
    app.chat_widget
        .handle_thread_session_quiet(test_thread_session(side, app.config.cwd.to_path_buf()));
    let other_ui = render_bottom_popup(&app.chat_widget, /*width*/ 80);
    while let Ok(event) = side_events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            assert!(
                cell.transcript_lines(/*width*/ 80)
                    .iter()
                    .all(|line| !line.to_string().contains("spoken partial"))
            );
        }
    }

    let (source_widget, _, mut source_events, _) = make_chatwidget_manual_with_sender().await;
    app.active_thread_id = Some(source);
    app.replace_chat_widget(source_widget);
    app.replay_thread_snapshot(
        empty_thread_snapshot(&app, source),
        /*resume_restored_queue*/ false,
    );
    assert!(!app.pending_realtime_transcript_replay.contains_key(&source));
    app.chat_widget.handle_server_notification(
        ServerNotification::ThreadRealtimeTranscriptDone(
            codex_app_server_protocol::ThreadRealtimeTranscriptDoneNotification {
                thread_id: source.to_string(),
                role: "user".into(),
                text: "spoken partial completed".into(),
            },
        ),
        /*replay_kind*/ None,
    );
    commit_realtime_history_events(&mut app.chat_widget, &mut source_events);
    let rendered = std::iter::from_fn(|| source_events.try_recv().ok())
        .filter_map(|event| match event {
            AppEvent::InsertHistoryCell(cell) => Some(
                cell.transcript_lines(/*width*/ 80)
                    .into_iter()
                    .map(|line| line.to_string())
                    .collect::<Vec<_>>()
                    .join("\n"),
            ),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n");
    assert_eq!(rendered.matches("spoken partial completed").count(), 1);
    insta::assert_snapshot!(
        "voice_partial_completed_after_thread_switch",
        normalize_voice_snapshot_directory(
            &format!(
                "Other task:\n{other_ui}\nRestored owner:\n{}\n{rendered}",
                render_bottom_popup(&app.chat_widget, /*width*/ 80)
            ),
            &app.config.cwd,
        )
    );
    while let Ok(event) = side_events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            assert!(
                cell.transcript_lines(/*width*/ 80)
                    .iter()
                    .all(|line| !line.to_string().contains("spoken partial"))
            );
        }
    }
}

fn queued_voice_caption_after_switch_returns_once_to_its_source_thread() {
    let (mut app, _events, _ops) = make_test_app_with_channels().await;
    let source = ThreadId::new();
    app.active_thread_id = Some(source);
    app.chat_widget
        .handle_thread_session_quiet(test_thread_session(source, app.config.cwd.to_path_buf()));
    crate::chatwidget::activate_voice_for_thread(&mut app.chat_widget, source);

    // Exercise a completion that arrives only after two switches without a prior delta.
    for _ in 0..2 {
        let (other_widget, _, _, _) = make_chatwidget_manual_with_sender().await;
        app.active_thread_id = Some(ThreadId::new());
        app.replace_chat_widget(other_widget);
        assert_eq!(app.voice_owner_thread_id(), Some(source));

        let (source_widget, _, _, _) = make_chatwidget_manual_with_sender().await;
        app.active_thread_id = Some(source);
        app.replace_chat_widget(source_widget);
        app.replay_thread_snapshot(
            empty_thread_snapshot(&app, source),
            /*resume_restored_queue*/ false,
        );
    }

    let other = ThreadId::new();
    let (other_widget, _, mut other_events, _) = make_chatwidget_manual_with_sender().await;
    app.active_thread_id = Some(other);
    app.replace_chat_widget(other_widget);
    app.chat_widget
        .handle_thread_session_quiet(test_thread_session(other, app.config.cwd.to_path_buf()));

    app.enqueue_thread_notification(
        source,
        ServerNotification::ThreadRealtimeTranscriptDone(
            codex_app_server_protocol::ThreadRealtimeTranscriptDoneNotification {
                thread_id: source.to_string(),
                role: "assistant".into(),
                text: "arrived after two switches".into(),
            },
        ),
    )
    .await
    .unwrap();

    app.enqueue_thread_notification(
        source,
        ServerNotification::ThreadRealtimeClosed(
            codex_app_server_protocol::ThreadRealtimeClosedNotification {
                thread_id: source.to_string(),
                reason: Some("requested".into()),
            },
        ),
    )
    .await
    .unwrap();

    for notification in [
        ServerNotification::ThreadRealtimeTranscriptDelta(
            codex_app_server_protocol::ThreadRealtimeTranscriptDeltaNotification {
                thread_id: source.to_string(),
                role: "user".into(),
                delta: "last ".into(),
            },
        ),
        ServerNotification::ThreadRealtimeTranscriptDelta(
            codex_app_server_protocol::ThreadRealtimeTranscriptDeltaNotification {
                thread_id: source.to_string(),
                role: "user".into(),
                delta: "words".into(),
            },
        ),
        ServerNotification::ThreadRealtimeTranscriptDone(
            codex_app_server_protocol::ThreadRealtimeTranscriptDoneNotification {
                thread_id: source.to_string(),
                role: "user".into(),
                text: "last words".into(),
            },
        ),
    ] {
        app.enqueue_thread_notification(source, notification)
            .await
            .unwrap();
    }
    app.enqueue_thread_notification(
        source,
        ServerNotification::ThreadRealtimeTranscriptDelta(
            codex_app_server_protocol::ThreadRealtimeTranscriptDeltaNotification {
                thread_id: source.to_string(),
                role: "assistant".into(),
                delta: "discarded partial".into(),
            },
        ),
    )
    .await
    .unwrap();
    app.enqueue_thread_notification(
        source,
        ServerNotification::ThreadRealtimeTranscriptDone(
            codex_app_server_protocol::ThreadRealtimeTranscriptDoneNotification {
                thread_id: source.to_string(),
                role: "assistant".into(),
                text: String::new(),
            },
        ),
    )
    .await
    .unwrap();
    while let Ok(event) = other_events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            assert!(
                cell.transcript_lines(/*width*/ 80)
                    .iter()
                    .all(|line| !line.to_string().contains("last words"))
            );
        }
    }

    let (source_widget, _, mut source_events, _) = make_chatwidget_manual_with_sender().await;
    app.active_thread_id = Some(source);
    app.replace_chat_widget(source_widget);
    app.replay_thread_snapshot(
        empty_thread_snapshot(&app, source),
        /*resume_restored_queue*/ false,
    );
    commit_realtime_history_events(&mut app.chat_widget, &mut source_events);
    let rendered = std::iter::from_fn(|| source_events.try_recv().ok())
        .filter_map(|event| match event {
            AppEvent::InsertHistoryCell(cell) => Some(
                cell.transcript_lines(/*width*/ 80)
                    .into_iter()
                    .map(|line| line.to_string())
                    .collect::<String>(),
            ),
            _ => None,
        })
        .collect::<String>();
    assert_eq!(rendered.matches("last words").count(), 1);
    assert_eq!(rendered.matches("arrived after two switches").count(), 1);
    assert!(!rendered.contains("last last words"));
}

fn replay_reconciles_only_matching_voice_captions_one_for_one() {
    let (mut app, _initial_events, _ops) = make_test_app_with_channels().await;
    let source = ThreadId::new();
    let (widget, _, mut events, _) = make_chatwidget_manual_with_sender().await;
    app.active_thread_id = Some(source);
