    let records = [
        ("user", "show <code> & tests"),
        ("user", "show <code> & tests"),
        ("assistant", "spoken answer"),
        ("user", "typed words"),
        ("assistant", "different caption"),
    ]
    .into_iter()
    .map(|(role, text)| crate::chatwidget::RealtimeTranscriptRecord {
        role: role.to_string(),
        text: text.to_string(),
        complete: true,
        before_turn_id: None,
    })
    .collect();
    app.pending_realtime_transcript_replay
        .insert(source, records);
    let voice = Turn {
        id: "voice-turn".into(),
