        ],
        items_view: TurnItemsView::Summary,
        status: TurnStatus::Completed,
        error: None,
        started_at: None,
        completed_at: None,
        duration_ms: None,
    };
    let typed = Turn {
        id: "typed-turn".into(),
        items: vec![test_user_message("typed-user", "typed words")],
        ..voice.clone()
    };
    app.replay_thread_snapshot(
        ThreadEventSnapshot {
