fn recap_generation_uses_bounded_structured_request_and_inserts_result() -> Result<()> {
    let chunks = [
        ev_response_created("recap-response"),
        ev_assistant_message(
            "recap-message",
            r#"{"summary":"Finished parsing.","next_action":"Run focused tests."}"#,
        ),
        ev_completed("recap-response"),
    ]
    .into_iter()
    .map(|event| StreamingSseChunk {
        gate: None,
        body: responses::sse(vec![event]),
    })
    .collect();
    let (model_server, _completions) = start_streaming_sse_server(vec![chunks]).await;
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let codex_home = tempdir()?;
    std::fs::write(
        codex_home.path().join("config.toml"),
        format!(
            r#"
model = "{MODEL}"
model_provider = "{MODEL_PROVIDER_ID}"

[model_providers.{MODEL_PROVIDER_ID}]
name = "Recap generation test"
base_url = "{}/v1"
wire_api = "responses"
request_max_retries = 0
stream_max_retries = 0
"#,
            model_server.uri()
        ),
    )?;
    app.config.codex_home = codex_home.path().to_path_buf().abs();
    app.config.sqlite = codex_state::SqliteConfig::new_for_testing(codex_home.path().abs());
    app.config.model = Some(MODEL.to_string());
    app.config.model_provider_id = MODEL_PROVIDER_ID.to_string();
    app.config.model_provider = ModelProviderInfo {
        name: "Recap generation test".to_string(),
        base_url: Some(format!("{}/v1", model_server.uri())),
        request_max_retries: Some(0),
        stream_max_retries: Some(0),
        ..ModelProviderInfo::default()
    };

    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let started = app_server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    app.replace_chat_widget_with_app_server_thread(
        &mut tui,
        started,
        ThreadAttachPresentation::SessionLineage,
        /*initial_user_message*/ None,
    )
    .await?;
    while app_event_rx.try_recv().is_ok() {}

    prepare_eligible_recap(&mut app, thread_id).await;
    app.transcript_cells
        .push(Arc::new(crate::history_cell::AgentMarkdownCell::new(
            format!(
                "Parser fix implemented. {} What should empty input do?",
                "progress ".repeat(/*n*/ 5_000)
            ),
            std::path::Path::new("."),
        )));
    app.transcript_cells
        .push(Arc::new(crate::history_cell::UserHistoryCell {
            message: "Keep follow-up work queued.".to_string(),
            spoken: false,
            text_elements: Vec::new(),
            local_image_paths: Vec::new(),
            remote_image_urls: Vec::new(),
        }));

    app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::CheckRecap { thread_id },
    )
    .await?;
    let started_event = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), app_event_rx.recv())
        .await?
        .expect("recap start event");
    assert!(matches!(started_event, AppEvent::RecapStarted { .. }));
    app.handle_event(&mut tui, &mut app_server, started_event)
        .await?;

    let generated_event = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), async {
        loop {
            tokio::select! {
                event = app_event_rx.recv() => {
                    let event = event.expect("app event stream");
                    if matches!(event, AppEvent::RecapGenerated { .. }) {
                        break Ok::<_, color_eyre::Report>(event);
                    }
                    app.handle_event(&mut tui, &mut app_server, event).await?;
                }
                event = app_server.next_event() => {
                    let event = event.expect("app-server event stream");
                    app.handle_app_server_event(&app_server, event).await;
                }
            }
        }
    })
    .await??;
    app.handle_event(&mut tui, &mut app_server, generated_event)
        .await?;

    let recap = app
        .transcript_cells
        .last()
        .and_then(|cell| {
            cell.as_any()
                .downcast_ref::<crate::history_cell::ThreadRecapHistoryCell>()
        })
        .expect("recap history cell");
    assert_eq!(
        recap
            .raw_lines()
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        vec![
            "Conversation recap",
            "Finished parsing.",
            "Next: Run focused tests.",
        ]
    );

    let model_requests = model_server.requests().await;
    assert_eq!(model_requests.len(), 1);
    let request: Value = serde_json::from_slice(&model_requests[0])?;
    let prompt = request["input"]
        .as_array()
        .and_then(|items| items.iter().rfind(|item| item["role"] == "user"))
        .and_then(|item| item["content"].as_array())
        .and_then(|content| content.iter().find(|item| item["type"] == "input_text"))
        .and_then(|item| item["text"].as_str())
        .expect("recap prompt");
    assert!(
        prompt.contains("Finish the recap implementation"),
        "prompt: {prompt}\nrequest: {request}"
    );
    assert!(prompt.len() <= recap::RECAP_PROMPT_MAX_BYTES);
    assert!(prompt.contains("Assistant: Parser fix implemented."));
    assert!(prompt.contains("What should empty input do?"));
    assert!(prompt.contains("[... excerpted ...]"));
    assert_eq!(
        prompt
            .matches("Pending user request: Keep follow-up work queued.")
            .count(),
        1
    );
    assert_eq!(request["text"]["format"]["type"], "json_schema");
    assert_eq!(
        request["text"]["format"]["schema"]["required"],
        serde_json::json!(["summary", "next_action"])
    );
    assert_eq!(request["tools"], serde_json::json!([]));

    app_server.shutdown().await?;
    model_server.shutdown().await;
    Ok(())
}

fn manual_recap_works_when_auto_recap_disabled() -> Result<()> {
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    app.local_settings.tui.auto_recap = false;
    let thread_id = ThreadId::new();
    app.active_thread_id = Some(thread_id);
    app.transcript_cells
        .push(Arc::new(crate::history_cell::UserHistoryCell {
            message: "Summarize this conversation".to_string(),
            spoken: false,
            text_elements: Vec::new(),
            local_image_paths: Vec::new(),
            remote_image_urls: Vec::new(),
        }));
    let (mut app_server, _requests, proxy) = start_recording_remote_app_server(&app.config).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;

    // An automatic request must not occupy the slot needed by a manual request.
    app.request_recap(&app_server, thread_id, RecapTrigger::Automatic);
    app.handle_event(
        &mut tui,
        &mut app_server,
        AppEvent::GenerateRecap { thread_id },
    )
    .await?;
    assert!(
        render_chat_widget(&app).contains("Generating conversation recap…"),
        "manual recap should show progress while generation is in flight"
    );
    let started_event = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), app_event_rx.recv())
        .await?
        .expect("manual recap start event");
    let (request, temporary_thread_id) = match &started_event {
        AppEvent::RecapStarted {
            thread_id: requested_thread_id,
            request_id,
            trigger,
            completed_turn_count,
            turn_revision,
            result: Ok(temporary_thread_id),
            ..
        } if *requested_thread_id == thread_id && *trigger == RecapTrigger::Manual => (
            recap::RecapRequest {
                thread_id: *requested_thread_id,
                request_id: *request_id,
                trigger: *trigger,
                completed_turn_count: *completed_turn_count,
                turn_revision: *turn_revision,
            },
            ThreadId::from_string(temporary_thread_id).expect("temporary recap thread ID"),
        ),
        other => panic!("expected a started manual recap, got {other:?}"),
    };

    app.handle_event(&mut tui, &mut app_server, started_event)
        .await?;

    assert_eq!(app.temporary_structured_requests.len(), 1);
    assert!(
        app.handle_generated_recap(
            request,
            temporary_thread_id,
            Err("temporary failure".to_string()),
        )
        .is_none()
    );
    assert!(
        !render_chat_widget(&app).contains("Generating conversation recap…"),
        "manual recap progress should clear when generation finishes"
    );

    let cell = match app_event_rx.try_recv() {
        Ok(AppEvent::InsertHistoryCell(cell)) => cell,
        other => panic!("expected visible manual recap error, got {other:?}"),
    };
    let rendered = lines_to_single_string(&cell.display_lines(/*width*/ 80));
    assert!(
        rendered.contains("Could not generate a recap. Please try again."),
        "rendered error: {rendered:?}"
    );

    // A completion quarantined during reconnect must not leave the next recap stuck as busy.
    app.app_server_target = AppServerTarget::Remote {
        endpoint: crate::RemoteAppServerEndpoint::WebSocket {
            websocket_url: "ws://127.0.0.1:1".into(),
            auth_token: None,
        },
    };
    app.request_recap(&app_server, thread_id, RecapTrigger::Manual);
    let stale = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), app_event_rx.recv())
        .await?
        .expect("recap completion before disconnect");
    assert!(matches!(stale, AppEvent::RecapStarted { .. }));
    assert!(app.begin_reconnect());
    app.handle_event(&mut tui, &mut app_server, stale).await?;
    while app_event_rx.try_recv().is_ok() {}
    app.reconnect.offline = false;
    app.request_recap(&app_server, thread_id, RecapTrigger::Manual);
    let next = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), app_event_rx.recv()).await?;
    assert!(
        matches!(next, Some(AppEvent::RecapStarted { .. })),
        "{next:?}"
    );

    app_server.shutdown().await?;
    proxy.await??;
    Ok(())
}

fn failed_close_status_read_reconnects_remote_or_closes_embedded() -> Result<()> {
    for (failure, expected_reads, offline) in [
        ("disconnect", 1, true),
        ("timeout", 1, true),
        ("transient", 2, false),
        ("persistent", 2, true),
        ("embedded", 2, false),
        ("unsupported", 1, false),
    ] {
        let (mut app, mut events, _commands) = make_test_app_with_channels().await;
        let id = ThreadId::new();
        app.enqueue_primary_thread_session(
            test_thread_session(id, app.config.cwd.to_path_buf()),
            Vec::new(),
        )
        .await?;
        let listener = TcpListener::bind("127.0.0.1:0").await?;
        let endpoint = crate::resolve_remote_addr(&format!("ws://{}", listener.local_addr()?))?;
        if failure != "embedded" {
            app.app_server_target = AppServerTarget::Remote {
                endpoint: endpoint.clone(),
            };
        }
        let reads = Arc::new(AtomicUsize::new(/*v*/ 0));
        let server_reads = reads.clone();
        let cwd = app.config.cwd.clone();
        let server = tokio::spawn(async move {
            let (stream, _) = listener.accept().await?;
            serve_reconnect_requests(
                tokio_tungstenite::accept_async(stream).await?,
                move |request| {
                    assert_eq!(request.method, "thread/read");
                    let attempt = server_reads.fetch_add(/*val*/ 1, Ordering::SeqCst);
                    let response = match failure {
                        "disconnect" | "timeout" => None,
                        "unsupported" => {
                            Some(json!({"error": {"code": -32601, "message": "method not found"}}))
                        }
                        "transient" if attempt == 1 => Some(json!({"result": {"thread": {
                            "id": id, "sessionId": id, "preview": "", "ephemeral": false,
                            "modelProvider": "test-provider", "createdAt": 1, "updatedAt": 2,
                            "status": {"type": "idle"}, "cwd": cwd, "cliVersion": "0.0.0",
                            "source": "cli", "turns": []
                        }}})),
                        _ => {
                            Some(json!({"error": {"code": -32603, "message": "temporary failure"}}))
                        }
                    };
                    async move {
                        if failure == "timeout" {
                            std::future::pending::<()>().await;
                        }
                        response
                    }
                },
            )
            .await
        });
        let session = AppServerSession::new(
            crate::backend_id::BackendId::new(),
            crate::connect_remote_app_server(endpoint).await?,
            ThreadParamsMode::Remote,
        );
        tokio::time::timeout(
            Duration::from_secs(/*secs*/ 10),
            app.handle_app_server_event(
                &session,
                AppServerEvent::ServerNotification(Box::new(thread_closed_notification(id))),
            ),
        )
        .await?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        app.drain_active_thread_events(&mut tui).await?;
        assert_eq!(
            (reads.load(Ordering::SeqCst), app.reconnect.offline),
            (expected_reads, offline),
            "{failure}"
        );
        assert_eq!(
            std::iter::from_fn(|| events.try_recv().ok())
                .any(|event| matches!(event, AppEvent::Exit(_) | AppEvent::FatalExitRequest(_))),
            matches!(failure, "embedded" | "unsupported"),
            "{failure}"
        );
        server.abort();
        let _ = server.await;
        session.shutdown().await?;
    }
    Ok(())
}

fn thread_close_exits_only_when_displayed_thread_is_unloaded() -> Result<()> {
    let (mut app, mut events, _commands) = make_test_app_with_channels().await;
    app.config.thread_unload_delay = Duration::ZERO;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let started = server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    app.drain_active_thread_events(&mut tui).await?;

    // The old runtime's notification can arrive after this thread ID is loaded again.
    app.handle_app_server_event(
        &server,
        AppServerEvent::ServerNotification(Box::new(thread_closed_notification(thread_id))),
    )
    .await;
    app.drain_active_thread_events(&mut tui).await?;
    assert!(
        !std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event, AppEvent::Exit(_)))
    );

    // A genuine close must still exit.
    server.thread_unsubscribe(thread_id).await?;
    let closed = tokio::time::timeout(Duration::from_secs(/*secs*/ 5), async {
        while let Some(event) = server.next_event().await {
            if matches!(&event,
                AppServerEvent::ServerNotification(notification)
                    if matches!(notification.as_ref(), ServerNotification::ThreadClosed(closed)
                        if closed.thread_id == thread_id.to_string()))
            {
                return event;
            }
        }
        panic!("server event stream ended before the thread closed");
    })
    .await?;
    app.handle_app_server_event(&server, closed).await;
    app.drain_active_thread_events(&mut tui).await?;
    assert!(
        std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event, AppEvent::Exit(ExitMode::Immediate)))
    );
    server.shutdown().await?;
    Ok(())
}

fn run_safety_retry(
    previous_prompt: Option<&str>,
    failing_draft: Option<&str>,
    committed_steer: Option<&str>,
    scenario: SafetyRetryScenario,
) -> Result<()> {
    let (active_chunks, release_active_response) = gated_response_chunks(
        "active-response",
        ev_completed_with_tokens("active-response", /*total_tokens*/ 100),
    );
    let mut release_active_response = Some(release_active_response);
    let (steered_chunks, release_steered_response) =
        gated_response_chunks("steered-response", ev_completed("steered-response"));
    let (previous_chunks, release_previous_response) =
        gated_response_chunks("previous-response", ev_completed("previous-response"));
    let (retry_chunks, release_retry_response) =
        gated_response_chunks("retry-response", ev_completed("retry-response"));
    let mut response_sequences = Vec::new();
    if previous_prompt.is_some() {
        if scenario == SafetyRetryScenario::InterruptedPrevious {
            response_sequences.push(previous_chunks);
        } else {
            response_sequences.push(response_chunks("previous-response"));
        }
    }
    response_sequences.push(active_chunks);
    if committed_steer.is_some() {
        response_sequences.push(steered_chunks);
    }
    if scenario == SafetyRetryScenario::RetryTwice {
        response_sequences.push(retry_chunks);
        response_sequences.push(response_chunks("second-retry-response"));
    } else {
        response_sequences.push(response_chunks("retry-response"));
    }
    response_sequences.push(vec![StreamingSseChunk {
        gate: None,
        body: responses::sse(vec![
            ev_response_created("goal-continuation-response"),
            ev_assistant_message("goal-continuation-message", "done"),
            ev_completed_with_tokens("goal-continuation-response", /*total_tokens*/ 1_000),
        ]),
    }]);
    let expected_request_count = response_sequences.len();
    let (server, _completions) = start_streaming_sse_server(response_sequences).await;

    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let codex_home = tempdir()?;
    // Keep text-only retry fixtures independent of the optional Code Mode host.
    let mut model_catalog = codex_models_manager::bundled_models_response()?;
    for model in model_catalog
        .models
        .iter_mut()
        .filter(|model| matches!(model.slug.as_str(), CURRENT_MODEL | FASTER_MODEL))
    {
        model.tool_mode = Some(ToolMode::Direct);
        if scenario == SafetyRetryScenario::UnsupportedPermissions && model.slug == FASTER_MODEL {
            model.available_access_programs = Some(ModelAccessPrograms {
                cyber: vec![CyberAccessProgram::Standard],
            });
        }
    }
    let model_catalog_path = codex_home.path().join("models.json");
    std::fs::write(&model_catalog_path, serde_json::to_vec(&model_catalog)?)?;
    let model_catalog_path = toml::Value::String(model_catalog_path.display().to_string());
    // The committed-steer case counts usage from the response that finishes before steering.
    let instant_interrupt_config = if committed_steer.is_some() {
        "instant_interrupt = false"
    } else {
        ""
    };
    std::fs::write(
        codex_home.path().join("config.toml"),
        format!(
            r#"
model = "{CURRENT_MODEL}"
model_provider = "{MODEL_PROVIDER_ID}"
model_catalog_json = {model_catalog_path}

[model_providers.{MODEL_PROVIDER_ID}]
name = "Safety retry test"
base_url = "{}/v1"
wire_api = "responses"
request_max_retries = 0
stream_max_retries = 0

[features]
goals = true
{instant_interrupt_config}
"#,
            server.uri()
        ),
    )?;
    app.config.codex_home = codex_home.path().to_path_buf().abs();
    app.config.sqlite = codex_state::SqliteConfig::new_for_testing(codex_home.path().abs());
    app.config.model = Some(CURRENT_MODEL.to_string());
    if scenario == SafetyRetryScenario::UnsupportedPermissions {
        app.model_catalog = Arc::new(ModelCatalog::new(
            model_catalog
                .models
                .iter()
                .cloned()
                .map(Into::into)
                .collect(),
        ));
    }
    app.config.model_catalog = Some(model_catalog);
    app.config.model_provider_id = MODEL_PROVIDER_ID.to_string();
    app.config.model_provider = ModelProviderInfo {
        name: "Safety retry test".to_string(),
        base_url: Some(format!("{}/v1", server.uri())),
        request_max_retries: Some(0),
        stream_max_retries: Some(0),
        ..ModelProviderInfo::default()
    };
    app.config
        .features
        .enable(Feature::Goals)
        .expect("test config should allow goals");

    if scenario == SafetyRetryScenario::PendingPermissions {
        app.config
            .permissions
            .set_permission_profile_from_session_snapshot(
                PermissionProfileSnapshot::from_session_snapshot(
                    PermissionProfile::Disabled,
                    Some(ActivePermissionProfile::new(":danger-full-access")),
                ),
            )?;
    }
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut started = app_server.start_thread(&app.config).await?;
    let source_thread_id = started.session.thread_id;
    // Keep ordered response fixtures focused on safety retries, not background naming.
    app_server
        .thread_set_name(source_thread_id, SAFETY_RETRY_THREAD_NAME.to_string())
        .await?;
    started.session.thread_name = Some(SAFETY_RETRY_THREAD_NAME.to_string());
    app.replace_chat_widget_with_app_server_thread(
        &mut tui,
        started,
        ThreadAttachPresentation::SessionLineage,
        /*initial_user_message*/ None,
    )
    .await?;
    while app_event_rx.try_recv().is_ok() {}

    if let Some(previous_prompt) = previous_prompt {
        submit_prompt(&mut app, previous_prompt);
        let previous_turn = next_user_turn_event(&mut app_event_rx);
        app.submit_thread_op(&mut app_server, source_thread_id, previous_turn)
            .await?;
        if scenario == SafetyRetryScenario::InterruptedPrevious {
            let previous_turn_id =
                next_turn_started(&mut app, &mut app_server, source_thread_id).await;
            drive_until_request_count(
                &mut app,
                &mut app_server,
                &server,
                /*expected_request_count*/ 1,
            )
            .await;
            app_server
                .turn_interrupt(source_thread_id, previous_turn_id)
                .await?;
        } else {
            wait_for_turn_completed(&mut app, &mut app_server, source_thread_id).await;
        }
    }

    let state_db = codex_state::StateRuntime::init(
        app.config.sqlite.clone(),
        app.config.model_provider_id.clone(),
    )
    .await
    .expect("state db should initialize");
    state_db
        .thread_goals()
        .replace_thread_goal(
            source_thread_id,
            RETRY_GOAL,
            codex_state::ThreadGoalStatus::Active,
            /*token_budget*/ Some(1_000),
        )
        .await
        .expect("source goal should be stored");
    let source_goal_id = state_db
        .thread_goals()
        .get_thread_goal(source_thread_id)
        .await
        .expect("source goal should be readable")
        .expect("source goal")
        .goal_id;
    state_db
        .thread_goals()
        .account_thread_goal_usage(
            source_thread_id,
            /*time_delta_seconds*/ 12,
            /*token_delta*/ 50,
            codex_state::GoalAccountingMode::ActiveOrStopped,
            Some(source_goal_id.as_str()),
        )
        .await
        .expect("source goal usage should be recorded");

    submit_prompt(&mut app, RETRY_PROMPT);
    let mut active_turn = next_user_turn_event(&mut app_event_rx);
    app.submit_thread_op(&mut app_server, source_thread_id, active_turn.clone())
        .await?;
    let active_turn_id = next_turn_started(&mut app, &mut app_server, source_thread_id).await;
    drive_until_request_count(
        &mut app,
        &mut app_server,
        &server,
        usize::from(previous_prompt.is_some()) + 1,
    )
    .await;

    if let Some(committed_steer) = committed_steer {
        submit_prompt(&mut app, committed_steer);
        let steer = next_user_turn_event(&mut app_event_rx);
        app.submit_thread_op(&mut app_server, source_thread_id, steer)
            .await?;
        let _ = release_active_response
            .take()
            .expect("active response should still be gated")
            .send(());
        drive_until_request_count(
            &mut app,
            &mut app_server,
            &server,
            usize::from(previous_prompt.is_some()) + 2,
        )
        .await;
        let source = app_server
            .thread_read(source_thread_id, /*include_turns*/ true)
            .await?;
        assert_eq!(user_message_count(&source, committed_steer), 1);
    }

    app.handle_app_server_event(
        &app_server,
        AppServerEvent::ServerNotification(Box::new(
            ServerNotification::ModelSafetyBufferingUpdated(
                ModelSafetyBufferingUpdatedNotification {
                    thread_id: source_thread_id.to_string(),
                    turn_id: active_turn_id.clone(),
                    model: CURRENT_MODEL.to_string(),
                    use_cases: Vec::new(),
                    reasons: Vec::new(),
                    show_buffering_ui: true,
                    faster_model: Some(FASTER_MODEL.to_string()),
                },
            ),
        )),
    )
    .await;
    drain_active_thread_events(&mut app);
    assert!(
        app.chat_widget
            .can_retry_safety_buffered_turn(&active_turn_id)
    );
    if let Some(draft) = failing_draft {
        app.chat_widget.apply_external_edit(draft.to_string());
        let source = app_server
            .thread_read(source_thread_id, /*include_turns*/ true)
            .await?;
        std::fs::remove_file(
            source
                .path
                .expect("source thread should have a rollout path"),
        )?;
    }

    let primary_thread_id = ThreadId::new();
    app.primary_thread_id = Some(primary_thread_id);
    let voice_owner = ThreadId::new();
    let (mut owner, _, _, _) = crate::chatwidget::tests::make_chatwidget_manual_with_sender().await;
    crate::chatwidget::activate_voice_for_thread(&mut owner, voice_owner);
    owner.park_voice();
    app.background_voice = Some(Box::new(owner));
    Box::pin(app.retry_safety_buffered_turn(
        &mut tui,
        &mut app_server,
        SafetyBufferedRetry {
            thread_id: source_thread_id,
            turn_id: active_turn_id.clone(),
            model: FASTER_MODEL.to_string(),
            turn: active_turn.clone(),
            prompt: UserMessage::from(RETRY_PROMPT),
        },
    ))
    .await;

    assert_eq!(app.primary_thread_id, Some(primary_thread_id));
    assert_eq!(app.active_thread_id, Some(source_thread_id));
    assert_eq!(app.chat_widget.thread_id(), Some(source_thread_id));
    app.primary_thread_id = Some(source_thread_id);
    while app_event_rx.try_recv().is_ok() {}

    if scenario == SafetyRetryScenario::UnsupportedPermissions {
        app_server
            .thread_settings_update(ThreadSettingsUpdateParams {
                thread_id: source_thread_id.to_string(),
                effort: Some(ReasoningEffortConfig::Low),
                ..Default::default()
            })
            .await?;
        let mut settings = next_thread_settings_updated(&mut app_server, source_thread_id).await;
        settings.thread_settings.model_provider = "openai".to_string();
        app.chat_widget.on_thread_settings_updated(settings);
        app.chat_widget.update_account_state(
            /*status_account_display*/ None, /*plan_type*/ None,
            /*has_chatgpt_account*/ true, /*has_codex_backend_auth*/ false,
        );
        app.chat_widget
            .set_feature_enabled(Feature::CliDaybreak, /*enabled*/ true);
        app.chat_widget.set_daybreak_enabled(/*enabled*/ true);
        Box::pin(app.retry_safety_buffered_turn(
            &mut tui,
            &mut app_server,
            SafetyBufferedRetry {
                thread_id: source_thread_id,
                turn_id: active_turn_id.clone(),
                model: FASTER_MODEL.to_string(),
                turn: active_turn.clone(),
                prompt: UserMessage::from(RETRY_PROMPT),
            },
        ))
        .await;
        assert_eq!(app.chat_widget.thread_id(), Some(source_thread_id));
        let source = app_server
            .thread_read(source_thread_id, /*include_turns*/ true)
            .await?;
        assert_eq!(
            source.turns.last().map(|turn| &turn.status),
            Some(&TurnStatus::InProgress)
        );
        let error_cell = std::iter::from_fn(|| app_event_rx.try_recv().ok())
            .find_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => Some(cell),
                _ => None,
            })
            .expect("unsupported Daybreak model should be added to history");
        insta::assert_snapshot!(
            lines_to_single_string(&error_cell.display_lines(/*width*/ 200)),
            @"■ Daybreak support for model gpt-5.6-luna could not be confirmed by the connected server. Use /daybreak to turn it off, or choose a compatible model and server."
        );
        app.chat_widget.set_daybreak_enabled(/*enabled*/ false);

        let extra_root =
            AbsolutePathBuf::resolve_path_against_base("extra", app.config.cwd.as_path());
        let permission_profile = PermissionProfile::Managed {
            network: NetworkSandboxPolicy::Restricted,
            file_system: ManagedFileSystemPermissions::Restricted {
                entries: vec![
                    FileSystemSandboxEntry {
                        path: FileSystemPath::Special {
                            value: FileSystemSpecialPath::Root,
                        },
                        access: FileSystemAccessMode::Read,
                        missing_path_behavior: None,
                    },
                    FileSystemSandboxEntry {
                        path: FileSystemPath::Path {
                            path: extra_root.into(),
                        },
                        access: FileSystemAccessMode::Write,
                        missing_path_behavior: None,
                    },
                ],
                glob_scan_max_depth: None,
            },
        };
        app.config
            .permissions
            .set_permission_profile(permission_profile.clone())?;
        app.chat_widget.set_permission_profile_with_active_profile(
            permission_profile,
            /*active_permission_profile*/ None,
        )?;
        app.runtime_permission_profile_override =
            Some(RuntimePermissionProfileOverride::from_config(&app.config));
        if let AppCommand::UserTurn {
            active_permission_profile,
            ..
        } = &mut active_turn
        {
            *active_permission_profile = None;
        }
    }

    if scenario == SafetyRetryScenario::PendingPermissions {
        app.runtime_permission_profile_override = Some(
            RuntimePermissionProfileOverride::from_config(app.chat_widget.config_ref()),
        );
        app.select_permission_profile(
            &mut app_server,
            PermissionProfileSelection {
                profile_id: ":read-only".into(),
                approval_policy: Some(AskForApproval::OnRequest),
                approvals_reviewer: Some(ApprovalsReviewer::User),
                display_label: "Read Only".into(),
            },
        )
        .await;
    }

    Box::pin(app.retry_safety_buffered_turn(
        &mut tui,
        &mut app_server,
        SafetyBufferedRetry {
            thread_id: source_thread_id,
            turn_id: active_turn_id.clone(),
            model: FASTER_MODEL.to_string(),
            turn: active_turn,
            prompt: UserMessage::from(RETRY_PROMPT),
        },
    ))
    .await;
    assert_eq!(app.voice_owner_thread_id(), Some(voice_owner));

    if scenario == SafetyRetryScenario::UnsupportedPermissions {
        assert_eq!(app.active_thread_id, Some(source_thread_id));
        assert_eq!(app.primary_thread_id, Some(source_thread_id));
        assert_eq!(app.chat_widget.thread_id(), Some(source_thread_id));
        assert!(
            app.chat_widget
                .can_retry_safety_buffered_turn(&active_turn_id)
        );
        let source = app_server
            .thread_read(source_thread_id, /*include_turns*/ true)
            .await?;
        assert_eq!(
            source.turns.last().map(|turn| &turn.status),
            Some(&TurnStatus::InProgress)
        );
        let error_cell = std::iter::from_fn(|| app_event_rx.try_recv().ok())
            .find_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => Some(cell),
                _ => None,
            })
            .expect("unsupported permissions should be added to history");
        insta::assert_snapshot!(
            lines_to_single_string(&error_cell.display_lines(/*width*/ 200)),
            @"■ Failed to retry with a faster model: the selected permission profile cannot be safely represented by the legacy app-server sandbox policy; select a named or legacy-compatible permission profile"
        );
        if let Some(release_active_response) = release_active_response.take() {
            let _ = release_active_response.send(());
        }
        let _ = release_steered_response.send(());
        let _ = release_previous_response.send(());
        let _ = release_retry_response.send(());
        app_server.shutdown().await?;
        server.shutdown().await;
        return Ok(());
    }

    let first_retry_thread_id = app.chat_widget.thread_id().expect("first retry thread id");
    if scenario == SafetyRetryScenario::RetryTwice {
        let first_retry_turn_id =
            next_turn_started(&mut app, &mut app_server, first_retry_thread_id).await;
        drive_until_request_count(
            &mut app,
            &mut app_server,
            &server,
            /*expected_request_count*/ 2,
        )
        .await;
        app.handle_app_server_event(
            &app_server,
            AppServerEvent::ServerNotification(Box::new(
                ServerNotification::ModelSafetyBufferingUpdated(
                    ModelSafetyBufferingUpdatedNotification {
                        thread_id: first_retry_thread_id.to_string(),
                        turn_id: first_retry_turn_id.clone(),
                        model: FASTER_MODEL.to_string(),
                        use_cases: Vec::new(),
                        reasons: Vec::new(),
                        show_buffering_ui: true,
                        faster_model: Some(FASTER_MODEL.to_string()),
                    },
                ),
            )),
        )
        .await;
        drain_active_thread_events(&mut app);
        assert!(
            app.chat_widget
                .can_retry_safety_buffered_turn(&first_retry_turn_id)
        );
        app.chat_widget
            .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        let second_retry = loop {
            match app_event_rx.try_recv() {
                Ok(event @ AppEvent::ConfirmSafetyBufferedRetry { .. }) => {
                    Box::pin(app.handle_event(&mut tui, &mut app_server, event)).await?;
                    app.chat_widget
                        .handle_key_event(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE));
                    app.chat_widget
                        .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
                }
                Ok(AppEvent::RetrySafetyBufferedTurn {
                    thread_id,
                    turn_id,
                    model,
                    turn,
                    prompt,
                }) => {
                    break SafetyBufferedRetry {
                        thread_id,
                        turn_id,
                        model,
                        turn,
                        prompt,
                    };
                }
                Ok(_) => continue,
                Err(err) => panic!("expected second safety-buffering retry event: {err}"),
            }
        };
        let AppCommand::UserTurn { items, .. } = &second_retry.turn else {
            panic!("second safety-buffering retry should retain the user turn");
        };
        assert!(items.iter().any(
            |item| matches!(item, AppServerUserInput::Text { text, .. } if text == RETRY_PROMPT)
        ));
        Box::pin(app.retry_safety_buffered_turn(&mut tui, &mut app_server, second_retry)).await;
    }

    if let Some(draft) = failing_draft {
        assert_eq!(
            app.chat_widget.composer_text_with_pending(),
            format!("{RETRY_PROMPT}\n{draft}")
        );
        assert_eq!(app.chat_widget.thread_id(), Some(source_thread_id));
        if let Some(release_active_response) = release_active_response.take() {
            let _ = release_active_response.send(());
        }
        let _ = release_steered_response.send(());
        app_server.shutdown().await?;
        server.shutdown().await;
        return Ok(());
    }

    let retry_thread_id = app.chat_widget.thread_id().expect("retry thread id");
    // Capture the completed retry before processing its automatic goal continuation.
    wait_for_turn_completed(&mut app, &mut app_server, retry_thread_id).await;
    if scenario == SafetyRetryScenario::PendingPermissions {
        assert_eq!(
            app.chat_widget
                .config_ref()
                .permissions
                .permission_profile(),
            &PermissionProfile::read_only()
        );
    }
    let mut replayed_history = String::new();
    while let Ok(event) = app_event_rx.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            let rendered = lines_to_single_string(&cell.transcript_lines(/*width*/ 80));
            if cell
                .as_any()
                .is::<crate::history_cell::FinalMessageSeparator>()
            {
                replayed_history
                    .push_str(&normalize_completion_timestamps(cell.as_ref(), rendered));
            } else {
                replayed_history.push_str(&rendered);
            }
        }
    }
    assert_eq!(
        replayed_history.contains("Conversation interrupted"),
        scenario == SafetyRetryScenario::InterruptedPrevious
    );
    let forked_history = replayed_history
        .rsplit_once("Thread forked from")
        .expect("safety retry should render fork lineage")
        .1;
    assert_eq!(
        forked_history.matches(RETRY_PROMPT).count(),
        1,
        "the fork should render the retried prompt once: {forked_history}"
    );
    if committed_steer.is_some() {
        let rendered_retry = forked_history
            .lines()
            .skip_while(|line| !line.contains(RETRY_PROMPT))
            .collect::<Vec<_>>()
            .join("\n");
        insta::assert_snapshot!("safety_retry_committed_steer_history", rendered_retry);
    }

    drive_until_request_count(&mut app, &mut app_server, &server, expected_request_count).await;
    let source = app_server
        .thread_read(source_thread_id, /*include_turns*/ true)
        .await?;
    let retry = app_server
        .thread_read(retry_thread_id, /*include_turns*/ true)
        .await?;
    assert_ne!(retry_thread_id, source_thread_id);
    assert_eq!(
        source.turns.last().map(|turn| &turn.status),
        Some(&TurnStatus::Interrupted)
    );
    assert_eq!(
        retry.forked_from_id.as_deref(),
        Some(
            if scenario == SafetyRetryScenario::RetryTwice {
                first_retry_thread_id
            } else {
                source_thread_id
            }
            .to_string()
        )
        .as_deref()
    );
    let expected_retry_prompt = match committed_steer {
        Some(committed_steer) => format!("{RETRY_PROMPT}\n{committed_steer}"),
        None => RETRY_PROMPT.to_string(),
    };
    assert_eq!(user_message_count(&source, RETRY_PROMPT), 1);
    assert_eq!(user_message_count(&retry, &expected_retry_prompt), 1);
    if let Some(committed_steer) = committed_steer {
        assert_eq!(user_message_count(&source, committed_steer), 1);
    }
    if let Some(previous_prompt) = previous_prompt {
        assert_eq!(user_message_count(&source, previous_prompt), 1);
        assert_eq!(user_message_count(&retry, previous_prompt), 1);
    }

    let source_goal = app_server
        .thread_goal_get(source_thread_id)
        .await?
        .goal
        .expect("source goal");
    let retry_goal = app_server
        .thread_goal_get(retry_thread_id)
        .await?
        .goal
        .expect("retry goal");
    let expected_source_tokens = if committed_steer.is_some() { 150 } else { 50 };
    assert_eq!(source_goal.objective, RETRY_GOAL);
    assert_eq!(source_goal.tokens_used, expected_source_tokens);
    assert!(source_goal.time_used_seconds >= 12);
    assert_eq!(retry_goal.objective, RETRY_GOAL);
    assert!(retry_goal.tokens_used >= expected_source_tokens);
    assert!(retry_goal.time_used_seconds >= source_goal.time_used_seconds);

    let request_bodies = server
        .requests()
        .await
        .iter()
        .map(|request| serde_json::from_slice::<Value>(request))
        .collect::<serde_json::Result<Vec<_>>>()?;
    let retry_request_index =
        usize::from(previous_prompt.is_some()) + usize::from(committed_steer.is_some()) + 1;
    let retry_request = request_bodies
        .get(retry_request_index)
        .expect("retry should issue a Responses API request");
    assert_eq!(retry_request["model"].as_str(), Some(FASTER_MODEL));
    assert_eq!(retry_request["reasoning"]["effort"].as_str(), Some("low"));
    let relevant_prompts = user_input_texts(retry_request)
        .into_iter()
        .filter(|text| {
            text == PREVIOUS_PROMPT
                || text == RETRY_PROMPT
                || committed_steer.is_some_and(|steer| text == steer)
        })
        .collect::<Vec<_>>();
    let mut expected_prompts = match previous_prompt {
        Some(previous_prompt) => vec![previous_prompt.to_string(), RETRY_PROMPT.to_string()],
        None => vec![RETRY_PROMPT.to_string()],
    };
    expected_prompts.extend(committed_steer.map(str::to_string));
    assert_eq!(relevant_prompts, expected_prompts);
    if previous_prompt.is_none() {
        assert!(
            !user_input_texts(retry_request)
                .iter()
                .any(|text| text.contains("<turn_aborted>")),
            "first-turn safety retry should not inherit an interruption marker"
        );
    }
    let goal_continuation_request_index = if scenario == SafetyRetryScenario::RetryTwice {
        let second_retry_request = request_bodies
            .get(retry_request_index + 1)
            .expect("second retry should issue a Responses API request");
        assert!(
            user_input_texts(second_retry_request)
                .iter()
                .any(|text| text == RETRY_PROMPT),
            "second safety retry should submit the original prompt"
        );
        assert!(
            !user_input_texts(second_retry_request)
                .iter()
                .any(|text| text.contains("<turn_aborted>")),
            "second safety retry should not inherit an interruption marker"
        );
        retry_request_index + 2
    } else {
        retry_request_index + 1
    };
    assert!(
        user_input_texts(&request_bodies[goal_continuation_request_index])
            .iter()
            .any(|text| text.contains(RETRY_GOAL)),
        "inherited goal continuation should resume after the explicit retry"
    );

    if let Some(release_active_response) = release_active_response.take() {
        let _ = release_active_response.send(());
    }
    let _ = release_steered_response.send(());
    let _ = release_previous_response.send(());
    let _ = release_retry_response.send(());
    app_server.shutdown().await?;
    server.shutdown().await;
    Ok(())
}

