fn next_user_turn_event(
    app_event_rx: &mut tokio::sync::mpsc::UnboundedReceiver<AppEvent>,
) -> AppCommand {
    while let Ok(event) = app_event_rx.try_recv() {
        if let AppEvent::CodexOp(turn @ AppCommand::UserTurn { .. }) = event {
            return turn;
        }
    }
    panic!("expected UserTurn app event");
}

fn interrupt_after_inactive_steer(switch: SteerSwitch) -> Result<()> {
    let via_overview = matches!(switch, SteerSwitch::BetweenTasks);
    let (chunks, release_response) =
        gated_response_chunks("interrupt-response", ev_completed("interrupt-response"));
    let (steered_chunks, release_steered_response) =
        gated_response_chunks("steered-response", ev_completed("steered-response"));
    let (server, _completions) = start_streaming_sse_server(vec![chunks, steered_chunks]).await;
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let codex_home = tempdir()?;
    std::fs::write(
        codex_home.path().join("config.toml"),
        format!(
            r#"
model = "{CURRENT_MODEL}"
model_provider = "{MODEL_PROVIDER_ID}"

[model_providers.{MODEL_PROVIDER_ID}]
name = "Interrupt test"
base_url = "{}/v1"
wire_api = "responses"
request_max_retries = 0
stream_max_retries = 0
"#,
            server.uri()
        ),
    )?;
    app.config.codex_home = codex_home.path().to_path_buf().abs();
    app.config.sqlite = codex_state::SqliteConfig::new_for_testing(codex_home.path().abs());
    app.config.model = Some(CURRENT_MODEL.to_string());
    app.config.model_provider_id = MODEL_PROVIDER_ID.to_string();
    app.config.model_provider = ModelProviderInfo {
        name: "Interrupt test".to_string(),
        base_url: Some(format!("{}/v1", server.uri())),
        request_max_retries: Some(0),
        stream_max_retries: Some(0),
        ..ModelProviderInfo::default()
    };

    let mut tui = crate::tui::test_support::make_test_tui()?;
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let started = app_server.start_thread(&app.config).await?;
    let thread_id = started.session.thread_id;
    app.replace_chat_widget_with_app_server_thread(
        &mut tui,
        started,
        ThreadAttachPresentation::SessionLineage,
        /*initial_user_message*/ None,
    )
    .await?;
    while app_event_rx.try_recv().is_ok() {}

    submit_prompt(&mut app, COMMITTED_STEER);
    let turn = next_user_turn_event(&mut app_event_rx);
    app.submit_thread_op(&mut app_server, thread_id, turn)
        .await?;
    let turn_id = next_turn_started(&mut app, &mut app_server, thread_id).await;
    // Leave the original message's completion queued until after submitting the identical steer.
    tokio::time::timeout(
        std::time::Duration::from_secs(/*secs*/ 5),
        server.wait_for_request_count(/*count*/ 1),
    )
    .await?;

    let acknowledged_input = app.chat_widget.capture_thread_input_state();
    submit_prompt(&mut app, COMMITTED_STEER);
    let steer = next_user_turn_event(&mut app_event_rx);
    let AppCommand::UserTurn {
        client_user_message_id,
        ..
    } = &steer
    else {
        unreachable!("user turn");
    };
    let expected_client_id = client_user_message_id.clone();
    let pending_input = app.chat_widget.capture_thread_input_state();
    app.submit_thread_op(&mut app_server, thread_id, steer)
        .await?;
    let other_id = ThreadId::from_string(
        &app_test_support::create_fake_rollout(
            app.config.codex_home.as_path(),
            "2025-01-05T12-00-00",
            "2025-01-05T12:00:00Z",
            "Other task",
            Some(MODEL_PROVIDER_ID),
            /*git_info*/ None,
        )
        .expect("materialize other task"),
    )?;
    let other = app_server
        .resume_thread(
            &app.local_settings,
            app.config.clone(),
            other_id,
            crate::app_server_session::ResumeModelSettings::PreserveExistingThread,
        )
        .await?;
    for cwd in [&app.config.cwd, &other.session.cwd] {
        crate::legacy_core::config::set_project_trust_level(
            app.config.codex_home.as_path(),
            cwd.as_path(),
            codex_protocol::config_types::TrustLevel::Trusted,
        )
        .map_err(std::io::Error::other)?;
    }
    app.thread_event_channels.insert(
        other_id,
        ThreadEventChannel::new_with_session(
            THREAD_EVENT_CHANNEL_CAPACITY,
            other.session,
            other.turns,
        ),
    );
    // Receive the real commit while another thread is visible, with no replay capacity.
    if via_overview {
        Box::pin(app.select_agents_overview_thread(&mut tui, &mut app_server, other_id)).await?;
    } else {
        Box::pin(app.select_agent_thread(&mut tui, &mut app_server, other_id)).await?;
        app.thread_event_channels[&thread_id]
            .store
            .lock()
            .await
            .capacity = 0;
    }
    assert_eq!(app.current_displayed_thread_id(), Some(other_id));
    let mut release_response = Some(release_response);
    loop {
        let event = tokio::time::timeout(
            std::time::Duration::from_secs(/*secs*/ 5),
            app_server.next_event(),
        )
        .await?
        .expect("app-server remains open");
        let committed_id = if let AppServerEvent::ServerNotification(notification) = &event
            && let ServerNotification::ItemCompleted(item) = notification.as_ref()
            && let ThreadItem::UserMessage {
                content, client_id, ..
            } = &item.item
            && ChatWidget::user_message_display_from_inputs(content).message == COMMITTED_STEER
        {
            Some(client_id.clone().expect("receipt echoes the submission ID"))
        } else {
            None
        };
        app.handle_app_server_event(&app_server, event).await;
        if let Some(client_id) = committed_id {
            let saved_input = if via_overview {
                assert!(!app.thread_event_channels.contains_key(&thread_id));
                app.agents_overview.input_states.get(&thread_id).cloned()
            } else {
                let store = app.thread_event_channels[&thread_id].store.lock().await;
                assert!(store.buffer.is_empty());
                store.input_state.clone()
            };
            if let Some(release_response) = release_response.take() {
                assert_ne!(client_id, expected_client_id);
                assert_eq!(saved_input, pending_input);
                let _ = release_response.send(());
            } else {
                assert_eq!(client_id, expected_client_id);
                assert_eq!(saved_input, acknowledged_input);
                break;
            }
        }
    }
    if via_overview {
        Box::pin(app.select_agents_overview_thread(&mut tui, &mut app_server, thread_id)).await?;
    } else {
        Box::pin(app.select_agent_thread(&mut tui, &mut app_server, thread_id)).await?;
    }
    assert_eq!(app.active_thread_id, Some(thread_id));

    let interrupt = AppCommand::interrupt();
    assert!(
        app.try_submit_active_thread_op_via_app_server(&mut app_server, thread_id, &interrupt)
            .await?
    );
    let AppServerRequestId::Integer(next_request_id) = app_server.next_request_id() else {
        unreachable!("embedded app-server request IDs are integers");
    };
    assert!(
        app.try_submit_active_thread_op_via_app_server(&mut app_server, thread_id, &interrupt)
            .await?
    );
    assert_eq!(
        app_server.next_request_id(),
        AppServerRequestId::Integer(next_request_id + 1)
    );
    {
        let store = app.thread_event_channels[&thread_id].store.lock().await;
        assert_eq!(store.active_turn_id.as_deref(), Some(turn_id.as_str()));
        assert_eq!(
            store.pending_interrupt_turn_id.as_deref(),
            Some(turn_id.as_str())
        );
    }

    while app_event_rx.try_recv().is_ok() {}
    app.handle_thread_event_now(ThreadBufferedEvent::Notification(Box::new(
        ServerNotification::Warning(WarningNotification {
            thread_id: Some(thread_id.to_string()),
            message: "event handled while interrupt is pending".to_string(),
        }),
    )));
    assert!(matches!(
        app_event_rx.try_recv(),
        Ok(AppEvent::InsertHistoryCell(_))
    ));

    wait_for_turn_completed(&mut app, &mut app_server, thread_id).await;
    assert_eq!(
        app.thread_event_channels[&thread_id]
            .store
            .lock()
            .await
            .pending_interrupt_turn_id,
        None
    );

    insta::assert_snapshot!(app.chat_widget.composer_text_with_pending(), @"");
    assert!(
        std::iter::from_fn(|| app_event_rx.try_recv().ok())
            .all(|event| !matches!(event, AppEvent::CodexOp(AppCommand::UserTurn { .. })))
    );
    let source = app_server
        .thread_read(thread_id, /*include_turns*/ true)
        .await?;
    assert_eq!(user_message_count(&source, COMMITTED_STEER), 2);
    let _ = release_steered_response.send(());
    app_server.shutdown().await?;
    server.shutdown().await;
    Ok(())
}

fn security_setup_fetch_with_default_features_uses_authenticated_codex_endpoint() -> Result<()>
{
    let (mut app, mut events, _ops) = make_test_app_with_channels().await;
    let backend = wiremock::MockServer::start().await;
    app.config.chatgpt_base_url = backend.uri();
    app.config.cli_auth_credentials_store_mode = AuthCredentialsStoreMode::File;
    std::fs::write(
        app.config.codex_home.join("config.toml"),
        format!("chatgpt_base_url = {:?}\n", backend.uri()),
    )?;
    write_chatgpt_auth(
        &app.config.codex_home,
        ChatGptAuthFixture::new("test-token")
            .email("user@example.com")
            .account_id("account")
            .chatgpt_user_id("user"),
        AuthCredentialsStoreMode::File,
    )
    .expect("write synthetic auth");
    app_test_support::mount_workspace_routing(&backend).await;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    wiremock::Mock::given(wiremock::matchers::path("/wham/security-setup"))
        .and(wiremock::matchers::header(
            "authorization",
            "Bearer test-token",
        ))
        .and(wiremock::matchers::header("ChatGPT-Account-ID", "account"))
        .and(wiremock::matchers::header(
            "User-Agent",
            codex_login::default_client::get_codex_user_agent(),
        ))
        .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!({
            "notice": {
                "title": "Keep using Daybreak mode", "description": "Set up security.",
                "action": {"label": "Set up security", "url": "https://chatgpt.com/cyber"}
            }
        })))
        .expect(3)
        .mount(&backend)
        .await;
    let request_id = app.chat_widget.security_setup_request_id;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let init = app.chatwidget_init_for_forked_or_resumed_thread(
        &mut tui,
        app.config.clone(),
        /*initial_user_message*/ None,
    );
    app.replace_chat_widget(ChatWidget::new_with_app_event(init));
    assert_eq!(app.chat_widget.security_setup_request_id, request_id);
    crate::security_setup::prefetch(&app.config, &server, app.app_event_tx.clone(), request_id);
    let notice = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            if let AppEvent::SecuritySetupLoaded {
                request_id: actual,
                identity,
                notice,
            } = events.recv().await.unwrap()
            {
                assert_eq!(actual, request_id);
                assert_eq!(
                    identity,
                    Identity {
                        account: "account".into(),
                        user: "user".into()
                    }
                );
                break notice;
            }
        }
    })
    .await?;
    assert!(notice.valid());
    let identity = Identity {
        account: "account".into(),
        user: "user".into(),
    };
    app.handle_event(
        &mut tui,
        &mut server,
        AppEvent::SecuritySetupLoaded {
            request_id,
            identity: identity.clone(),
            notice: notice.clone(),
        },
    )
    .await?;
    assert!(render_bottom_popup(&app.chat_widget, /*width*/ 70).contains("Set up security"));
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert!(!render_bottom_popup(&app.chat_widget, /*width*/ 70).contains("Set up security"));

    // Reconnect can emit AccountUpdated for the same identity more than once.
    for _ in 0..2 {
        let stale_request_id = app.chat_widget.security_setup_request_id;
        app.handle_app_server_event(
            &server,
            AppServerEvent::ServerNotification(Box::new(ServerNotification::AccountUpdated(
                AccountUpdatedNotification {
                    auth_mode: Some(AuthMode::Chatgpt),
                    plan_type: None,
                },
            ))),
        )
        .await;
        let request_id = app.chat_widget.security_setup_request_id;
        assert_ne!(request_id, stale_request_id);
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::SecuritySetupLoaded {
                request_id: stale_request_id,
                identity: Identity {
                    account: "stale-account".into(),
                    ..identity.clone()
                },
                notice: notice.clone(),
            },
        )
        .await?;
        assert!(!render_bottom_popup(&app.chat_widget, /*width*/ 70).contains("Set up security"));

        let init = app.chatwidget_init_for_forked_or_resumed_thread(
            &mut tui,
            app.config.clone(),
            /*initial_user_message*/ None,
        );
        app.replace_chat_widget(ChatWidget::new_with_app_event(init));
        let event = tokio::time::timeout(Duration::from_secs(5), async {
            let mut security_notice = None;
            let mut email_loaded = false;
            loop {
                let event = events.recv().await.unwrap();
                if matches!(event, AppEvent::AccountEmailLoaded { .. }) {
                    app.handle_event(&mut tui, &mut server, event).await?;
                    email_loaded = true;
                } else if let AppEvent::SecuritySetupLoaded {
                    request_id: actual,
                    identity: actual_identity,
                    ..
                } = &event
                {
                    assert_eq!(*actual, request_id);
                    assert_eq!(actual_identity, &identity);
                    security_notice = Some(event);
                }
                if email_loaded && let Some(event) = security_notice.take() {
                    break Result::<AppEvent>::Ok(event);
                }
            }
        })
        .await??;
        app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::AccountEmailLoaded {
                request_id: uuid::Uuid::new_v4(),
                email: Some("stale@example.com".into()),
            },
        )
        .await?;
        assert_eq!(
            app.chat_widget.status_account_display(),
            Some(&StatusAccountDisplay::ChatGpt {
                email: Some("user@example.com".into()),
                plan: None,
            })
        );
        app.handle_event(&mut tui, &mut server, event).await?;
        assert!(!render_bottom_popup(&app.chat_widget, /*width*/ 70).contains("Set up security"));
    }
    backend.verify().await;
    server.shutdown().await?;
    Ok(())
}

fn transcript_alt_beginning_loads_every_older_history_page() -> Result<()> {
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let codex_home = tempdir()?;
    app.config.codex_home = codex_home.path().to_path_buf().abs();
    app.config.sqlite = SqliteConfig::new_for_testing(codex_home.path().abs());
    app.local_settings.tui.terminal_resize_reflow_max_rows = Some(2);
    let thread_id = create_fake_paginated_rollout(
        codex_home.path(),
        "2026-01-02T00-00-00",
        "2026-01-02T00:00:00Z",
        "multi-page transcript",
        Some(app.config.model_provider_id.as_str()),
        /*git_info*/ None,
    )
    .map_err(|error| color_eyre::eyre::eyre!("failed to create paginated rollout: {error}"))?;
    let thread_id = ThreadId::from_string(&thread_id)?;
    let path = rollout_path(
        codex_home.path(),
        "2026-01-02T00-00-00",
        &thread_id.to_string(),
    );
