    let session = started.session.clone();
    app.enqueue_primary_thread_session(started.session, started.turns)
        .await?;
    app_server
        .thread_goal_set(
            thread_id,
            Some("Do not restart this stopped goal".to_string()),
            Some(ThreadGoalStatus::Blocked),
            /*token_budget*/ None,
        )
