    app.enqueue_primary_thread_session(session, vec![failed_turn])
        .await?;
    let precaution = render_bottom_popup(&app.chat_widget, /*width*/ 80);
    let AppServerRequestId::Integer(next_request_id) = app_server.next_request_id() else {
        unreachable!("embedded app-server request IDs are integers");
    };

    app.maybe_prompt_resume_paused_goal_after_resume(&mut app_server, thread_id)
        .await;
    for event in [
        AppEvent::CodexOp(queued_turn),
        AppEvent::CodexOp(crate::app_command::AppCommand::ExecApproval {
            id: "queued-approval".to_string(),
            turn_id: None,
            decision: codex_app_server_protocol::CommandExecutionApprovalDecision::Accept,
        }),
        AppEvent::SetThreadGoalStatus {
            thread_id,
            status: ThreadGoalStatus::Active,
        },
        AppEvent::SetThreadGoalDraft {
            thread_id,
            draft: crate::goal_files::GoalDraft {
                objective: "Do not replace this stopped goal".to_string(),
                ..Default::default()
            },
            mode: crate::app_event::ThreadGoalSetMode::ReplaceExisting,
        },
        AppEvent::StartSide {
            parent_thread_id: thread_id,
            user_message: Some("Do not fork this stopped thread".into()),
        },
        AppEvent::ForkCurrentSession { name: None },
        AppEvent::StartManagedWorktree {
            mode: crate::app_event::ManagedWorktreeMode::Fork,
            name: None,
        },
        AppEvent::OpenAgentPicker,
        AppEvent::SelectAgentThread(thread_id),
    ] {
        app.handle_event(&mut tui, &mut app_server, event).await?;
    }

    assert!(!app.config.codex_home.join("worktrees").exists());
    assert_eq!(
        app_server.next_request_id(),
        AppServerRequestId::Integer(next_request_id + 1)
    );
    assert_eq!(
        render_bottom_popup(&app.chat_widget, /*width*/ 80),
        precaution
    );
    assert_eq!(
        app_server
            .thread_goal_get(thread_id)
            .await?
            .goal
            .unwrap()
            .status,
        ThreadGoalStatus::Blocked
    );

    app_server.shutdown().await?;
    Ok(())
}

fn unavailable_thread_routes_local_and_recovery_commands() -> Result<()> {
    let (mut app, mut events, mut ops) = make_test_app_with_channels().await;
    let id = ThreadId::new();
    app.active_thread_id = Some(id);
    app.primary_thread_id = Some(id);
    app.app_server_target = AppServerTarget::Remote {
        endpoint: crate::resolve_remote_addr("ws://127.0.0.1:1")?,
    };
    app.chat_widget
        .handle_thread_session(test_thread_session(id, app.config.cwd.to_path_buf()));
    app.ensure_thread_channel(id).mark_replay_only();
    app.chat_widget
        .restore_user_message_to_composer("pending input".into());
    app.chat_widget.handle_key_event(KeyCode::Enter.into());
    app.chat_widget
        .restore_user_message_to_composer("keep queued input".into());
    app.chat_widget.handle_key_event(KeyCode::Tab.into());
    assert_eq!(
        app.chat_widget.queued_user_message_texts(),
        vec!["keep queued input"]
    );
    app.chat_widget.pause_unavailable_thread();
    assert_eq!(
        app.chat_widget.queued_user_message_texts(),
        vec!["pending input", "keep queued input"]
    );
    app.chat_widget
        .set_local_worktree_operations(/*enabled*/ false);
    let mut session = start_config_write_test_app_server(&app).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    while events.try_recv().is_ok() {}
    while ops.try_recv().is_ok() {}

    for command in [
        "/new",
        "/clear recovery",
        "/resume",
        "/agents",
        "/subagents",
        "/raw on",
        "/warnings",
        "/quit",
        "/exit",
    ] {
        app.chat_widget
            .restore_user_message_to_composer(command.into());
        app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
            .await?;
        let mut dispatched = false;
        while let Ok(event) = events.try_recv() {
            dispatched |= matches!((command, &event),
                ("/clear recovery", AppEvent::ClearUi { name: Some(name) }) if name == "recovery"
            );
            dispatched |= matches!(
                (command, &event),
                ("/new", AppEvent::NewSession { name: None })
                    | ("/resume", AppEvent::OpenResumePicker)
                    | ("/agents", AppEvent::OpenAgentsOverview)
                    | ("/subagents", AppEvent::OpenAgentPicker)
                    | ("/raw on", AppEvent::RawOutputModeChanged { enabled: true })
                    | ("/warnings", AppEvent::OpenWarnings)
                    | ("/quit" | "/exit", AppEvent::Exit(_))
            );
        }
        assert!(dispatched, "{command}");
        assert!(ops.try_recv().is_err(), "{command}");
    }

    app.chat_widget
        .restore_user_message_to_composer("/pwd".into());
    app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
        .await?;
    let history = drain_history(&mut app, &mut tui, &mut session, &mut events).await?;
    assert!(history.contains("Current working directory:"));
    assert_snapshot!(
        "unavailable_thread_local_command",
        history.replace(&app.config.cwd.display().to_string(), "/project")
    );

    app.chat_widget
        .restore_user_message_to_composer("/status".into());
    app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
        .await?;
    let history = drain_history(&mut app, &mut tui, &mut session, &mut events).await?;
    assert!(history.contains("Model:"), "{history}");
    assert!(app.chat_widget.composer_is_empty());
    assert!(ops.try_recv().is_err());

    let input = app.chat_widget.capture_thread_input_state();
    app.chat_widget
        .restore_user_message_to_composer("/copy".into());
    app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
        .await?;
    app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Esc.into()))
        .await?;
    while let Ok(event) = events.try_recv() {
        assert!(!matches!(event, AppEvent::CodexOp(_)));
        app.handle_event(&mut tui, &mut session, event).await?;
    }
    assert_eq!(app.chat_widget.capture_thread_input_state(), input);
    assert!(ops.try_recv().is_err());

    for offline in [false, true] {
        app.reconnect.offline = offline;
        for draft in if offline {
            vec!["/new", "/clear", "/status"]
        } else {
            vec!["keep my draft", "/review", "/rename changed"]
        } {
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL)),
            )
            .await?;
            app.handle_tui_event(
                &mut tui,
                &mut session,
                TuiEvent::Key(KeyCode::Backspace.into()),
            )
            .await?;
            app.chat_widget
                .restore_user_message_to_composer(draft.into());
            app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
                .await?;
            assert_eq!(app.chat_widget.composer_text_with_pending(), draft);
            assert!(events.try_recv().is_err());
            assert!(ops.try_recv().is_err());
        }
    }
    session.shutdown().await?;
    Ok(())
}

fn unavailable_thread_new_and_clear_start_a_writable_session() -> Result<()> {
    for (command, activity) in ["/new", "/clear"]
        .into_iter()
        .flat_map(|command| ["idle", "review", "mcp"].map(|activity| (command, activity)))
    {
        let (mut app, mut events, _) = make_test_app_with_channels().await;
        let id = ThreadId::new();
        app.active_thread_id = Some(id);
        app.primary_thread_id = Some(id);
        app.app_server_target = AppServerTarget::Remote {
            endpoint: crate::resolve_remote_addr("ws://127.0.0.1:1")?,
        };
        app.chat_widget
            .handle_thread_session(test_thread_session(id, app.config.cwd.to_path_buf()));
        app.ensure_thread_channel(id).mark_replay_only();
        match activity {
            "review" => app.chat_widget.replay_thread_turns(
                vec![test_turn(
                    "review",
                    TurnStatus::InProgress,
                    vec![ThreadItem::EnteredReviewMode {
                        id: "review-start".into(),
                        review: "changes against main".into(),
                    }],
                )],
                ReplayKind::ResumeInitialMessages,
            ),
            "mcp" => app.chat_widget.handle_server_notification(
                ServerNotification::McpServerStatusUpdated(McpServerStatusUpdatedNotification {
                    thread_id: Some(id.to_string()),
                    name: "slow".into(),
                    status: McpServerStartupState::Starting,
                    error: None,
                    failure_reason: None,
                }),
                /*replay_kind*/ None,
            ),
            _ => {}
        }
        app.chat_widget.pause_unavailable_thread();
        app.chat_widget
            .set_local_worktree_operations(/*enabled*/ false);
        let mut session = start_config_write_test_app_server(&app).await?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        while events.try_recv().is_ok() {}
        app.chat_widget
            .restore_user_message_to_composer(command.into());
        app.handle_tui_event(&mut tui, &mut session, TuiEvent::Key(KeyCode::Enter.into()))
            .await?;
        while let Ok(event) = events.try_recv() {
            if matches!(
                event,
                AppEvent::NewSession { .. } | AppEvent::ClearUi { .. }
            ) {
                app.handle_event(&mut tui, &mut session, event).await?;
                break;
            }
        }
        let new_id = app.chat_widget.thread_id().expect("new thread");
        assert_ne!(new_id, id, "{command}");
        assert!(!app.thread_unavailable(new_id), "{command}");
        session.shutdown().await?;
    }
    Ok(())
}

fn inactive_thread_user_verification_replays_queued_request_once() -> Result<()> {
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let primary_thread_id = ThreadId::new();
    let side_thread_id = ThreadId::new();
    let thread_id = ThreadId::new();
    let request = user_verification_server_request(thread_id, /*request_id*/ 11);

    app.primary_thread_id = Some(primary_thread_id);
    app.active_thread_id = Some(side_thread_id);
    app.side_threads
        .insert(side_thread_id, SideThreadState::new(primary_thread_id));
    app.agent_navigation.upsert(
        thread_id,
        Some("Verifier".to_string()),
        Some("worker".to_string()),
        /*is_closed*/ false,
    );
    app.enqueue_thread_request(thread_id, request.clone())
        .await?;

    assert!(!app.chat_widget.has_active_view());
    assert_eq!(
        app.pending_inactive_thread_requests().await,
        vec![(thread_id, request)]
    );

    app.side_threads.remove(&side_thread_id);
    app.active_thread_id = Some(primary_thread_id);
    app.surface_pending_inactive_thread_interactive_requests()
        .await?;
    app.surface_pending_inactive_thread_interactive_requests()
        .await?;
    insta::assert_snapshot!(
        "inactive_thread_user_verification_prompt",
        render_bottom_popup(&app.chat_widget, /*width*/ 80)
    );
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));

    assert_eq!(
        next_submitted_thread_op(&mut app_event_rx).await,
        (
            thread_id,
            Op::ResolveUserVerification {
                server_name: "deployments".to_string(),
                request_id: AppServerRequestId::Integer(11),
                response: crate::app_command::UserVerificationResponse::Cancel,
            }
        )
    );
    assert!(!app.chat_widget.has_active_view());
    assert!(
        !std::iter::from_fn(|| app_event_rx.try_recv().ok())
            .any(|event| matches!(event, AppEvent::SubmitThreadOp { .. }))
    );
    Ok(())
}

fn discarding_side_cancels_verification_and_ignores_late_proof() -> Result<()> {
    let (mut app, mut events, _ops) = make_test_app_with_channels().await;
    let mut app_server =
        crate::start_embedded_app_server_for_picker(app.chat_widget.config_ref()).await?;
    let primary_thread_id = ThreadId::new();
    let side_thread_id = ThreadId::new();
    let request = user_verification_server_request(side_thread_id, /*request_id*/ 19);
    app.active_thread_id = Some(primary_thread_id);
    app.side_threads
        .insert(side_thread_id, SideThreadState::new(primary_thread_id));
    app.thread_event_channels
        .insert(side_thread_id, ThreadEventChannel::new(/*capacity*/ 4));
    app.pending_app_server_requests
        .note_server_request(&request);
    let attempt = app
        .pending_app_server_requests
        .user_verification
        .begin(&side_thread_id.to_string(), "deployments", request.id())
        .expect("pending side-thread verification");

    app.discard_side_thread_in_background(&mut app_server, side_thread_id)
        .await;
    assert!(attempt.cancelled.is_cancelled());
    assert!(
        !app.pending_app_server_requests
            .contains_server_request(&request)
    );

    app.finish_user_verification(
        &mut app_server,
        side_thread_id,
        "deployments".to_string(),
        request.id().clone(),
        attempt.id,
        Ok(codex_app_server_protocol::UserVerificationProof {
            credential_id: "discarded-credential".to_string(),
            signature: "discarded-signature".to_string(),
        }),
    )
    .await?;
    assert!(
        !std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event, AppEvent::SubmitThreadOp { .. }))
    );
    app_server.shutdown().await?;
    Ok(())
}

fn inactive_thread_user_verification_preserves_foreground_stream() -> Result<()> {
    let (mut app, mut app_event_rx, _op_rx) = make_test_app_with_channels().await;
    let foreground_thread_id = ThreadId::new();
    let thread_id = ThreadId::new();
    app.primary_thread_id = Some(foreground_thread_id);
    app.active_thread_id = Some(foreground_thread_id);
    app.chat_widget.handle_thread_session(test_thread_session(
        foreground_thread_id,
        test_path_buf("/tmp/project"),
    ));
    while app_event_rx.try_recv().is_ok() {}
    app.chat_widget.handle_server_notification(
        agent_message_delta_notification(
            foreground_thread_id,
            "turn-foreground",
            "message-foreground",
            "The foreground answer",
        ),
        /*replay_kind*/ None,
    );
    assert!(app.chat_widget.has_active_agent_stream());

    app.enqueue_thread_request(
        thread_id,
        user_verification_server_request(thread_id, /*request_id*/ 13),
    )
    .await?;
    assert!(app.chat_widget.has_active_view());
    assert!(app.chat_widget.has_active_agent_stream());
    app.chat_widget
        .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));

    app.chat_widget.handle_server_notification(
        agent_message_delta_notification(
            foreground_thread_id,
            "turn-foreground",
            "message-foreground",
            " continues.",
        ),
        /*replay_kind*/ None,
    );
    app.chat_widget.handle_server_notification(
        ServerNotification::ItemCompleted(codex_app_server_protocol::ItemCompletedNotification {
            thread_id: foreground_thread_id.to_string(),
            turn_id: "turn-foreground".to_string(),
            completed_at_ms: 0,
            item: ThreadItem::AgentMessage {
                id: "message-foreground".to_string(),
                text: "The foreground answer continues.".to_string(),
                phase: None,
                memory_citation: None,
                delivery: None,
                questions: None,
            },
        }),
        /*replay_kind*/ None,
    );

    let mut approved = Vec::new();
    let mut completed_messages = Vec::new();
    let mut tui = crate::tui::test_support::make_test_tui()?;
    while let Ok(event) = app_event_rx.try_recv() {
        match event {
            AppEvent::UserVerificationApproved {
                thread_id,
                server_name,
                request_id,
            } => approved.push((thread_id, server_name, request_id)),
            AppEvent::InsertHistoryCell(cell) => app.insert_history_cell(&mut tui, cell),
            AppEvent::ConsolidateAgentMessage {
                source,
                copy_source,
                cwd,
                inline_visualization_context,
                scrollback_reflow,
                deferred_history_cell,
            } => {
                completed_messages.push(source.clone());
                app.handle_consolidate_agent_message(
                    &mut tui,
                    history_cell::AgentMarkdownCell::new_with_inline_visualizations(
                        source,
                        &cwd,
                        inline_visualization_context,
                    )
                    .with_copy_source(copy_source),
                    scrollback_reflow,
                    deferred_history_cell,
                )?;
                app.chat_widget.note_stream_consolidation_completed();
            }
            _ => {}
        }
    }
    assert_eq!(
        approved,
        vec![(
            thread_id,
            "deployments".to_string(),
            AppServerRequestId::Integer(13)
        )]
    );
    assert_eq!(completed_messages, vec!["The foreground answer continues."]);
    assert!(!app.chat_widget.has_active_agent_stream());
    insta::assert_snapshot!(
        "inactive_thread_user_verification_foreground_history",
        app.render_transcript_lines_for_reflow(/*width*/ 80)
            .lines
            .iter()
            .map(rendered_line_text)
            .collect::<Vec<_>>()
            .join("\n")
    );
    Ok(())
}

fn next_submitted_thread_op(
    app_event_rx: &mut tokio::sync::mpsc::UnboundedReceiver<AppEvent>,
) -> (ThreadId, Op) {
    time::timeout(std::time::Duration::from_secs(/*secs*/ 1), async {
        loop {
            match app_event_rx.recv().await {
                Some(AppEvent::SubmitThreadOp { thread_id, op }) => break (thread_id, op),
                Some(_) => {}
                None => panic!("app event channel closed before submitting an operation"),
            }
        }
    })
    .await
    .expect("user-verification operation should be submitted promptly")
}

fn open_thread_goal_editor(
        &mut self,
        app_server: &mut AppServerSession,
        thread_id: Option<ThreadId>,
    ) {
        let Some(thread_id) = thread_id else {
            self.show_no_thread_goal_to_edit();
            return;
        };

        let result = app_server.thread_goal_get(thread_id).await;
        if self.current_displayed_thread_id() != Some(thread_id) {
            return;
        }

        let response = match result {
            Ok(response) => response,
            Err(err) => {
                self.chat_widget
                    .add_error_message(thread_goal_error_message("read", &err));
                return;
            }
        };

        let Some(mut goal) = response.goal else {
            self.show_no_thread_goal_to_edit();
            return;
        };

        let codex_home = app_server.codex_home_path(&self.config.codex_home);
        match goal_files::objective_text_for_edit(app_server, codex_home.as_ref(), &goal.objective)
            .await
        {
            Ok(objective) => goal.objective = objective,
            Err(err) => {
                self.chat_widget.add_error_message(err.to_string());
            }
        }
        if self.current_displayed_thread_id() != Some(thread_id) {
            return;
        }
        self.chat_widget.show_goal_edit_prompt(thread_id, goal);
    }

