fn try_submit_active_thread_op_via_app_server(
        &mut self,
        app_server: &mut AppServerSession,
        thread_id: ThreadId,
        op: &AppCommand,
    ) -> Result<bool> {
        if user_turn_submission::try_submit_user_turn(self, app_server, thread_id, op).await? {
            return Ok(true);
        }
        match op {
            AppCommand::Interrupt => {
                let mut turn_id = self
                    .active_turn_id_for_thread(thread_id)
                    .await
                    .unwrap_or_default();
                let (thread_event_tx, thread_event_store) = {
                    let channel = self.ensure_thread_channel(thread_id);
                    (channel.sender.clone(), Arc::clone(&channel.store))
                };
                self.reset_backtrack_state();
                if !turn_id.is_empty() {
                    let mut store = thread_event_store.lock().await;
                    if store.pending_interrupt_turn_id.as_deref() == Some(turn_id.as_str()) {
                        return Ok(true);
                    }
                    store.pending_interrupt_turn_id = Some(turn_id.clone());
                }
                let request_handle = app_server.request_handle();
                let request_ids = [app_server.next_request_id(), app_server.next_request_id()];
                tokio::spawn(async move {
                    for (attempt, request_id) in request_ids.into_iter().enumerate() {
                        let result = request_handle
                            .request_typed::<TurnInterruptResponse>(ClientRequest::TurnInterrupt {
                                request_id,
                                params: TurnInterruptParams {
                                    thread_id: thread_id.to_string(),
                                    turn_id: turn_id.clone(),
                                },
                            })
                            .await;

                        match result {
                            Ok(_) => break,
                            Err(error) => {
                                if attempt == 0
                                    && let Some(actual_turn_id) = active_turn_interrupt_race(&error)
                                    && actual_turn_id != turn_id
                                {
                                    thread_event_store.lock().await.pending_interrupt_turn_id =
                                        Some(actual_turn_id.clone());
                                    turn_id = actual_turn_id;
                                    continue;
                                }
                                tracing::warn!(error = %error, "turn/interrupt failed in TUI");
                                let notification =
                                    ServerNotification::Warning(WarningNotification {
                                        thread_id: Some(thread_id.to_string()),
                                        message: format!("Failed to interrupt turn: {error}"),
                                    });
                                let should_send = {
                                    let mut store = thread_event_store.lock().await;
                                    store.push_notification_ref(&notification);
                                    store.active
                                };
                                if should_send
                                    && let Err(error) = thread_event_tx
                                        .send(ThreadBufferedEvent::Notification(Box::new(
                                            notification,
                                        )))
                                        .await
                                {
                                    tracing::warn!(error = %error, "thread event channel closed");
                                }
                                break;
                            }
                        }
                    }
                });
                Ok(true)
            }
            AppCommand::ListSkills { cwds, force_reload } => {
                // A queued refresh can outlive the workspace it was requested for.
                if !cwds
                    .iter()
                    .any(|cwd| cwd == self.chat_widget.config_ref().cwd.as_path())
                {
                    return Ok(true);
                }
                self.handle_skills_list_result(
                    app_server
                        .skills_list(codex_app_server_protocol::SkillsListParams {
                            cwds: cwds.clone(),
                            force_reload: *force_reload,
                        })
                        .await,
                    "failed to refresh skills",
                );
                Ok(true)
            }
            AppCommand::Compact => {
                app_server.thread_compact_start(thread_id).await?;
                Ok(true)
            }
            AppCommand::SetThreadName { name } => {
                let name = name.to_string();
                app_server.thread_set_name(thread_id, name.clone()).await?;
                self.chat_widget.expect_manual_thread_name(thread_id, name);
                self.cancel_thread_title_generation(thread_id);
                Ok(true)
            }
            AppCommand::Review { target } => {
                let response = app_server.review_start(thread_id, target.clone()).await?;
                let review_thread_id = ThreadId::from_string(&response.review_thread_id)
                    .wrap_err("review/start returned invalid review thread id")?;
                let store = Arc::clone(&self.ensure_thread_channel(review_thread_id).store);
                let mut store = store.lock().await;
                store.set_active_turn_id(response.turn.id);
                self.chat_widget.on_review_started();
                Ok(true)
            }
            AppCommand::CleanBackgroundTerminals => {
                app_server
                    .thread_background_terminals_clean(thread_id)
                    .await?;
                Ok(true)
            }
            AppCommand::RealtimeConversationStart {
                thread_id: realtime_thread_id,
                offer_sdp,
            } => {
                if *realtime_thread_id != thread_id {
                    return Ok(true);
                }
                let model = self
                    .chat_widget
                    .config_ref()
                    .experimental_realtime_ws_model
                    .clone();
                let voices = self.realtime_voices(app_server).await?;
                let voice = self.effective_realtime_voice(app_server, &voices).await?;
                app_server
                    .thread_realtime_start(
                        *realtime_thread_id,
                        String::from(offer_sdp.clone()),
                        model,
                        voice,
                    )
                    .await?;
                Ok(true)
            }
            AppCommand::RealtimeConversationStop {
                thread_id: realtime_thread_id,
            } => {
                app_server.thread_realtime_stop(*realtime_thread_id).await?;
                Ok(true)
            }
            AppCommand::RealtimeConversationSpeech {
                thread_id: realtime_thread_id,
                attempt_id,
                input_generation,
                delivery_id,
                text,
            } => {
                if !self.chat_widget.has_pending_realtime_speech(*delivery_id) {
                    return Ok(true);
                }
                if *realtime_thread_id != thread_id
                    || !self.chat_widget.is_current_realtime_attempt(
                        *realtime_thread_id,
                        *attempt_id,
                        *input_generation,
                    )
                {
                    self.chat_widget
                        .restore_undelivered_realtime_speech(*delivery_id);
                    return Ok(true);
                }
                app_server
                    .thread_realtime_append_speech(*realtime_thread_id, text.as_str().to_owned())
                    .await?;
                self.chat_widget.accept_realtime_speech(*delivery_id);
                Ok(true)
            }
            AppCommand::RunUserShellCommand { command } => {
                app_server
                    .thread_shell_command(thread_id, command.to_string())
                    .await?;
                Ok(true)
            }
            AppCommand::ReloadUserConfig => {
                app_server.reload_user_config().await?;
                Ok(true)
            }
            AppCommand::OverrideTurnContext { .. } => {
                self.sync_override_turn_context_settings(app_server, thread_id, op)
                    .await;
                Ok(true)
            }
            AppCommand::ApproveGuardianDeniedAction { event } => {
                app_server
                    .thread_approve_guardian_denied_action(thread_id, event)
                    .await?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

