fn fetch_models(&self, request_id: Uuid, app_event_tx: AppEventSender) {
        let request_handle = self.request_handle();
        tokio::spawn(async move {
            let result = request_handle
                .request_typed::<ModelListResponse>(ClientRequest::ModelList {
                    request_id: RequestId::String(format!("model-list-{request_id}")),
                    params: ModelListParams {
                        cursor: None,
                        limit: None,
                        include_hidden: Some(true),
                    },
                })
                .await
                .map(|response| {
                    response
                        .data
                        .into_iter()
                        .map(model_preset_from_api_model)
                        .collect()
                })
                .map_err(|err| err.to_string());
            app_event_tx.send(AppEvent::ModelsLoaded { request_id, result });
        });
    }

fn actionable_banner(&self, clock_format: ClockFormat) -> ActionableBanner {
        let reset_time = self
            .reset_at
            .and_then(|timestamp| DateTime::from_timestamp(timestamp, /*nsecs*/ 0))
            .map(|time| {
                crate::status::format_reset_timestamp(
                    time.with_timezone(&Local),
                    Local::now(),
                    clock_format,
                )
            });
        let copy = |text: &str| {
            let text: String = text
                .chars()
                .filter(|c| !c.is_control() || *c == '\n')
                .collect();
            match reset_time.as_deref() {
                Some(reset_time) => text.replace("{time}", reset_time),
                None => text,
            }
        };
        let actions = self
            .ctas
            .iter()
            .filter_map(|cta| {
                if cta.label.trim().is_empty()
                    || cta.label.len() > 256
                    || cta.label.chars().any(char::is_control)
                {
                    return None;
                }
                let action = self.resolve_action(&cta.action)?;
                Some(SelectionItem {
                    name: cta.label.clone(),
                    actions: vec![Box::new(move |tx| {
                        tx.send(match &action {
                            BannerAction::OpenUrl(url) => {
                                AppEvent::OpenUrlInBrowser { url: url.clone() }
                            }
                            BannerAction::NotifyOwner(credit_type) => {
                                AppEvent::SendAddCreditsNudgeEmail {
                                    credit_type: *credit_type,
                                }
                            }
                            BannerAction::ResetUsage => AppEvent::OpenRateLimitResetCredits,
                        })
                    })],
                    dismiss_on_select: false,
                    ..Default::default()
                })
            })
            .collect::<Vec<_>>();
        ActionableBanner {
            title: copy(&self.title),
            description: copy(&self.description),
            actions,
            dismissal: if self.presentation == BannerPresentation::Dismissible {
                BannerDismissal::Dismissible
            } else {
                BannerDismissal::Persistent
            },
            ..Default::default()
        }
    }

fn open_external_url(&mut self) {
        self.app_event_tx.send(AppEvent::OpenUrlInBrowser {
            url: self.url.clone(),
        });
        if !self.is_installed || self.is_browser_action_suggestion() {
            self.screen = AppLinkScreen::InstallConfirmation;
            self.selected_action = 0;
