            composer.handle_key_event(KeyEvent::new(KeyCode::Char('j'), KeyModifiers::NONE));
        assert_eq!(composer.draft.textarea.text(), "second");
        assert_eq!(composer.draft.textarea.cursor(), "second".len() - 1);

