fn slash_popup_preserves_footer_and_selection_style() {
    let (tx, _rx) = unbounded_channel::<AppEvent>();
    let mut composer = ChatComposer::new(
        /*has_input_focus*/ true,
        AppEventSender::new(tx),
        /*enhanced_keys_supported*/ false,
        "Ask Codex to do anything".to_string(),
        /*disable_paste_burst*/ true,
    );
    composer.set_status_line_enabled(/*enabled*/ true);
    composer.set_status_line(Some("model · high · fast".into()));
    for ch in ['/', 'm'] {
        composer.handle_key_event(KeyEvent::from(KeyCode::Char(ch)));
    }
    composer.handle_key_event(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE));

    for (width, clipped) in [(80, false), (32, false), (80, true)] {
        let height = if clipped {
            6
        } else {
            composer.desired_height(width)
        };
        let area = Rect::new(/*x*/ 0, /*y*/ 0, width, height);
        let mut buf = Buffer::empty(area);
        composer.render(area, &mut buf);
        let ComposerLayout {
            composer: surface,
            textarea,
            popup,
            footer,
            ..
        } = composer.layout_with_options(area, ComposerRenderOptions::default());
        assert_eq!(popup.bottom(), surface.y);
        assert_eq!(surface.bottom(), footer.y);
        assert_eq!(composer.cursor_pos(area), Some((3, textarea.y)));
        let footer_text: String = (0..width).map(|x| buf[(x, height - 1)].symbol()).collect();
        assert!(footer_text.contains("model · high · fast"));
        if !clipped && width == 80 {
            insta::assert_snapshot!("slash_popup_footer_wide", format!("{buf:?}"));
        }
    }

    let footer = TranscriptFooter {
        text: "transcript status".into(),
        cursor_column: None,
        is_interactive: false,
    };
    let options = composer.resolve_render_options(ComposerRenderOptions {
        footer: Some(&footer),
        ..Default::default()
    });
    assert!(options.footer.is_some());
    let width = 80;
    let area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        width,
        composer.desired_height_with_options(width, options),
    );
    let mut buf = Buffer::empty(area);
    composer.render_with_options(area, &mut buf, /*mask_char*/ None, options);
    let footer_text: String = (0..width)
        .map(|x| buf[(x, area.bottom() - 1)].symbol())
        .collect();
    assert!(footer_text.contains("transcript status"));
}

fn advance_search_from(
        &mut self,
        mut offset: usize,
        direction: HistorySearchDirection,
        boundary_if_exhausted: bool,
        app_event_tx: &AppEventSender,
    ) -> HistorySearchResult {
        let total_entries = self.total_entries();
        while offset < total_entries {
            if let Some(entry) = self.entry_at_cached_offset(offset) {
                if self.search_matches(&entry) && self.search_result_is_unique(&entry) {
                    return self.search_match(offset, entry);
                }
            } else if !self.fetched_history.contains_key(&offset)
                && offset < self.persistent_entry_count
            {
                if direction == HistorySearchDirection::Older
                    && let Some(cursor) = self
                        .search
                        .as_ref()
                        .and_then(|search| search.next_older_cursor)
                    && cursor.end_offset() == offset
                {
                    return self.request_older_search_batch(
                        cursor,
                        boundary_if_exhausted,
                        app_event_tx,
                    );
                }
                if let (Some(thread_id), Some(log_id)) = (self.thread_id, self.persistent_log_id) {
                    if let Some(search) = self.search.as_mut() {
                        search.awaiting = Some(PendingHistorySearch::Entry {
                            offset,
                            direction,
                            boundary_if_exhausted,
                        });
                    }
                    app_event_tx.send(AppEvent::LookupMessageHistoryEntry {
                        thread_id,
                        offset,
                        log_id,
                    });
                    return HistorySearchResult::Pending;
                }
            }

            let next_offset = match direction {
                HistorySearchDirection::Older => offset.checked_sub(1),
                HistorySearchDirection::Newer => {
                    offset.checked_add(1).filter(|next| *next < total_entries)
                }
            };
            let Some(next_offset) = next_offset else {
                return HistorySearchResult::NotFound;
            };
            offset = next_offset;
        }

        HistorySearchResult::NotFound
    }

