fn try_handle_shortcut(&mut self, key_event: &KeyEvent) -> bool {
        if self.approval_keymap.open_fullscreen.is_pressed(*key_event) {
            self.app_event_tx.send(
                crate::app_event::AppEvent::FullScreenUserVerificationRequest(self.request.clone()),
            );
            return true;
        }
        if self.list_keymap.cancel.is_pressed(*key_event)
            || self.approval_keymap.cancel.is_pressed(*key_event)
        {
            self.cancel();
            return true;
        }
        if !matches!(self.state, UserVerificationState::Prompt) {
            return true;
        }
        if let Some(idx) = self
            .options
            .iter()
            .position(|option| option.shortcuts.iter().any(|key| key.is_press(*key_event)))
        {
            self.apply_selection(idx);
            return true;
        }
        false
    }

fn full_screen_request_is_available_before_and_during_verification() {
    for state in [
        UserVerificationState::Prompt,
        UserVerificationState::Waiting,
    ] {
        let (mut view, mut decisions) = make_view();
        let (app_tx, mut app_rx) = unbounded_channel();
        view.app_event_tx = AppEventSender::new(app_tx);
        view.approval_keymap.open_fullscreen = vec![crate::key_hint::ctrl(KeyCode::Char('v'))];
        view.state = state;
        view.handle_key_event(KeyEvent::new(KeyCode::Char('v'), KeyModifiers::CONTROL));
        let crate::app_event::AppEvent::FullScreenUserVerificationRequest(request) =
            app_rx.try_recv().expect("full-screen request")
        else {
            panic!("expected full-screen request");
        };
        assert_eq!(request.description, view.request.description);
        assert!(decisions.try_recv().is_err());
        assert!(!view.is_complete());
        assert!(view.terminal_title_requires_action());
    }
}

fn close(self) {
        let mut dismissed = Vec::new();
        let mut kept = Vec::new();
        for (index, (entry, visited)) in self.entries.into_iter().zip(self.visited).enumerate() {
            if self.kept.contains(&index) {
                kept.push(entry);
            } else if visited.get() {
                dismissed.push(entry);
            }
        }
        if !dismissed.is_empty() || !kept.is_empty() {
            self.tx.send(AppEvent::UpdateWarnings {
                transcript: self.transcript,
                dismissed,
                kept,
            });
        }
    }

fn handle_key(&mut self, event: KeyEvent) -> bool {
        if event.kind == KeyEventKind::Release {
            return false;
        }
        let action = if key_hint::plain(KeyCode::Char('k')).is_press(event) {
            if event.kind != KeyEventKind::Press {
                return false;
            }
            self.kept.insert(self.current);
            if self.current + 1 >= self.entries.len() {
                return true;
            }
            Some(ListAction::MoveRight)
        } else {
            self.keymap
                .list
                .action_for(event)
                .filter(|action| *action != ListAction::Accept)
        };
        if action.is_none() && self.keymap.app.open_warnings.is_pressed(event) {
            return true;
        }
        if action.is_none() && self.keymap.app.copy.is_pressed(event) {
            if let Some(entry) = self.entries.get(self.current) {
                self.tx.send(AppEvent::CopyWarning(entry.details.clone()));
            }
            return false;
        }
        let offset = self.offset.get();
        match action {
            Some(ListAction::MoveLeft | ListAction::MoveRight) => {
                let previous = self.current;
                self.current = if action == Some(ListAction::MoveLeft) {
                    self.current.saturating_sub(/*rhs*/ 1)
                } else {
                    (self.current + 1).min(self.entries.len().saturating_sub(/*rhs*/ 1))
                };
                if self.current != previous {
                    self.offset.set(/*val*/ 0);
                }
            }
            Some(ListAction::MoveUp) => self.offset.set(offset.saturating_sub(/*rhs*/ 1)),
            Some(ListAction::MoveDown) => self.offset.set((offset + 1).min(self.max_offset.get())),
            Some(ListAction::PageUp) => {
                self.offset.set(offset.saturating_sub(self.page_size.get()))
            }
            Some(ListAction::PageDown) => self.offset.set(
                offset
                    .saturating_add(self.page_size.get())
                    .min(self.max_offset.get()),
            ),
            Some(ListAction::JumpTop) => self.offset.set(/*val*/ 0),
            Some(ListAction::JumpBottom) => self.offset.set(self.max_offset.get()),
            Some(ListAction::Cancel) => return true,
            Some(ListAction::Accept) | None => {}
        }
        false
    }

fn warning_pages_copy_only_the_current_diagnostic() {
