fn handle_command_execution_completed_now(&mut self, item: ThreadItem) {
        enum ExecEndTarget {
            // Normal case: the active exec cell already tracks this call id.
            ActiveTracked,
            // We have an active exec group, but it does not contain this call id. Render the end
            // as a standalone finalized history cell so the active group remains intact.
            OrphanHistoryWhileActiveExec,
            // No active exec cell can safely own this end; build a new cell from the end payload.
            NewCell,
        }

        let ThreadItem::CommandExecution {
            id,
            command,
            process_id: _,
            source,
            status,
            command_actions,
            aggregated_output,
            exit_code,
            duration_ms,
            ..
        } = item
        else {
            return;
        };
        let event_command = split_command_string(&command);
        let event_parsed = command_actions
            .into_iter()
            .map(codex_app_server_protocol::CommandAction::into_core)
            .collect();
        let duration = Duration::from_millis(duration_ms.unwrap_or_default().max(0) as u64);
        let exit_code = if status == codex_app_server_protocol::CommandExecutionStatus::Completed {
            exit_code.unwrap_or_default()
        } else {
            exit_code.filter(|code| *code != 0).unwrap_or(1)
        };
        let aggregated_output = aggregated_output.unwrap_or_default();

        let running = self.running_commands.remove(&id);
        if self.suppressed_exec_calls.remove(&id) {
            return;
        }
        let (command, parsed, source) = match running {
            Some(rc) => (rc.command, rc.parsed_cmd, rc.source),
            None => (event_command, event_parsed, source),
        };
        let parsed = self.annotate_skill_reads_in_parsed_cmd(parsed);
        let is_unified_exec_interaction =
            matches!(source, ExecCommandSource::UnifiedExecInteraction);
        let is_user_shell = source == ExecCommandSource::UserShell;
        // Completion-only replay has no begin event to join adjacent exploration. Extend only
        // a finished, compatible group; an unrelated running group must retain orphan routing.
        if let Some(cell) = self
            .transcript
            .active_cell
            .as_mut()
            .and_then(|cell| cell.as_any_mut().downcast_mut::<ExecCell>())
            && !cell.is_active()
            && !cell.should_flush()
            && !cell.iter_calls().any(|call| call.call_id == id)
        {
            cell.add_call(
                id.clone(),
                command.clone(),
                parsed.clone(),
                source,
                /*interaction_input*/ None,
            );
        }
        let end_target = match self.transcript.active_cell.as_ref() {
            Some(cell) => match cell.as_any().downcast_ref::<ExecCell>() {
                Some(exec_cell) if exec_cell.iter_calls().any(|call| call.call_id == id) => {
                    ExecEndTarget::ActiveTracked
                }
                Some(exec_cell) if exec_cell.is_active() => {
                    ExecEndTarget::OrphanHistoryWhileActiveExec
                }
                None if cell.as_any().is::<McpToolCallCell>()
                    || cell
                        .as_any()
                        .downcast_ref::<history_cell::ComputerActivityCell>()
                        .is_some_and(history_cell::ComputerActivityCell::is_active) =>
                {
                    ExecEndTarget::OrphanHistoryWhileActiveExec
                }
                Some(_) | None => ExecEndTarget::NewCell,
            },
            None => ExecEndTarget::NewCell,
        };

        let output = if is_unified_exec_interaction {
            CommandOutput::new(exit_code, String::new())
        } else {
            CommandOutput::new(exit_code, aggregated_output)
        };

        match end_target {
            ExecEndTarget::ActiveTracked => {
                if let Some(cell) = self
                    .transcript
                    .active_cell
                    .as_mut()
                    .and_then(|c| c.as_any_mut().downcast_mut::<ExecCell>())
                {
                    let completed = cell.complete_call(&id, output, duration);
                    debug_assert!(completed, "active exec cell should contain {id}");
                    if cell.should_flush() {
                        self.flush_active_cell();
                    } else {
                        self.bump_active_cell_revision();
                        self.request_redraw();
                    }
                }
            }
            ExecEndTarget::OrphanHistoryWhileActiveExec => {
                let mut orphan = new_active_exec_command(
                    id.clone(),
                    command,
                    parsed,
                    source,
                    /*interaction_input*/ None,
                    self.local_settings.tui.animations && self.local_settings.tui.effects.progress,
                );
                let completed = orphan.complete_call(&id, output, duration);
                debug_assert!(completed, "new orphan exec cell should contain {id}");
                self.app_event_tx
                    .send(AppEvent::InsertHistoryCell(Box::new(orphan)));
                self.request_redraw();
            }
            ExecEndTarget::NewCell => {
                let mut cell = new_active_exec_command(
                    id.clone(),
                    command,
                    parsed,
                    source,
                    /*interaction_input*/ None,
                    self.local_settings.tui.animations && self.local_settings.tui.effects.progress,
                );
                let completed = cell.complete_call(&id, output, duration);
                debug_assert!(completed, "new exec cell should contain {id}");
                if let Some(active) = self
                    .transcript
                    .active_cell
                    .as_mut()
                    .and_then(|cell| cell.as_any_mut().downcast_mut::<ExecCell>())
                    && !active.is_active()
                    && active.is_exploring_cell()
                    && cell.is_exploring_cell()
                {
                    // Replayed commands have completion events without matching starts.
                    active.group.calls.extend(cell.group.calls);
                    self.bump_active_cell_revision();
                    self.request_redraw();
                } else {
                    self.flush_active_cell();
                    if cell.should_flush() {
                        self.add_to_history(cell);
                    } else {
                        self.transcript.active_cell = Some(Box::new(cell));
                        self.bump_active_cell_revision();
                        self.request_redraw();
                    }
                }
            }
        }
        if is_user_shell {
            self.maybe_send_next_queued_input();
        }
    }

fn flush_unified_exec_wait_streak(&mut self) {
        let Some(wait) = self.unified_exec_wait_streak.take() else {
            return;
        };
        let cell = history_cell::new_unified_exec_interaction(wait.command_display, String::new());
        if let Err(cell) = self.absorb_activity_detail(Box::new(cell)) {
            self.app_event_tx.send(AppEvent::InsertHistoryCell(cell));
        }
        self.restore_reasoning_status_header();
    }

fn refresh_connector_mentions(&mut self, force_refresh: bool) {
        if !self.connectors_enabled() || self.thread_id.is_none() {
            return;
        }
        if self.connectors.mention_refresh_in_flight {
            self.connectors.mention_refresh_pending =
                Some(self.connectors.mention_refresh_pending.unwrap_or_default() || force_refresh);
            return;
        }

        self.connectors.locally_disabled.clear();
        self.connectors.mention_refresh_in_flight = true;
        self.app_event_tx
            .send(AppEvent::FetchInstalledConnectorMentions {
                force_refresh,
                generation: self.connectors.generation,
            });
    }

fn connectors_popup_params(
        &self,
        connectors: &[AppInfo],
        selected_connector_id: Option<&str>,
    ) -> SelectionViewParams {
        let total = connectors.len();
        let installed = connectors
            .iter()
            .filter(|connector| connector.is_accessible)
            .count();
        let header = Paragraph::new(vec![
            Line::from("Apps".bold()),
            Line::from("Use $ to insert an installed app into your prompt.".dim()),
            Line::from(format!("Installed {installed} of {total} available apps.").dim()),
        ])
        .wrap(Wrap { trim: false });
        let initial_selected_idx = selected_connector_id.and_then(|selected_connector_id| {
            connectors
                .iter()
                .position(|connector| connector.id == selected_connector_id)
        });
        let mut items: Vec<SelectionItem> = Vec::with_capacity(connectors.len());
        for connector in connectors {
            let connector_label = codex_connectors::metadata::connector_display_label(connector);
            let connector_title = connector_label.clone();
            let link_description = Self::connector_description(connector);
            let description = Self::connector_brief_description(connector);
            let status_label = Self::connector_status_label(connector);
            let search_value = format!("{connector_label} {}", connector.id);
            let mut item = SelectionItem {
                name: connector_label,
                description: Some(description),
                search_value: Some(search_value),
                ..Default::default()
            };
            let is_installed = connector.is_accessible;
            let selected_label = if is_installed {
                format!(
                    "{status_label} · Press Enter to open the app page to install, manage, or enable/disable this app"
                )
            } else {
                format!("{status_label} · Press Enter to open the app page to install this app")
            };
            let missing_label = format!("{status_label} · App link unavailable");
            let instructions = if connector.is_accessible {
                "Manage this app in your browser."
            } else {
                "Install this app in your browser, then reload Codex."
            };
            if let Some(install_url) = connector.install_url.clone() {
                let app_id = connector.id.clone();
                let is_enabled = connector.is_enabled;
                let title = connector_title.clone();
                let instructions = instructions.to_string();
                let description = link_description.clone();
                item.actions = vec![Box::new(move |tx| {
                    tx.send(AppEvent::OpenAppLink {
                        app_id: app_id.clone(),
                        title: title.clone(),
                        description: description.clone(),
                        instructions: instructions.clone(),
                        url: install_url.clone(),
                        is_installed,
                        is_enabled,
                    });
                })];
                item.dismiss_on_select = true;
                item.selected_description = Some(selected_label);
            } else {
                let missing_label_for_action = missing_label.clone();
                item.actions = vec![Box::new(move |tx| {
                    tx.send(AppEvent::InsertHistoryCell(Box::new(
                        history_cell::new_info_event(
                            missing_label_for_action.clone(),
                            /*hint*/ None,
                        ),
                    )));
                })];
                item.dismiss_on_select = true;
                item.selected_description = Some(missing_label);
            }
            items.push(item);
        }

        SelectionViewParams {
            view_id: Some(CONNECTORS_SELECTION_VIEW_ID),
            header: Box::new(header),
            items,
            is_searchable: true,
            search_placeholder: Some("Type to search apps".to_string()),
            col_width_mode: ColumnWidthMode::AutoAllRows,
            initial_selected_idx,
            ..SelectionViewParams::picker()
        }
    }

