fn flush_completed_hook_output(&mut self) {
        let Some(completed_cell) = self
            .active_hook_cell
            .as_mut()
            .and_then(HookCell::take_completed_persistent_runs)
        else {
            return;
        };
        let active_cell_is_empty = self
            .active_hook_cell
            .as_ref()
            .is_some_and(HookCell::is_empty);
        if active_cell_is_empty {
            self.active_hook_cell = None;
        }
        self.flush_completed_tool_activity();
        self.bump_active_cell_revision();
        self.app_event_tx
            .send(AppEvent::InsertHistoryCell(Box::new(completed_cell)));
        self.request_pending_usage_output_insertion();
    }

fn finish_active_hook_cell_if_idle(&mut self) {
        let Some(cell) = self.active_hook_cell.as_ref() else {
            return;
        };
        if cell.is_empty() {
            self.active_hook_cell = None;
            self.bump_active_cell_revision();
            self.request_pending_usage_output_insertion();
            return;
        }
        if cell.should_flush()
            && let Some(cell) = self.active_hook_cell.take()
        {
            self.bump_active_cell_revision();
            self.app_event_tx
                .send(AppEvent::InsertHistoryCell(Box::new(cell)));
            self.request_pending_usage_output_insertion();
        }
    }

fn prepare_image_submission(
        &mut self,
        message: UserMessage,
        history_record: UserMessageHistoryRecord,
        source: UserMessageSource,
    ) {
        let id = uuid::Uuid::new_v4();
        let images = message.local_images.clone();
        let remote_bytes = message.remote_image_urls.iter().map(String::len).sum();
        let (mut tx, result) = oneshot::channel();
        let events = self.app_event_tx.clone();
        tokio::spawn(async move {
            let permit = tokio::select! {
                biased;
                _ = tx.closed() => return,
                permit = IMAGE_PREPARATION.lock() => permit,
            };
            let prepared = tokio::task::spawn_blocking(move || {
                let _permit = permit;
                prepare_images(images, remote_bytes)
            })
            .await
            .unwrap_or_else(|error| Err(format!("Failed to prepare images: {error}")));
            if tx.send(prepared).is_ok() {
                events.send(AppEvent::ImagesPrepared(id));
            }
        });
        self.pending_image_submission = Some(PendingImageSubmission {
            id,
            message,
            history_record,
            source,
            result,
        });
        self.refresh_pending_input_preview();
        self.request_redraw();
    }

