fn prepare_last_response_copy(&mut self) -> KeyEventAction {
        self.app_event_tx.send(AppEvent::FollowTranscript);
        let action = match self.transcript.last_agent_markdown.as_deref() {
            Some(markdown) if !markdown.is_empty() => {
                KeyEventAction::CopyLastResponse(markdown.into())
            }
            _ => {
                self.add_error_message("No agent response to copy".into());
                KeyEventAction::None
            }
        };
        self.request_redraw();
        action
    }

fn show_rename_prompt(&mut self) {
        if !self.ensure_thread_rename_allowed() {
            return;
        }
        let tx = self.app_event_tx.clone();
        let existing_name = self.thread_name.as_deref().filter(|name| !name.is_empty());
        let title = if existing_name.is_some() {
            "Rename thread"
        } else {
            "Name thread"
        };
        let suggestion_request = self
            .thread_id
            .map(|thread_id| (thread_id, uuid::Uuid::new_v4()));
        let mut view = CustomPromptView::new(
            title.to_string(),
            "Type a name and press Enter".to_string(),
            /*initial_text*/ existing_name.unwrap_or_default().to_string(),
            /*context_label*/ None,
            Box::new(move |name: String| {
                let Some(name) = normalize_thread_name(&name) else {
                    tx.send(AppEvent::InsertHistoryCell(Box::new(
                        history_cell::new_error_event("Thread name cannot be empty.".to_string()),
                    )));
                    return;
                };
                tx.set_thread_name(name);
            }),
        );
        if let Some((_, request_id)) = suggestion_request {
            view = view.with_text_suggestion(
                request_id,
                "Generating a title suggestion…".to_string(),
                "Suggested from this conversation".to_string(),
            );
        }
        self.bottom_pane.show_text_prompt(view);
        if let Some((thread_id, request_id)) = suggestion_request {
            self.app_event_tx.send(AppEvent::SuggestThreadName {
                thread_id,
                request_id,
            });
        }
    }

fn pause_active_goal_for_interrupt(&self) {
        if !self.is_active_goal_turn_running() {
            return;
        }
        let Some(thread_id) = self.thread_id else {
            return;
        };
        self.app_event_tx.send(AppEvent::SetThreadGoalStatus {
            thread_id,
            status: AppThreadGoalStatus::Paused,
        });
    }

fn open_luna_reserve_model_popup(
        &mut self,
        presets: Vec<ModelPreset>,
        view_id: &'static str,
    ) {
        let normal_model_slug = self
            .rate_limit_snapshots_by_limit_id
            .values()
            .find(|snapshot| snapshot.limit_name == LUNA_RESERVE_MODEL)
            .and_then(|snapshot| snapshot.normal_model_slug.as_deref());
        let preset = normal_model_slug
            .and_then(|slug| presets.iter().find(|preset| preset.model == slug))
            .or_else(|| presets.iter().find(|preset| preset.model == LUNA_MODEL));
        let Some(mut preset) = preset.cloned() else {
            self.bottom_pane.dismiss_view_by_id(view_id);
            self.add_info_message(
                "Luna model settings are unavailable; please try /model again in a moment."
                    .to_string(),
                /*hint*/ None,
            );
            return;
        };

        // Only borrow the normal model's presentation and supported efforts. Selecting an
        // effort must keep the authorized Reserve model and the saved ordinary return target.
        preset.model = LUNA_RESERVE_MODEL.to_string();
        let single_supported_effort = preset.supported_reasoning_efforts.len() == 1;
        let name = preset.display_name.clone();
        let description = (!preset.description.is_empty()).then_some(preset.description.clone());
        let actions: Vec<SelectionAction> = vec![Box::new(move |tx| {
            tx.send(AppEvent::OpenReasoningPopup {
                model: preset.clone(),
            });
        })];
        let header = self.model_menu_header(
            "Select Model",
            "Other models return when ordinary usage is available again.",
        );
        self.show_model_selection_view(
            vec![LUNA_RESERVE_MODEL.to_string()],
            SelectionViewParams {
                view_id: Some(view_id),
                header,
                footer_hint: Some(picker_hint_line_for_keymap(&self.bottom_pane.list_keymap())),
                items: vec![SelectionItem {
                    name,
                    description,
                    is_current: true,
                    actions,
                    dismiss_on_select: single_supported_effort,
                    dismiss_parent_on_child_accept: !single_supported_effort,
                    ..Default::default()
                }],
                ..SelectionViewParams::picker()
            },
        );
    }

