fn show_misalignment_policy_precaution(&mut self) {
        if !self.has_misalignment_policy_violation() {
            return;
        }
        self.bottom_pane.dismiss_view_by_id(PRECAUTION_VIEW);
        let mut items = vec![
            SelectionItem {
                name: "New chat".to_string(),
                actions: vec![Box::new(|tx| tx.send(AppEvent::NewSession { name: None }))],
                dismiss_on_select: true,
                ..Default::default()
            },
            SelectionItem {
                name: "Resume another chat".to_string(),
                actions: vec![Box::new(|tx| tx.send(AppEvent::OpenResumePicker))],
                ..Default::default()
            },
        ];
        let review = self
            .misalignment_policy_violation
            .as_ref()
            .and_then(|violation| violation.review.clone());
        if let Some(review) = &review {
            let review = Arc::clone(review);
            items.insert(
                0,
                SelectionItem {
                    name: "Review findings".to_string(),
                    actions: vec![Box::new(move |tx| {
                        tx.send(AppEvent::ReviewMisalignment(Arc::clone(&review)));
                    })],
                    ..Default::default()
                },
            );
        }
        if self.remote_connection.is_some() {
            items.insert(
                1,
                SelectionItem {
                    name: "Agent command center".to_string(),
                    actions: vec![Box::new(|tx| tx.send(AppEvent::OpenAgentsOverview))],
                    ..Default::default()
                },
            );
        }
        self.bottom_pane.show_selection_view(SelectionViewParams {
            view_id: Some(PRECAUTION_VIEW),
            header: Box::new(
                Paragraph::new(vec![
                    Line::from(if review.is_some() { "Chat paused as a precaution" } else { MISALIGNMENT_POLICY_TITLE }).bold(),
                    Line::from(if review.is_some() {
                        "We couldn’t confirm the agent was interpreting your instructions correctly. Review what we detected before deciding to continue."
                    } else { MISALIGNMENT_POLICY_DESCRIPTION }).dim(),
                ])
                .wrap(Wrap { trim: false }),
            ),
            items,
            allow_cancel: false,
            ..SelectionViewParams::picker()
        });
    }

fn show_misalignment_review_confirmation(
        &mut self,
        review: Arc<MisalignmentReview>,
    ) {
        if !self.is_current_misalignment_review(&review) {
            return;
        }
        let can_continue = review.continuation_message().is_some();
        self.bottom_pane.dismiss_view_by_id(PRECAUTION_VIEW);
        self.bottom_pane.show_selection_view(SelectionViewParams {
            view_id: Some(PRECAUTION_VIEW),
            title: Some("Chat paused as a precaution".to_string()),
            items: vec![
                SelectionItem {
                    name: "Acknowledge findings and continue".to_string(),
                    is_disabled: !can_continue,
                    actions: vec![Box::new(move |tx| {
                        tx.send(AppEvent::ContinueMisalignment(Arc::clone(&review)));
                    })],
                    require_explicit_confirmation: true,
                    dismiss_on_select: true,
                    ..Default::default()
                },
                SelectionItem {
                    name: "Back".to_string(),
                    actions: vec![Box::new(|tx| tx.send(AppEvent::CloseMisalignmentReview))],
                    ..Default::default()
                },
            ],
            allow_cancel: false,
            ..SelectionViewParams::confirmation()
        });
    }

fn refresh_account_scoped_models(&mut self) {
        if self.status_account_display == Some(StatusAccountDisplay::ApiKey) {
            for model in &mut Arc::make_mut(&mut self.model_catalog).models {
                model.available_access_programs = None;
            }
        }
        let request_id = uuid::Uuid::new_v4();
        self.model_popup_request_id = Some(request_id);
        self.app_event_tx.send(AppEvent::FetchModels { request_id });
    }

fn model_selection_actions(
        &self,
        model_for_action: String,
        effort_for_action: Option<ReasoningEffortConfig>,
        should_prompt_plan_mode_scope: bool,
    ) -> Vec<SelectionAction> {
        let warning = effort_for_action
            .as_ref()
            .and_then(|effort| self.ultra_reasoning_concurrency_warning(effort));
        let thread_id = self.thread_id();
        let sparkle_thread = self.sparkle_thread_for_picker_action(&model_for_action);
        vec![Box::new(move |tx| {
            if model_for_action == LUNA_RESERVE_MODEL {
                // Reserve is temporary: update the active task without persisting a model default.
                if let Some(thread_id) = thread_id {
                    tx.send(AppEvent::UpdateLunaReserveReasoning {
                        thread_id,
                        effort: effort_for_action.clone(),
                    });
                }
            } else if effort_for_action == Some(ReasoningEffortConfig::Ultra) {
                tx.send(
                    AstraModelPickerAction::ApplyAdvancedReasoning {
                        effort: ReasoningEffortConfig::Ultra,
                    }
                    .into_picker_event(sparkle_thread, model_for_action.clone()),
                );
            } else if should_prompt_plan_mode_scope {
                tx.send(AppEvent::OpenPlanReasoningScopePrompt {
                    model: model_for_action.clone(),
                    effort: effort_for_action.clone(),
                });
            } else {
                tx.send(
                    AstraModelPickerAction::UpdateModel
                        .into_picker_event(sparkle_thread, model_for_action.clone()),
                );
                tx.send(AppEvent::UpdateReasoningEffort(effort_for_action.clone()));
                tx.send(AppEvent::PersistModelSelection {
                    model: model_for_action.clone(),
                    effort: effort_for_action.clone(),
                });
            }
            if let Some(warning) = warning.clone() {
                tx.send(AppEvent::InsertHistoryCell(Box::new(
                    history_cell::new_warning_event(warning),
                )));
            }
        })]
    }

