fn open_auto_review_denials_popup(&mut self) {
        if self.review.recent_auto_review_denials.is_empty() {
            self.add_info_message(
                "No recent auto-review denials in this thread.".to_string(),
                Some("Denials are recorded after auto-review rejects an action.".to_string()),
            );
            return;
        }
        let Some(thread_id) = self.thread_id() else {
            self.add_error_message("That thread is no longer available.".to_string());
            return;
        };

        let mut items = vec![SelectionItem {
            name: "Action".to_string(),
            description: Some("Rationale".to_string()),
            is_disabled: true,
            search_value: Some(String::new()),
            ..Default::default()
        }];
        items.extend(
            self.review
                .recent_auto_review_denials
                .entries()
                .map(|event| {
                    let id = event.id.clone();
                    let summary = auto_review_denials::action_summary(&event.action);
                    let rationale = event
                        .rationale
                        .as_deref()
                        .unwrap_or("Auto-review did not include a rationale");
                    SelectionItem {
                        name: summary.clone(),
                        description: Some(rationale.to_string()),
                        selected_description: Some(rationale.to_string()),
                        search_value: Some(format!("{summary} {rationale}")),
                        actions: vec![Box::new(move |tx| {
                            tx.send(AppEvent::ApproveRecentAutoReviewDenial {
                                thread_id,
                                id: id.clone(),
                            });
                        })],
                        dismiss_on_select: true,
                        ..Default::default()
                    }
                }),
        );

        self.bottom_pane.show_selection_view(SelectionViewParams {
            header: Box::new(
                Paragraph::new(vec![
                    Line::from("Auto-review Denials".bold()),
                    Line::from("Select a denied action to approve.".dim()),
                ])
                .wrap(Wrap { trim: false }),
            ),
            items,
            is_searchable: true,
            // Denial rationales remain visible before authorizing a retry.
            description_layout: crate::bottom_pane::SelectionDescriptionLayout::Columns,
            ..SelectionViewParams::picker()
        });
        self.request_redraw();
    }

fn handle_permission_shortcut(&mut self, key_event: KeyEvent) -> bool {
        let forward = if self.chat_keymap.next_permission_mode.is_pressed(key_event) {
            true
        } else if self
            .chat_keymap
            .previous_permission_mode
            .is_pressed(key_event)
        {
            false
        } else {
            return false;
        };
        if !self.bottom_pane.no_modal_or_popup_active() {
            return false;
        }
        if self.permission_shortcut_pending {
            return true;
        }
        if self.blocks_direct_input {
            self.add_error_message(PARENT_OWNED_INPUT_MESSAGE.to_string());
            return true;
        }
        let Some(thread_id) = self.thread_id else {
            return true;
        };

        let Some(discovery) = self.permission_discovery.as_ref() else {
            self.request_permission_profiles();
            return true;
        };
        let server_requirements = codex_config::ConfigRequirements {
            auto_review_required_models: discovery
                .requirements
                .as_ref()
                .and_then(|requirements| requirements.auto_review.as_ref())
                .and_then(|auto_review| auto_review.required_on_models.as_ref())
                .map(|models| {
                    codex_config::Sourced::new(
                        models.iter().cloned().collect(),
                        codex_config::RequirementSource::Unknown,
                    )
                }),
            ..Default::default()
        };
        let current_approval =
            AskForApproval::from(self.config.permissions.approval_policy.value());
        let active_profile = self.config.permissions.active_permission_profile();
        let mut choices = Vec::new();
        for preset in builtin_approval_presets() {
            if !matches!(preset.id, "read-only" | "auto") {
                continue;
            }
            for reviewer in [ApprovalsReviewer::User, ApprovalsReviewer::AutoReview] {
                if reviewer == ApprovalsReviewer::AutoReview
                    && (preset.id != "auto"
                        || !self.config.features.enabled(Feature::GuardianApproval))
                {
                    continue;
                }
                let approval = AskForApproval::from(preset.approval);
                if discovery
                    .disabled_reason(
                        &preset.active_permission_profile.id,
                        Some(approval),
                        Some(reviewer.into()),
                    )
                    .is_some()
                    || (server_requirements.auto_review_required_for_model(self.current_model())
                        && reviewer != ApprovalsReviewer::AutoReview)
                {
                    continue;
                }
                // These modes still need explicit Windows setup.
                #[cfg(target_os = "windows")]
                if preset.id == "auto"
                    && (matches!(
                        self.windows_sandbox_host,
                        crate::app::WindowsSandboxHost::Mixed
                            | crate::app::WindowsSandboxHost::Unknown
                    ) || (self.windows_sandbox_host != crate::app::WindowsSandboxHost::Remote
                        && reviewer == ApprovalsReviewer::User
                        && !self.windows_sandbox_config.is_enabled()))
                {
                    continue;
                }
                let is_current = current_approval == approval
                    && self.config.approvals_reviewer == reviewer
                    && active_profile.as_ref().map_or_else(
                        || {
                            Self::preset_matches_current(
                                current_approval,
                                self.config.permissions.permission_profile(),
                                self.config.cwd.as_path(),
                                &preset,
                            )
                        },
                        |active| active.id == preset.active_permission_profile.id,
                    );
                let label = match (preset.id, reviewer) {
                    ("auto", ApprovalsReviewer::User) => ASK_FOR_APPROVAL_LABEL,
                    ("auto", ApprovalsReviewer::AutoReview) => APPROVE_FOR_ME_LABEL,
                    _ => preset.label,
                };
                choices.push((
                    is_current,
                    PermissionProfileSelection {
                        profile_id: preset.active_permission_profile.id.clone(),
                        approval_policy: Some(approval),
                        approvals_reviewer: Some(reviewer),
                        display_label: label.to_string(),
                    },
                ));
            }
        }
        if !forward {
            choices.reverse();
        }
        let start = choices
            .iter()
            .position(|(current, _)| *current)
            .map_or(0, |index| index + 1);
        if let Some((_, selection)) = choices
            .iter()
            .cycle()
            .skip(start)
            .take(choices.len())
            .find(|(current, _)| !current)
        {
            self.permission_shortcut_pending = true;
            self.app_event_tx.send(AppEvent::ApplyPermissionShortcut {
                thread_id,
                selection: selection.clone(),
            });
        } else {
            self.add_info_message(
                "No other permission modes are available.".to_string(),
                /*hint*/ None,
            );
        }
        true
    }

fn try_select_permission_profile(
        &mut self,
        discovery: &PermissionDiscovery,
        profile_id: &str,
        requested_approval_policy: Option<AskForApproval>,
        requested_reviewer: Option<ApprovalsReviewer>,
    ) -> bool {
        let reviewer = match profile_id {
            ":approve-for-me" if !self.config.features.enabled(Feature::GuardianApproval) => {
                self.add_error_message(
                    "Approve for me is unavailable. Run `/permissions` to see available profiles."
                        .into(),
                );
                return false;
            }
            ":approve-for-me" => ApprovalsReviewer::AutoReview,
            _ => ApprovalsReviewer::User,
        };
        let profile_id = match profile_id {
            ":ask-for-approval" | ":approve-for-me" => BUILT_IN_PERMISSION_PROFILE_WORKSPACE,
            id => id,
        };
        let Some(profile) = discovery
            .profiles
            .iter()
            .find(|profile| profile.id == profile_id)
        else {
            self.add_error_message(format!(
                "Unknown permission profile `{profile_id}`. Run `/permissions` to see available profiles."
            ));
            return false;
        };
        let preset = builtin_approval_presets()
            .into_iter()
            .find(|preset| preset.active_permission_profile.id == profile_id);
        let approval_policy = requested_approval_policy.or_else(|| {
            preset
                .as_ref()
                .map(|preset| AskForApproval::from(preset.approval))
        });
        let approvals_reviewer = requested_reviewer.or_else(|| preset.as_ref().map(|_| reviewer));
        if approvals_reviewer == Some(ApprovalsReviewer::AutoReview)
            && !self.config.features.enabled(Feature::GuardianApproval)
        {
            self.add_error_message(
                "Approve for me is unavailable. Run `/permissions` to see available profiles."
                    .into(),
            );
            return false;
        }
        if let Some(reason) = discovery.disabled_reason(
            profile_id,
            approval_policy,
            approvals_reviewer.map(Into::into),
        ) {
            self.add_error_message(format!(
                "Permission profile `{profile_id}` is unavailable: {reason}."
            ));
            return false;
        }
        let display_label = preset.as_ref().map_or(profile.id.as_str(), |preset| {
            match (preset.id, approvals_reviewer) {
                ("auto", Some(ApprovalsReviewer::AutoReview)) => APPROVE_FOR_ME_LABEL,
                ("auto", _) => ASK_FOR_APPROVAL_LABEL,
                _ => preset.label,
            }
        });
        let selection = PermissionProfileSelection {
            profile_id: profile_id.to_string(),
            approval_policy,
            approvals_reviewer,
            display_label: display_label.to_string(),
        };
        if let Some(preset) = preset {
            let Some(action) = self
                .permission_mode_actions(
                    &preset,
                    display_label.to_string(),
                    approvals_reviewer.unwrap_or(reviewer),
                    /*profile_selection*/ Some(selection),
                    /*return_to_permissions*/ true,
                )
                .into_iter()
                .next()
            else {
                return false;
            };
            action(&self.app_event_tx);
            return true;
        }
        self.app_event_tx
            .send(AppEvent::SelectPermissionProfile(selection));
        true
    }

