fn select_pet_by_id(&mut self, pet_id: String) {
        if self.warn_if_pets_unsupported() {
            return;
        }

        self.app_event_tx.send(AppEvent::PetSelected { pet_id });
    }

fn start_pet_picker_preview(&mut self, pet_id: String) {
        self.pet_picker_preview_request_id =
            self.pet_picker_preview_request_id.wrapping_add(/*rhs*/ 1);
        let request_id = self.pet_picker_preview_request_id;
        self.pet_picker_preview_pet = None;
        if pet_id == crate::pets::DISABLED_PET_ID {
            self.pet_picker_preview_state.set_disabled();
            self.request_redraw();
            return;
        }

        self.pet_picker_preview_state.set_loading();
        self.request_redraw();

        let codex_home = self.local_settings.codex_home.clone();
        let frame_requester = self.frame_requester.clone();
        let tx = self.app_event_tx.clone();
        let pet_http_client = self.pet_http_client.clone();
        spawn_pet_load(
            async move {
                crate::pets::load_pet_with_assets(
                    pet_id,
                    codex_home,
                    frame_requester,
                    /*animations_enabled*/ false,
                    &pet_http_client,
                )
                .await
                .map_err(|err| err.to_string())
            },
            tx,
            move |result| AppEvent::PetPreviewLoaded { request_id, result },
        );
    }

fn pet_load_without_runtime_sends_completion_event() {
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    let app_event_tx = AppEventSender::new(tx);

    spawn_pet_load(
        async { Ok::<Option<crate::pets::AmbientPet>, String>(None) },
        app_event_tx,
        |result| AppEvent::ConfiguredPetLoaded {
            generation: next_configured_pet_load_generation(),
            pet_id: crate::pets::DEFAULT_PET_ID.to_string(),
            result,
        },
    );

    match rx.blocking_recv().expect("pet load completion event") {
        AppEvent::ConfiguredPetLoaded { pet_id, result, .. } => {
            assert_eq!(pet_id, crate::pets::DEFAULT_PET_ID);
            assert!(result.expect("successful pet load").is_none());
        }
        event => panic!("expected configured pet completion, got {event:?}"),
    }
}

fn configured_pet_loads_are_scoped_across_widget_replacements() {
    let (mut replaced_chat, _replaced_tx, mut replaced_rx, _replaced_op_rx) =
        crate::chatwidget::tests::make_chatwidget_manual_with_sender().await;
    let (mut chat, _tx, mut rx, _op_rx) =
        crate::chatwidget::tests::make_chatwidget_manual_with_sender().await;
    let codex_home = tempfile::tempdir().unwrap();
    replaced_chat.local_settings.codex_home =
        AbsolutePathBuf::from_absolute_path(codex_home.path()).expect("absolute temporary path");
    chat.local_settings.codex_home =
        AbsolutePathBuf::from_absolute_path(codex_home.path()).expect("absolute temporary path");
    let pet_id = "missing-custom-pet".to_string();

    replaced_chat.set_tui_pet(/*pet*/ Some(pet_id.clone()));
    let replaced_event = tokio::time::timeout(
        std::time::Duration::from_secs(/*secs*/ 5),
        replaced_rx.recv(),
    )
    .await
    .expect("replaced widget pet load completion")
    .expect("replaced widget pet load event");
    let AppEvent::ConfiguredPetLoaded {
        generation: replaced_generation,
        ..
    } = replaced_event
    else {
        panic!("expected configured pet completion");
    };

    chat.set_tui_pet(/*pet*/ Some(pet_id.clone()));
    let event = tokio::time::timeout(std::time::Duration::from_secs(/*secs*/ 5), rx.recv())
        .await
        .expect("configured pet load completion")
        .expect("configured pet load event");
    let AppEvent::ConfiguredPetLoaded {
        generation,
        pet_id: loaded_pet_id,
        ..
    } = event
    else {
        panic!("expected configured pet completion");
    };
    assert_eq!(loaded_pet_id, pet_id);

    assert!(!chat.finish_configured_pet_load(
        replaced_generation,
        pet_id.clone(),
        /*result*/ Ok(None),
    ));
    assert!(chat.finish_configured_pet_load(
        generation,
        pet_id,
        /*result*/
        Ok(Some(crate::pets::test_ambient_pet(
            chat.frame_requester.clone(),
            /*animations_enabled*/ false,
        ))),
    ));
    let area = ratatui::layout::Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 80, /*height*/ 24,
    );
    assert!(chat.ambient_pet_draw(area, area.bottom()).is_some());
}

fn selection_view_params(
    default_mask: Option<CollaborationModeMask>,
    plan_markdown: Option<&str>,
    clear_context_usage_label: Option<&str>,
) -> SelectionViewParams {
    let (implement_actions, implement_disabled_reason) = match default_mask.clone() {
        Some(mask) => {
            let user_text = PLAN_IMPLEMENTATION_CODING_MESSAGE.to_string();
            let actions: Vec<SelectionAction> = vec![Box::new(move |tx| {
                tx.send(AppEvent::FollowTranscript);
                tx.send(AppEvent::SubmitUserMessageWithMode {
                    text: user_text.clone(),
                    collaboration_mode: mask.clone(),
                });
            })];
            (actions, None)
        }
        None => (
            Vec::new(),
            Some(PLAN_IMPLEMENTATION_DEFAULT_UNAVAILABLE.to_string()),
        ),
    };

    let (clear_context_actions, clear_context_disabled_reason) = match (default_mask, plan_markdown)
    {
        (None, _) => (
            Vec::new(),
            Some(PLAN_IMPLEMENTATION_DEFAULT_UNAVAILABLE.to_string()),
        ),
        (Some(_), Some(plan_markdown)) if !plan_markdown.trim().is_empty() => {
            let user_text =
                format!("{PLAN_IMPLEMENTATION_CLEAR_CONTEXT_PREFIX}\n\n{plan_markdown}");
            let actions: Vec<SelectionAction> = vec![Box::new(move |tx| {
                tx.send(AppEvent::ClearUiAndSubmitUserMessage {
                    text: user_text.clone(),
                });
            })];
            (actions, None)
        }
        (Some(_), _) => (
            Vec::new(),
            Some(PLAN_IMPLEMENTATION_NO_APPROVED_PLAN.to_string()),
        ),
    };

    let clear_context_description = clear_context_usage_label.map_or_else(
        || "Fresh thread with this plan".to_string(),
        |label| format!("Start a fresh thread (current context: {label})"),
    );

    SelectionViewParams {
        title: Some(PLAN_IMPLEMENTATION_TITLE.to_string()),
        subtitle: None,
        footer_hint: Some(standard_popup_hint_line()),
        items: vec![
            SelectionItem {
                name: PLAN_IMPLEMENTATION_YES.to_string(),
                description: Some("Switch to Default and start coding".to_string()),
                selected_description: None,
                is_current: false,
                actions: implement_actions,
                disabled_reason: implement_disabled_reason,
                dismiss_on_select: true,
                ..Default::default()
            },
            SelectionItem {
                name: PLAN_IMPLEMENTATION_CLEAR_CONTEXT.to_string(),
                description: Some(clear_context_description),
                selected_description: None,
                is_current: false,
                actions: clear_context_actions,
                disabled_reason: clear_context_disabled_reason,
                dismiss_on_select: true,
                ..Default::default()
            },
            SelectionItem {
                name: PLAN_IMPLEMENTATION_NO.to_string(),
                description: Some("Continue planning with the model".to_string()),
                selected_description: None,
                is_current: false,
                actions: Vec::new(),
                dismiss_on_select: true,
                ..Default::default()
            },
        ],
        ..SelectionViewParams::picker()
    }
}

