fn show_security_setup(&mut self, identity: Identity, notice: Notice) {
        if !notice.valid() {
            return;
        }
        if self.security_setup_identity.as_ref() != Some(&identity) {
            self.invalidate_security_setup();
            self.security_setup_identity = Some(identity);
            self.security_setup_dismissed = false;
        }
        // Reconnect fetches must preserve the current occurrence, including Esc dismissal.
        if self.security_setup_presented || self.security_setup_dismissed {
            return;
        }
        tracing::debug!(
            has_backend_banner = self.has_applicable_backend_banner(),
            "presenting security setup notice"
        );
        if self.has_applicable_backend_banner() {
            return;
        }
        self.security_setup_presented = true;
        self.bottom_pane.set_inline_banner(Some(ActionableBanner {
            title: notice.title,
            description: notice.description,
            actions: vec![SelectionItem {
                name: notice.action.label,
                actions: vec![Box::new(move |tx| {
                    tx.send(AppEvent::OpenUrlInBrowser {
                        url: notice.action.url.clone(),
                    })
                })],
                ..Default::default()
            }],
            ..Default::default()
        }));
    }

fn set_service_tier_selection(&mut self, service_tier: Option<String>) {
        self.set_service_tier(service_tier.clone());
        self.app_event_tx
            .send(AppEvent::CodexOp(AppCommand::override_turn_context(
                /*cwd*/ None,
                /*approval_policy*/ None,
                /*approvals_reviewer*/ None,
                /*permission_profile*/ None,
                /*active_permission_profile*/ None,
                /*model*/ None,
                /*effort*/ None,
                /*summary*/ None,
                Some(service_tier.clone()),
                /*collaboration_mode*/ None,
            )));
        self.app_event_tx
            .send(AppEvent::PersistServiceTierSelection { service_tier });
    }

fn emit_forked_thread_event(
        &mut self,
        forked_from_id: ThreadId,
        fork_parent_title: Option<String>,
    ) {
        let forked_from_id_text = forked_from_id.to_string();
        let line: Line<'static> = if let Some(name) = fork_parent_title
            && !name.trim().is_empty()
        {
            vec![
                "• ".dim(),
                "Thread forked from ".into(),
                name.fg(accent_color()),
                " (".into(),
                forked_from_id_text.fg(accent_color()),
                ")".into(),
            ]
            .into()
        } else {
            vec![
                "• ".dim(),
                "Thread forked from ".into(),
                forked_from_id_text.fg(accent_color()),
            ]
            .into()
        };
        self.app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
            ForkedThreadHistoryCell(PlainHistoryCell::new(vec![line])),
        )));
    }

