fn image_submission_is_portable_for_new_turns_and_steers() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("image.png");
    // Transport must not apply the helper's default 2048-pixel resize policy.
    let pixels = image::RgbImage::from_pixel(
        /*width*/ 3000,
        /*height*/ 2,
        image::Rgb([12, 34, 56]),
    );
    pixels.save(&path).unwrap();
    let placeholder = "[Image #1]";
    let message = UserMessage {
        local_images: vec![LocalImageAttachment {
            placeholder: placeholder.into(),
            path,
        }],
        text_elements: vec![TextElement::new(
            (0..placeholder.len()).into(),
            Some(placeholder.into()),
        )],
        ..UserMessage::from("[Image #1] describe")
    };
    for running in [false, true] {
        let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
        chat.thread_id = Some(ThreadId::new());
        chat.snapshot_local_images = true;
        chat.codex_op_target = CodexOpTarget::AppEvent;
        // Repeated identical submissions each render once, across supported receipt shapes.
        for (echo_client_id, omit_media) in [(false, false), (true, false), (true, true)] {
            let mut message = message.clone();
            if omit_media {
                message.text.push_str("\u{1b}[31m");
            }
            if running {
                handle_turn_started(&mut chat, "turn");
            }
            assert!(
                chat.submit_user_message_with_shell_escape_policy(
                    message,
                    ShellEscapePolicy::Disallow
                )
                .is_none()
            );
            let mut rendered = Vec::new();
            let (items, client_user_message_id) = loop {
                match rx.recv().await.unwrap() {
                    AppEvent::ImagesPrepared(id) => chat.on_images_prepared(id),
                    AppEvent::InsertHistoryCell(cell) => {
                        rendered.push(cell.display_lines(/*width*/ 80))
                    }
                    AppEvent::CodexOp(AppCommand::UserTurn {
                        items,
                        client_user_message_id,
                        ..
                    }) => {
                        break (items, client_user_message_id);
                    }
                    _ => {}
                }
            };
            let [
                UserInput::Image {
                    image: ImageReference::Inline { url },
                    detail,
                },
                UserInput::Text { .. },
            ] = items.as_slice()
            else {
                panic!("local image must be portable on the wire");
            };
            let (_, encoded) = url.split_once(";base64,").unwrap();
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(encoded)
                .unwrap();
            assert_eq!(
                (image::load_from_memory(&bytes).unwrap().to_rgb8(), detail),
                (pixels.clone(), &None)
            );
            let mut receipt = items.clone();
            if omit_media {
                receipt.retain(|item| !matches!(item, UserInput::Image { .. }));
            }
            for _ in 0..2 {
                chat.on_committed_user_message(
                    &receipt,
                    echo_client_id.then_some(client_user_message_id.as_str()),
                    /*from_replay*/ false,
                    "turn",
                );
            }
            rendered.extend(drain_insert_history(&mut rx));
            assert_eq!(rendered.len(), 1);
            assert_chatwidget_snapshot!(
                "portable_image_echo_renders_once",
                lines_to_single_string(&rendered[0])
            );
            assert!(chat.input_queue.pending_steers.is_empty());
            chat.on_committed_user_message(
                &items,
                Some(&client_user_message_id),
                /*from_replay*/ true,
                "turn",
            );
            let replayed = drain_insert_history(&mut rx);
            assert_eq!(replayed, rendered);
            handle_turn_completed(&mut chat, "turn", /*duration_ms*/ None);
            drain_insert_history(&mut rx);
        }
    }
}

fn computer_activity_keeps_reasoning_in_order_live_and_replayed() {
    use codex_app_server_protocol::McpToolCallStatus;
    let mut outputs = Vec::new();
    for replay in [false, true] {
        let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
        for id in ["1", "2"] {
            let item = computer_item(id, McpToolCallStatus::Completed);
            if replay {
                chat.replay_thread_item(
                    item.clone(),
                    "turn-1".to_string(),
                    ReplayKind::ThreadSnapshot,
                );
            } else {
                chat.on_mcp_tool_call_started(computer_item(id, McpToolCallStatus::InProgress));
                if id == "1" {
                    chat.on_mcp_tool_call_completed(item.clone());
                }
            }
            for part in ["Inspecting", "Checking"] {
                let summary = format!("{part} action {id}");
                if replay {
                    chat.replay_thread_item(
                        AppServerThreadItem::Reasoning {
                            id: summary.clone(),
                            summary: vec![summary],
                            content: Vec::new(),
                        },
                        "turn-1".to_string(),
                        ReplayKind::ThreadSnapshot,
                    );
                } else {
                    chat.on_agent_reasoning_delta(summary);
                    chat.on_agent_reasoning_final();
                }
            }
            if !replay && id == "2" {
                // Reasoning can arrive before a running call completes.
                chat.on_mcp_tool_call_completed(item);
            }
        }
        assert!(drain_insert_history(&mut rx).is_empty());
        // A visible message commits the whole group, including trailing reasoning.
        chat.prepare_assistant_message();
        let cells = std::iter::from_fn(|| rx.try_recv().ok())
            .filter_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => Some(cell),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(cells.len(), 1);
        let cell = &cells[0];
        outputs.push(format!(
            "Compact:\n{}\nExpanded:\n{}\nRaw:\n{}",
            lines_to_single_string(&cell.display_lines(/*width*/ 80)),
            lines_to_single_string(&cell.transcript_lines(/*width*/ 100)),
            lines_to_single_string(&cell.raw_lines()),
        ));
    }
    assert_eq!(outputs[0], outputs[1]);
    insta::assert_snapshot!(outputs[0]);
}

