}

fn apply_patch_full_flow_integration_like() {
    let (mut chat, mut rx, mut op_rx) = make_chatwidget_manual(/*model_override*/ None).await;

    // 1) Backend requests approval
    let mut changes = HashMap::new();
    changes.insert(
        PathBuf::from("pkg.rs"),
        FileChange::Add { content: "".into() },
    );
    handle_apply_patch_approval_request(
        &mut chat,
        "sub-xyz",
        ApplyPatchApprovalRequestEvent {
            call_id: "call-1".into(),
            turn_id: "turn-call-1".into(),
            changes,
            reason: None,
            grant_root: None,
        },
    );

    // 2) User approves via 'y' and App receives a thread-scoped op
    chat.handle_key_event(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE));
    let mut maybe_op: Option<Op> = None;
    while let Ok(app_ev) = rx.try_recv() {
        if let AppEvent::SubmitThreadOp { op, .. } = app_ev {
            maybe_op = Some(op);
            break;
        }
    }
    let op = maybe_op.expect("expected thread-scoped op after key press");

    // 3) App forwards to widget.submit_op, which pushes onto codex_op_tx
    chat.submit_op(op);
    let forwarded = op_rx
        .try_recv()
        .expect("expected op forwarded to codex channel");
    match forwarded {
        Op::PatchApproval { id, decision } => {
            assert_eq!(id, "call-1");
            assert_matches!(
                decision,
                codex_app_server_protocol::FileChangeApprovalDecision::Accept
            );
        }
        other => panic!("unexpected op forwarded: {other:?}"),
    }

    // 4) Simulate patch begin/end events from backend; ensure history cells are emitted
    let mut changes2 = HashMap::new();
    changes2.insert(
        PathBuf::from("pkg.rs"),
        FileChange::Add { content: "".into() },
    );
    handle_patch_apply_begin(&mut chat, "call-1", "turn-call-1", changes2);
    let mut end_changes = HashMap::new();
    end_changes.insert(
        PathBuf::from("pkg.rs"),
        FileChange::Add { content: "".into() },
    );
    handle_patch_apply_end(
        &mut chat,
        "call-1",
        "turn-call-1",
        end_changes,
        AppServerPatchApplyStatus::Completed,
    );
}

fn adjacent_exploration_groups_across_reasoning_live_and_replayed() {
    let mut renders = Vec::new();
    for replay in [false, true] {
        let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
        chat.on_task_started();
        for (id, script, exit_code) in [
            ("list", "ls missing", 1),
            ("read", "cat index.html", 0),
            ("run", "echo boundary", 0),
            ("later", "cat later.txt", 0),
            ("after-message", "cat final.txt", 0),
        ] {
            let command = vec!["bash".to_string(), "-lc".to_string(), script.to_string()];
            let mut item = AppServerThreadItem::CommandExecution {
                model_context: None,
                sandbox_type: None,
                id: id.to_string(),
                command: codex_shell_command::parse_command::shlex_join(&command),
                cwd: chat.config.cwd.clone().into(),
                process_id: None,
                plugin_id: None,
                script_path: None,
                source: ExecCommandSource::UnifiedExecStartup,
                status: AppServerCommandExecutionStatus::InProgress,
                command_actions: codex_shell_command::parse_command::parse_command(&command)
                    .into_iter()
                    .map(|parsed| {
                        AppServerCommandAction::from_core_with_cwd(parsed, &chat.config.cwd)
                    })
                    .collect(),
                aggregated_output: Some(format!("{id} output\n")),
                exit_code: Some(exit_code),
                duration_ms: Some(5),
            };
            if !replay {
                handle_exec_begin(&mut chat, item.clone());
            }
            if let AppServerThreadItem::CommandExecution { status, .. } = &mut item {
                *status = if exit_code == 0 {
                    AppServerCommandExecutionStatus::Completed
                } else {
                    AppServerCommandExecutionStatus::Failed
                };
            }
            if replay {
                chat.replay_thread_item(item, "turn-1".to_string(), ReplayKind::ThreadSnapshot);
            } else {
                handle_exec_end(&mut chat, item);
            }
            if id == "list" {
                for summary in ["Inspecting the page", "Checking its contents"] {
                    if replay {
                        chat.replay_thread_item(
                            AppServerThreadItem::Reasoning {
                                id: summary.to_string(),
                                summary: vec![summary.to_string()],
                                content: Vec::new(),
                            },
                            "turn-1".to_string(),
                            ReplayKind::ThreadSnapshot,
                        );
                    } else {
                        chat.on_agent_reasoning_delta(summary.to_string());
                        chat.on_agent_reasoning_final();
                    }
                }
            }
            if id == "later" {
                complete_assistant_message(
                    &mut chat,
                    "message",
                    "Checking one more file.",
                    Some(MessagePhase::Commentary),
                );
            }
        }
        chat.flush_active_cell();
        let cells = std::iter::from_fn(|| rx.try_recv().ok())
            .filter_map(|event| match event {
                AppEvent::InsertHistoryCell(cell) => Some(cell),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(cells.len(), 5);
        let mut render = String::new();
        for mode in ["Compact", "Expanded", "Raw"] {
            render.push_str(&format!("{mode}:\n"));
            for cell in &cells {
                let lines = match mode {
                    "Compact" => cell.display_lines(/*width*/ 80),
                    "Expanded" => cell.transcript_lines(/*width*/ 80),
                    _ => cell.raw_lines(),
                };
                render.push_str(&lines_to_single_string(&lines));
                render.push('\n');
            }
        }
        renders.push(render);
    }
    assert_eq!(renders[0], renders[1]);
    insta::assert_snapshot!(renders[0]);
}

