    chat.handle_history_entry_response(response(1, "use [$sample](plugin://sample@test)"));

    assert_eq!(next_lookup_offset(), 0);
    chat.handle_history_entry_response(response(0, "/rename smoke-1"));
    assert_eq!(chat.bottom_pane.composer_text(), "/rename smoke-1");
}

fn list_spacing_streams_compact_then_reflows_on_completion_or_interruption() {
    let source = "1. One\n2. This item has enough words to wrap\n3. Three\n4. Four";
    let mut stages = Vec::new();
    for (enabled, alternate_screen) in [
        (true, AltScreenMode::Always),
        (false, AltScreenMode::Always),
        (true, AltScreenMode::Never),
    ] {
        for plan in [false, true] {
            for interrupted in [false, true] {
                let (mut chat, mut rx, _ops) =
                    make_chatwidget_manual(/*model_override*/ None).await;
                chat.config.tui_fullscreen_transcript = enabled;
                chat.config.tui_alternate_screen = alternate_screen;
                chat.local_settings = LocalSettings::from(&chat.config);
                let owned = chat.local_settings.transcript_mode.is_owned();
                let width = if plan { 28 } else { 26 };
                chat.note_rendered_width(width);
                if plan {
                    chat.set_feature_enabled(Feature::CollaborationModes, /*enabled*/ true);
                    chat.set_collaboration_mask(CollaborationModeMask {
                        name: "Plan".into(),
                        mode: Some(ModeKind::Plan),
                        model: None,
                        reasoning_effort: None,
                        developer_instructions: None,
                    });
                }
                drain_insert_history(&mut rx);
                let mut live = Vec::new();
                for chunk in source.split_inclusive('\n') {
                    let (cell, tail) = if plan {
                        chat.on_plan_delta(chunk.into());
                        let controller = chat.plan_stream_controller.as_mut().unwrap();
                        (
                            controller.on_commit_tick_batch(usize::MAX).0,
                            controller.current_tail_display_lines(),
                        )
                    } else {
                        chat.on_agent_message_delta(chunk.into());
                        let controller = chat.stream_controller.as_mut().unwrap();
                        (
                            controller.on_commit_tick_batch(usize::MAX).0,
                            controller.current_tail_lines(),
                        )
                    };
                    live.extend(
                        drain_insert_history_with(&mut rx, |cell| cell.display_lines(width))
                            .into_iter()
                            .flatten(),
                    );
                    if let Some(cell) = cell {
                        live.extend(cell.display_lines(width));
                    }
                    if chunk.ends_with('\n') {
                        assert!(tail.is_empty(), "completed list rows must not be held back");
                    }
                }
                if interrupted {
                    chat.flush_answer_and_plan_streams();
                } else if plan {
                    chat.on_plan_item_completed(source.into());
                } else {
                    chat.finalize_completed_assistant_message(Some(source));
                }
                let mut completed = None;
                while let Ok(event) = rx.try_recv() {
                    match event {
                        AppEvent::InsertHistoryCell(cell) => live.extend(cell.display_lines(width)),
                        AppEvent::ConsolidateAgentMessage {
                            source: final_source,
                            cwd,
                            deferred_history_cell,
                            ..
                        } => {
                            if let Some(cell) = deferred_history_cell {
                                live.extend(cell.display_lines(width));
                            }
                            assert_eq!(final_source.trim_end(), source);
                            completed = Some(Box::new(history_cell::AgentMarkdownCell::new(
                                final_source,
                                &cwd,
                            ))
                                as Box<dyn HistoryCell>);
                        }
                        AppEvent::ConsolidateProposedPlan(final_source) => {
                            assert_eq!(final_source.trim_end(), source);
                            completed = Some(Box::new(history_cell::new_proposed_plan(
                                final_source,
                                &chat.config.cwd,
                            ))
                                as Box<dyn HistoryCell>);
                        }
                        _ => {}
                    }
                }
                let completed = completed.expect("termination must retain source for reflow");
                let text = |lines: Vec<Line<'static>>| {
                    lines
                        .iter()
                        .map(|line| line.to_string().trim_end().to_owned())
                        .collect::<Vec<_>>()
                        .join("\n")
                };
                let render = |width| {
                    if owned {
                        completed.retained_hyperlink_lines(width, /*detailed*/ false)
                    } else {
                        completed.display_hyperlink_lines(width)
                    }
                };
                let narrow = render(width);
                let native = completed.display_hyperlink_lines(width);
                if owned {
                    assert_ne!(native, narrow);
                }
                let wide = render(/*width*/ 100);
                assert_eq!(
                    render(width),
                    narrow,
                    "width and spacing must both key the render cache"
                );
                let live = text(live);
                assert_eq!(live.contains("wrap\n\n"), !owned);
                let stage = format!(
                    "owned={owned}, plan={plan}\nStreaming:\n{live}\nCompleted:\n{}\nWide:\n{}",
                    text(crate::terminal_hyperlinks::visible_lines(narrow)),
                    text(crate::terminal_hyperlinks::visible_lines(wide))
                );
                if enabled && alternate_screen == AltScreenMode::Always {
                    if interrupted {
                        assert_eq!(stages.last(), Some(&stage));
                    } else {
                        stages.push(stage);
                    }
                }
            }
        }
    }
    insta::assert_snapshot!(stages.join("\n\n---\n\n"));
}

fn luna_reserve_selector_supports_arrows_enter_shortcuts_and_escape_without_losing_draft() {
    for (keys, destination) in [
        (
            vec![KeyCode::Down, KeyCode::Enter],
            Some("https://chatgpt.com/?cta_tab=personal&highlight_plan=plus#pricing"),
        ),
        (
            vec![KeyCode::Down, KeyCode::Up, KeyCode::Enter],
            Some("https://chatgpt.com/settings/usage?credits_modal=true"),
        ),
        (
            vec![KeyCode::Char('1')],
            Some("https://chatgpt.com/settings/usage?credits_modal=true"),
        ),
        (
            vec![KeyCode::Char('2')],
            Some("https://chatgpt.com/?cta_tab=personal&highlight_plan=plus#pricing"),
        ),
        (vec![KeyCode::Down, KeyCode::Esc], None),
    ] {
        let (mut chat, mut events, _ops) = make_chatwidget_manual(Some("gpt-reserve")).await;
        chat.has_chatgpt_account = true;
        chat.apply_external_edit("saved draft".into());
        chat.on_rate_limit_snapshot(Some(reserve_snapshot(
            /*primary_used*/ 48, /*weekly_used*/ 20,
        )));
        let response = serde_json::from_value(json!({
            "accountId": "account-preview", "rateLimits": {},
            "rateLimitUpsell": {
                "banner_type": "luna_reserve", "presentation": "dismissible",
                "title": "You’re now using Luna, a faster model for simpler tasks.",
                "description": "Add credits or upgrade to continue using the most advanced models.",
                "ctas": [{"action": "add_credits", "label": "Add credits"},
                    {"action": "open_pricing_dialog", "label": "Upgrade"}]
            }
        }))
        .unwrap();
        chat.update_backend_banner(&response);
        let rendered = normalize_snapshot_paths(render_bottom_popup(&chat, /*width*/ 90));
        assert!(
            !rendered.contains("saved draft"),
            "selector owns input focus"
        );
        assert!(rendered.contains("esc to continue working"));
        while events.try_recv().is_ok() {}
        for key in keys {
            chat.handle_key_event(KeyEvent::from(key));
            if key == KeyCode::Down {
                insta::assert_snapshot!(
                    "luna_reserve_selector_second_choice",
                    normalize_snapshot_paths(render_bottom_popup(&chat, /*width*/ 90))
                );
            }
        }
        let queued = std::iter::from_fn(|| events.try_recv().ok()).collect::<Vec<_>>();
        let urls: Vec<_> = queued
            .iter()
            .filter_map(|event| match event {
                AppEvent::OpenUrlInBrowser { url } => Some(url.as_str()),
                _ => None,
            })
            .collect();
        assert_eq!(urls, destination.into_iter().collect::<Vec<_>>());
        assert!(
            !queued
                .iter()
                .any(|event| matches!(event, AppEvent::CodexOp(AppCommand::UserTurn { .. })))
        );
        assert_eq!(chat.composer_text_with_pending(), "saved draft");
        // A periodic usage reply must not reopen a selector the user just closed.
        chat.update_backend_banner(&response);
        let rendered = normalize_snapshot_paths(render_bottom_popup(&chat, /*width*/ 90));
        assert!(!rendered.contains("You’re now using Luna"));
        assert!(rendered.contains("saved draft"));
        assert!(rendered.contains("Luna Reserve"));
    }
}

