fn model_picker_refresh_preserves_highlight() {
    for (remove_selected, reasoning_submenu, expected) in [
        (false, false, "gpt-5.6-terra"),
        (true, false, "gpt-5.5"),
        (false, true, "gpt-5.6-terra"),
        (true, true, "gpt-5.5"),
