fn rate_limit_recovery_holds_submissions_until_model_change() {
    let (mut chat, mut events, mut ops) = make_chatwidget_manual(Some("test-model-a")).await;
    set_chatgpt_auth(&mut chat);
    chat.thread_id = Some(ThreadId::new());
    handle_turn_started(&mut chat, "failed-turn");
    chat.queue_user_message(UserMessage::from("queued follow-up"));
    chat.on_rate_limit_error(RateLimitErrorKind::UsageLimit, "Usage exhausted".into());
    assert!(
        std::iter::from_fn(|| events.try_recv().ok()).any(|event| matches!(
            event,
            AppEvent::RefreshRateLimits {
                origin: crate::app_event::RateLimitRefreshOrigin::Recovery
            }
        ))
    );
    chat.submit_user_message(UserMessage::from("submitted during recovery"));
    assert_no_submit_op(&mut ops);
    assert_eq!(
        chat.queued_user_message_texts(),
        vec!["queued follow-up", "submitted during recovery"]
    );

    chat.set_model("test-model-b");
    chat.finish_rate_limit_recovery();
    let Op::UserTurn { model, items, .. } = next_submit_op(&mut ops) else {
        panic!("expected queued follow-up on the fallback model");
    };
    assert_eq!(model, "test-model-b");
    assert!(
        matches!(items.as_slice(), [UserInput::Text { text, .. }] if text == "queued follow-up")
    );
    assert_eq!(
        chat.queued_user_message_texts(),
        vec!["submitted during recovery"]
    );
    chat.finish_rate_limit_recovery();
    assert_no_submit_op(&mut ops);
}

fn completed_reasoning_stays_in_expanded_transcript_for_live_and_replay() {
    let mut renders = Vec::new();
    for replay in [false, true] {
        let (mut chat, mut rx, _ops) = make_chatwidget_manual(/*model_override*/ None).await;
        chat.on_task_started();
        for (id, summary) in [
            ("first", "**Inspecting repository structure**"),
            ("second", "Mapping the app structure"),
            (
                "third",
                "**Tracing terminal components**\n\nThe playback clock preserves elapsed time.",
            ),
        ] {
            if replay {
                chat.handle_thread_item(
                    AppServerThreadItem::Reasoning {
                        id: id.to_string(),
                        summary: vec![summary.to_string()],
                        content: Vec::new(),
                    },
                    "turn-1".to_string(),
                    ThreadItemRenderSource::Replay(ReplayKind::ThreadSnapshot),
                );
            } else {
                handle_agent_reasoning_started(&mut chat, id);
                delta(&mut chat, id, summary);
                complete(&mut chat, id);
            }
        }
        let mut compact = Vec::new();
        let mut expanded = Vec::new();
        while let Ok(event) = rx.try_recv() {
            if let AppEvent::InsertHistoryCell(cell) = event {
                compact.extend(cell.display_lines(/*width*/ 80));
                expanded.extend(cell.transcript_lines(/*width*/ 80));
                assert!(cell.raw_lines().is_empty());
            }
        }
        let rendered = format!(
            "Compact history:\n{}\nLive status:\n{}\nExpanded transcript:\n{}",
            ratatui::text::Text::from(compact),
            chat.bottom_pane.status_widget().unwrap().header(),
            ratatui::text::Text::from(expanded),
        );
        renders.push(rendered);
    }
    assert_eq!(renders[0], renders[1]);
    insta::assert_snapshot!(renders[0], @r"
        Compact history:

        Live status:
        The playback clock preserves elapsed time.
        Expanded transcript:
        • Inspecting repository structure
        • Mapping the app structure
        • The playback clock preserves elapsed time.
        ");
}

fn item_completed_pops_pending_steer_with_local_image_and_text_elements() {
    let (mut chat, mut rx, mut op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
    chat.thread_id = Some(ThreadId::new());
    chat.on_task_started();

    let temp = tempdir().expect("tempdir");
    let image_path = temp.path().join("pending-steer.png");
    const TINY_PNG_BYTES: &[u8] = &[
        137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13, 73, 72, 68, 82, 0, 0, 0, 1, 0, 0, 0, 1, 8, 6,
        0, 0, 0, 31, 21, 196, 137, 0, 0, 0, 11, 73, 68, 65, 84, 120, 156, 99, 96, 0, 2, 0, 0, 5, 0,
        1, 122, 94, 171, 63, 0, 0, 0, 0, 73, 69, 78, 68, 174, 66, 96, 130,
    ];
    std::fs::write(&image_path, TINY_PNG_BYTES).expect("write image");

    let text = "note".to_string();
    let text_elements = vec![TextElement::new((0..4).into(), Some("note".to_string()))];
    chat.submit_user_message(UserMessage {
        text: text.clone(),
        local_images: vec![LocalImageAttachment {
            placeholder: "[Image #1]".to_string(),
            path: image_path,
        }],
        remote_image_urls: Vec::new(),
        text_elements,
        mention_bindings: Vec::new(),
    });

    match next_submit_op(&mut op_rx) {
        Op::UserTurn { .. } => {}
        other => panic!("expected Op::UserTurn, got {other:?}"),
    }

    assert_eq!(chat.input_queue.pending_steers.len(), 1);
    let pending = chat.input_queue.pending_steers.front().unwrap();
    assert_eq!(pending.user_message.local_images.len(), 1);
    assert_eq!(pending.user_message.text_elements.len(), 1);
    assert_eq!(pending.compare_key.message, text);
    assert_eq!(pending.compare_key.image_count, 1);

    complete_user_message_for_inputs(
        &mut chat,
        "user-1",
        vec![
            UserInput::Image {
                image: ImageReference::Inline {
                    url: "data:image/png;base64,placeholder".to_string(),
                },
                detail: None,
            },
            UserInput::Text {
                text,
                text_elements: Vec::new(),
            },
        ],
    );

    assert!(chat.input_queue.pending_steers.is_empty());

    let mut user_cell = None;
    while let Ok(ev) = rx.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = ev
            && let Some(cell) = cell.as_any().downcast_ref::<UserHistoryCell>()
        {
            user_cell = Some((
                cell.message.clone(),
                cell.text_elements.clone(),
                cell.local_image_paths.clone(),
                cell.remote_image_urls.clone(),
            ));
            break;
        }
    }

    let (stored_message, stored_elements, stored_images, stored_remote_image_urls) =
        user_cell.expect("expected pending steer user history cell");
    assert_eq!(stored_message, "note");
    assert_eq!(
        stored_elements,
        vec![TextElement::new((0..4).into(), Some("note".to_string()))]
    );
    assert_eq!(stored_images.len(), 1);
    assert!(stored_images[0].ends_with("pending-steer.png"));
    assert!(stored_remote_image_urls.is_empty());
}

