fn security_setup_preserves_draft_action_and_dismissal_across_widgets() {
    let (mut chat, _rx, _ops) = make_chatwidget_manual(Some("test-model-a")).await;
    chat.show_security_setup(setup_identity(), setup_notice());
    let rendered = normalize_snapshot_paths(render_bottom_popup(&chat, /*width*/ 70));
    insta::assert_snapshot!("security_setup_banner", rendered);
    let (mut replacement, mut events, _ops) = make_chatwidget_manual(Some("test-model-a")).await;
    chat.app_event_tx
        .voice_only
        .store(/*val*/ true, std::sync::atomic::Ordering::Relaxed);
    replacement.inherit_security_setup(&mut chat);
    chat = replacement;
    assert!(render_bottom_popup(&chat, /*width*/ 70).contains("Set up security"));
    chat.handle_key_event(KeyEvent::new(KeyCode::Char('1'), KeyModifiers::NONE));
    assert!(
        matches!(events.try_recv(), Ok(AppEvent::OpenUrlInBrowser { url }) if url == "https://chatgpt.com/cyber")
    );
    assert!(render_bottom_popup(&chat, /*width*/ 70).contains("Set up security"));
    chat.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert!(!render_bottom_popup(&chat, /*width*/ 70).contains("Set up security"));

    let (mut replacement, _events, _ops) = make_chatwidget_manual(Some("test-model-a")).await;
    replacement.inherit_security_setup(&mut chat);
    replacement.show_security_setup(setup_identity(), setup_notice());
    assert_eq!(
        replacement.bottom_pane.inline_banner_lifecycle(),
        (true, true)
    );
    assert!(!render_bottom_popup(&replacement, /*width*/ 70).contains("Set up security"));

    replacement.invalidate_security_setup();
    replacement.show_security_setup(setup_identity(), setup_notice());
    assert!(!render_bottom_popup(&replacement, /*width*/ 70).contains("Set up security"));

    // A verified change of account starts a new notice occurrence.
    replacement.invalidate_security_setup();
    replacement.show_security_setup(
        Identity {
            account: "other-account".into(),
            ..setup_identity()
        },
        setup_notice(),
    );
    assert!(render_bottom_popup(&replacement, /*width*/ 70).contains("Set up security"));
}

fn session_model_selection_accepts_final_choices_without_saving() {
    for picker in [
        "auto",
        "single",
        "default_only",
        "reasoning",
        "max",
        "ultra",
    ] {
        let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(Some("gpt-5.5")).await;
        let effort = match picker {
            "max" => ReasoningEffortConfig::Max,
            "ultra" => ReasoningEffortConfig::Ultra,
            _ => ReasoningEffortConfig::High,
        };
        let mut preset = get_available_model(&chat, "gpt-5.5");
        preset.default_reasoning_effort = effort.clone();
        preset.supported_reasoning_efforts = vec![ReasoningEffortPreset {
            effort: effort.clone(),
            description: "Selected effort".into(),
        }];
        if picker == "auto" {
            preset.model = "codex-auto-test".into();
        }
        let expected_model = preset.model.clone();
        if picker == "default_only" {
            preset.supported_reasoning_efforts.clear();
        }
        match picker {
            "auto" | "single" | "default_only" => chat.open_model_popup_with_presets(vec![preset]),
            "max" | "ultra" => chat.open_advanced_reasoning_popup(preset),
            "reasoning" => {
                chat.set_reasoning_effort(Some(effort.clone()));
                preset
                    .supported_reasoning_efforts
                    .push(ReasoningEffortPreset {
                        effort: ReasoningEffortConfig::Low,
                        description: "Low effort".into(),
                    });
                chat.open_reasoning_popup(preset);
            }
            _ => unreachable!(),
        }
        while rx.try_recv().is_ok() {}
        chat.handle_key_event(KeyEvent::from(KeyCode::Char('s')));
        let selected = rx.try_recv().expect("session-only selection");
        assert_matches!(selected, AppEvent::SelectSessionModel { model, effort: selected_effort, service_tier: None }
            if model == expected_model && selected_effort.as_ref() == Some(&effort));
        assert!(chat.bottom_pane.no_modal_or_popup_active(), "{picker}");
        assert!(
            std::iter::from_fn(|| rx.try_recv().ok()).all(|event| matches!(
                event,
                AppEvent::InsertHistoryCell(_) | AppEvent::SettingsSelectionClosed
            )),
            "{picker}"
        );
    }
}

