fn goal_control_slash_commands_emit_goal_events() {
    let cases = [
        ("/goal clear", None),
        ("/goal pause", Some(AppThreadGoalStatus::Paused)),
        ("/goal resume", Some(AppThreadGoalStatus::Active)),
    ];

    for (command, status) in cases {
        let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
        chat.set_feature_enabled(Feature::Goals, /*enabled*/ true);
        let thread_id = ThreadId::new();
        chat.thread_id = Some(thread_id);
        chat.bottom_pane.set_vim_enabled(/*enabled*/ true);

        chat.bottom_pane
            .set_composer_text(command.into(), Vec::new(), Vec::new());
        chat.handle_key_event(KeyCode::Esc.into());
        chat.handle_key_event(KeyCode::Enter.into());
        assert_matches!(rx.try_recv(), Ok(AppEvent::FollowTranscript));

        match status {
            Some(status) => {
                let event = rx.try_recv().expect("expected goal status event");
                let AppEvent::SetThreadGoalStatus {
                    thread_id: actual_thread_id,
                    status: actual_status,
                } = event
                else {
                    panic!("expected SetThreadGoalStatus, got {event:?}");
                };
                assert_eq!(actual_thread_id, thread_id);
                assert_eq!(actual_status, status);
            }
            None => {
                let event = rx.try_recv().expect("expected clear goal event");
                let AppEvent::ClearThreadGoal {
                    thread_id: actual_thread_id,
                } = event
                else {
                    panic!("expected ClearThreadGoal, got {event:?}");
                };
                assert_eq!(actual_thread_id, thread_id);
            }
        }
        chat.handle_key_event(KeyCode::Char('x').into());
        chat.handle_key_event(KeyCode::Right.into());
        chat.handle_key_event(KeyCode::Esc.into());
        chat.handle_key_event(KeyCode::Char('.').into());
        assert_eq!(chat.bottom_pane.composer_text(), "xx");
    }
}

