fn overlapping_reads_keep_older_success_when_newer_read_fails() -> color_eyre::Result<()> {
    let mut app = crate::app::test_support::make_test_app().await;
    let mut session = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    let low = snapshot(/*used_percent*/ 92);
    let healthy = snapshot(/*used_percent*/ 10);
    for (first_id, rolling, update, expected) in [
        (
            1,
            None,
            low.clone(),
            Some((low.primary.clone().unwrap(), false)),
        ),
        (
            3,
            Some(low.clone()),
            healthy.clone(),
            Some((low.primary.clone().unwrap(), false)),
        ),
        (5, None, healthy, None),
    ] {
        for request_id in first_id..=first_id + 1 {
            app.chat_widget
                .add_status_output(/*refreshing_rate_limits*/ true, Some(request_id));
            app.refresh_rate_limits(
                &session,
                RateLimitRefreshOrigin::StatusCommand { request_id },
            );
        }
        if let Some(rolling) = rolling {
            app.chat_widget.on_rolling_rate_limit_snapshot(rolling);
        }
        let before = app.chat_widget.usage_notice_state.current();
        for (request_id, result, expected) in [
            (first_id + 1, Err("transient failure".into()), before),
            (first_id, Ok(update), expected),
        ] {
            app.handle_event(
                &mut tui,
                &mut session,
                AppEvent::RateLimitsLoaded {
                    request_id,
                    origin: RateLimitRefreshOrigin::StatusCommand { request_id },
                    hard_stop_generation: 0,
                    result: result.map(|update| {
                        serde_json::from_value(serde_json::json!({"rateLimits": update})).unwrap()
                    }),
                },
            )
            .await?;
            assert_eq!(app.chat_widget.usage_notice_state.current(), expected);
        }
    }
    session.shutdown().await?;
    Ok(())
}

fn open_windows_sandbox_fallback_prompt(
        &mut self,
        preset: ApprovalPreset,
        profile_selection: Option<PermissionProfileSelection>,
    ) {
        use ratatui_macros::line;

        let allow_unelevated = self
            .windows_sandbox_config
            .allows(WindowsSandboxSetupMode::Unelevated);
        let setup_choice_is_required =
            !allow_unelevated || self.elevated_windows_sandbox_setup_required();
        let mut lines = Vec::new();
        lines.push(line![
            "Couldn't set up your sandbox with Administrator permissions".bold()
        ]);
        lines.push(line![""]);
        if allow_unelevated {
            lines.push(line![
                "You can still use Codex in a non-admin sandbox. It carries greater risk if prompt injected."
            ]);
        } else {
            lines.push(line![
                "Your organization requires the default sandbox before Codex can continue."
            ]);
        }
        lines.push(line![
            "Learn more <https://developers.openai.com/codex/windows>"
        ]);

        let mut header = ColumnRenderable::new();
        header.push(crate::terminal_hyperlinks::HyperlinkText::new(lines));

        let elevated_preset = preset.clone();
        let legacy_preset = preset;
        let retry_preset = elevated_preset.clone();
        let retry_profile_selection = profile_selection.clone();
        let elevated_profile_selection = profile_selection.clone();
        let legacy_profile_selection = profile_selection;
        let quit_otel = self.session_telemetry.clone();
        let elevated_item = SelectionItem {
