fn request_working_directory_change(&mut self, path: &str) {
        if !self.is_session_configured() {
            self.add_error_message(
                "The session must start before you can change its working directory.".to_string(),
            );
            return;
        }

        let Some(thread_id) = self.thread_id else {
            return;
        };
        if !self.can_change_working_directory(thread_id) {
            let message =
                "Changing directories requires an idle primary session without queued input.";
            self.app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
                history_cell::new_error_event(message.to_string()),
            )));
            return;
        }

        self.app_event_tx.send(AppEvent::ChangeWorkingDirectory {
            thread_id,
            requested_cwd: PathBuf::from(path),
        });
    }

fn managed_worktree_action(
        &self,
        request: &Request,
        action: Action,
    ) -> Option<AppEvent> {
        if !self.worktree_request_is_current(request) {
            return None;
        }
        Some(match action {
            Action::Resume(owner) => AppEvent::ResumeSessionByIdOrName(owner.to_string()),
            Action::Copy(cwd) => AppEvent::CopySelection {
                text: cwd.to_str()?.into(),
                label: "Worktree working directory".to_string(),
                format: crate::clipboard_copy::CopyFormat::PlainText,
            },
            Action::Remove(root) => AppEvent::RemoveManagedWorktree {
                request: request.clone(),
                root,
            },
        })
    }

