fn discovery_preserves_config_scope_and_bounds_server_requests() {
    let home = tempfile::tempdir().unwrap();
    for case in [
        "local",
        "session-only",
        "remote",
        "remote-default",
        "thread",
        "legacy",
        "empty",
        "unsupported",
        "config-error",
        "cycle",
        "limit",
        "timeout",
    ] {
        let mode = if matches!(case, "local" | "session-only" | "timeout") {
            ThreadParamsMode::Embedded
        } else {
            ThreadParamsMode::Remote
        };
        let overrides = if case == "session-only" {
            vec![
                (
                    "permissions.session-only.extends".into(),
                    ":workspace".into(),
                ),
                ("default_permissions".into(), "session-only".into()),
            ]
        } else {
            Vec::new()
        };
        let config = ConfigBuilder::default()
            .codex_home(home.path().to_path_buf())
            .cli_overrides(overrides)
            .build()
            .await
            .unwrap();
        let thread_cwd = (case == "thread").then_some(std::path::Path::new("/thread"));
        let remote_cwd = (case != "remote-default").then_some("/server");
        let cwd = thread_cwd.map(|path| path.to_str().unwrap()).or_else(|| {
            if mode == ThreadParamsMode::Embedded {
                config.cwd.to_str()
            } else {
                remote_cwd
            }
        });
        let data = json!([
            {"id": ":workspace", "description": null, "allowed": true},
            {"id": "remote-profile", "description": "Server description", "allowed": true}
        ]);
        let requirements = json!({"allowedPermissionProfiles": {"remote-profile": true}});
        let mut replies = vec![json!({"result": {"requirements": requirements}})];
        replies.extend(match case {
            "empty" => vec![json!({"result": {"data": [], "nextCursor": null}})],
            "unsupported" => vec![json!({"error": {"code": -32601, "message": "Unknown method"}})],
            "config-error" => {
                vec![json!({"error": {"code": -32603, "message": "Invalid project config"}})]
            }
            "cycle" => vec![json!({"result": {"data": [], "nextCursor": "repeat"}}); 2],
            "limit" => (0..10)
                .map(|i| json!({"result": {"data": [], "nextCursor": i.to_string()}}))
                .collect(),
            _ => vec![
                json!({"result": {"data": [data[0]], "nextCursor": "second"}}),
                json!({"result": {"data": [data[1]], "nextCursor": null}}),
            ],
        });
        if case == "timeout" {
            replies = vec![Value::Null; 4];
        }
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let websocket_url = format!("ws://{}", listener.local_addr().unwrap());
        let server = tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            let mut socket = tokio_tungstenite::accept_async(stream).await.unwrap();
            let mut replies = replies.into_iter();
            let mut requests = Vec::new();
            while let Some(Ok(Message::Text(text))) = socket.next().await {
                let request: Value = serde_json::from_str(&text).unwrap();
                if request["id"].is_null() {
                    continue;
                }
                let mut response = if request["method"] == "initialize" {
                    json!({"result": {"userAgent": "permission-discovery-test", "platformFamily": "unix", "platformOs": "linux"}})
                } else {
                    requests.push(request.clone());
                    replies.next().expect("unexpected discovery request")
                };
                if response.is_null() {
                    continue;
                }
                response["id"] = request["id"].clone();
                socket
                    .send(Message::Text(response.to_string().into()))
                    .await
                    .unwrap();
            }
            requests
        });
        let client = crate::connect_remote_app_server(crate::RemoteAppServerEndpoint::WebSocket {
            websocket_url,
            auth_token: None,
        })
        .await
        .unwrap();
        let session = AppServerSession::new(crate::backend_id::BackendId::new(), client, mode)
            .with_remote_cwd_override(remote_cwd.map(std::path::PathBuf::from));
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        if case == "timeout" {
            tokio::time::pause();
        } // Keep real time for the socket handshake.
        for _ in 0..if case == "timeout" { 4 } else { 1 } {
            fetch(
                &session,
                Uuid::new_v4(),
                &config,
                thread_cwd,
                AppEventSender::new(tx.clone()),
            );
            let AppEvent::PermissionProfilesLoaded { result, .. } = rx.recv().await.unwrap() else {
                panic!("expected discovery result")
            };
            let error = match case {
                "unsupported" => Some("Upgrade"),
                "config-error" => Some("Invalid project config"),
                "cycle" | "limit" => Some("pagination limit"),
                "timeout" => Some("timed out"),
                _ => None,
            };
            if let Some(error) = error {
                assert!(result.unwrap_err().contains(error));
                continue;
            }
            let discovery = result.unwrap();
            if case == "empty" {
                assert!(discovery.profiles.is_empty());
            } else {
                assert_eq!(serde_json::to_value(&discovery.profiles).unwrap(), data);
                assert_eq!(
                    discovery.requirements,
                    Some(serde_json::from_value(requirements.clone()).unwrap())
                );
            }
        }
        session.shutdown().await.unwrap();
        let requests = server.await.unwrap();
        match case {
            "timeout" => {
                assert_eq!(requests.len(), 4);
                let ids: HashSet<_> = requests.iter().map(|request| &request["id"]).collect();
                assert_eq!(ids.len(), requests.len());
            }
            "local" | "session-only" | "remote" | "remote-default" | "thread" | "legacy" => {
                let pages: Vec<_> = requests
                    .iter()
                    .filter(|request| request["method"] == "permissionProfile/list")
                    .map(|request| request["params"].clone())
                    .collect();
                assert_eq!(
                    pages,
                    vec![
                        json!({"cwd": cwd, "limit": 100, "cursor": null}),
                        json!({"cwd": cwd, "limit": 100, "cursor": "second"})
                    ]
                );
            }
            _ => {}
        }
        if case == "timeout" {
            tokio::time::resume();
        }
    }
}

fn build_pet_picker_params(
    current_pet: Option<&str>,
    codex_home: &Path,
    preview_state: PetPickerPreviewState,
) -> SelectionViewParams {
    let preferred_pet = current_pet.unwrap_or(DEFAULT_PET_ID);
    let mut entries = available_pet_entries(codex_home);
    entries.sort_by(|left, right| left.display_name.cmp(&right.display_name));
    if let Some(disabled_idx) = entries
        .iter()
        .position(|entry| entry.selector == DISABLED_PET_ID)
    {
        let disabled_entry = entries.remove(disabled_idx);
        entries.insert(0, disabled_entry);
    }

    let mut initial_selected_idx = None;
    let preview_pet_ids = entries
        .iter()
        .map(|entry| entry.selector.clone())
        .collect::<Vec<_>>();
    let on_selection_changed: crate::bottom_pane::OnSelectionChangedCallback = Some(Box::new(
        move |idx: usize, tx: &crate::app_event_sender::AppEventSender| {
            if let Some(pet_id) = preview_pet_ids.get(idx) {
                tx.send(AppEvent::PetPreviewRequested {
                    pet_id: pet_id.clone(),
                });
            }
        },
    ));

    let items = entries
        .into_iter()
        .enumerate()
        .map(|(idx, entry)| {
            let is_current = current_pet.is_some_and(|current_pet| {
                current_pet == entry.selector
                    || entry.legacy_selector.as_deref() == Some(current_pet)
            });
            if preferred_pet == entry.selector
                || entry.legacy_selector.as_deref() == Some(preferred_pet)
            {
                initial_selected_idx = Some(idx);
            }
            let pet_id = entry.selector.clone();
            let search_value = if pet_id == DISABLED_PET_ID {
                "disable disabled hide hidden off none".to_string()
            } else {
                entry.selector
            };
            let actions: Vec<SelectionAction> = if pet_id == DISABLED_PET_ID {
                vec![Box::new(|tx| {
                    tx.send(AppEvent::PetDisabled);
                })]
            } else {
                vec![Box::new(move |tx| {
                    tx.send(AppEvent::PetSelected {
                        pet_id: pet_id.clone(),
                    });
                })]
            };
            SelectionItem {
                name: entry.display_name,
                description: entry.description,
                is_current,
                dismiss_on_select: true,
                search_value: Some(search_value),
                actions,
                ..Default::default()
            }
        })
        .collect();

    SelectionViewParams {
        view_id: Some(PET_PICKER_VIEW_ID),
        title: Some("Select Pet".to_string()),
        subtitle: Some("Choose a pet to wake in the terminal.".to_string()),
        footer_hint: Some(standard_popup_hint_line()),
        items,
        is_searchable: true,
        search_placeholder: Some("Type to filter pets...".to_string()),
        initial_selected_idx,
        side_content: Box::new(preview_state.renderable()),
        side_content_width: SideContentWidth::Fixed(PET_PICKER_PREVIEW_WIDTH),
        side_content_min_width: 28,
        stacked_side_content: Some(Box::new(())),
        preserve_side_content_bg: true,
        on_selection_changed,
        ..SelectionViewParams::picker()
    }
}

