fn log_inbound_app_event_with(logger: &SessionLogger, event: &AppEvent) {
    // Log only if enabled
    if !logger.is_enabled() {
        return;
    }

    match event {
        AppEvent::NewSession { .. } => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "new_session",
            });
            logger.write_json_line(value);
        }
        AppEvent::ClearUi { .. } => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "clear_ui",
            });
            logger.write_json_line(value);
        }
        AppEvent::InsertHistoryCell(cell) => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "insert_history_cell",
                "lines": cell.transcript_lines(u16::MAX).len(),
            });
            logger.write_json_line(value);
        }
        AppEvent::StartFileSearch(query) => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "file_search_start",
                "query": query,
            });
            logger.write_json_line(value);
        }
        AppEvent::FileSearchResult { query, matches } => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "file_search_result",
                "query": query,
                "matches": matches.len(),
            });
            logger.write_json_line(value);
        }
        AppEvent::PetPreviewLoaded { request_id, result } => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "app_event",
                "variant": "PetPreviewLoaded",
                "request_id": request_id,
                "ok": result.is_ok(),
            });
            logger.write_json_line(value);
        }
        AppEvent::PetSelectionLoaded {
            request_id,
            pet_id,
            result,
        } => {
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "app_event",
                "variant": "PetSelectionLoaded",
                "request_id": request_id,
                "pet_id": pet_id,
                "ok": result.is_ok(),
            });
            logger.write_json_line(value);
        }
        // Noise or control flow – record variant only
        other => {
            let variant: &'static str = other.into();
            let value = json!({
                "ts": now_ts(),
                "dir": "to_tui",
                "kind": "app_event",
                "variant": variant,
            });
            logger.write_json_line(value);
        }
    }
}

fn inbound_fallback_records_only_variant_names() {
    let directory = tempfile::tempdir().expect("temporary log directory");
    let path = directory.path().join("session.jsonl");
    let logger = SessionLogger::new();
    logger.open(path.clone()).expect("open session log");
    for event in [
        AppEvent::CopySelection {
            text: Arc::from("private plan without parentheses"),
            label: "private label".to_string(),
            format: crate::clipboard_copy::CopyFormat::Markdown,
        },
        AppEvent::CopySelection {
            text: Arc::from("private code(with parentheses)"),
            label: "private label".to_string(),
            format: crate::clipboard_copy::CopyFormat::PlainText,
        },
        AppEvent::ConsolidateProposedPlan("private tuple payload".to_string()),
        AppEvent::SettingsSelectionClosed,
    ] {
        log_inbound_app_event_with(&logger, &event);
    }
    let records = std::fs::read_to_string(path)
        .expect("read session log")
        .lines()
        .map(|line| {
            let mut record: serde_json::Value = serde_json::from_str(line).expect("valid log JSON");
            record.as_object_mut().expect("log object").remove("ts");
            record
        })
        .collect::<Vec<_>>();
    assert_eq!(
        records,
        [
            "CopySelection",
            "CopySelection",
            "ConsolidateProposedPlan",
            "SettingsSelectionClosed"
        ]
        .map(|variant| json!({"dir": "to_tui", "kind": "app_event", "variant": variant}))
    );
}

fn fragmented_terminal_response_cannot_grant_startup_hook_trust() {
        let (tx_raw, _rx) = unbounded_channel::<AppEvent>();
        let keymap = RuntimeKeymap::defaults();
        let mut view = selection_view(
            &entry(),
            /*trust_all_error*/ None,
            /*trusting_all*/ false,
            AppEventSender::new(tx_raw),
            &keymap,
        );

        // A delayed OSC reply can lose its escape prefix in the protected-screen input drain.
        for character in "20;rgb:2222/ffff/ffff".chars() {
            view.handle_key_event(KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE));
            assert_ne!(
                selected_choice(&mut view),
                Some(StartupHooksReviewSelection::TrustAllAndContinue)
            );
        }

        assert_eq!(view.selected_index(), Some(1));
        view.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert_eq!(
            selected_choice(&mut view),
            Some(StartupHooksReviewSelection::TrustAllAndContinue)
        );
    }

