fn model_theme_files_preview_select_and_restore() {
    if std::env::var_os("CODEX_MODEL_THEME_TEST_CHILD").is_none() {
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "theme_picker::model_tests::model_theme_files_preview_select_and_restore",
                "--nocapture",
            ])
            .env("CODEX_MODEL_THEME_TEST_CHILD", "1")
            .env("FORCE_COLOR", "3")
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        return;
    }
    let original = highlight::current_syntax_theme();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    let tx = AppEventSender::new(tx);
    let mut snapshot = String::new();
    for name in ["ada", "babbage", "curie", "cushman", "dali", "davinci"] {
        let light = matches!(name, "babbage" | "cushman" | "davinci");
        let colors = crate::terminal_probe::DefaultColors {
            fg: if light { (32, 32, 32) } else { (224, 224, 224) },
            bg: if light { (255, 255, 255) } else { (24, 24, 24) },
        };
        with_test_default_colors(colors, || {
            let params = build_theme_picker_params(Some(name), /*codex_home*/ None, Some(120));
            let idx = params.initial_selected_idx.unwrap();
            assert_eq!(params.items[idx].search_value.as_deref(), Some(name));
            params.on_selection_changed.as_ref().unwrap()(idx, &tx);
            assert!(matches!(
                rx.try_recv().unwrap(),
                AppEvent::SyntaxThemePreviewed
            ));
            let code = "let answer = 42;\n";
            let lines = highlight::highlight_code_to_lines(code, "rust");
            assert!(lines.iter().all(|line| line.style.bg.is_none()
                && line.spans.iter().all(|span| span.style.bg.is_none())));
            let area = Rect::new(
                /*x*/ 0, /*y*/ 0, /*width*/ 54, /*height*/ 4,
            );
            let mut buffer = Buffer::empty(area);
            ThemePreviewNarrowRenderable.render(area, &mut buffer);
            if matches!(name, "dali" | "davinci") {
                assert!(
                    buffer
                        .content
                        .iter()
                        .all(|cell| cell.bg == ratatui::style::Color::Reset)
                );
            }
            snapshot.push_str(&format!(
                "{name}: accent={:?}\n",
                crate::style::accent_style()
            ));
            for y in 0..area.height {
                let row: String = (0..area.width).map(|x| buffer[(x, y)].symbol()).collect();
                snapshot.push_str(row.trim_end());
                snapshot.push('\n');
            }
            let styles = buffer
                .content
                .iter()
                .map(|cell| format!("{:?}", cell.style()))
                .collect::<std::collections::BTreeSet<_>>();
            snapshot.push_str(&format!("preview styles: {styles:?}\nsyntax: {lines:?}\n"));
            params.items[idx].actions[0](&tx);
            assert!(
                matches!(rx.try_recv().unwrap(), AppEvent::SyntaxThemeSelected { name: selected } if selected == name)
            );
            params.on_cancel.as_ref().unwrap()(&tx);
            assert!(matches!(
                rx.try_recv().unwrap(),
                AppEvent::SyntaxThemePreviewed
            ));
            assert_eq!(highlight::current_syntax_theme(), original);
        });
    }
    insta::assert_snapshot!(snapshot);
}

fn empty_copy_releases_input_guard() {
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    let guard = Arc::new(crate::copy_input_guard::CopyInputGuard(
        crate::app_event_sender::AppEventSender::new(tx),
    ));
    let weak = Arc::downgrade(&guard);
    let mut view = TranscriptView::default();
    assert!(!view.begin_copy_mode(&[], Some(guard)));
    assert!(weak.upgrade().is_none());
    assert!(matches!(
        rx.try_recv(),
        Ok(crate::app_event::AppEvent::TranscriptCopyClosed)
    ));
}

fn copy_input_guard_is_released_on_all_selector_exits() {
    let cells: Vec<Arc<dyn HistoryCell>> = vec![Arc::new(AgentMarkdownCell::new(
        "response".into(),
        Path::new("/"),
    ))];
    for exit in ["escape", "find", "mouse", "confirmed", "presentation"] {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let guard = Arc::new(crate::copy_input_guard::CopyInputGuard(
            crate::app_event_sender::AppEventSender::new(tx),
        ));
        let weak = Arc::downgrade(&guard);
        let mut view = TranscriptView::default();
        render(&mut view, &cells, /*width*/ 40, /*height*/ 5);
        view.begin_copy_mode(&cells, Some(guard));
        assert!(weak.upgrade().is_some());
        match exit {
            "escape" => {
                view.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &cells);
            }
            "find" => view.begin_search(),
            "mouse" => {
                view.begin_selection(&cells, /*column*/ 2, /*row*/ 0, /*clicks*/ 1)
            }
            "confirmed" => {
                view.copy_selected_text_with(
                    &cells,
                    "response",
                    /*clear_selection*/ true,
                    |_, _| Ok(CopyStatus::Confirmed),
                )
                .unwrap();
            }
            "presentation" => view.set_presentation(
                /*detailed*/ true,
                crate::history_cell::HistoryRenderMode::Raw,
            ),
            _ => unreachable!(),
        }
        assert!(weak.upgrade().is_none(), "{exit}");
        assert!(matches!(
            rx.try_recv(),
            Ok(crate::app_event::AppEvent::TranscriptCopyClosed)
        ));
    }
}

fn mapped_shift_enter_renders_newlines_in_the_composer() {
    use crate::app_event::AppEvent;
    use crate::app_event_sender::AppEventSender;
    use crate::bottom_pane::ChatComposer;
    use crate::bottom_pane::InputResult;
    use crate::render::renderable::Renderable;
    use ratatui::Terminal;
    use ratatui::backend::TestBackend;

    let (tx, _rx) = tokio::sync::mpsc::unbounded_channel::<AppEvent>();
    let mut composer = ChatComposer::new(
        /*has_input_focus*/ true,
        AppEventSender::new(tx),
        /*enhanced_keys_supported*/ false,
        "Ask Codex to do anything".to_string(),
        /*disable_paste_burst*/ true,
    );
    for event in decoded(keys("first line\u{1b}[13;2u\u{1b}[13;2usecond line [13;2u")).await {
        let Event::Key(key) = event else {
            unreachable!()
        };
        assert!(matches!(
            composer.handle_key_event(key).0,
            InputResult::None
        ));
    }
    assert_eq!(composer.current_text(), "first line\n\nsecond line [13;2u");
    let mut terminal = Terminal::new(TestBackend::new(/*width*/ 60, /*height*/ 9)).unwrap();
    terminal
        .draw(|frame| composer.render(frame.area(), frame.buffer_mut()))
        .unwrap();
    insta::assert_snapshot!("windows_mapped_shift_enter", terminal.backend());
}

fn fetch(
    request: Request,
    codex_home: PathBuf,
    app_server: AppServerRequestHandle,
    tx: AppEventSender,
) {
    tokio::spawn(async move {
        let result = async {
            let mut entries = list(codex_home.clone(), request.cwd.clone()).await?;
            let archive_root = codex_home.join(codex_rollout::ARCHIVED_SESSIONS_SUBDIR);
            for entry in &mut entries {
                let Owner::Unavailable(id) = entry.owner else {
                    continue;
                };
                let response = app_server
                    .request_typed::<ThreadReadResponse>(ClientRequest::ThreadRead {
                        request_id: RequestId::String(uuid::Uuid::new_v4().to_string()),
                        params: ThreadReadParams {
                            thread_id: id.to_string(),
                            include_turns: false,
                        },
                    })
                    .await;
                if let Ok(response) = response {
                    let thread = response.thread;
                    let Some(path) = thread.path.as_ref() else {
                        continue;
                    };
                    let Some(path) = codex_rollout::existing_rollout_path(path).await else {
                        continue;
                    };
                    let archived = path.starts_with(&archive_root);
                    let title = thread
                        .name
                        .filter(|name| !name.trim().is_empty())
                        .unwrap_or_else(|| {
                            thread
                                .preview
                                .lines()
                                .next()
                                .filter(|preview| !preview.trim().is_empty())
                                .unwrap_or("Untitled conversation")
                                .to_string()
                        });
                    let title = if title.chars().count() > 80 {
                        format!("{}…", title.chars().take(79).collect::<String>())
                    } else {
                        title
                    };
                    let summary = ThreadSummary {
                        id,
                        title,
                        updated_at: thread.updated_at,
                    };
                    entry.owner = if archived {
                        Owner::Archived(summary)
                    } else {
                        Owner::Resumable(summary)
                    };
                }
            }
            anyhow::Ok(entries)
        }
        .await
        .map_err(|error| error.to_string());
        tx.send(AppEvent::ManagedWorktreesLoaded { request, result });
    });
}

