AppEvent::UpdateAskForApprovalPolicy(policy) => {
                if self.reject_pending_permission_change() {
                    return Ok(AppRunControl::Continue);
                }
                let mut config = self.config.clone();
                if !self.try_set_approval_policy_on_config(
                    &mut config,
