                    Ok(ExternalAgentConfigMigrationFlowOutcome::TerminalError(err)) => {
                        return Err(err.into());
                    }
                    Err(error_message) => {
                        self.chat_widget.add_error_message(error_message);
                    }
                }
                tui.frame_requester().schedule_frame();
            }

